RG.HK["30"] = [{"id":"30_kongobuji","n":"高野山 金剛峯寺（真言密教の総本山）","yomi":"こうやさん こんごうぶじ","cat":"寺社","y":816,"era":["heian","azuchi","edo"],"sh":"国指定史跡（金剛峯寺境内）・世界遺産","rank":"S","ad":"伊都郡高野町高野山","st":"南海高野線 極楽橋駅からケーブルカーで高野山駅、バス «金剛峯寺前» 下車すぐ（ケーブル・バスあわせて約20分）","la":34.2131,"lo":135.5843,"hook":"標高およそ800mの山の上に、お寺が100以上も集まる «宗教都市»。その中心が、空海が開いた真言密教の総本山・金剛峯寺だ。","lead":"816年、空海（弘法大師）は嵯峨天皇から高野山の土地をいただき、修行の道場を開きました。«金剛峯寺» はもともと高野山全体を指す名前で、今の建物は豊臣秀吉が母のために建てたお寺がもとになっています。2004年には «紀伊山地の霊場と参詣道» として世界遺産になりました。","story":["平安時代のはじめ、唐（中国）で密教を学んで帰ってきた空海は、ひとつの願いを持っていました。«都のさわがしさから離れて、心静かに修行できる場所がほしい»。若いころ山や海をめぐって修行した空海は、紀伊の山奥に、周りを八つの峰に囲まれた平らな土地があることを知っていたといわれます。","816年、空海は嵯峨天皇に «この土地をいただきたい» と願い出て、ゆるしを得ました。山の上の平地は、蓮の花びらのような峰に囲まれていることから «八葉の蓮華» にたとえられます。なぜこんな山奥に? それは、仏の世界をこの地上につくり出すためだったのです。","空海が亡くなったあと、高野山は大火事や争いで何度もさびれかけました。それでも僧たちや、各地から集まる信者の力で立ち直ります。戦国時代には、天下統一を進める豊臣秀吉とも向き合いました。秀吉は高野山を攻めることはせず、やがて母・大政所の菩提をとむらうため «青巌寺» を建てさせます。","その青巌寺の «柳の間» では、1595年、秀吉のおいで関白だった豊臣秀次が自害したと伝わります。華やかなふすま絵の部屋に、そんな悲しい記憶が重なっているのです。明治のはじめ、青巌寺は隣の興山寺と一緒になり、今の «金剛峯寺» という名前を受け継ぎました。","いま金剛峯寺を訪ねると、広い主殿のふすま絵、台所の大きなかまど、そして雲海に浮かぶ龍をあらわしたという石庭 «蟠龍庭» が迎えてくれます。«山全体が一つのお寺» という高野山の考え方を、まずここで感じてみましょう。"],"tl":[["816年","空海が嵯峨天皇から高野山の地を賜る"],["835年","空海が高野山で入定（亡くなる）"],["921年","醍醐天皇から «弘法大師» の名がおくられる"],["1593年","豊臣秀吉が母の菩提のため青巌寺を建てる"],["1595年","豊臣秀次が青巌寺で自害したと伝わる"],["1869年","青巌寺と興山寺が合わさり «金剛峯寺» となる"],["2004年","世界遺産 «紀伊山地の霊場と参詣道» に登録"],["2015年","高野山開創1200年の記念法会"]],"who":[["空海（弘法大師）","高野山を開いた僧。真言密教を日本に広めた"],["嵯峨天皇","空海に高野山の地を与えた天皇。空海とは書の友でもあった"],["豊臣秀吉","母のために青巌寺（今の金剛峯寺のもと）を建てた"],["豊臣秀次","秀吉のおい。青巌寺で自害したと伝わる"]],"deep":["«金剛峯寺» という名は、空海のころは高野山全体を指す寺号でした。いまでも «一山境内地» といい、山全体がお寺の境内だと考えられています。","明治の合併で寺名を受け継いだのは、秀吉ゆかりの青巌寺と、木食応其が開いた興山寺。どちらも秀吉と高野山の橋渡しをした木食応其が深く関わっています。","主殿のふすま絵は狩野派の絵師によるものと伝わり、«柳の間» の柳鷺図などが知られます。ふだんの公開範囲は季節により異なります。","石庭 «蟠龍庭» は昭和の造営で、2,000㎡を超える広さは日本最大級といわれます。花こう岩140個ほどで雌雄の龍を表すとされます。","明治以前の高野山は «女人禁制»。1872年に政府の布告でゆるめられるまで、女性は山の入口にあった «女人堂» までしか入れませんでした。","世界遺産の登録では、高野山は吉野・大峯、熊野三山と、それらを結ぶ参詣道とともに «一つの文化的景観» として評価されています。"],"look":["主殿の大玄関（天皇や皇族などしか通れなかったという正門）","«柳の間» のふすま絵","日本最大級の石庭 «蟠龍庭»","大きなかまどが並ぶ «台所»","屋根の上の天水桶（火事にそなえた水おけ）"],"q":["明治になるまで «金剛峯寺» は何を指す名前だった？","高野山全体のお寺の名前。今の金剛峯寺の建物は、秀吉ゆかりの青巌寺がもとです。"],"koji":[{"w":"弘法にも筆の誤り","m":"書の名人の空海でさえ書き損じることがある。どんな名人も失敗することがあるというたとえ"}],"myth":"秀次が自害したのが «柳の間» という話や、ふすま絵の作者については伝承を含む。","img":["空海","高野山","豊臣秀次","紀伊山地の霊場と参詣道"],"wp":"金剛峯寺","rel":{"ev":["kukai"],"grave":[]},"ph":[["c:e/e1/Danjogaran_Koyasan16n4272.jpg",4272,2848,"金剛峯寺"],["c:a/ad/Gobyoubasi.jpg",4265,3173],["c:5/57/AmidaRaigo.jpg",8192,3978],["c:1/17/Kongobuji_Koyasan01n4272.jpg",4272,2848],["c:6/62/Danjogaran_Koyasan08n4272.jpg",4272,2848],["c:a/a4/Danjogaran_Koyasan05s5s4272.jpg",4272,2848],["c:1/13/Danjogaran_Koyasan02s5s3200.jpg",4272,2848],["c:b/b7/Daimon_Koyasan01n4272.jpg",4272,2848]]},{"id":"30_okunoin","n":"高野山 奥之院と弘法大師御廟","yomi":"こうやさん おくのいん と こうぼうだいし ごびょう","cat":"墓所","y":835,"era":["heian","azuchi","edo"],"sh":"国指定史跡（金剛峯寺境内）・世界遺産","rank":"S","ad":"伊都郡高野町高野山（奥之院）","st":"高野山駅からバス «奥の院口»（一の橋）約15分、または «奥の院前» 下車。一の橋から御廟まで歩いて約2km","la":34.2185,"lo":135.5985,"hook":"杉の巨木の下、約2kmの参道に戦国武将から名もない人まで、20万基をこえるといわれる墓や供養塔が並ぶ。その奥で、空海は «今も瞑想を続けている» と信じられている。","lead":"奥之院は、空海（弘法大師）が眠る御廟のある聖地です。空海は835年に亡くなりましたが、«亡くなったのではなく、深い瞑想（入定）に入って今も人々を救っている» と信じられ、今も毎日食事が運ばれています。参道には織田信長や武田信玄など、敵同士だった武将たちの供養塔も仲良く並びます。","story":["一の橋をわたると、空気がすっと冷たくなります。樹齢数百年の杉が空をおおい、苔むした石の塔が、道の両側にどこまでも続きます。ここは高野山でいちばん神聖な場所、奥之院。いったいなぜ、これほど多くの人がここにお墓をつくりたがったのでしょう?","835年3月21日、空海は高野山で静かに息を引き取りました。ところが弟子たちの間には、«大師は亡くなったのではない。弥勒菩薩がこの世に現れるその日まで、瞑想を続けておられるのだ» という信仰が広まります。これを «入定信仰» といいます。大師のそばに眠れば救われる――そう願った人々が、身分を問わず供養塔を建てていったのです。","参道を歩くと、驚くような名前に出会います。武田信玄と勝頼、上杉謙信、織田信長、明智光秀、豊臣家、石田三成……。生きていたころは戦い合った者どうしが、ここでは同じ杉木立の中に並んでいます。«死ねばみな大師のもとで平等» という高野山の考え方が、目に見える形になっているのです。","御廟橋をわたると、そこからは撮影禁止の聖域です。燈籠堂には、たくさんの灯りがともっています。その中には、貧しい娘が自分の髪を売って献じたと伝わる «貧女の一灯»、平安時代に高野山を立て直した僧・祈親上人がともしたとされる «祈親灯» があり、千年近く消えずに燃え続けていると伝わります。","毎日、朝と昼前の2回、僧たちが御廟へ食事を運ぶ儀式 «生身供（しょうじんぐ）» が行われます。お膳を担いだ行列が静かに橋をわたる姿を見ると、ここでは空海が «今も生きている» ことが、人々にとって当たり前の真実なのだと感じられます。"],"tl":[["835年","空海が入定。奥之院に葬られる"],["921年","醍醐天皇が «弘法大師» の名をおくる。勅使が御廟を訪れたと伝わる"],["1016年ごろ","祈親上人定誉が高野山の復興に取り組む（祈親灯の伝承）"],["平安時代後期","貴族の «高野詣» がさかんになる"],["戦国〜江戸時代","大名たちが競って供養塔を建てる"],["2004年","世界遺産に登録"]],"who":[["空海（弘法大師）","御廟に眠る。今も瞑想を続けていると信じられている"],["祈親上人定誉","平安時代に高野山を再興した僧。«祈親灯» の伝承で知られる"],["織田信長","参道に供養塔がある。生前は高野山と対立した"],["武田信玄・上杉謙信","宿敵どうしの供養塔が同じ参道にある"],["醍醐天皇","空海に «弘法大師» の名をおくった"]],"deep":["«入定» は仏教で深い瞑想に入ること。空海の入定信仰は平安時代中ごろから強まり、弥勒菩薩が現れる56億7千万年後まで待つという考えと結びつきました。","墓碑・供養塔の数は «20万基以上» とよくいわれますが、正確に数えた数ではありません。中世の五輪塔から、現代の企業の供養塔まで時代もさまざまです。","供養塔の多くは «遺骨がある墓» ではなく、魂を大師のそばに置くための «供養塔»。一人の武将の供養塔が高野山内の複数の場所にあることもあります。","御廟橋は36枚の橋板でできていて、橋全体で37尊（金剛界の仏）を表すといわれます。橋の手前で一礼するのが作法です。","中の橋の近くにある «汗かき地蔵» や «姿見の井戸»（のぞいて姿が映らないと3年以内に死ぬ、という言い伝え）など、参道には民間信仰の名所も多くあります。","奥之院の杉並木は、江戸時代の絵図にもほぼ今と同じ姿で描かれています。ここは長い時間をかけて育てられてきた «信仰の森» なのです。"],"look":["一の橋から御廟までの約2kmの杉並木の参道","武田・上杉・織田・豊臣など戦国大名の供養塔","御廟橋（ここから先は撮影・飲食禁止）","燈籠堂の «貧女の一灯» «祈親灯»","毎日の «生身供»（時間が合えば遠くから静かに見学）"],"q":["空海のもとへ毎日食事を運ぶ儀式を何という？","«生身供（しょうじんぐ）»。空海が今も瞑想を続けているという信仰にもとづき、1日2回行われます。"],"koji":[{"w":"貧者の一灯","m":"貧しい人が真心をこめてささげる小さな灯りは、金持ちの万の灯りよりも尊いということ。仏教の説話に由来する"}],"myth":"«貧女の一灯» «祈親灯» が千年消えずに燃えているという話や、姿見の井戸は伝承。墓碑の数も概数。","img":["空海","紀伊山地の霊場と参詣道"],"wp":"高野山","rel":{"ev":[],"grave":[]},"ph":[["c:1/17/Danjogaran_Koyasan12n3200.jpg",3200,2133,"高野山"],["c:5/5c/Nyonindo_001.jpg",5417,3611],["c:1/1f/Looking_up_the_main_street_near_the_fire_department_and_post_office%2C_Koyasan%2C_2016.jpg",6016,3539],["c:2/2f/Koyasan_Danjogaran_Fudodo.JPG",4288,2848],["c:c/cd/Kongosanmaiin_Tahoto.JPG",4288,2848],["c:c/ce/Kongobuji_Koyasan02n4272.jpg",4272,2848],["c:4/49/Autumn_Koyasan_Wakayama01s5s3200.jpg",4230,2820],["c:b/b3/Danjogaran_Koyasan01n3200.jpg",3200,2133]]},{"id":"30_danjo_garan","n":"高野山 壇上伽藍（根本大塔）","yomi":"こうやさん だんじょうがらん","cat":"寺社","y":819,"era":["heian","showa","heisei"],"sh":"国宝（不動堂）・国指定史跡（金剛峯寺境内）・世界遺産","rank":"S","ad":"伊都郡高野町高野山","st":"高野山駅からバス «金堂前» 下車すぐ（約15分）。金剛峯寺から歩いて約5分","la":34.2127,"lo":135.5806,"hook":"空海が高野山で最初に «仏の世界» を形にしようとした場所。朱色の根本大塔は、立体でつくられた曼荼羅だ。","lead":"壇上伽藍は、空海が高野山を開いたとき、まず最初に建物を建て始めた場所です。高さ約48.5mの根本大塔の中には、大日如来を中心に仏たちがならび、密教の宇宙をそのまま目で見られるようになっています。火事で何度も焼けては建て直され、今の大塔は昭和の再建です。","story":["高野山の地を賜った空海が、最初に取りかかったのが «伽藍（お寺の建物群）» づくりでした。ここは高野山の «壇上»、つまり修行のための聖なる舞台。奥之院が «空海の眠る場所» なら、壇上伽藍は «空海が夢見た仏の世界» を表した場所です。","空海がいちばん大切にしたのが、大きな塔でした。«なぜお寺に、こんなに大きな塔を?» それは、密教の教えをことばではなく、形で見せるためです。塔の中には胎蔵界の大日如来と、金剛界の四仏が並び、柱には菩薩が描かれています。塔そのものが、立体の曼荼羅なのです。","けれど山の上の大きな木の建物は、雷や火事に弱いものでした。大塔は空海の生きているうちには完成せず、弟子たちの代に仕上がったとされます。その後も落雷などで何度も焼け、そのたびに人々が力を合わせて建て直しました。平安時代の末には、若き日の平清盛が大塔の再建にたずさわったと伝わります。","江戸時代の終わり、1843年の大火では大塔をはじめ多くの建物が焼けてしまいました。大塔がふたたび姿を現したのは、なんと約90年後の1937年。燃えないよう鉄筋コンクリートで建てられたのです。さらに2015年、開創1200年を記念して、長く失われていた «中門» が172年ぶりに再建されました。","伽藍の一角には、柵に囲まれた一本の松があります。空海が唐から日本へ帰るとき、«密教を広めるのにふさわしい地を示したまえ» と、仏具の三鈷杵を投げたところ、この松の枝にかかっていた――。そんな伝説の «三鈷の松» です。葉が三本に分かれた珍しい松葉を、お守りに探す人もいます。"],"tl":[["816年","空海が高野山を賜る"],["819年ごろ","伽藍の建設が始まったとされる"],["9世紀後半","根本大塔が完成したとされる（弟子の代）"],["平安時代末","平清盛が大塔の再建にかかわったと伝わる"],["1843年","大火で大塔など多くの堂塔が焼失"],["1932年","金堂が再建される"],["1937年","根本大塔が鉄筋コンクリートで再建"],["2015年","中門が172年ぶりに再建"]],"who":[["空海（弘法大師）","壇上伽藍の建設を始めた"],["真然","空海のおいで弟子。大塔の完成など伽藍整備を進めたとされる"],["平清盛","大塔の再建にかかわったと伝わる。«血曼荼羅» の伝説も"]],"deep":["根本大塔は、下が四角・上が円形の «多宝塔» という形式。高さ約48.5mで、この形式の塔としては最大級です。","不動堂は鎌倉時代の創建と伝わり、今の建物は14世紀ごろのものとされ、国宝です。四隅の形がそれぞれちがう、珍しいつくりです。","金堂にはかつて平清盛が自分の頭の血を絵の具にまぜて描かせたという «血曼荼羅» が伝わっていました（伝承）。現在は霊宝館で保管されています。","中門の再建（2015年）では、焼け残った持国天・多聞天に加え、新たに増長天・広目天の像がつくられ、胸にセミやトンボの彫刻がある遊び心が話題になりました。","«三鈷の松» の伝説では、空海は中国の港（明州）から三鈷杵を投げたとされます。距離を考えると信仰の物語として楽しむべき話です。","西塔は1834年の再建で、壇上伽藍の中では古い木造の塔。大塔と対になって配置されています。"],"look":["根本大塔の内部（立体曼荼羅）","国宝の不動堂","三鈷の松（三本葉の松葉を探してみよう）","2015年に再建された中門の四天王像","蛇腹道（壇上伽藍へ続く紅葉の名所）"],"q":["空海が唐から投げた三鈷杵がかかっていたと伝わる松の名前は？","«三鈷の松»。普通の松葉は2本ですが、この松には3本葉のものがまじっています。"],"koji":[],"myth":"三鈷の松、清盛の大塔再建・血曼荼羅は伝承。大塔の完成時期は諸説。","img":["金剛峯寺","空海","平清盛"],"wp":"壇上伽藍","rel":{"ev":["kukai"],"grave":[]},"ph":[["c:e/e1/Danjogaran_Koyasan16n4272.jpg",4272,2848,"壇上伽藍"],["c:a/ad/Gobyoubasi.jpg",4265,3173],["c:5/57/AmidaRaigo.jpg",8192,3978],["c:1/17/Kongobuji_Koyasan01n4272.jpg",4272,2848],["c:6/62/Danjogaran_Koyasan08n4272.jpg",4272,2848],["c:a/a4/Danjogaran_Koyasan05s5s4272.jpg",4272,2848],["c:1/13/Danjogaran_Koyasan02s5s3200.jpg",4272,2848],["c:b/b7/Daimon_Koyasan01n4272.jpg",4272,2848]]},{"id":"30_hongu","n":"熊野本宮大社","yomi":"くまのほんぐうたいしゃ","cat":"寺社","y":1090,"era":["heian","meiji"],"sh":"国の重要文化財（本殿）・国指定史跡（熊野三山）・世界遺産","rank":"S","ad":"田辺市本宮町本宮","st":"JR紀伊田辺駅または新宮駅から路線バス «本宮大社前» 下車すぐ（紀伊田辺から約2時間、新宮から約1時間20分）","la":33.8405,"lo":135.7735,"hook":"«蟻の熊野詣» とうたわれるほど、上皇から庶民までが列をなして目指した熊野信仰の中心。三本足のカラスが、今日も参拝者を迎える。","lead":"熊野本宮大社は、熊野三山（本宮・新宮・那智）のまとめ役ともいえる神社です。平安時代には上皇たちが何度も京都から歩いて参拝しました。もとは熊野川の中洲にありましたが、明治の大洪水で流され、今の高台に移りました。","story":["京都から熊野まで、片道およそ300km。往復に1か月ほどかかる旅に、平安時代の上皇たちはくり返し出かけました。後白河上皇は34回、後鳥羽上皇は28回も訪れたと伝わります。なぜそこまでして熊野へ? それは熊野が «この世にある浄土»、生まれ変わりの地と信じられていたからです。","熊野本宮大社にまつられるのは «家都美御子大神（けつみみこのおおかみ）»。素戔嗚尊と同じ神とされます。仏教と神道がまじりあった時代、この神は阿弥陀如来の姿で現れたものと考えられ、«ここにお参りすれば極楽往生できる» と信じられました。","やがて貴族だけでなく武士や庶民も、白い装束を身につけて熊野を目指すようになります。その行列は、アリがえさへ向かって一列に進むように途切れなかったので、«蟻の熊野詣» と呼ばれました。熊野の神は «浄・不浄を問わず»、身分や男女の区別なく人々を受け入れたとされます。","明治22年（1889年）8月、紀伊半島を大雨がおそいました。熊野川は大あふれし、中洲にあった社殿の多くが流されてしまいます。残った上四社の社殿は、1891年、今の高台へ移されました。158段の石段を上った先に並ぶ檜皮ぶきの社殿は、その時に移された江戸時代の建物です。","境内では、三本足のカラス «八咫烏（やたがらす）» の姿をあちこちで見かけます。神話で神武天皇を熊野から大和へ道案内したとされる、熊野の神の使いです。日本サッカー協会のシンボルマークにもなっているので、W杯の前には必勝祈願に訪れる人もいます。"],"tl":[["1090年","白河上皇が熊野御幸。上皇の熊野詣がさかんになる"],["12世紀","後白河上皇が34回、熊野を訪れたと伝わる"],["1201年","後鳥羽上皇の熊野御幸に藤原定家が同行（«熊野御幸記»）"],["1274年","一遍が本宮で神のお告げを受けたと伝わる（時宗のはじまり）"],["1889年","大水害で中洲の社殿の多くが流失"],["1891年","上四社を現在地へ移す"],["2004年","世界遺産に登録"]],"who":[["後白河上皇","熊野を34回訪れたと伝わる熊野信仰の熱心な信者"],["後鳥羽上皇","28回の熊野御幸を行ったと伝わる"],["藤原定家","後鳥羽上皇に同行し、旅のつらさを日記に書いた"],["一遍","本宮で神託を受けて念仏の布教を始めたとされる"],["神武天皇","神話で八咫烏に導かれ熊野から大和へ向かった"]],"deep":["熊野三山はもとは別々の信仰でしたが、平安時代に互いの神を祀りあい «熊野十二所権現» としてまとまりました。本宮の主神は阿弥陀如来、新宮は薬師如来、那智は千手観音を本地（本来の姿）とします。","今の社殿は上四社のうち3棟で、第三殿が主神・家都美御子大神。本殿は国の重要文化財です。社殿の配置は流される前の旧社地の並びを受け継いでいます。","熊野のお札 «熊野牛王宝印» はカラスの絵を組み合わせた文字でできていて、中世には誓約書の用紙にも使われました。これに書いた誓いを破ると «熊野のカラスが死ぬ» と恐れられました。","«蟻の熊野詣» の最盛期は院政期。熊野御幸は、白河・鳥羽・後白河・後鳥羽の4上皇で約100回にのぼるといわれます。","1889年の大水害は奈良県十津川村にも大きな被害を出し、多くの村人が北海道へ移住して «新十津川村» をつくりました。","社務所前の «八咫烏ポスト» は黒いポストとして知られます。サッカー日本代表のエンブレムと本宮との関係は、よく話題になる意外なつながりです。"],"look":["158段の石段と «熊野大権現» ののぼり","檜皮ぶきの本殿（重要文化財）","八咫烏の意匠や黒い «八咫烏ポスト»","約500m先の旧社地・大斎原（大鳥居）","熊野牛王宝印（お札）"],"q":["熊野の神の使いで、サッカー日本代表のマークにもなっている鳥は？","三本足のカラス «八咫烏»。神話で神武天皇を道案内したとされます。"],"koji":[{"w":"蟻の熊野詣","m":"熊野へ参る人の列が、アリの行列のように途切れず続いたことから、たいへん多くの人が次々と参詣するようす"}],"myth":"上皇ごとの参詣回数は史料により数え方がちがい、諸説ある。","img":["熊野三山","八咫烏","熊野古道","後白河天皇"],"wp":"熊野本宮大社","rel":{"ev":[],"grave":[]},"ph":[["c:b/b3/Inside_the_Kumano_Hongu_Taisha.jpg",2272,1704,"熊野本宮大社"],["c:6/66/Kumano_Kodo_Kumano_Hongu_Taisha_World_heritage_%E7%86%8A%E9%87%8E%E6%9C%AC%E5%AE%AE%E5%A4%A7%E7%A4%BE18.JPG",4608,3456],["c:8/8d/Kumano_Kodo_Kumano_Hongu_Taisha_World_heritage_%E7%86%8A%E9%87%8E%E6%9C%AC%E5%AE%AE%E5%A4%A7%E7%A4%BE102.JPG",3456,4608],["c:0/05/Kumano_Kodo_Kumano_Hongu_Taisha_World_heritage_%E7%86%8A%E9%87%8E%E6%9C%AC%E5%AE%AE%E5%A4%A7%E7%A4%BE07.JPG",4608,3456],["c:d/d9/Kumano_Kodo_Dainichigoe_World_heritage01.JPG",4608,3456],["c:2/22/Kumano-hong%C3%BB-taisha_Shrine_-_Stone_monument_of_a_crow_%22Yatagarasu%22.jpg",3096,4128],["c:6/6d/Daimonzaka8618.JPG",1200,1600],["c:a/a9/Emperor_Go-Shirakawa2.jpg",2450,2680,"後白河天皇"]]},{"id":"30_oyunohara","n":"大斎原（明治の大洪水まで本宮があった中洲）","yomi":"おおゆのはら","cat":"寺社","y":1889,"era":["heian","meiji","heisei"],"sh":"国指定史跡（熊野三山）・世界遺産","rank":"S","ad":"田辺市本宮町本宮","st":"バス «本宮大社前» から歩いて約5〜10分（熊野本宮大社から約500m）","la":33.8375,"lo":135.7708,"hook":"田んぼの向こうに、高さ約34mの巨大な鳥居。その奥の森こそ、明治の大洪水までおよそ2千年、熊野本宮があったと伝わる «神の中洲» だ。","lead":"大斎原は、熊野川と音無川・岩田川が合わさる中洲で、1889年まで熊野本宮大社がありました。大洪水で社殿の多くが流され、神社は今の場所に移りましたが、旧社地には石の祠が建ち、今も大切な聖地です。入口には2000年に完成した日本一の高さを誇る大鳥居が立っています。","story":["かつての熊野詣の旅人たちは、長い山道を歩いたあと、最後に音無川を歩いて渡りました。冷たい水で足をぬらし、身も心も清めてから本宮へ入る――。これを «濡れ藁沓（わらぐつ）の入堂» といいます。川に囲まれた中洲の森は、まさに «水に守られた神の島» でした。","そのころの本宮は、今よりずっと大きな神社でした。五棟、八棟と社殿が並び、楼門や多くの建物が中洲を埋めていたといわれます。«大斎原» の «斎» は、神をまつるために身を清めることを意味します。","1274年ごろ、念仏を広める旅をしていた僧・一遍は、自分の教えに迷いを感じていました。本宮にこもった一遍の前に、熊野の神が姿を現し、«信じる・信じないを問わず、念仏の札を配りなさい» と告げたと伝わります。これが一遍の開いた時宗のはじまりとされ、この地は «一遍成道の地» とも呼ばれます。","1889年8月、紀伊半島を記録的な豪雨がおそいました。上流の山々が崩れ、熊野川は濁流となって中洲をのみこみます。社殿の多くが流され、残った上四社は2年後、北西の高台へ移されました。上流の奈良県十津川村などでも多くの命が失われた、たいへんな災害でした。","今、大斎原の森の中には、流された中四社・下四社などをまつる二つの石の祠が静かに建っています。社殿がなくなっても、人々はここを見捨てませんでした。毎年春の例大祭では、神様が大斎原へお渡りになります。巨大な鳥居をくぐると、かつての熊野詣の人々と同じ景色の中に立っている気持ちになります。"],"tl":[["平安時代","熊野本宮が中洲にあり、上皇たちが参詣"],["1274年ごろ","一遍がここで熊野の神のお告げを受けたと伝わる"],["1889年8月","大水害で社殿の多くが流失"],["1891年","残った上四社を現在の高台へ移す"],["2000年","高さ約34mの大鳥居が完成"],["2004年","世界遺産に登録"]],"who":[["一遍","時宗の開祖。本宮で神託を受けたと伝わる"],["後白河上皇","中洲にあった本宮へ何度も参詣した"],["十津川の人々","同じ大水害で被災し、北海道に新十津川村をつくった"]],"deep":["大鳥居は高さ33.9m、幅42mで、鉄筋コンクリートなどでつくられ、2000年に完成しました。«日本一の大鳥居» として知られます。","水害の原因として、明治に入って山林の伐採が進んでいたことを指摘する説もあります。自然災害と人の営みの関係を考える材料になっています。","旧社地のうち、上四社は現在の本宮へ移され、中四社・下四社と境内の末社などは石の祠にまつられました。社殿がないのに «聖地» として守られているのが大斎原の特徴です。","一遍が熊野で受けた神託は、絵巻 «一遍聖絵»（国宝）に描かれています。熊野本宮の神が山伏の姿で現れる場面は有名です。","大斎原では例大祭（4月）の «湯登神事» や «渡御祭» など、今も旧社地をめぐる神事が続いています。","周辺には «熊野本宮» と地名が同じ集落が広がり、湯の峰温泉・川湯温泉など熊野詣の人が体を清めた湯も近くにあります。"],"look":["高さ約34mの大鳥居","田んぼの中の参道（春は菜の花、夏は緑の稲）","森の中の石の祠（中は撮影を控えるよう案内あり）","一遍上人の神勅名号碑（本宮大社周辺）","熊野川の流れと中洲の地形"],"q":["明治の大洪水まで熊野本宮大社があった中洲を何という？","«大斎原（おおゆのはら）»。1889年の水害で社殿の多くが流され、神社は高台へ移りました。"],"koji":[{"w":"信不信をえらばず","m":"一遍が熊野の神から受けたとされる教え。信じる人も信じない人も分けへだてなく救う、という意味"}],"myth":"«約2千年本宮があった» は由緒による言い伝え。水害の原因は諸説。","img":["一遍","時宗"],"wp":"熊野本宮大社","rel":{"ev":[],"grave":[]},"ph":[["c:b/b3/Inside_the_Kumano_Hongu_Taisha.jpg",2272,1704,"熊野本宮大社"],["c:6/66/Kumano_Kodo_Kumano_Hongu_Taisha_World_heritage_%E7%86%8A%E9%87%8E%E6%9C%AC%E5%AE%AE%E5%A4%A7%E7%A4%BE18.JPG",4608,3456],["c:8/8d/Kumano_Kodo_Kumano_Hongu_Taisha_World_heritage_%E7%86%8A%E9%87%8E%E6%9C%AC%E5%AE%AE%E5%A4%A7%E7%A4%BE102.JPG",3456,4608],["c:0/05/Kumano_Kodo_Kumano_Hongu_Taisha_World_heritage_%E7%86%8A%E9%87%8E%E6%9C%AC%E5%AE%AE%E5%A4%A7%E7%A4%BE07.JPG",4608,3456],["c:d/d9/Kumano_Kodo_Dainichigoe_World_heritage01.JPG",4608,3456],["c:2/22/Kumano-hong%C3%BB-taisha_Shrine_-_Stone_monument_of_a_crow_%22Yatagarasu%22.jpg",3096,4128],["c:6/6d/Daimonzaka8618.JPG",1200,1600],["c:d/d0/%E4%B8%80%E9%81%8D%E4%B8%8A%E4%BA%BA%E5%83%8F.jpg",3008,4512,"一遍"]]},{"id":"30_nachi_taisha","n":"熊野那智大社","yomi":"くまのなちたいしゃ","cat":"寺社","y":1590,"era":["heian","azuchi","edo"],"sh":"国の重要文化財（社殿）・国指定史跡（熊野三山）・世界遺産","rank":"S","ad":"東牟婁郡那智勝浦町那智山","st":"JR紀伊勝浦駅から熊野交通バス «那智山» 行き約30分、終点から石段を上って約15分","la":33.6689,"lo":135.8906,"hook":"那智の大滝を神と仰いだ人々が、山の中腹に築いた朱塗りの社。夏の火祭りでは、12本の大松明が石段を燃え下る。","lead":"熊野那智大社は、熊野三山のひとつで、熊野夫須美大神（くまのふすみのおおかみ）を主な神としてまつります。もともとは那智の滝そのものを拝む信仰から始まったと考えられています。隣には青岸渡寺があり、神社とお寺が並ぶ «神仏習合» の姿を今に伝えています。","story":["那智山の石段を息を切らして上ると、朱色の社殿が目に飛び込んできます。ふり返れば、遠くに熊野の海。そして木々のあいだから白い一本の線――那智の大滝が見えます。ここに神社がある理由は、この滝にありました。","古い言い伝えでは、神武天皇が熊野に上陸したとき、那智の山に光り輝く滝を見つけ、これを神としてまつったといいます。やがて滝の近くから山の中腹へと社殿が移され、熊野の神々をまとめてまつる大きな神社になりました。仁徳天皇の時代に社殿が建てられたという由緒も伝わります。","平安時代、那智は «観音さまの浄土への入口» と信じられ、上皇や貴族が本宮・新宮とあわせて参詣しました。滝では多くの修行者が荒行にはげみ、那智は山伏たちの修行の場としても知られるようになります。","戦国時代の終わりには、地元の武士どうしの争いに巻き込まれ、社殿が焼けてしまったと伝わります。天下を取った豊臣秀吉がその再建を助け、江戸時代には紀州徳川家が社殿を整えました。今の社殿は江戸時代末、1853年に建てられたものです。","毎年7月14日、«那智の扇祭り» が行われます。滝の姿をかたどった12体の扇神輿が滝へ向かい、それを迎える12本の大松明が炎をあげて石段を上り下りします。«なぜ火で迎えるの?» 神様が年に一度、滝のもとへ里帰りする道を清め、照らすためだといわれます。"],"tl":[["伝承 仁徳天皇の時代","社殿が建てられたと伝わる"],["平安時代","熊野三山として上皇・貴族の参詣がさかんに"],["1581年ごろ","戦乱で社殿が焼けたと伝わる"],["1590年","豊臣秀吉の支援で再建が進む"],["1853年","現在の社殿が建てられる"],["1868年以降","神仏分離で青岸渡寺と分かれる"],["2004年","世界遺産に登録"]],"who":[["熊野夫須美大神","主祭神。本地は千手観音とされた"],["神武天皇","神話で那智の滝を見つけまつったと伝わる"],["豊臣秀吉","戦国時代に焼けた社殿の再建を支援した"],["花山法皇","那智で修行したと伝わり、西国三十三所巡礼の中興とされる"]],"deep":["社殿は第一殿から第五殿と八社殿の計6棟が並ぶ独特の配置で、いずれも国の重要文化財。熊野造りと呼ばれる形式です。","«熊野夫須美» の «ふすみ» は «むすび» に通じ、ものを生み出す力を表すという解釈があります。","境内の大クスは平重盛が植えたと伝わり、樹齢約850年とされます。幹の空洞をくぐる «胎内くぐり» ができます。","«那智の扇祭り（那智の火祭り）» は国の重要無形民俗文化財。大松明は1本50kgほどといわれ、白装束の氏子がかついで石段を進みます。","境内の «烏石» は、神武天皇を導いた八咫烏が姿を石に変えて休んでいるものと伝わります。","明治の神仏分離で、多くの仏堂がこわされましたが、如意輪堂だけは残され、青岸渡寺として独立しました。お寺と神社が隣り合う今の景色はそのなごりです。"],"look":["朱塗りの社殿（重要文化財）","平重盛の手植えと伝わる大クスと胎内くぐり","八咫烏が化したという «烏石»","社殿前からの那智の大滝の遠望","7月14日の扇祭り（混雑するので事前に確認）"],"q":["那智の扇祭りで石段を進む大松明は何本？","12本。滝をかたどった12体の扇神輿を炎で迎え清めます。"],"koji":[],"myth":"神武天皇が滝を見つけた話、社殿の創建年代、大クスの手植えは伝承。焼失の年や事情は諸説。","img":["熊野三山","那智の扇祭り","青岸渡寺"],"wp":"熊野那智大社","rel":{"ev":[],"grave":[]},"ph":[["c:9/9c/Shrine_Kumano_nachi01.jpg",600,450,"熊野那智大社"],["c:d/d4/Kumano_Nachi_Taisha_201908-2.jpg",3609,2706],["c:c/c0/Kumano-Nachi-shrine004.JPG",3264,2448],["c:7/7f/Kumanonachitaisha3s2048.jpg",2040,1360],["c:d/d0/Kumanonachitaisha1s2048.jpg",1980,1320],["c:6/6d/Daimonzaka8618.JPG",1200,1600],["c:b/b5/GOOUNACHI.JPG",1536,1024],["c:b/bb/Seigantoji01.JPG",3264,2448,"青岸渡寺"]]},{"id":"30_nachi_taki","n":"那智滝（飛瀧神社）","yomi":"なちのたき（ひろうじんじゃ）","cat":"寺社","y":1100,"era":["heian","kamakura"],"sh":"国指定名勝・世界遺産","rank":"S","ad":"東牟婁郡那智勝浦町那智山","st":"JR紀伊勝浦駅から熊野交通バス約25分 «那智の滝前» 下車、石段を下りて約5分","la":33.675,"lo":135.8886,"hook":"一段の滝として日本一の落差133m。本殿のない神社が、滝そのものを神として拝んできた。","lead":"那智の滝は、原生林の中を133mの高さから一気に落ちる大きな滝です。華厳の滝（栃木）・袋田の滝（茨城）とともに «日本三名瀑» に数えられます。飛瀧神社には本殿がなく、滝そのものが御神体です。","story":["大鳥居をくぐり、杉木立の石段を下りていくと、ごうごうという音がだんだん大きくなってきます。そして目の前に現れる、白い水のすだれ。落差133m、一段で落ちる滝としては日本一の高さです。昔の人がこれを «神» だと感じたのも、自然なことでしょう。","飛瀧（ひろう）神社には、ふつうの神社にある本殿がありません。«なぜ?» 拝む対象が、目の前の滝そのものだからです。大昔の信仰の形――山や岩、滝を神として拝む姿が、ここにはそのまま残っています。","平安時代になると、那智は修行者たちの聖地になりました。出家した花山法皇が、この滝のそばで千日間こもって修行したと伝わります。また、平安時代末の僧・文覚は、真冬の滝に打たれる荒行で気を失い、不動明王の使いの童子に助けられた――という話が «平家物語» などに語られています。","鎌倉時代には、この滝を描いた «那智滝図» が生まれました。まっすぐ落ちる白い滝と、その上に顔を出す月。絵そのものが拝む対象になったと考えられ、今では国宝になっています。滝は、人々にとって見る景色であると同時に、祈る相手でもあったのです。","2011年9月、台風12号による紀伊半島大水害では、那智川の流域で大きな被害が出て、多くの方が亡くなりました。滝つぼも土砂で埋まり、周辺の姿が変わりました。それでも滝は流れ続け、人々は復旧に力をつくしました。今日も、滝の前で静かに手を合わせる人の姿が絶えません。"],"tl":[["伝承 神武東征","神武天皇が那智の山に輝く滝を見つけたと伝わる"],["10世紀末","花山法皇が那智で修行したと伝わる"],["平安時代末","文覚が滝で荒行をしたと伝わる"],["鎌倉時代","«那智滝図»（国宝）が描かれる"],["2004年","世界遺産に登録"],["2011年","紀伊半島大水害で那智川流域に大きな被害"]],"who":[["花山法皇","出家後、那智で千日の修行をしたと伝わる"],["文覚","滝に打たれる荒行の伝説で知られる僧。のちに源頼朝に挙兵をすすめたとされる"],["神武天皇","神話で滝を見つけまつったとされる"]],"deep":["落差133m、滝口の幅は約13m。«那智の滝» は本来、那智山中にある多くの滝の総称で、この大滝は «一の滝» にあたります。","那智大滝は国の名勝、周囲の «那智原始林» は国の天然記念物。滝の周りの森も一体として守られています。","«那智滝図»（根津美術館蔵・国宝）は、滝を神の姿として描いた «垂迹画» の代表例とされます。","滝の上の岩にかかるしめ縄は、年2回（7月と12月）に張り替えられる «御滝注連縄張替» の神事で新しくなります。","お滝拝所の舞台（有料）では滝に近づけ、«延命長寿の水» として滝の水を飲めるようになっています。","文覚の荒行の話は «平家物語» や «源平盛衰記» に見えますが、文学作品の描写で、史実かどうかは確かめられません。"],"look":["大鳥居からの滝の全景","お滝拝所舞台（滝のすぐ近くまで行ける）","滝口の岩にかかるしめ縄","延命長寿の水","那智大社・青岸渡寺の三重塔と滝を同時に望む景色"],"q":["那智の滝の落差は何m？","133m。一段で落ちる滝として日本一の落差です。"],"koji":[],"myth":"花山法皇の千日籠もり、文覚の荒行、神武天皇の発見は伝承・文学由来。","img":["熊野那智大社","文覚","紀伊山地の霊場と参詣道"],"wp":"那智滝","rel":{"ev":[],"grave":[]},"ph":[["c:d/db/Nachi_Falls_2025-10-13.jpg",4000,6000,"那智滝"],["c:d/d8/Three-storied_Pagoda_of_Seiganto-ji_and_Nachi_Falls.jpg",6000,4000],["c:2/24/Nachi_Waterfall_in_Winter_03.jpg",4000,3000],["c:9/93/Nachi_Falls002.JPG",2448,3264],["c:6/6d/Daimonzaka8618.JPG",1200,1600],["c:a/ab/Nachi_Falls.jpg",593,1651],["c:9/9c/Shrine_Kumano_nachi01.jpg",600,450,"熊野那智大社"],["c:f/f1/Mongaku.jpg",866,960,"文覚"]]},{"id":"30_hayatama","n":"熊野速玉大社","yomi":"くまのはやたまたいしゃ","cat":"寺社","y":1100,"era":["heian","meiji","showa"],"sh":"国宝（古神宝類）・国指定史跡（熊野三山）・世界遺産","rank":"S","ad":"新宮市新宮","st":"JR新宮駅から歩いて約15分、またはバス «権現前» 下車すぐ","la":33.7303,"lo":135.9843,"hook":"熊野川の河口に立つ «新しい宮»。境内には平重盛が植えたと伝わる樹齢千年のナギの木が枝を広げ、千点をこえる国宝が眠る。","lead":"熊野速玉大社は熊野三山のひとつで、熊野速玉大神と熊野夫須美大神をまつります。近くの神倉山にまつられていた神を、ふもとに新しく建てた社に移したことから «新宮» と呼ばれるようになったと伝わります。平安時代から伝わる宝物は1,000点をこえ、まとめて国宝になっています。","story":["新宮の町なかを歩いていくと、朱色の鳥居が現れます。ここは熊野川が海へ注ぐ河口の町。山と川と海が出会うこの場所は、昔から熊野への玄関口でした。舟で熊野川を下ってきた参詣者たちは、ここで速玉の神に手を合わせたのです。","«なぜ «新宮» という名前なの?» 言い伝えでは、熊野の神々はまず、町の背後にある神倉山の大岩（ゴトビキ岩）に降りてきたといいます。のちに神々をふもとの新しい社に移したので、神倉山を «元宮»、こちらを «新宮» と呼ぶようになった、というのです。","境内で目を引くのが、大きなナギの木です。平安時代末、平清盛の長男・重盛が熊野を詣でたときに植えたと伝わり、樹齢は約千年といわれます。ナギの葉は横に引っ張ってもなかなかちぎれないので、«縁が切れない» お守りとして旅人が大切に持ち帰りました。","明治16年（1883年）、社殿は火事で焼けてしまいます。けれど宝物殿におさめられていた古い宝物の多くは無事でした。鏡、衣装、手箱など、平安時代から室町時代の神々への捧げものが、今も «熊野速玉大社古神宝類» として国宝に指定されています。社殿は昭和42年（1967年）に再建されました。","毎年10月16日の例大祭 «御船祭» では、熊野川に早舟が浮かび、川の中の御船島のまわりを競いあうようにこぎます。神様を乗せた神幸船がそのあとに続く、川と海の町らしい祭りです。"],"tl":[["伝承","神倉山の神をふもとに移し «新宮» と呼ばれる"],["平安時代","熊野三山として上皇・貴族の参詣がさかんに"],["平安時代末","平重盛がナギの木を植えたと伝わる"],["1883年","火災で社殿を焼失"],["1967年","社殿を再建"],["2004年","世界遺産に登録"]],"who":[["熊野速玉大神","主祭神の一柱。本地は薬師如来とされた"],["平重盛","清盛の長男。境内のナギの木を植えたと伝わる"],["後白河上皇","熊野三山をたびたび参詣した"],["佐藤春夫","新宮出身の詩人・作家。境内に記念館がある"]],"deep":["国宝 «熊野速玉大社古神宝類» は約1,200点にのぼるといわれ、足利義満らが奉納したと伝わる装束や手箱などが含まれます。熊野神宝館で一部を見られます。","ナギの木は国の天然記念物。一本の木としては日本最大級のナギといわれます。","熊野三山のうち、速玉大社の本地は薬師如来。«過去を救う本宮、現在を救う新宮、未来を救う那智» のように語られることもあります。","御船祭では、何艘もの早舟が河口近くの御船島のまわりを回る速さを競います。神様の乗る神幸船が、そのあとを静かに進みます。","境内の佐藤春夫記念館は、東京・文京区にあった春夫の家を移築したもの。«望郷の詩人» と故郷の神社が結ばれています。","神倉神社は速玉大社の摂社で、2月のお燈祭りも速玉大社の祭りの一部です。元宮と新宮はセットでめぐるのがおすすめです。"],"look":["樹齢約千年と伝わるナギの大木","熊野神宝館（国宝の古神宝）","朱塗りの社殿と鳥居","境内の佐藤春夫記念館","熊野川の河口と御船島（祭りの舞台）"],"q":["ナギの葉が «縁結び» や «旅のお守り» とされたのはなぜ？","葉の筋が縦に通っていて、横に引いてもちぎれにくいから。«縁が切れない» といわれました。"],"koji":[],"myth":"新宮の名の由来、重盛の手植え、古神宝の奉納者は伝承を含む。点数は概数。","img":["神倉神社","平重盛","佐藤春夫"],"wp":"熊野速玉大社","rel":{"ev":[],"grave":[]},"ph":[["c:f/fa/Kumanohayatama-taisha12s5s4200.jpg",4200,2800,"熊野速玉大社"],["c:4/48/Kumanohayatama-taisha08s4s4592.jpg",3056,4592],["c:a/a7/Kumanohayatama-taisha02s4s4592.jpg",4592,3056],["c:a/a4/Kumano-hayatama-taisha_Shrine_-_Torii_of_entrance.jpg",4128,3096],["c:5/53/Kumano-hayatama-taisha_Shrine_-_Shing%C3%BB-jinja_Shrine.jpg",3096,4128],["c:1/1d/Kumano-hayatama-taisha_Shrine_-_Setsumatsu-sha.jpg",4128,3096],["c:e/e5/Kumanohayatama-taisha10s4s4440.jpg",4410,2940],["c:1/10/Kumanohayatamataisha3s1920.jpg",4200,2800]]},{"id":"30_nakahechi","n":"熊野古道 中辺路","yomi":"くまのこどう なかへち","cat":"街道","y":1201,"era":["heian","kamakura","edo"],"sh":"国指定史跡（熊野参詣道）・世界遺産","rank":"S","ad":"田辺市中辺路町〜本宮町（滝尻王子から熊野本宮大社まで）","st":"起点の滝尻王子へはJR紀伊田辺駅からバス約40分 «滝尻» 下車。区間ごとにバスを組み合わせて歩ける","la":33.7836,"lo":135.5413,"hook":"上皇も庶民も、石と木の根をふみしめて歩いた «祈りの道»。道そのものが世界遺産になった、世界でもめずらしい例だ。","lead":"中辺路は、紀伊田辺から山を越えて熊野本宮大社へ向かう熊野古道のメインルートです。平安時代の上皇たちの熊野御幸もこの道を通りました。道ぞいには «王子» と呼ばれる小さな神社が点々とあり、旅人はそこで祈りながら進みました。","story":["田辺の町から山に入る入口が滝尻王子です。ここからが本当の «熊野の聖域» とされ、旅人は川で身を清め、気を引きしめて急な坂道にいどみました。本宮までは山道でおよそ40km。今のハイカーでも2〜3日かけて歩く道のりです。","1201年、後鳥羽上皇の熊野御幸にお供した歌人・藤原定家は、日記に旅のつらさを書き残しました。雨にぬれ、体調をくずし、«心身ともにへとへとだ» となげく定家。華やかな歌の名人が見せる弱音に、800年前の旅がぐっと身近に感じられます。","道のとちゅうには «九十九王子» と呼ばれる熊野の神の分身がまつられていました。実際には «たくさん» という意味で、数は時代によってちがいます。近露王子、継桜王子、発心門王子……。旅人は王子ごとに祈り、ときには歌を詠んだり舞を奉納したりしました。","伏拝王子には、平安時代の歌人・和泉式部の伝説が残ります。やっとここまで来たのに体の不調で参拝できないと悲しんだ式部が歌を詠むと、その夜、熊野の神が夢に現れ «気にせずお参りなさい» と返歌をくれた――。熊野の神は、だれでも受け入れるという信仰をよく表す話です。","江戸時代になると、伊勢参りと組み合わせて熊野を詣でる庶民が増えました。やがて鉄道や道路ができると古道は忘れられかけましたが、地元の人々が守り続け、2004年に世界遺産に。今は世界中から歩く人が訪れ、スペインの «サンティアゴ・デ・コンポステーラの巡礼路» とは姉妹道になっています。"],"tl":[["907年","宇多法皇が熊野へ参詣（記録に残る早い例）"],["1090年","白河上皇の熊野御幸"],["1201年","後鳥羽上皇の熊野御幸。藤原定家が同行し日記を残す"],["江戸時代","庶民の熊野詣がさかんになる"],["1998年","サンティアゴ巡礼路と姉妹道提携"],["2000年","国の史跡 «熊野参詣道» に指定"],["2004年","世界遺産に登録"]],"who":[["藤原定家","後鳥羽上皇の熊野御幸に同行し、旅の苦労を日記に書いた"],["後鳥羽上皇","熊野を28回訪れたと伝わる"],["和泉式部","伏拝王子に歌の伝説が残る"],["花山法皇","牛馬童子像は法皇の旅姿と伝わる"]],"deep":["定家の日記の熊野の部分は «後鳥羽院熊野御幸記»（国宝）として知られます。定家自身の筆による記録で、当時の宿泊地や王子での儀式がわかる一級史料です。","«王子» は熊野の神の御子神とされ、平安時代末から鎌倉時代にかけて整えられました。大阪の窪津（八軒家）から熊野まで続いていたといいます。","箸折峠の «牛馬童子像» は、花山法皇の旅姿を表したものと伝わる小さな石像。明治時代の作とされます。","継桜王子の «野中の一方杉» は、枝が南の那智の方向にだけのびる巨杉群。明治の神社合祀のとき、南方熊楠らが伐採に反対したことでも知られます。","発心門王子は本宮の «入口» とされ、ここから先は熊野本宮の神域と考えられました。本宮まで約7km、初心者向けの人気区間です。","道として世界遺産に登録された例は、世界でもサンティアゴ巡礼路（スペイン）など少数です。«道» が文化財になるという考え方を示した例でもあります。"],"look":["滝尻王子と胎内くぐり（岩の間をくぐる伝承の場）","牛馬童子像（箸折峠）","継桜王子と «野中の一方杉»","発心門王子から本宮への道","伏拝王子からの大斎原の遠望"],"q":["藤原定家が熊野の旅のつらさを書いた日記は、だれの熊野御幸に同行したもの？","後鳥羽上皇。1201年の御幸で、その記録は «後鳥羽院熊野御幸記» と呼ばれます。"],"koji":[{"w":"九十九王子","m":"熊野への道にまつられた多くの王子社のこと。«九十九» は実際の数ではなく «とても多い» という意味"}],"myth":"和泉式部の伝説、牛馬童子が花山法皇の姿だという話は伝承。王子の数は時代で異なる。","img":["九十九王子","藤原定家","南方熊楠"],"wp":"熊野古道","rel":{"ev":[],"grave":[]},"ph":[["c:6/6a/Daimonzaka28-640.jpg",1536,2048],["c:b/b7/Kumano-Kaido_Monument_at_Intersection_of_Tosabori-dori_and_Oharai-suji.jpg",1200,1600],["c:6/6d/Daimonzaka8618.JPG",1200,1600],["c:0/04/Kumano_Kodo_Gyuba-doji.jpg",640,480],["c:f/fc/Daimonzaka17_1024.jpg",768,1024,"九十九王子"],["c:2/2d/Teika%283%29.jpg",832,848,"藤原定家"],["c:b/b5/Minakata-Kumagusu.jpg",900,1300,"南方熊楠"]]},{"id":"30_wakayama_jo","n":"和歌山城（紀州徳川家の居城）","yomi":"わかやまじょう","cat":"城","y":1585,"era":["azuchi","edo","showa"],"sh":"国指定史跡・国の重要文化財（岡口門）","rank":"S","ad":"和歌山市一番丁","st":"南海和歌山市駅から歩いて約10分。JR和歌山駅からバス «公園前» 下車すぐ（約10分）","la":34.2275,"lo":135.1717,"hook":"豊臣秀長が築き、徳川御三家・紀州藩の城となった虎伏山の城。八代将軍・吉宗もここから江戸へ旅立った。","lead":"和歌山城は、1585年に豊臣秀吉が紀州を平定したあと、弟の秀長に命じて築かせた城です。江戸時代には徳川家康の十男・頼宣が入り、紀州徳川家の居城になりました。天守は戦争の空襲で焼けてしまい、今のものは1958年の再建です。","story":["1585年、紀州の寺院勢力や地元の武士たちを攻め従えた豊臣秀吉は、海と川に面したこの小高い山に目をつけました。«ここに城を築け»。命じられたのは弟の秀長。実際の工事には、のちに «築城の名人» とたたえられる藤堂高虎が関わったとされます。","城の建つ山は、虎がうずくまったような形から «虎伏山» と呼ばれ、城も «虎伏城» の別名を持ちます。石垣をよく見ると、青っぽい石、白っぽい石、きっちり四角に加工した石など、時代ごとに積み方がちがいます。«なぜバラバラなの?» 城の持ち主がかわるたびに、増築や改修がくり返されたからです。","1619年、徳川家康の十男・頼宣が入城し、紀州藩55万5千石の城下町が整えられました。紀州徳川家は尾張・水戸とならぶ «御三家»。その五代藩主・吉宗は、のちに八代将軍となり «享保の改革» を進めます。紀州の殿様が、日本の政治の中心に立ったのです。","江戸時代の終わりの1846年、天守は落雷で焼けてしまいました。ところが幕府は、御三家の城ということで特別に再建を認め、1850年に天守がよみがえります。しかしその天守も、1945年7月9日の和歌山大空襲で、城下の町や多くの人の命とともに失われました。","焼け跡から13年後の1958年、市民の願いによって天守は鉄筋コンクリートで再建されました。一方、城の東側の岡口門は江戸時代の建物が残り、国の重要文化財になっています。天守から見わたす紀の川と和歌浦の海は、秀吉がこの地を選んだ理由を、今もはっきり教えてくれます。"],"tl":[["1585年","豊臣秀吉が紀州を平定。秀長が築城を始める"],["1600年","関ヶ原の戦いのあと、浅野幸長が入城"],["1619年","徳川頼宣が入城し、紀州藩が成立"],["1705年","徳川吉宗が紀州藩主となる"],["1716年","吉宗が八代将軍に"],["1846年","落雷で天守が焼失"],["1850年","天守が再建される"],["1945年7月9日","和歌山大空襲で天守などが焼失"],["1958年","天守を鉄筋コンクリートで再建"]],"who":[["豊臣秀長","秀吉の弟。城を築かせた最初の城主"],["藤堂高虎","築城に関わったとされる。のちの築城の名人"],["浅野幸長","関ヶ原のあとの城主。城を大きく改修した"],["徳川頼宣","家康の十男。紀州徳川家の初代"],["徳川吉宗","紀州藩主から八代将軍となった"]],"deep":["石垣は大きく三種類。初期の «紀州青石»（緑色片岩）の野面積み、浅野時代の和泉砂岩を使った打込接、徳川時代の切込接で、時代の変化を一か所で見比べられます。","天守は大天守と小天守を渡櫓などでつないだ «連立式»。姫路城・松山城とならぶ代表例とされます。","«御橋廊下» は藩主が二の丸と西の丸を行き来した屋根付きの廊下橋で、斜めに傾いた珍しいつくり。2006年に復元されました。","西の丸の «紅葉渓庭園» は、頼宣が造ったと伝わる池泉回遊式庭園で、国の名勝です。","1850年の天守再建は、幕末に天守が再建された数少ない例です。戦前は国宝（旧国宝）に指定されていましたが、空襲で失われました。","初めのころの城代は秀長の家臣・桑山重晴。秀長自身は大和郡山城にいて、和歌山城には城代を置いていました。"],"look":["時代ごとに異なる三種類の石垣","岡口門（重要文化財・江戸時代の建物）","斜めの廊下橋 «御橋廊下»","紅葉渓庭園（名勝）","天守からの紀の川と和歌浦の眺め"],"q":["紀州藩主から八代将軍になり、享保の改革を行ったのはだれ？","徳川吉宗。紀州藩五代藩主から、1716年に将軍になりました。"],"koji":[],"myth":"藤堂高虎の関与の程度には諸説。","img":["徳川吉宗","徳川頼宣","豊臣秀長","紀州藩"],"wp":"和歌山城","rel":{"ev":[],"grave":[]},"ph":[["c:5/51/%E5%92%8C%E6%AD%8C%E5%B1%B1%E5%9F%8E_%E5%A4%A9%E5%AE%88%E9%96%A3%EF%BC%882024%E5%B9%B4%EF%BC%89.jpg",3024,4032,"和歌山城"],["c:1/1c/Wakayama_Castle_viewed_from_Wakayama_city_office.jpg",5990,3657],["c:9/92/Wakayama_Castle_Nishinomaru_Garden10s4592.jpg",4592,3056],["c:7/7c/Wakayama_Castle32n4592.jpg",4592,3056],["c:9/9c/Wakayama_Castle28n4592.jpg",4592,3056],["c:0/06/Wakayama_Castle24n4592.jpg",4592,3056],["c:9/9e/Wakayama_Castle16n4592.jpg",4592,3056],["c:2/20/Wakayama_Castle%2C_tenshu-3.jpg",6016,4000]]},{"id":"30_negoroji","n":"根来寺（大塔と根来衆）","yomi":"ねごろじ","cat":"寺社","y":1585,"era":["heian","muromachi","azuchi"],"sh":"国宝（大塔）・国指定史跡（根来寺境内）・名勝（根来寺庭園）","rank":"S","ad":"岩出市根来","st":"JR阪和線 紀伊駅または岩出駅からバス約10〜15分 «根来寺» 下車。車なら京奈和道 岩出根来ICから約5分","la":34.2872,"lo":135.3189,"hook":"戦国時代、鉄砲を手にした僧兵集団 «根来衆» の本拠地。秀吉の焼き討ちを生きのびた大塔には、今も弾丸の跡と伝わる穴が残る。","lead":"根来寺は、平安時代の僧・覚鑁（かくばん）が開いた新義真言宗の総本山です。戦国時代には多くの僧坊が立ち並び、鉄砲を使いこなす «根来衆» が大名とわたりあうほどの力を持ちました。1585年、豊臣秀吉に攻められて多くの建物が焼けましたが、日本最大級の木造多宝塔 «大塔» は残り、国宝になっています。","story":["平安時代の終わり、高野山に覚鑁という才能あふれる僧がいました。鳥羽上皇の信頼を得て、高野山の中心に立とうとした覚鑁でしたが、それに反発する僧たちとの争いが激しくなります。1140年、覚鑁は弟子たちとともに山を下り、根来の地に移りました。","覚鑁がこの世を去ってから約150年後、高野山にあった覚鑁ゆかりの «大伝法院» の拠点も根来へ移され、根来寺は «新義真言宗» の中心として大きく育っていきます。室町時代には学問の寺としても栄え、多くの学僧が集まりました。","戦国時代、根来寺はお寺でありながら強い軍事力を持っていました。種子島に鉄砲が伝わると、いち早くその技術を取り入れたと伝わります。鉄砲を自在に操る僧兵たち «根来衆» は、あちこちの大名に雇われて戦場で活躍しました。«なぜお寺が鉄砲を?» 広い寺領と寺の自治を、自分たちの力で守るためでした。","しかし天下統一をめざす豊臣秀吉にとって、根来衆は見過ごせない存在でした。1585年、秀吉は大軍で紀州へ攻めこみます。根来寺は火につつまれ、立ち並んでいた坊舎の大半が焼けてしまいました。このとき焼け残った建物のひとつが、大塔です。","江戸時代、紀州徳川家の保護を受けて根来寺は少しずつ立ち直りました。いま境内を歩くと、戦いの激しさがうそのような静けさです。けれど大塔の柱や壁に残る小さな穴は、秀吉軍の鉄砲の弾の跡だと伝わっています。朱塗りの大塔を見上げると、鉄砲の時代の音が聞こえてくるようです。"],"tl":[["1132年","覚鑁が高野山に大伝法院を建てる"],["1140年","覚鑁が高野山を下り根来へ移る"],["1143年","覚鑁が亡くなる"],["1288年","頼瑜が大伝法院を根来へ移す"],["1547年ごろ","大塔が完成したとされる"],["16世紀中ごろ","根来衆が鉄砲を取り入れる"],["1585年","豊臣秀吉の紀州攻めで大半が焼失"],["江戸時代","紀州徳川家の保護で再興"]],"who":[["覚鑁（興教大師）","根来寺を開いた新義真言宗の祖"],["頼瑜","大伝法院を根来へ移し、新義真言宗の教えを整えた学僧"],["津田監物","根来で鉄砲をつくり広めたと伝わる人物"],["豊臣秀吉","1585年に根来寺を攻めた"]],"deep":["大塔は高さ約40mで、木造の多宝塔としては日本最大とされます。室町時代の天文年間（16世紀中ごろ）に完成したとされ、国宝です。","最盛期の根来寺は «坊舎は2,700余り»«寺領は70万石余り» などといわれますが、これらは後世の記録による数字で、誇張をふくむ可能性があります。","根来衆の鉄砲は、種子島から津田監物が技術を持ち帰ったという伝承が «鉄炮記» などで知られます。泉州の堺とも近く、鉄砲生産の一大拠点でした。","漆器の «根来塗» は、根来寺の僧たちが使った朱塗りの器が名前の由来とされます。使いこむうちに朱の下から黒がのぞく風合いが愛されています。","大師堂（重要文化財）も秀吉の焼き討ちを免れた建物です。大塔と並んで、戦国時代以前の姿を伝えます。","紀州攻めのあと、根来の僧のなかには各地へ逃れた者もいて、江戸の «根来組»（鉄砲百人組の一つ）に根来衆の子孫が加わったとされます。"],"look":["国宝の大塔（柱に残る弾痕と伝わる穴）","大師堂（重要文化財）","名勝の根来寺庭園（聖天池と石組み）","覚鑁をまつる奥の院","根来塗の器（寺の展示や周辺の工房）"],"q":["根来寺の僧兵集団が戦国時代に得意とした武器は？","鉄砲。«根来衆» は鉄砲隊として各地の戦に加わりました。"],"koji":[],"myth":"弾痕、津田監物の鉄砲伝来、最盛期の坊舎数・石高は伝承や後世の記録による。","img":["覚鑁","根来衆","紀州征伐"],"wp":"根来寺","rel":{"ev":[],"grave":[]},"ph":[["c:2/24/Negoroji_spring.JPG",1500,997,"根来寺"],["c:7/77/Dai-dempo-do_Negoro-ji.JPG",4608,3456],["c:e/ea/Negoroji_Kogyodaishi_Mausoleum.jpg",4288,2848],["c:c/cc/Negoroji25s3872.jpg",3872,2592],["c:a/af/Negoroji14s3872.jpg",2592,3872],["c:0/0e/Negoroji02s3872.jpg",3872,2592],["c:d/d7/Negoroji05s3200.jpg",3600,2400],["c:e/e9/Negoroji04s3200.jpg",3510,2340]]},{"id":"30_iwase_senzuka","n":"岩橋千塚古墳群（紀伊風土記の丘）","yomi":"いわせせんづかこふんぐん","cat":"遺跡","y":550,"era":["kofun"],"sh":"国指定特別史跡","rank":"S","ad":"和歌山市岩橋（紀伊風土記の丘）","st":"JR和歌山駅からバス約20分 «紀伊風土記の丘» 下車すぐ","la":34.2155,"lo":135.2275,"hook":"山の尾根いっぱいに、およそ850の古墳がひしめく。石の板を積み、天井に «はり» を渡した不思議な石室は、紀伊の王たちの独自の工夫だ。","lead":"岩橋千塚古墳群は、和歌山市東部の山の上に広がる、日本でも有数の大きな古墳群です。4世紀末から7世紀にかけて、およそ850もの古墳がつくられました。紀伊の有力な豪族・紀氏にかかわる人々の墓と考えられ、国の特別史跡になっています。","story":["«千塚» とは、«たくさんの塚（古墳）» という意味です。紀の川の南の岩橋山のまわりを歩くと、あちこちに土のこんもりした盛り上がりが見つかります。その数、およそ850基。一つの古墳群としては全国でも最大級です。","だれのお墓なのでしょう? 手がかりは、この地域の歴史にあります。古代の紀伊には、海を渡って朝鮮半島とも行き来した豪族 «紀氏» がいました。紀氏は紀伊国造（くにのみやつこ）として、日前神宮・國懸神宮にも仕えた一族です。岩橋千塚は、その紀氏と、彼らに仕えた人々の墓域だったと考えられています。","古墳の中に入ると、ほかの地域ではあまり見ない石室に出会います。緑色っぽい薄い石の板を積み上げた壁、そして天井近くに横に渡された石の «はり»。これは «岩橋型石室» と呼ばれ、石の天井を支える工夫だとも、特別な意味をもつ飾りだともいわれます。«なぜこんな形に?» まだ答えは出ていません。","古墳群で最大の前方後円墳・大日山35号墳（全長86m）からは、つばさを広げた鳥の形の埴輪や、前と後ろに顔がある人物の埴輪など、ほかでは見られない珍しい埴輪が見つかりました。紀伊の人々のゆたかな想像力が伝わってきます。","1971年、この古墳群の一部を整備して «紀伊風土記の丘» がつくられました。資料館で出土品を見たあと、山道を歩いて実際に古墳の石室をのぞいてみましょう。暗い石室の中で懐中電灯を照らすと、1500年前の石工たちの手あとが、すぐそこにあります。"],"tl":[["4世紀末","古墳づくりが始まる"],["5〜6世紀","古墳づくりの最盛期。前方後円墳や岩橋型石室がつくられる"],["7世紀","古墳づくりが終わる"],["1952年","国の特別史跡に指定"],["1971年","«紀伊風土記の丘» が開園"],["2000年代以降","大日山35号墳などの発掘・整備が進む"]],"who":[["紀氏","紀伊の有力豪族。古墳群をつくった中心と考えられる"],["紀伊国造","紀氏が代々務めた地方の長。日前神宮・國懸神宮に仕えた"]],"deep":["古墳の数は «約850基» が一般的な説明ですが、調査のたびに数え直されています。前方後円墳から小さな円墳まで、大きさも形もさまざまです。","«岩橋型石室» は、紀伊の «緑泥片岩（青石）» を板状に割って積み、天井近くに «石梁（いしばり）» や «石棚» を設ける独特の横穴式石室です。","天王塚古墳は石室の高さが約6mにもなり、全国でも屈指の高い石室とされます（ふだんは非公開）。","大日山35号墳（全長86m）は、和歌山県内で最大級の前方後円墳です。«翼を広げた鳥形埴輪» «両面人物埴輪» の出土で知られます。","特別史跡は史跡の中でも特に重要なもの。和歌山県内の特別史跡は、この岩橋千塚古墳群だけです。","紀氏は、ヤマト王権のもとで朝鮮半島への軍事や外交に関わった豪族として «日本書紀» に名前が見えます。海の民としての性格が強かったと考えられます。"],"look":["紀伊風土記の丘資料館（埴輪などの出土品）","中に入れる石室（懐中電灯があると便利）","大日山35号墳の復元整備された墳丘","移築された古民家（園内）","尾根からの和歌山平野の眺め"],"q":["岩橋千塚古墳群に特有の石室を何という？","«岩橋型石室»。板状の石を積み、天井近くに石の «はり» を渡すのが特徴です。"],"koji":[],"myth":"被葬者を紀氏とするのは有力な説で、確定ではない。石梁の目的は諸説。","img":["紀氏","紀伊国造"],"wp":"岩橋千塚古墳群","rel":{"ev":[],"grave":[]},"ph":[["c:6/63/Iwase-senzuka-kofungun-1.JPG",6016,4000,"岩橋千塚古墳群"],["c:3/3e/%E5%B2%A9%E6%A9%8B%E5%8D%83%E5%A1%9A%E5%8F%A4%E5%A2%B3%E7%BE%A4%E5%89%8D%E5%B1%B1A56%E5%8F%B7%E5%A2%B3.JPG",3456,5184],["c:8/8f/%E5%B2%A9%E6%A9%8B%E5%8D%83%E5%A1%9A%E5%8F%A4%E5%A2%B3%E7%BE%A4%E5%89%8D%E5%B1%B1A46%E5%8F%B7%E5%A2%B3.JPG",3456,5184],["c:2/25/%E5%B2%A9%E6%A9%8B%E5%8D%83%E5%A1%9A%E5%8F%A4%E5%A2%B3%E7%BE%A4%E5%89%8D%E5%B1%B1A13%E5%8F%B7%E5%A2%B3.JPG",3456,5184],["c:6/62/%E5%B2%A9%E6%A9%8B%E5%8D%83%E5%A1%9A%E5%8F%A4%E5%A2%B3%E7%BE%A4%E5%89%8D%E5%B1%B1A111%E5%8F%B7%E5%A2%B3.JPG",5184,3456],["c:f/ff/%E5%B2%A9%E6%A9%8B%E5%8D%83%E5%A1%9A%E5%8F%A4%E5%A2%B3%E7%BE%A4%E5%89%8D%E5%B1%B1A100%E5%8F%B7%E5%A2%B3.JPG",5184,3456],["c:e/ea/Tennozuka_Kofun_%28Wakayama%29%2C_genshitsu-2.jpg",4000,6016],["c:0/06/Tennozuka_Kofun_%28Wakayama%29%2C_funkyu.jpg",6016,4000]]},{"id":"30_hiromura_teibo","n":"広村堤防（浜口梧陵と «稲むらの火»）","yomi":"ひろむらていぼう","cat":"事件","y":1854,"era":["edo","showa"],"sh":"国指定史跡","rank":"S","ad":"有田郡広川町広","st":"JR紀勢本線 湯浅駅から歩いて約15分","la":34.0295,"lo":135.1755,"hook":"津波の夜、刈り取った稲の束に火をつけて村人を高台へ導いた男がいた。彼は財産を投げうって堤防を築き、90年後、その堤防が町を守った。","lead":"広村堤防は、1854年の安政南海地震の津波のあと、村の実業家・浜口梧陵（儀兵衛）が私財を投じて築いた防潮堤です。梧陵は津波の夜、稲むらに火を放って村人を安全な場所へ導いたことで知られ、この話は «稲むらの火» として教科書にものりました。1946年の昭和南海地震では、堤防が津波から町の中心を守りました。","story":["1854年（嘉永7年／安政元年）11月5日の夕方、大きな地震が紀伊半島をおそいました。広村に帰っていた浜口梧陵は、海の水が異様に引いていくのを見て、«津波が来る» と直感します。すでに日は暮れかけ、村人たちは暗い中で逃げ道がわかりません。","梧陵は、田んぼに積んであった «稲むら»（刈り取った稲わらを積んだもの）に次々と火をつけさせました。燃え上がる炎は、高台にある広八幡神社への道しるべ。«こっちだ、上がれ!» 村人たちは炎を目印に坂をかけ上がり、多くの命が救われたのです。","それでも津波は村の家々を押し流し、犠牲になった人もいました。家や仕事を失った人々が村を捨ててしまえば、村はほろびてしまう――。そう考えた梧陵は、ある決断をします。«村人を雇って、大きな堤防をつくろう»。工事の賃金で暮らしを支え、同時に次の津波から村を守るという、一石二鳥の計画でした。","工事はおよそ4年。長さ約600m、高さ約5mの土の堤防が完成し、海側には松が、陸側にはハゼの木が植えられました。費用は銀94貫といわれ、すべて梧陵が出したと伝わります。梧陵は千葉県銚子の醤油醸造家・濱口家の当主で、今のヤマサ醤油の7代目にあたる人物でした。","1946年12月、昭和南海地震の津波が広村をおそいました。堤防は町の中心部を守り、「梧陵さんの堤防」は約90年ごしにその役目を果たしたのです。2015年、国連は安政南海地震の日にちなみ、11月5日を «世界津波の日» と定めました。毎年秋には、堤防に土を運ぶ «津浪祭» が今も続いています。"],"tl":[["1854年11月5日（旧暦）","安政南海地震。梧陵が稲むらに火を放ち村人を導く"],["1855年","梧陵が堤防の工事を始める"],["1858年","広村堤防が完成"],["1897年","小泉八雲（ラフカディオ・ハーン）が英語の作品 «A Living God» で梧陵をモデルに書く"],["1937年","中井常蔵の «稲むらの火» が国語教科書にのる"],["1938年","国の史跡に指定"],["1946年","昭和南海地震の津波から町を守る"],["2015年","国連が11月5日を «世界津波の日» に制定"]],"who":[["浜口梧陵（儀兵衛）","稲むらに火を放って村人を救い、私財で堤防を築いた。ヤマサ醤油7代目"],["小泉八雲","梧陵をモデルにした短編を英語で書き、世界に紹介した"],["中井常蔵","和歌山の小学校教師。八雲の作品をもとに «稲むらの火» を書いた"]],"deep":["«稲むら» は脱穀後の稲わらを積んだものとされます。八雲の作品では収穫前の稲の束に火をつける老人の話になっており、事実とは異なる脚色があります。","八雲の «A Living God» では、主人公は丘の上に住む老人・五兵衛で、津波を見て自分の稲に火をつけます。実際の梧陵は当時30代半ばで、地震のあと村を走り回っていました。","堤防は «石堤（古い堤防）» と «土の堤防» の二重構造で、海側に松、陸側にハゼの木を植えて潮風や波を防ぐ工夫がされていました。","梧陵はのちに和歌山県の初代県会議長をつとめ、また紀州藩の藩政改革にも関わりました。1885年、海外旅行中のニューヨークで亡くなっています。","堤防のそばには «稲むらの火の館»（濱口梧陵記念館・津波防災教育センター）があり、当時の様子を学べます。","毎年11月の «津浪祭» では、子どもたちも堤防に土を盛り、先人への感謝と防災の心を受け継いでいます。"],"look":["広村堤防と松並木","稲むらの火の館（記念館と防災教育センター）","高台の広八幡神社（梧陵が村人を導いた場所）","堤防の上から見る広湾","«感恩碑»（梧陵をたたえる碑）"],"q":["国連が定めた «世界津波の日» は何月何日？","11月5日。1854年の安政南海地震（旧暦）の日にちなんでいます。"],"koji":[{"w":"稲むらの火","m":"とっさの判断と自己犠牲で人々を救うこと。津波防災の教えとして語り継がれる"}],"myth":"«稲むらの火» の物語（八雲の作品など）は史実を脚色した創作をふくむ。工費の額は伝承。","img":["浜口梧陵","稲むらの火","安政南海地震","小泉八雲"],"wp":"広村堤防","rel":{"ev":[],"grave":[]},"ph":[["c:f/f3/Hiromura_Teibo_Seawall_Aerial_photograph.jpg",1105,782,"広村堤防"],["c:2/22/%E5%BA%83%E6%9D%91%E5%A0%A4%E9%98%B2_2024.jpg",4032,3024],["c:d/d9/Hiromura-teibou_and_sea.JPG",3264,2448],["c:f/f4/Hamaguchi_Goryo.jpg",730,1129],["c:0/06/1854_Ansei_Nankai_earthquake_intensity.PNG",512,512,"安政南海地震"],["c:0/07/Lafcadio_Hearn_portrait.jpg",712,1024,"小泉八雲"]]},{"id":"30_ertugrul","n":"エルトゥールル号遭難の地と慰霊碑（紀伊大島 樫野）","yomi":"えるとぅーるるごう そうなんのち","cat":"事件","y":1890,"era":["meiji","showa"],"sh":"","rank":"S","ad":"東牟婁郡串本町樫野（紀伊大島）","st":"JR串本駅から串本町コミュニティバス約40分 «樫野灯台口» 下車、歩いて約10分。車が便利","la":33.472,"lo":135.857,"hook":"嵐の夜、岩礁にくだけたトルコの軍艦。わずかな食料を分け合って生存者を救った島の人々の真心は、95年後、テヘランの空で返された。","lead":"1890年9月16日の夜、オスマン帝国（今のトルコ）の軍艦エルトゥールル号が、台風で紀伊大島の樫野崎沖の岩礁に乗り上げて沈みました。500人をこえる乗組員が亡くなるなか、大島の人々は69人の命を救いました。この出来事は、日本とトルコの友情の原点として今も語り継がれています。","story":["1890年、オスマン帝国の軍艦エルトゥールル号は、皇帝の親書を明治天皇に届ける使節団を乗せて、はるばる日本へやって来ました。東京で大歓迎を受けた一行は、9月に帰国の途につきます。ところが和歌山の沖で、激しい台風が船をおそいました。","9月16日の夜、船は大島の樫野崎の岩礁に打ちつけられ、爆発を起こして沈みました。嵐の海に投げ出された乗組員たち。けがをしながら崖をよじのぼった一人が、樫野埼灯台にたどり着きます。言葉は通じません。灯台守は万国信号書を見せ、トルコの船だとわかりました。","知らせを受けた大島の村人たちは、嵐の中を浜へ向かいました。冷えきった体を自分の肌で温め、けが人を背負って運びました。当時、島の暮らしは豊かではありません。それでも村人たちは、とっておきのサツマイモや、非常用に飼っていたニワトリまで差し出したと伝えられています。«自分たちが食べる分がなくなっても» ――そんな思いだったのでしょう。","助かったのは69人。亡くなった人は、使節団の長をふくめ500人をこえました。村人たちは海岸に流れついた遺体を引き上げ、ていねいに葬りました。生存者は日本の軍艦 «比叡» と «金剛» で、翌年はじめにイスタンブールへ送り届けられました。","それから95年後の1985年、イラン・イラク戦争のさなか、イランの首都テヘランに日本人が取り残されました。そのとき救援機を出してくれたのがトルコでした。«エルトゥールル号の恩を返すときだ» ――トルコの人々はそう語ったといわれます。樫野崎の慰霊碑の前では、今も5年ごとに日本とトルコがともに慰霊祭を行っています。"],"tl":[["1887年","小松宮彰仁親王がオスマン帝国を訪問（使節派遣のきっかけ）"],["1889年7月","エルトゥールル号がイスタンブールを出航"],["1890年6月","横浜に到着し、使節が明治天皇に親書を渡す"],["1890年9月16日","樫野崎沖で遭難。69人が救助される"],["1890年10月","生存者が «比叡» «金剛» で送還される（翌年1月着）"],["1891年","遭難現場近くに慰霊碑が建てられる"],["1985年","テヘラン在留邦人をトルコ機が救出"]],"who":[["オスマン・パシャ","使節団の代表（特使）。遭難で亡くなった"],["大島・樫野の人々","嵐の中、生存者の救助と遺体の埋葬にあたった"],["樫野埼灯台の灯台守","最初に生存者を保護し、船の国籍を確かめた"],["明治天皇","使節団を迎え、生存者の送還を命じた"]],"deep":["乗員は約650人、死者は580人以上とされ、生存者は69人。数字は資料によって少しちがいます。","船は1860年代に建造された木造のフリゲート艦で、長旅の間に傷みが進んでいたことも遭難の一因とされます。","遭難のことを知った新聞各社は義援金を呼びかけ、全国から寄付が集まりました。作家の山田寅次郎は義援金を持ってトルコへ渡り、その後長くトルコに住んで両国の交流に力をつくしました。","2007年からトルコと日本の合同チームが海底の調査を行い、船の部品や遺品が引き上げられました。一部は «トルコ記念館» で見られます。","樫野埼灯台は1870年に灯りがともった日本で最初の石造り灯台の一つで、イギリス人技師ブラントンが設計しました。","串本町はトルコのヤカケントなどと姉妹都市の関係を結び、学生の交流も続いています。"],"look":["エルトゥールル号殉難将士慰霊碑","トルコ記念館（引き上げられた遺品）","樫野埼灯台（見学できる石造り灯台）","遭難現場の «船甲羅» を望む崖","遭難者の墓地"],"q":["1985年、テヘランに取り残された日本人を救うため救援機を出した国は？","トルコ。エルトゥールル号の救助への恩返しとして語られています。"],"koji":[{"w":"情けは人の為ならず","m":"人に親切にすれば、めぐりめぐって自分によい報いが返ってくるということ"}],"myth":"ニワトリを差し出した話や、1985年の救援の動機については伝承・語りを含む。死者数は資料で差がある。","img":["樫野埼灯台","紀伊大島","山田寅次郎"],"wp":"エルトゥールル号遭難事件","rel":{"ev":[],"grave":[]},"ph":[["c:c/ca/%E3%82%A8%E3%83%AB%E3%83%88%E3%82%A5%E3%83%BC%E3%83%AB%E3%83%AB%E5%8F%B7%E6%AE%89%E9%9B%A3%E5%B0%86%E5%A3%AB%E6%85%B0%E9%9C%8A%E7%A2%91_%282022.1.2%29.jpg",4032,3024,"エルトゥールル号遭難事件"],["c:0/09/Kasinosaki-Lighthouse_Feb2010.jpg",4000,3000],["c:5/5e/C%C3%A9r%C3%A9monie_fun%C3%A9raire_Ertugrul.jpg",6266,4769],["c:8/82/Kongo%281878%29.jpg",3600,2778],["c:9/9e/Kii_oshima_turkey_ship_crash001.JPG",3072,2304],["c:1/17/Abdul_Hamid_II_in_Balmoral_Castle_in_1867.jpg",884,1187],["c:c/c9/McDonnell_Douglas_DC-10-10%2C_Turkish_Airlines_AN1108419.jpg",1024,701],["c:e/ee/%E6%A8%AB%E9%87%8E%E5%B4%8E%E7%81%AF%E5%8F%B0%282021%29.jpg",4032,3024,"樫野埼灯台"]]},{"id":"30_ota_jo","n":"太田城跡（秀吉の水攻め・紀州征伐）","yomi":"おおたじょうあと","cat":"古戦場","y":1585,"era":["azuchi"],"sh":"","rank":"S","ad":"和歌山市太田","st":"JR和歌山駅（東口）から歩いて約10分","la":34.233,"lo":135.1955,"hook":"秀吉は城を攻めるのではなく、城のまわりに長い堤を築いて «湖» に沈めた。高松城・忍城とならぶ «日本三大水攻め» の舞台。","lead":"太田城は、今のJR和歌山駅の東にあった戦国時代の城です。1585年、豊臣秀吉の紀州攻めのとき、城主の太田左近たちが立てこもり、秀吉は城のまわりに堤防を築いて水を流しこむ «水攻め» を行いました。城は約1か月で降伏し、現在は小さな石碑と、ゆかりの寺にその記憶が残っています。","story":["戦国時代の紀州は、大名がいない不思議な土地でした。根来寺や粉河寺などの寺院、雑賀衆などの地元の武士たちが力を持ち、自分たちのことは自分たちで決める «自治» を守っていたのです。太田城を拠点とした太田党も、そうした紀州の勢力の一つでした。","1585年3月、天下統一を進める豊臣秀吉は、10万ともいわれる大軍で紀州へ攻めこみます。根来寺は焼かれ、雑賀の勢力も次々に降伏しました。しかし太田城の太田左近たちは、城に立てこもって最後まで抵抗します。","秀吉が選んだのは、力攻めではなく «水攻め» でした。城のまわりをぐるりと囲む長い堤防を、たった数日で築きあげたといわれます。そこへ紀の川の水を引きこみ、城を水の中に孤立させる作戦です。«なぜ水攻め?» 兵の損害を少なくし、秀吉の力を見せつけるためだったとも考えられています。","城内では水と食料が少なくなっていきました。1か月ほどののち、城方は降伏します。太田左近ら中心となった人々は責任を取って命を落とし、そのほかの人々は助けられたと伝わります。城のあとは、しだいに田畑や町にのみこまれていきました。","いま太田城のあった場所の近くには、来迎寺の境内に «太田城跡» の碑が建ち、その近くには犠牲になった人々をとむらう «小山塚» も残ります。和歌山駅のすぐそばに、秀吉と紀州の人々の最後の戦いの記憶が眠っているのです。"],"tl":[["16世紀","太田党が太田城を拠点に力を持つ"],["1585年3月","秀吉の紀州攻め。根来寺などが焼かれる"],["1585年3月下旬","秀吉が太田城のまわりに堤防を築き水攻めを始める"],["1585年4月","太田城が降伏"],["1585年","和歌山城の築城が始まる"]],"who":[["太田左近（宗正）","太田城に立てこもった中心人物。降伏後に命を落としたと伝わる"],["豊臣秀吉","紀州攻めを行い、太田城を水攻めにした"],["豊臣秀長","紀州攻めに加わり、のちに和歌山城を築かせた"]],"deep":["«日本三大水攻め» とされるのは、備中高松城（1582年・秀吉）、紀州太田城（1585年・秀吉）、武蔵忍城（1590年・石田三成）。いずれも秀吉の政権が関わっています。","堤防の長さや高さは «約6km» などとされますが、史料や研究者によって数字がちがいます。短期間で築いたことはたしかとされます。","太田城の周辺には «出水» の地名や、堤の一部と考えられる高まりが残るとされ、水攻めの跡を探す手がかりになっています。","水攻めのあと、城方で首をはねられた人々の首を埋めたと伝わるのが «小山塚» です。大切な供養の場所なので静かに訪れましょう。","紀州攻めは、秀吉にとって四国攻めの直前の大きな戦いでした。紀州を押さえたことで、大坂の南の守りが固まりました。","水攻めのあと秀吉は、紀州を治める城として和歌山城の築城を秀長に命じました。太田城の落城は、和歌山城下町の始まりと表裏の出来事です。"],"look":["来迎寺境内の «太田城跡» の碑","犠牲者をとむらう «小山塚»","周辺の «出水» などの地名","JR和歌山駅から歩ける距離感（城の位置を想像しよう）"],"q":["秀吉が太田城を落とすために使った作戦は？","城のまわりに堤防を築いて水を流しこむ «水攻め» です。"],"koji":[],"myth":"堤防の規模、犠牲者の数、首塚の由来には諸説・伝承を含む。","img":["紀州征伐","水攻め","備中高松城"],"wp":"太田城 (紀伊国)","rel":{"ev":[],"grave":[]},"ph":[["c:8/80/Ota_Castle_%28Kii%29%2C_sekihi.jpg",6016,4000,"太田城 (紀伊国)"],["c:0/01/Raikoji_%28Wakayama%29%2C_sanmon.jpg",5858,3750],["c:7/72/Ota_Castle_%28Kii%29%2C_teibou.jpg",6016,4000],["c:c/cd/Ota_Castle_%28Kii%29%2C_Koyamazuka.jpg",6010,3990],["c:c/cb/Negoroji1.jpg",3550,4222],["c:3/38/Maru_ni_chigaitakanoha.png",4000,4000],["c:1/13/Dairyuji_%28Wakayama%29%2C_sanmon.jpg",6016,4000],["c:3/3c/Osaka_Castle_Keep_tower_of_%E3%80%8CA_figure_of_camp_screen_of_the_Osaka_summer%E3%80%8D.jpg",3101,2689]]},{"id":"30_seigantoji","n":"那智山 青岸渡寺（西国三十三所 第一番）","yomi":"なちさん せいがんとじ","cat":"寺社","y":1590,"era":["heian","azuchi","meiji"],"sh":"国の重要文化財（本堂）・世界遺産","rank":"A","ad":"東牟婁郡那智勝浦町那智山","st":"JR紀伊勝浦駅から熊野交通バス «那智山» 行き約30分、終点から石段を上って約15分（那智大社の隣）","la":33.6688,"lo":135.8898,"hook":"西国三十三所めぐりの «第一番»。朱色の三重塔と那智の大滝が一枚の絵におさまる景色は、日本を代表する名風景だ。","lead":"青岸渡寺は、那智大社のすぐ隣にある天台宗のお寺で、西国三十三所観音霊場の第一番札所です。もともとは那智大社と一体の «那智山» の一部でしたが、明治時代の神仏分離でお寺として独立しました。本堂は1590年に豊臣秀吉が再建したもので、国の重要文化財です。","story":["全長1,000kmをこえる観音霊場めぐり «西国三十三所»。その旅の始まりが、ここ青岸渡寺です。巡礼者たちは本堂の前で手を合わせ、はるか岐阜県の谷汲山華厳寺まで続く長い旅の無事を祈りました。","お寺の始まりには、こんな言い伝えがあります。昔、インドから «裸形上人» という僧が熊野の浜に流れ着き、那智の滝で修行していたところ、滝つぼで小さな観音像を見つけ、草庵を建ててまつった――。これが青岸渡寺の起こりだといわれています。","平安時代、出家した花山法皇が那智で修行し、その後、観音霊場をめぐる旅を再びさかんにしたと伝わります。«なぜ那智が第一番なの?» 那智は観音菩薩の浄土 «補陀落» に最も近い場所と信じられていたから、とも考えられています。","戦国時代の終わり、那智山の建物は戦乱で焼けてしまいます。豊臣秀吉は弟の秀長に命じて本堂を再建させ、1590年に完成しました。太い柱と大きな屋根をもつ桃山時代の本堂は、今も熊野に残る最も古い建物のひとつです。","江戸時代まで、那智山は «神と仏がいっしょ» の聖地でした。ところが明治のはじめ、政府は神社とお寺を分けるよう命じます。多くの仏堂はこわされましたが、如意輪観音をまつる本堂だけは残され、«青岸渡寺» として新しい歩みを始めました。境内から見える三重塔と大滝の組み合わせは、そんな長い歴史をくぐりぬけた、祈りの風景です。"],"tl":[["伝承 仁徳天皇の時代","裸形上人が観音像をまつったと伝わる"],["10世紀末","花山法皇が那智で修行したと伝わる"],["1581年ごろ","戦乱で那智山の堂舎が焼けたと伝わる"],["1590年","豊臣秀長の手で本堂が再建される"],["明治初め","神仏分離で那智大社と分かれ、青岸渡寺となる"],["1972年","三重塔が再建される"],["2004年","世界遺産に登録"]],"who":[["裸形上人","インドから来たと伝わる開基の僧"],["花山法皇","西国三十三所巡礼を再興したと伝わる"],["豊臣秀吉・秀長","本堂の再建を行った"]],"deep":["本堂は入母屋造の大きな建物で、太い柱や力強い組物に桃山時代の特徴を残し、国の重要文化財です。","本堂には豊臣秀吉が寄進したと伝わる大きな鰐口（わにぐち）があり、日本最大級といわれます。","三重塔は昔あった塔の跡に1972年に再建されたもので、中を見学できる時期もあります。塔と大滝が並ぶ構図はポスターなどでよく使われます。","西国三十三所は、奈良時代の徳道上人が始め、花山法皇が再興したという伝説が広く知られますが、史料で確かめられるのは平安時代後期以降の巡礼です。","明治の神仏分離のとき、那智山では多くの仏像や仏具が失われたり移されたりしました。境内のほかの寺院も一部しか残っていません。","宗派は天台宗。熊野の修験道とも深く関わり、今も山伏による行事が行われます。"],"look":["桃山時代の本堂（重要文化財）","秀吉寄進と伝わる大鰐口","三重塔と那智の大滝が並ぶ景色","西国三十三所の納経所（御朱印）","隣り合う那智大社との境目"],"q":["西国三十三所観音霊場の第一番札所はどこ？","那智山青岸渡寺。ここから岐阜県の華厳寺（第三十三番）まで巡礼が続きます。"],"koji":[],"myth":"裸形上人の開基、花山法皇の巡礼再興は伝承。鰐口の寄進者も伝承。","img":["西国三十三所","花山天皇","熊野那智大社"],"wp":"青岸渡寺","rel":{"ev":[],"grave":[]},"ph":[["c:b/bb/Seigantoji01.JPG",3264,2448,"青岸渡寺"],["c:d/d8/Three-storied_Pagoda_of_Seiganto-ji_and_Nachi_Falls.jpg",6000,4000],["c:2/29/Seiganto-ji_Temple_-_Sonsh%C3%B4-in.jpg",4128,3096],["c:7/7c/Kimiidera_Wakayama03n4272.jpg",2848,4272],["c:f/f1/Seigantoji02.JPG",3264,2448],["c:c/c3/Sanmon%2C_Seigantoji.jpg",3840,2160],["c:b/bb/Hokyointo%2C_Seigantoji.jpg",3124,2083],["c:e/e8/Seigantoji04.JPG",1632,1224]]},{"id":"30_daimonzaka","n":"那智 大門坂（石畳の参詣道）","yomi":"なち だいもんざか","cat":"街道","y":1100,"era":["heian","kamakura","edo"],"sh":"国指定史跡（熊野参詣道）・世界遺産","rank":"A","ad":"東牟婁郡那智勝浦町那智山","st":"JR紀伊勝浦駅から熊野交通バス約20分 «大門坂» 下車、歩いて約5分で夫婦杉","la":33.6637,"lo":135.8963,"hook":"樹齢800年といわれる夫婦杉の間をくぐると、苔むした石段が杉木立の中へ吸いこまれていく。平安の熊野詣のふんいきを最もよく残す坂道。","lead":"大門坂は、熊野古道中辺路の終わり近く、那智大社・青岸渡寺へ上る石段の参詣道です。長さは600mほどで、杉の大木にはさまれた石畳が続きます。坂の上にはかつて大きな門（大門）があったことが、名前の由来です。","story":["バスを降りて少し歩くと、道の両側に大きな杉が2本、門番のように立っています。«夫婦杉» と呼ばれるこの木は、樹齢800年ほどといわれます。ここから先が大門坂。石段は267段とも数えられ、杉の間を一歩一歩上っていきます。","熊野詣の人たちは、本宮・新宮とめぐったあと、この坂を上って那智を目指しました。長い旅の最後の上り坂。息を切らしながらも、坂の上にある那智の神仏に会えるうれしさで、足が軽くなったかもしれません。","坂の入口近くには «多富気（たふけ）王子» がまつられています。熊野の道に点々とあった «九十九王子» の、最後の王子とされる場所です。«ここまで来たぞ» ――旅人は王子の前で祈り、最後の力をふりしぼりました。","那智は、本宮・新宮とならぶ熊野三山のひとつであると同時に、滝での修行や «補陀落渡海» の出発地でもある、特別な聖地でした。浜ノ宮の補陀洛山寺に立ち寄った旅人は、那智川ぞいの道を山へ向かい、この大門坂で最後の祈りの坂にさしかかったのです。距離は短くても、長旅で疲れた足にはずっしりこたえる上りだったことでしょう。","坂の上にはかつて、仁王像の立つ大きな門がありました。今はありませんが、«大門坂» の名前が、そのにぎわいを今に伝えています。昔は那智山で修行する人や、参詣者の世話をする人々の住まいも坂のまわりに並んでいたといいます。","今では、平安時代の装束を貸してくれるお店もあり、着物姿で石段を上る人の姿も見られます。雨上がりの石畳は、しっとりと光って美しい反面、とてもすべりやすいので気をつけて。杉の香りと沢の音を感じながら、昔の旅人と同じ坂をゆっくり上ってみましょう。"],"tl":[["平安時代","熊野詣の人々が那智へ向かう参詣道として使う"],["1201年","後鳥羽上皇の熊野御幸で、一行が那智へ参詣する（藤原定家の日記に記録）"],["江戸時代","石段・石畳が整えられていったと考えられる"],["2000年","熊野参詣道の一部として国の史跡に指定"],["2004年","世界遺産に登録"]],"who":[["熊野詣の旅人","本宮・新宮とめぐり最後にこの坂を上った"],["那智山の修験者","坂の周辺で修行し、参詣者を案内した"],["藤原定家","後鳥羽上皇の熊野御幸に同行し、那智への参詣も日記に書いた"]],"deep":["大門坂は全長約600m余り、石段は267段といわれます。坂を上りきっても、那智大社の社殿まではさらに石段が続きます。","夫婦杉は根元がつながった2本の杉で、樹齢は約800年とされます。坂の両側には樹齢数百年の杉並木が続きます。","多富気王子は «手向け» に由来する名ともいわれ、旅人が神に幣（ぬさ）をたむけた場所と考えられています。","大門坂の石畳は、山から切り出した自然石を組み合わせたもの。雨の多い熊野では、石畳が道を守る役目を果たしてきました。","坂のふもとにある «大門坂茶屋» では平安衣装の貸し出しがあり、«壺装束» などで熊野詣の旅姿を体験できます。","坂の途中の «十一文関» は、昔、通行料を取った関所の跡と伝わり、那智山の運営を支えた仕組みを想像させます。"],"look":["入口の夫婦杉","多富気王子跡","苔むした石段と杉並木","十一文関跡","坂の上から見える那智の滝（晴れた日）"],"q":["大門坂の入口に立つ、2本の大きな杉を何という？","«夫婦杉»。樹齢800年ほどといわれます。"],"koji":[],"myth":"段数・樹齢は概数。十一文関の由来は伝承。","img":["熊野古道","熊野那智大社","九十九王子"],"wp":"大門坂","rel":{"ev":[],"grave":[]},"ph":[["c:c/cc/Daimonzaka-e.jpg",4272,2848,"大門坂"],["c:7/73/Daimonzaka25_2048.jpg",1536,2048],["c:b/b4/Daimonzaka10_2048.jpg",1536,2048],["c:6/6d/Daimonzaka8618.JPG",1200,1600],["c:9/9c/Shrine_Kumano_nachi01.jpg",600,450,"熊野那智大社"],["c:f/fc/Daimonzaka17_1024.jpg",768,1024,"九十九王子"]]},{"id":"30_fudarakusanji","n":"補陀洛山寺（補陀落渡海の寺）","yomi":"ふだらくさんじ","cat":"寺社","y":868,"era":["heian","muromachi","edo"],"sh":"国の重要文化財（本尊 十一面千手千眼観音像）・世界遺産","rank":"A","ad":"東牟婁郡那智勝浦町浜ノ宮","st":"JR紀勢本線 那智駅から歩いて約3分","la":33.6437,"lo":135.9275,"hook":"南の海のかなたにある観音さまの浄土をめざし、小さな船に閉じこもって帰らぬ旅に出た僧たちがいた。その出発点が、この浜の寺だ。","lead":"補陀洛山寺は、那智の浜辺にある小さなお寺です。ここは、観音菩薩が住むとされる南の浄土 «補陀落（ふだらく）» をめざして僧たちが船出した «補陀落渡海» の出発地として知られます。平安時代から江戸時代にかけて、20人以上の僧がここから海へ出たと記録されています。","story":["熊野の人々は、南の海のずっと先に、観音さまの住む浄土 «補陀落山» があると信じていました。«この世で修行をつんだ者は、生きたままその浄土へ行ける» ――そう考えた僧たちが選んだのが、小さな船で南の海へこぎ出す «補陀落渡海» でした。","渡海船は、ふつうの船ではありませんでした。船の上に小さな屋形をつくり、その四方に鳥居を立てます。僧が中に入ると、屋形の出入口は外から板で打ちつけられたと伝えられます。わずかな食料と灯りだけを積み、伴走の船が沖まで引いていき、あとは綱を切って流すのです。«帰ってくることはない» 旅でした。","記録によれば、最初の渡海は868年の慶龍上人。その後、室町時代にとくに多く行われ、江戸時代までに20人以上が海へ出たとされます。なかには、那智の山で修行を重ねた高僧や、お寺の住職もいました。","こんな話も伝わっています。戦国時代、金光坊という僧が渡海に出ましたが、途中で船が島に流れ着き、«助けてくれ» と願いました。ところが見送りの人々は彼を海へ突き落としてしまった――。その島は «金光坊島» と呼ばれるようになったといいます。作家・井上靖はこの話をもとに小説 «補陀落渡海記» を書きました。","江戸時代になると、生きたまま船出するのではなく、亡くなった住職の遺体を船に乗せて送る形に変わっていったと考えられています。いま境内には復元された渡海船が置かれ、裏山には渡海した僧たちの墓（供養塔）が並んでいます。命をかけて信仰をつらぬいた人々に、静かに思いをはせたい場所です。"],"tl":[["伝承 仁徳天皇の時代","裸形上人が開いたと伝わる"],["868年","慶龍上人が渡海したと記録される"],["室町時代","渡海がとくに多く行われる"],["16世紀","金光坊の伝承が生まれる"],["1722年","記録に残る最後の渡海（住職の遺体を送ったとされる）"],["2004年","世界遺産に登録"]],"who":[["慶龍上人","記録上最初の渡海僧とされる"],["金光坊","途中で船から逃れようとしたと伝わる僧"],["裸形上人","寺を開いたと伝わる僧"],["井上靖","小説 «補陀落渡海記» を書いた作家"]],"deep":["補陀落（ポータラカ）は、インドの南の海上にあるとされた観音菩薩の住む山。チベットのポタラ宮の名もこれに由来するとされます。","渡海の記録は «熊野年代記» などに残りますが、中世の記事には伝承的なものも含まれ、人数や年代には諸説あります。","渡海船の四方の鳥居は、仏教の修行の四つの段階 «発心・修行・菩提・涅槃» の門を表すともいわれます。神仏習合らしい姿です。","本尊の十一面千手千眼観音立像は平安時代の作とされ、国の重要文化財。ふだんは秘仏で、公開日が決まっています。","隣の «熊野三所大神社» は、もとは補陀洛山寺と一体の «浜の宮» でした。那智山への参詣者が最初に立ち寄る場所でもありました。","補陀落渡海は熊野だけでなく、高知の足摺岬など各地で行われた記録がありますが、那智はその中心地でした。"],"look":["境内の復元された渡海船","裏山の渡海上人の供養塔","隣接する熊野三所大神社","浜ノ宮の海岸（渡海の出発地）","本尊の公開日（事前に確認）"],"q":["補陀落渡海で僧たちが目指した «補陀落» とはどんな場所？","観音菩薩が住むとされる南の海の浄土です。"],"koji":[],"myth":"金光坊の話は伝承。渡海の人数・年代・方法には諸説があり、小説の描写は創作をふくむ。","img":["補陀落渡海","井上靖"],"wp":"補陀洛山寺","rel":{"ev":[],"grave":[]},"ph":[["c:4/41/Fudarakusanji03s2010.jpg",2010,1340,"補陀洛山寺"],["c:6/6d/Daimonzaka8618.JPG",1200,1600],["c:c/cb/Fudarakusanji02s1024.jpg",1024,768],["c:a/ad/Inoue_Yasushi.JPG",410,525,"井上靖"]]},{"id":"30_kamikura","n":"神倉神社（ゴトビキ岩とお燈祭）","yomi":"かみくらじんじゃ","cat":"寺社","y":1100,"era":["yayoi","heian","kamakura"],"sh":"世界遺産（熊野速玉大社の一部）","rank":"A","ad":"新宮市神倉","st":"JR新宮駅から歩いて約15分。石段を上って社殿まで約20分","la":33.7303,"lo":135.9893,"hook":"急な石段538段の上に、ヒキガエルのような巨岩 «ゴトビキ岩»。2月の夜、白装束の男たちが松明を手にこの石段をかけ下りる。","lead":"神倉神社は、新宮の町を見下ろす神倉山にある熊野速玉大社の摂社です。山頂の巨岩 «ゴトビキ岩» が御神体で、熊野の神が最初に降りた場所と伝わります。毎年2月6日の «お燈祭り» では、松明を持った男たちが急な石段を一気にかけ下ります。","story":["鳥居をくぐると、目の前にほとんど壁のような石段がそびえます。自然の石を積んだだけのでこぼこの段が、538段も続くのです。手すりをにぎり、一段ずつ上っていくと、やがて頭上に大きな岩の姿が現れます。これが «ゴトビキ岩»。«ゴトビキ» とは、この地方の言葉でヒキガエルのことです。","«日本書紀» には、神武天皇が東征の途中で熊野に至り、«天磐盾（あまのいわたて）» に登ったと書かれています。神倉山はその天磐盾だと伝えられてきました。また、熊野の神々は最初にこの岩に降り立ち、のちにふもとの速玉大社に移ったともいわれ、神倉山は «元宮» とも呼ばれます。","岩のまわりからは、弥生時代の銅鐸のかけらや、平安時代に経典を埋めた «経塚» の跡が見つかっています。«なぜこんなところに?» 大昔から人々がこの岩を特別なものとしてあがめ、祈りの場としてきた証拠なのです。","毎年2月6日の夜、«お燈祭り» が行われます。白装束に荒縄をしめた «上り子» たちが、たいまつを手に山頂に集まります。やがて山門が開かれると、2,000人近い男たちが、いっせいに石段をかけ下りていきます。新宮の人々は、その火の流れを «下り龍» と呼んできました。","石段は、鎌倉時代に源頼朝が寄進したと伝わります。祭りの夜の勇ましさとはうらはらに、ふだんの神倉山は静かで、山頂からは新宮の町と熊野灘が一望できます。上りよりも下りのほうがずっとこわい石段なので、歩きやすい靴で、ゆっくりと。"],"tl":[["弥生時代","ゴトビキ岩の周辺で祭祀が行われたと考えられる（銅鐸片の出土）"],["伝承 神武東征","神武天皇が天磐盾に登ったと伝わる"],["平安時代","岩のまわりに経塚がつくられる"],["鎌倉時代","源頼朝が石段を寄進したと伝わる"],["2004年","世界遺産に登録"],["毎年2月6日","お燈祭りが行われる"]],"who":[["神武天皇","神話で天磐盾（神倉山）に登ったとされる"],["源頼朝","石段を寄進したと伝わる"],["上り子","お燈祭りで松明を持って石段をかけ下りる男たち"]],"deep":["石段の «538段» は、源頼朝の寄進と伝わる «鎌倉積み»（自然石を積んだ石段）の数として知られます。とくに下の部分が急です。","ゴトビキ岩の下から出土した銅鐸片は、袈裟襷文（けさだすきもん）の銅鐸のものとされ、弥生時代からの岩への信仰を示すと考えられています。","お燈祭りは «熊野速玉祭» とともに «熊野の火祭り» として知られ、新宮節に «お燈まつりは男の祭り、山は火の滝、下り龍» と歌われています。","お燈祭りは伝統的に男性だけが参加する祭りで、上り子は数日前から白い食べ物を食べるなど身を清めます。","«元宮と新宮»: 神倉山が元の宮、ふもとの速玉大社が新しい宮、という関係が «新宮» という地名の由来の一つとされます。","神倉山は中世には修験者の修行の場でもあり、山の上には «神倉聖（かみくらひじり）» と呼ばれる僧たちが住んでいたといわれます。"],"look":["538段の急な石段（上りも下りも慎重に）","御神体のゴトビキ岩","山頂から見る新宮の町と熊野灘","ふもとの太鼓橋と鳥居","2月6日のお燈祭り（見学は石段下から）"],"q":["神倉神社の御神体の巨岩 «ゴトビキ岩» の «ゴトビキ» とは何のこと？","ヒキガエル。岩の形がヒキガエルに見えることから名づけられました。"],"koji":[],"myth":"神武天皇の天磐盾、頼朝の石段寄進、神々が最初に降りた話は伝承。","img":["熊野速玉大社","神武東征"],"wp":"神倉神社","rel":{"ev":["jinmu"],"grave":[]},"ph":[["c:4/44/Kamikura-jinja%2C_shaden.jpg",6016,4000,"神倉神社"],["c:2/2a/Kamikura-jinja%2C_chouzu.jpg",6002,3978],["c:1/14/518wakayama-Kumano_Oto_Festival-xl.jpg",4928,3280],["c:e/ea/Kamikura-jinja13s2048.jpg",1536,2048],["c:0/0b/Kamikura-jinja03s2048.jpg",1536,2048],["c:b/bf/Kamikura-jinja01s2048.jpg",2048,1536],["c:6/6d/Daimonzaka8618.JPG",1200,1600],["c:f/fa/Kumanohayatama-taisha12s5s4200.jpg",4200,2800,"熊野速玉大社"]]},{"id":"30_hinokuma","n":"日前神宮・國懸神宮（紀伊国一之宮）","yomi":"ひのくまじんぐう・くにかかすじんぐう","cat":"寺社","y":500,"era":["kofun","heian","edo"],"sh":"","rank":"A","ad":"和歌山市秋月","st":"和歌山電鐵貴志川線 日前宮駅から歩いてすぐ","la":34.2215,"lo":135.1932,"hook":"一つの鳥居の奥に、二つの «神宮»。伊勢の八咫鏡より先につくられたと伝わる鏡を御神体とする、紀伊国の一之宮だ。","lead":"日前神宮と國懸神宮は、同じ境内に並んで建つ二つの神社で、まとめて «日前宮（にちぜんぐう）» と呼ばれます。それぞれ «日像鏡»«日矛鏡» という鏡を御神体とし、伊勢神宮の八咫鏡と深いつながりがあると伝えられています。古代から紀伊国造の紀氏が代々お仕えしてきた、紀伊国一之宮です。","story":["和歌山市の東、田んぼと住宅地の中に、こんもりとした森があります。鳥居をくぐり、ひんやりとした参道を進むと、道は左右に分かれます。左に日前神宮、右に國懸神宮。一つの境内に二つの «神宮» が向かい合う、全国でもめずらしい神社です。","«神宮» と名のつく神社は、伊勢神宮をはじめ特に格の高いものに限られます。なぜ和歌山のこの神社が? そこには、天の岩戸の神話が関わっています。天照大神が岩戸にかくれたとき、神々は大神の姿をうつす鏡をつくりました。そのとき最初につくられた鏡が日前宮にまつられ、そのあとつくられたのが伊勢の八咫鏡だ――と伝えられているのです。","神社にお仕えしてきたのは、紀伊国造（きのくにのみやつこ）の紀氏です。紀氏は古代の紀伊を治めた有力な一族で、近くの岩橋千塚古墳群にはその一族の墓があると考えられています。国造家は明治になるまで、日前宮の神職を代々つとめました。","平安時代、日前宮は朝廷から特に重んじられる «名神大社» とされ、広い領地を持っていました。ところが1585年、紀州攻めを行った豊臣秀吉によって領地を取り上げられ、社殿も荒れてしまいます。江戸時代、紀州徳川家の初代・頼宣が社殿を再建し、神社は再びととのえられました。","いまの境内は大きな木々に囲まれ、にぎやかな町のそばとは思えないほど静かです。華やかな飾りのない素朴な社殿は、古い時代の神社の姿を感じさせます。森の中で耳をすますと、古代の紀伊の人々が鏡に祈った声が聞こえてくるようです。"],"tl":[["伝承 神武天皇の時代","天道根命が鏡を奉じて紀伊に来たと伝わる"],["伝承 垂仁天皇の時代","現在地にまつられたと伝わる"],["平安時代","«延喜式» で名神大社とされる"],["1585年","豊臣秀吉が社領を没収、社勢が衰える"],["江戸時代初め","紀州藩主・徳川頼宣が社殿を再建"],["1871年","官幣大社となる"]],"who":[["天道根命","紀伊国造家の祖とされ、鏡を奉じてきたと伝わる"],["紀氏（紀伊国造家）","古代から明治まで神職をつとめた一族"],["豊臣秀吉","紀州攻めで社領を取り上げた"],["徳川頼宣","紀州藩初代藩主。社殿を再建した"]],"deep":["御神体は、日前神宮が «日像鏡（ひがたのかがみ）»、國懸神宮が «日矛鏡（ひぼこのかがみ）»。«日本書紀» の一書に «日前神» の名が見えます。","紀伊国造家は、出雲国造家などとならび、古代からの家系が今に続く数少ない家の一つとされます。","平安時代の «延喜式» では、日前神社・國懸神社ともに名神大社とされ、神階も高く、朝廷からの尊崇がとても厚かったことがわかります。","紀伊国一之宮は、日前神宮・國懸神宮、伊太祁曽神社、丹生都比売神社の三つが名乗っており、どれを一之宮とするかは時代や史料で異なります。","伝承では、日前宮はもと伊太祁曽神社の場所にあり、伊太祁曽神社が現在地へ移ったあとに入ったともいわれます。","秀吉による社領没収のあと、国造家は領地を失い、神社の経営は苦しくなりました。江戸時代の再建は紀州徳川家の支えによるものです。"],"look":["左右に分かれる参道と二つの社殿","境内の深い森（クスノキの大木）","素朴な社殿の造り","和歌山電鐵の «日前宮駅» からの参道"],"q":["伊勢神宮の八咫鏡より先につくられたと伝わる鏡をまつる神社はどこ？","日前神宮。御神体の «日像鏡» がそれにあたると伝わります。"],"koji":[],"myth":"鏡の由来、天道根命、創建・遷座の年代はいずれも伝承。伊太祁曽神社との土地の話も伝承。","img":["紀伊国造","八咫鏡"],"wp":"日前神宮・國懸神宮","rel":{"ev":[],"grave":[]},"ph":[["c:3/35/Hinokuma-jingu_Kunikakasu-jingu%2C_entrance-2.jpg",6014,3998,"日前神宮・國懸神宮"],["c:6/6f/Kunikakasu-jingu%2C_torii.jpg",6012,3994],["c:2/2d/Hinokuma-jingu_Ichiebisu-jinja.jpg",4128,3096],["c:7/7c/Hinokuma-jingu%2C_torii.jpg",6014,3996],["c:9/91/130112_Hinokumajingu_Kunikakasujingu_Wakayama_Japan07s5.jpg",4800,3200],["c:6/66/130112_Hinokumajingu_Kunikakasujingu_Wakayama_Japan06s5.jpg",4912,3264],["c:a/a8/130112_Hinokumajingu_Kunikakasujingu_Wakayama_Japan01s3.jpg",4912,3264],["c:f/fb/Hinokumajingu_Kunikakasujingu_12.JPG",4288,2848]]},{"id":"30_niutsuhime","n":"丹生都比売神社（天野の里）","yomi":"にうつひめじんじゃ","cat":"寺社","y":816,"era":["heian","muromachi"],"sh":"国の重要文化財（本殿・楼門）・世界遺産","rank":"A","ad":"伊都郡かつらぎ町上天野","st":"JR和歌山線 妙寺駅からかつらぎ町コミュニティバス約30分 «丹生都比売神社前» 下車。本数が少ないので車が便利","la":34.2744,"lo":135.5245,"hook":"高野山を開こうとする空海に、この土地の女神が «山を譲った» と伝わる。山あいの天野の里で、朱色の太鼓橋が静かに水面にうつる。","lead":"丹生都比売神社は、高野山のふもと、天野の盆地にある古い神社です。まつられている丹生都比売大神は、この地域一帯の土地の神で、空海に高野山の地を授けたと伝わります。そのため高野山とは深いつながりがあり、2004年には世界遺産の一部になりました。","story":["高野山へ向かう山道の途中、ふっと視界が開けると、田んぼの広がる小さな盆地が現れます。ここが天野の里。標高450mほどの静かな里に、朱色の太鼓橋 «輪橋（りんきょう）» と、美しい楼門が見えてきます。","言い伝えによれば、空海が修行の地を探して山を歩いていたとき、黒と白の犬を連れた狩人に出会いました。狩人は丹生都比売大神の子・高野御子大神の化身で、犬に空海を高野山まで案内させた、といいます。そして母神の丹生都比売大神は、«この山をあなたに授けましょう» と、自分の領地を空海にゆずったと伝えられています。","«丹生（にう）» とは、赤い顔料 «朱（しゅ）» の原料になる水銀のこと。紀伊の山々は古くから水銀の産地で、丹生都比売大神はその恵みの神だったとも考えられています。«なぜ山の神が水銀と?» 朱は、魔よけや、お寺・神社の柱を塗る大切な色だったのです。","高野山では今も、この地の神々を «地主の神» として大切にまつっています。高野山の壇上伽藍には、丹生明神と高野明神をまつる «御社» があり、山の上と里の神社が、千年以上も結ばれているのです。","境内の本殿4棟は室町時代の再建で、春日造の社殿が横一列に並ぶ姿は見事です。天野の里には、西行の妻と娘が暮らしたという伝説も残り、ゆったりした時間が流れています。高野山へ上る前に、まずこの «山の主» にあいさつしてみてはいかがでしょう。"],"tl":[["伝承 古代","丹生都比売大神がこの地にまつられる"],["816年ごろ","空海が高野山を開く。丹生都比売大神から土地を授かったと伝わる"],["平安時代","«延喜式» で名神大社とされる"],["1469年","本殿が再建されたとされる"],["1499年","楼門が建てられたとされる"],["2004年","世界遺産に登録"]],"who":[["丹生都比売大神","主祭神。空海に高野山の地を授けたと伝わる"],["高野御子大神","狩人の姿で空海を案内したと伝わる神"],["空海（弘法大師）","丹生都比売神社の神々を高野山の守り神としてまつった"],["西行","妻と娘が天野に住んだという伝承がある"]],"deep":["本殿は第一殿から第四殿まであり、春日造の社殿としては日本最大級とされ、国の重要文化財です。楼門も室町時代の建物で重要文化財です。","«輪橋» は、豊臣秀吉の側室・淀殿が寄進したと伝わる石の太鼓橋。とても急なので渡るときは注意が必要です。","«丹» は硫化水銀からとれる赤い顔料。全国に «丹生» の地名や «丹生神社» が多いのは、水銀の採掘と関わりがあると考えられています。","高野山の «町石道» は慈尊院から始まり、途中、天野の里の近くを通ります。丹生都比売神社へ立ち寄る参詣者も多くいました。","明治の神仏分離までは神社の中にお寺の建物もあり、高野山の僧が神事にも関わっていました。神と仏が一体だったころの面影が残ります。","狩場明神（高野御子大神）の連れていた白と黒の犬は、高野山のいくつかの場所で今も絵や像に表されています。"],"look":["朱色の太鼓橋 «輪橋»","室町時代の楼門（重要文化財）","横一列に並ぶ本殿4棟（重要文化財）","天野の里ののどかな田園風景","近くの西行の妻子ゆかりの伝承地"],"q":["«丹生» の «丹» は何のこと？","赤い顔料 «朱» のもとになる水銀（硫化水銀）のこと。紀伊の山は古くからその産地でした。"],"koji":[],"myth":"空海に土地を授けた話、白黒の犬の案内、淀殿の輪橋寄進、西行の妻子の話は伝承。建立年は諸説。","img":["空海","高野山","西行"],"wp":"丹生都比売神社","rel":{"ev":[],"grave":[]},"ph":[["c:b/b9/Niutsuhime-jinja_roumon-3.jpg",5514,3630,"丹生都比売神社"],["c:2/2c/Niutsuhime-jinja_sototorii.JPG",6016,4000],["c:0/08/Niutsuhime-jinja_sotoba.JPG",6016,4000],["c:3/32/Niutsuhime-jinja_roumon.JPG",5998,3974],["c:8/83/Niutsuhime-jinja_rinkyo.JPG",6016,4000],["c:6/6f/Niutsuhime-jinja_honden-2.jpg",5514,3630],["c:0/0b/Niutsuhime-jinja_futatsutorii.JPG",6016,4000],["c:9/99/Niutsuhime-jinja_Saba-jinja.JPG",6016,4000]]},{"id":"30_itakiso","n":"伊太祁曽神社（木の神・紀伊国一之宮）","yomi":"いたきそじんじゃ","cat":"寺社","y":713,"era":["nara","heian"],"sh":"","rank":"A","ad":"和歌山市伊太祈曽","st":"和歌山電鐵貴志川線 伊太祈曽駅から歩いて約5分","la":34.2082,"lo":135.2437,"hook":"«紀伊» はもともと «木の国»。その木々の種を日本中にまいたと伝わる神・五十猛命をまつる、森の神社。","lead":"伊太祁曽神社は、木の神・五十猛命（いたけるのみこと）をまつる、紀伊国一之宮の一つです。«日本書紀» には、五十猛命が木の種を日本中に植え、国じゅうを緑にしたと書かれています。昔から «木の神さま» として林業の人々などから信仰されてきました。","story":["«和歌山» の昔の国の名前は «紀伊国»。もともとは «木の国» だったといわれます。紀伊半島は、今も山と森にうめつくされた土地。その «木の国» の神さまをまつるのが、伊太祁曽神社です。","«日本書紀» によると、素戔嗚尊（すさのおのみこと）の子・五十猛命は、父とともに天から降りるとき、たくさんの木の種を持ってきました。そして九州から全国に種をまき、日本中を青々とした森にしたといいます。その功績から «有功（いさおし）の神» とたたえられ、紀伊国にまつられたと書かれています。","«古事記» にも、この神と思われる «大屋毘古神（おおやびこのかみ）» が登場します。兄弟の神々に命をねらわれた大国主神は、木の国の大屋毘古神のもとへ逃れ、木のまたから抜け出させてもらって助かった――という話です。木の国の神は、困った者を助ける神でもありました。","伊太祁曽神社は、もとは今の日前宮（日前神宮・國懸神宮）の場所にあったと伝わります。そこへ日前宮がまつられることになり、奈良時代の初めごろに今の場所へ移ったといわれます。平安時代には朝廷から特に重んじられる «名神大社» とされました。","境内には、二つに割れた大きな木の幹 «いのちの木» があり、その間をくぐると災いから逃れられるとされています。大国主神が木のまたをくぐって助かった神話にちなむものです。深い森に包まれた境内を歩くと、«木の国» の神の息づかいを感じられます。"],"tl":[["神話","五十猛命が木の種を日本中に植えたと «日本書紀» に記される"],["713年ごろ","現在地に移ったと伝わる"],["平安時代","«延喜式» で名神大社とされる"],["1871年","国幣中社となる"]],"who":[["五十猛命","主祭神。木の種を全国に植えた木の神"],["大屋都比売命・都麻津比売命","五十猛命の妹神。いっしょに木の種をまいたとされる"],["素戔嗚尊","五十猛命の父"],["大国主神","«古事記» で木の国の神に助けられた"]],"deep":["社名の表記には «伊太祁曽» のほか «伊太祈曽» などのゆれがあり、駅名や地名は «伊太祈曽» と書かれます。«いたきそ» という読みは共通です。","五十猛命と «古事記» の大屋毘古神を同じ神とする考え方は古くからありますが、確定しているわけではありません。","伝承では、紀の川の流域一帯に木の神の信仰が広がっていたとされ、周辺には «大屋都比売神社»«都麻津比売神社» もあります。","紀伊国一之宮は、日前神宮・國懸神宮、伊太祁曽神社、丹生都比売神社がそれぞれ名乗り、史料によって扱いが異なります。","境内の «いのちの木» は、もとは境内にあった木の幹を使ったもので、厄よけのくぐりとして人気があります。","現在地への遷座の年を «713年（和銅6年）» とする説明がありますが、根拠となる史料については諸説があります。"],"look":["二つに割れた «いのちの木»","深い森に囲まれた参道","本殿（五十猛命をまつる）","境内の摂社・末社"],"q":["五十猛命がたたえられる理由は？","木の種を持って降り、日本中に植えて森にしたと «日本書紀» に書かれているからです。"],"koji":[],"myth":"旧社地が日前宮の場所だったこと、遷座年は伝承・諸説。","img":["五十猛神","紀伊国"],"wp":"伊太祁曽神社","rel":{"ev":[],"grave":[]},"ph":[["c:3/3f/Itakisojinja_02.JPG",4288,2848,"伊太祁曽神社"],["c:f/f8/Itakiso-jinja_Ooyatsuhime.jpg",4128,3096],["c:3/3d/Itakiso-jinja%2C_haisho.jpg",6000,3976],["c:e/ea/Itakisojinja_05.JPG",4288,2848],["c:e/e9/Chain_saw_art_dragon.jpg",480,854],["c:9/99/Isotakeru_shinbutsu-zue.jpg",993,1324,"五十猛神"]]},{"id":"30_kamayama","n":"竈山神社（彦五瀬命の墓）","yomi":"かまやまじんじゃ","cat":"墓所","y":-660,"era":["myth","meiji"],"sh":"","rank":"A","ad":"和歌山市和田","st":"和歌山電鐵貴志川線 竈山駅から歩いて約10分","la":34.2138,"lo":135.213,"hook":"«ひきょうな者の矢で死ぬのか» ――神武天皇の兄・彦五瀬命が雄たけびをあげて亡くなったという地に、その墓と伝わる塚がある。","lead":"竈山神社は、初代・神武天皇の兄、彦五瀬命（ひこいつせのみこと）をまつる神社です。神話によると、彦五瀬命は大和へ向かう戦いで矢に当たって傷つき、紀伊の地で亡くなり、竈山に葬られました。社殿の裏には、宮内庁が管理する «竈山墓» があります。","story":["«古事記» や «日本書紀» は、神武天皇の «東征» の物語を語ります。九州を出た神武天皇（カムヤマトイワレビコ）と兄の五瀬命は、大和を目指して瀬戸内海を東へ進み、今の大阪湾から上陸しました。ところがそこで、土地の豪族・長髄彦（ながすねびこ）の激しい反撃にあいます。","戦いのさなか、五瀬命の腕（または体）に矢が当たりました。五瀬命は言います。«われらは日の神の子。なのに日に向かって戦ったのがよくなかった。日を背にして戦おう»。一行は大きく南へ回りこみ、紀伊半島をめぐって、太陽を背に大和へ入ることにしました。この決断が、のちの熊野回りの東征へとつながります。","しかし五瀬命の傷は重く、紀伊の «男之水門（おのみなと）» で、ついに力つきます。«古事記» は、五瀬命が «いやしき奴の手負いで死ぬのか» と雄たけびをあげて亡くなったと伝え、そこから «男（お）の水門» の名がついたと記します。その亡きがらは «竈山» に葬られました。","竈山神社は、この五瀬命の墓とされる場所にまつられた神社です。平安時代の «延喜式» にもその名が見え、古くから大切にされてきました。明治になると、神武天皇の兄をまつる社として格式が上げられ、社殿も整えられました。","いま社殿の奥には、こんもりとした森の中に «竈山墓» があります。神話の人物の墓として宮内庁が管理しており、中に入ることはできません。«神話は本当にあったの?» そんな問いを胸に、静かな森の前に立ってみると、古代の人々がこの物語を大切に語り継いできた気持ちが伝わってきます。"],"tl":[["神話","彦五瀬命が長髄彦との戦いで傷つき、紀伊で亡くなる"],["神話","竈山に葬られる（«古事記»«日本書紀»）"],["平安時代","«延喜式» に竈山神社の名が見える"],["明治時代","竈山墓が彦五瀬命の墓として宮内省の管理となる"],["1915年","官幣大社となる"]],"who":[["彦五瀬命","主祭神。神武天皇の兄。東征で傷つき紀伊で亡くなったとされる"],["神武天皇","初代天皇とされる。兄とともに東征した"],["長髄彦","大和の豪族。五瀬命を矢で傷つけたとされる"]],"deep":["«古事記» では五瀬命が亡くなった場所を紀国の «男之水門»、«日本書紀» では «雄水門» とし、竈山に葬ったと記します。男之水門の場所は和歌山市内の諸説があります。","«日に向かって戦ったのがいけない» という五瀬命のことばは、東征のルートが熊野回りになった理由として語られる有名な場面です。","竈山墓は宮内庁が管理する «陵墓参考地» ではなく «墓» として扱われています。社殿の裏にありますが、立ち入りはできません。","神武天皇の即位を紀元前660年とするのは «日本書紀» の年代にもとづくもので、歴史的な年代ではありません。この地の «y» も神話上の目安です。","竈山神社は、和歌山電鐵沿線の日前宮・伊太祁曽神社とあわせて «三社参り» として参拝されることがあります。","明治以降、竈山神社は神武天皇の兄をまつる社として格式が大きく上がり、社殿や参道も整えられました。"],"look":["本殿と拝殿","社殿の裏の «竈山墓»（外から拝む）","境内の森","近くの日前宮・伊太祁曽神社（三社参り）"],"q":["彦五瀬命が亡くなる前に «日に向かって戦ったのがよくなかった» と言ったのはなぜ？","自分たちは日の神（天照大神）の子孫なので、太陽を背にして戦うべきだと考えたからです。"],"koji":[],"myth":"すべて «古事記»«日本書紀» の神話にもとづく伝承。墓の比定は明治に定められたもの。","img":["彦五瀬命","神武東征"],"wp":"竈山神社","rel":{"ev":[],"grave":[]},"ph":[["c:5/54/Kamayama-jinja_haiden.JPG",6016,4000,"竈山神社"],["c:7/7d/Shizuhi-jinja.JPG",6016,4000],["c:8/88/Kamayamano-haka-2.jpg",6002,3978],["c:8/81/Kamayama-jinja_torii.JPG",5998,3974],["c:2/22/Kamayama-jinja_shinmon.JPG",6016,4000],["c:9/9a/Kamayama-jinja_shaden.JPG",6016,4000],["c:b/b4/Kamayama-jinja_sandou.JPG",6016,4000],["c:2/28/Kamayama-jinja_otorii.JPG",6016,4000]]},{"id":"30_tokugawa_reidai","n":"高野山 徳川家霊台","yomi":"こうやさん とくがわけれいだい","cat":"墓所","y":1643,"era":["edo"],"sh":"国の重要文化財","rank":"A","ad":"伊都郡高野町高野山","st":"高野山駅からバス «浪切不動前» 下車、歩いてすぐ（約10分）","la":34.2159,"lo":135.5895,"hook":"日光東照宮を思わせるきらびやかな二つの霊屋。三代将軍・家光が、祖父・家康と父・秀忠をまつるために高野山に建てた。","lead":"徳川家霊台は、江戸幕府の三代将軍・徳川家光が1643年に完成させた、家康と秀忠をまつる2棟の霊屋（おたまや）です。漆や金箔、彫刻で飾られた豪華な建物で、国の重要文化財になっています。高野山と徳川家の深いつながりを伝える建物です。","story":["高野山の中心から少し歩くと、石段の上に二つのお堂が並んで建っています。向かって右が家康、左が秀忠の霊屋。屋根の下には細かな彫刻がびっしりとほどこされ、漆塗りと金具がきらめきます。質素な山のお寺の中で、ここだけ別世界のような華やかさです。","«なぜ将軍家が高野山に?» 戦国時代から江戸時代にかけて、大名たちは高野山のお寺と «宿坊» の関係を結び、一族の供養をたのんでいました。徳川家とつながりの深かったのが大徳院というお寺です。家光はその大徳院の境内に、祖父と父の霊をまつる霊屋を建てたのです。","家光は祖父・家康をたいへん尊敬していました。日光東照宮を大規模に建て替えたのも家光です。そのころの家光は、日光だけでなく、高野山にも祖父と父を大切にまつる場所を設けました。«徳川の世が長く続きますように» という願いもこめられていたのでしょう。","大徳院はその後、別の場所へ移りましたが、霊台はもとの場所に残されました。明治以降、多くの建物が火事などで失われるなか、2棟の霊屋は370年以上、この地で山の風雪にたえてきました。","霊屋の中には入れませんが、石段を上って外から見学できます。近くで見ると、柱や扉、軒下のひとつひとつに意匠がこらされていることがわかります。奥之院の大名たちの供養塔と見比べてみると、江戸の権力と高野山の関係がよりいっそう立体的に見えてきます。"],"tl":[["1616年","徳川家康が亡くなる"],["1632年","徳川秀忠が亡くなる"],["1636年","家光が日光東照宮の大造替を行う"],["1643年","家光が高野山に家康・秀忠の霊屋を完成させる"],["2004年","世界遺産 «紀伊山地の霊場と参詣道» の一部となる"]],"who":[["徳川家光","三代将軍。霊台を建てた"],["徳川家康","右の霊屋にまつられる。江戸幕府を開いた"],["徳川秀忠","左の霊屋にまつられる。二代将軍"]],"deep":["2棟の霊屋はどちらも小さな建物ですが、内外が漆・彩色・金具で飾られ、江戸時代初期の霊廟建築の特徴をよく伝えています。","大徳院は徳川家の宿坊として知られ、徳川家の祖先とされる松平氏とのゆかりも語られます。霊台はその旧境内にあたります。","家光が建てた建物は日光東照宮・大猷院などが有名ですが、高野山の霊台はそれらより小規模なぶん、細部をじっくり見られるのが魅力です。","霊台は2004年の世界遺産登録で、金剛峯寺の関連建造物の一つとして構成資産に含まれています。","高野山の奥之院にも徳川家の供養塔があり、なかでも二代秀忠夫人・崇源院（お江）の «一番石» と呼ばれる巨大な五輪塔が有名です。","霊台の拝観は有料で、冬季は時間が短くなるなど季節で変わります。"],"look":["家康の霊屋（向かって右）","秀忠の霊屋（向かって左）","軒下の彫刻と金具の細工","霊台へ上る石段と周囲の杉木立","奥之院の崇源院の五輪塔（比べて見る）"],"q":["高野山の徳川家霊台を建てた将軍はだれ？","三代将軍・徳川家光。祖父の家康と父の秀忠をまつりました。"],"koji":[],"myth":"大徳院と松平氏のゆかりは伝承をふくむ。","img":["徳川家光","徳川家康","徳川秀忠","高野山"],"wp":"徳川家霊台","rel":{"ev":[],"grave":[]},"ph":[["c:0/09/Tokugawa_Mausoleum_-_Koyasan_-_Japan_-_06_%2847956835238%29.jpg",3648,2736,"徳川家霊台"],["c:5/5d/Tokugawa_Mausoleum_-_Koyasan_-_Japan_-_05_%2847956863881%29.jpg",2736,3648],["c:c/ce/Tokugawa_Mausoleum_-_Koyasan_-_Japan_-_04_%2847956835458%29.jpg",3648,2736],["c:3/3b/Tokugawa_Mausoleum_-_Koyasan_-_Japan_-_02_%2847956864136%29.jpg",3648,2736],["c:7/7b/Ieyasu-tamaya.jpg",3264,2448],["c:a/a6/Hidetada-tamaya.jpg",3264,2448],["c:2/2c/Tokugawa_Mausoleums%2C_Koyasan%2C_Japan.JPG",2560,1920],["c:6/6d/Daimonzaka8618.JPG",1200,1600]]},{"id":"30_koyasan_daimon","n":"高野山 大門","yomi":"こうやさん だいもん","cat":"寺社","y":1705,"era":["kamakura","edo"],"sh":"国の重要文化財・世界遺産","rank":"A","ad":"伊都郡高野町高野山","st":"高野山駅からバス «大門» 下車すぐ（約20分）","la":34.2135,"lo":135.57,"hook":"高さ約25mの朱色の門が、雲海と夕日を背に立ちふさがる。ここが «山全体がお寺» である高野山の、正式な入口だ。","lead":"大門は、高野山の西の端に立つ総門で、山全体の玄関にあたります。今の門は1705年に再建されたもので、高さは約25.1m、左右に大きな金剛力士像が立っています。ふもとから続く参詣道 «町石道» のゴールでもあり、夕日の名所としても知られます。","story":["いまはバスや車で高野山に上る人がほとんどですが、昔の人は、ふもとの九度山から険しい山道を歩いて上ってきました。やっとたどり着いた山の上で、まず目に入ったのがこの大門です。«ついに高野山に着いた!» そう胸をなでおろした旅人の姿が目に浮かびます。","大門のある場所は、高野山の西のはし。門の前に立つと、うしろは深い谷になっていて、晴れた日には遠くの山々、ときには雲海まで見わたせます。夕方には、門の向こうに太陽がしずんでいき、朱色の門がいっそう赤くかがやきます。","最初の門は、もう少し下の «九十九折谷» にあった鳥居だったといわれます。その後、門はこの場所に移され、何度も焼けたり、たおれたりしながら建て直されてきました。今の門は、江戸時代の1705年に再建されたもの。二階建ての «楼門» で、国の重要文化財です。","門の左右には、高さ5mをこえる金剛力士像（仁王像）が立ち、にらみをきかせています。柱には «日々の影向を闕かさずして 処々の遺跡を検知す» という言葉が掲げられています。空海は毎日、姿を現して人々を見守り、ゆかりの地をめぐっている――という意味だとされます。","大門は、ふもとの慈尊院から続く «町石道» のゴールでもあります。約22kmの道に、1町（約109m）ごとに «町石» が立ち、旅人は町石をひとつずつ数えながら上りました。鎌倉時代に建てられた石の道しるべが、今も道ぞいに残っています。大門をくぐる前に、ふり返って道のりを思ってみてください。"],"tl":[["平安時代","高野山の入口に門（最初は鳥居）が置かれたと伝わる"],["1265〜1285年","町石道の石造町石が整えられる"],["1705年","大門が再建される"],["1986年","大規模な修理が行われる"],["2004年","世界遺産に登録"]],"who":[["空海（弘法大師）","高野山を開いた。門の柱の聯には空海の姿が語られる"],["覚斅（かくきょう）","鎌倉時代、町石を石造にすることを発願した僧とされる"]],"deep":["大門は五間三戸の二重門（楼門）で、高さ約25.1m。江戸時代の楼門としては大型のもので、国の重要文化財です。","金剛力士像は江戸時代の作で、奈良の東大寺南大門の像に次ぐ大きさともいわれます。","«町石» は、慈尊院から壇上伽藍までの180基と、伽藍から奥之院までの36基があり、«高野山町石» として国の史跡に指定されています。","鎌倉時代、それまで木の卒塔婆だった町石を石にかえる事業が始まり、約20年かけて完成したとされます。安達泰盛ら鎌倉幕府の有力者も寄進しました。","大門の前は高野山で数少ない、西側がひらけた場所で、夕日と雲海の撮影スポットとして人気があります。","高野山の «結界» の考えでは、大門から内側が聖域とされ、ここで一礼してから入るのが古くからの作法です。"],"look":["朱色の楼門と «日々の影向» の聯","左右の金剛力士像","門の前からの夕日と雲海","門のそばの町石（«一町石» など）","ふもとから歩く町石道（体力に余裕があれば）"],"q":["ふもとの慈尊院から高野山まで、1町ごとに立てられた石の道しるべを何という？","«町石»。慈尊院から壇上伽藍までに180基あります。"],"koji":[],"myth":"門の最初の場所・移転年は伝承をふくむ。力士像の大きさ比較は俗説。","img":["町石道","金剛峯寺"],"wp":"高野山","rel":{"ev":[],"grave":[]},"ph":[["c:1/17/Danjogaran_Koyasan12n3200.jpg",3200,2133,"高野山"],["c:5/5c/Nyonindo_001.jpg",5417,3611],["c:1/1f/Looking_up_the_main_street_near_the_fire_department_and_post_office%2C_Koyasan%2C_2016.jpg",6016,3539],["c:2/2f/Koyasan_Danjogaran_Fudodo.JPG",4288,2848],["c:c/cd/Kongosanmaiin_Tahoto.JPG",4288,2848],["c:c/ce/Kongobuji_Koyasan02n4272.jpg",4272,2848],["c:4/49/Autumn_Koyasan_Wakayama01s5s3200.jpg",4230,2820],["c:b/b3/Danjogaran_Koyasan01n3200.jpg",3200,2133]]},{"id":"30_choishimichi","n":"高野山町石道","yomi":"こうやさんちょういしみち","cat":"街道","rank":"A","y":1285,"era":["heian","kamakura"],"sh":"国指定史跡（町石は国の重要文化財）","ad":"伊都郡九度山町慈尊院〜高野町高野山","st":"南海高野線 九度山駅から起点の慈尊院まで歩いて約25分。全部歩くと約20km・6〜7時間","la":34.2998,"lo":135.5608,"hook":"1町（約109m）ごとに立つ石の道しるべが、ふもとから山上の聖地まで約700年間、巡礼者の足元を数え続けている。","lead":"高野山町石道は、ふもとの慈尊院から高野山の大門、そして奥之院へ続く参詣道です。道には «町石» という五輪塔の形をした石柱が1町ごとに立ち、残りの距離を教えてくれます。鎌倉時代に立てられた石の多くが今も道ばたに立ち、世界遺産の一部になっています。","story":["平安時代のはじめ、空海が高野山を開いたころ、ふもとから山上へは険しい山道しかありませんでした。やがて道に木の卒塔婆（そとば）が立てられ、道しるべになったといわれます。空海自身が木の卒塔婆を立てたという言い伝えもありますが、これは確かめられていません。","木は雨や風ですぐにくさってしまいます。鎌倉時代、高野山の僧・覚斅（かくきょう）が «これを石にかえて、永く残る道しるべにしよう» と呼びかけました。1265年ごろに始まったこの計画には、上皇や鎌倉幕府の有力者たちが次々とお金を出し、1本ずつ寄進者の名前が刻まれていきました。完成して供養が行われたのは1285年、20年近い大事業でした。","なぜ石の数にこだわったのでしょう? 町石は高野山の中心・壇上伽藍の根本大塔を «0» として数えます。ふもと側は慈尊院まで180基、奥之院側は36基。180は胎蔵界、37（36基と大塔）は金剛界という密教の仏の数にあたるといわれ、町石の一本一本が仏そのものとして拝まれました。巡礼者は一本ごとに手を合わせながら登ったのです。","道の途中には «袈裟掛石»«押上石»«鏡石» など、名前のついた岩が点々とあります。袈裟掛石は空海が袈裟を掛けたと伝わり、押上石は空海の母が押し上げたという伝承が残ります。女性の入山が禁じられていた時代の、母と子の物語が道に刻まれているようです。","2004年、町石道は «紀伊山地の霊場と参詣道» の一部として世界遺産になりました。今も白装束の巡礼者や、トレッキングを楽しむ人が同じ石を数えながら歩きます。一本一本の町石は、700年前の人が «ここまで来たよ、あと少し» と語りかけてくる声のようです。"],"tl":[["816年","空海が朝廷から高野山の地をたまわる"],["1265年ごろ","覚斅が木の卒塔婆を石の町石にかえる計画を始める"],["1285年","町石の完成を祝う供養が行われる"],["1977年","町石道が国の史跡に指定される"],["2004年","世界遺産 «紀伊山地の霊場と参詣道» に登録"]],"who":[["空海（弘法大師）","高野山の開祖。道の始まりと多くの伝承に登場"],["覚斅","鎌倉時代の高野山の僧。石の町石への建て替えを呼びかけた"],["安達泰盛","鎌倉幕府の有力御家人。町石の建立を強く後押ししたとされる"]],"deep":["町石は花こう岩製の五輪塔形で、高さは約3mほど。上から空・風・火・水・地を表す形が一本の石に彫り出され、梵字・町数・寄進者の名が刻まれています。","寄進者には上皇や北条氏一門、御家人の名も見られます。1本ずつ誰が寄進したかがわかる、鎌倉時代の «寄付者名簿» としても貴重な史料です。","数え方の基準は根本大塔。ふもと側を180町、奥之院側を36町とし、奥之院の町石は御廟に近づくほど数が増える仕組みです。","途中の «二つ鳥居» は、天野にある丹生都比売神社の神域への入口とされる鳥居です。高野山が山の神（丹生・高野の神）とともに歩んできたことがわかります。","すべてが鎌倉時代の石ではなく、失われたものは後の時代に補われています。当初の石か後の補充かを見くらべるのも歴オタの楽しみ方です。","町石道の近くには «笠石»«卒塔婆» の伝承地もあり、道そのものが信仰の場。長い距離を一本の «数えられた道» にした発想は、他の参詣道ではあまり見られません。"],"look":["慈尊院の石段の途中にある «百八十町石»（出発点）","二つ鳥居と、そこから見わたす紀の川の眺め","袈裟掛石・押上石など名前のある岩","高野山大門近くの町石と、ゴールの壇上伽藍"],"q":["町石道で «0町» にあたる場所はどこ?","壇上伽藍の根本大塔です。ここを基準に、ふもとへ180町、奥之院へ36町を数えます。"],"koji":[],"myth":"空海が最初に木の卒塔婆を立てた話、袈裟掛石・押上石の由来は伝承。","img":["金剛峯寺","慈尊院","紀伊山地の霊場と参詣道"],"wp":"高野山町石道","rel":{"ev":[],"grave":[]},"ph":[["c:4/42/Koyasan_Choishimichi1.jpg",3264,2448,"高野山町石道"],["c:f/f8/Koyasan_Choishimichi_01.JPG",2848,4288],["c:a/ab/Koyasan_Choishimichi-Kesakakeichi.jpg",3264,2448],["c:9/96/Jison-in_Two-storey_pagoda.jpg",3264,2448],["c:6/6d/Daimonzaka8618.JPG",1200,1600],["c:e/e1/Danjogaran_Koyasan16n4272.jpg",4272,2848,"金剛峯寺"],["c:3/3a/Jisonin_hondo.jpg",3264,2448,"慈尊院"],["c:7/73/Daimonzaka25_2048.jpg",1536,2048,"紀伊山地の霊場と参詣道"]]},{"id":"30_kongosanmaiin","n":"金剛三昧院（北条政子ゆかりの多宝塔）","yomi":"こんごうさんまいいん","cat":"寺社","rank":"A","y":1223,"era":["kamakura"],"sh":"国宝（多宝塔）","ad":"伊都郡高野町高野山","st":"南海りんかんバス «千手院橋» から歩いて約10分","la":34.2118,"lo":135.5905,"hook":"夫と息子を失った «尼将軍» 北条政子が、祈りをこめて建てた寺。その多宝塔は、高野山でいちばん古い建物として今も立つ。","lead":"金剛三昧院は、鎌倉幕府を開いた源頼朝の妻・北条政子が、頼朝と三代将軍の実朝の菩提をとむらうために建てた寺です。境内の多宝塔は1223年に建てられ、国宝になっています。高野山のたび重なる火事をくぐりぬけた、奇跡のような建物です。","story":["1219年、鎌倉の鶴岡八幡宮で、三代将軍・源実朝が甥の公暁に討たれました。政子は夫・頼朝をすでに失い、長男・頼家も亡くしていました。«子どもたちをすべて見送ってしまった» ── 政子の悲しみはどれほどだったでしょう。","じつは政子は、それより前の1211年に、高野山に頼朝の供養のための寺を建てていました。はじめは «禅定院» と呼ばれ、実朝が亡くなると、その菩提もとむらう寺として «金剛三昧院» に改められたと伝わります。開山には栄西の弟子で、禅と密教の両方に通じた退耕行勇（たいこうぎょうゆう）が招かれました。","1223年、境内に多宝塔が建ちました。下が四角、上が丸い二重の塔で、ひかえめな大きさながら、軒の反りがやわらかく上品です。高野山は何度も大火にあい、壇上伽藍の建物もほとんど建て直されてきました。«なぜこの塔だけ残ったの?» ── 伽藍から少し離れた場所にあったことが幸いしたのかもしれません。","寺には、実朝の家臣だった安達景盛も深く関わりました。景盛は実朝の死後に出家し、高野山で «高野入道» と呼ばれて寺を支えたといわれます。鎌倉の武士たちにとって、高野山は亡き主君の魂を託す場所でした。","いまの金剛三昧院は宿坊でもあり、泊まって朝のおつとめに参加することもできます。春には境内のシャクナゲが咲き、800年前の塔をいろどります。政子の祈りの場は、今も静かに人を迎えています。"],"tl":[["1211年","北条政子が頼朝の菩提のため «禅定院» を建てる"],["1219年","源実朝が鶴岡八幡宮で討たれる"],["1219年以後","実朝の菩提もとむらう «金剛三昧院» となる"],["1223年","多宝塔が建てられる（現存）"],["2004年","世界遺産 «紀伊山地の霊場と参詣道» の構成資産に"]],"who":[["北条政子","源頼朝の妻。寺の創建者"],["源実朝","鎌倉幕府三代将軍。寺はその菩提をとむらう"],["退耕行勇","開山。栄西の弟子で鎌倉幕府とも深いつながり"],["安達景盛","実朝の家臣。出家して高野山で寺を支えた"]],"deep":["多宝塔は高野山に現存する最古の建物で、全国の多宝塔の中でも石山寺の多宝塔に次ぐ古さといわれます。鎌倉時代初めの様式を知る基準作です。","客殿・台所、経蔵、四所明神社本殿なども国の重要文化財。多宝塔だけでなく、寺全体が中世の雰囲気を伝えています。","金剛三昧院は、真言密教だけでなく禅や律も学ぶ «兼修» の場でした。鎌倉幕府が支えたことで、中世には将軍家の祈りの寺として大きな力を持ちました。","安達氏は景盛の孫の泰盛の時代にも高野山と深くつながり、泰盛は町石道の建立を後押ししました。金剛三昧院と町石道は «鎌倉の武士と高野山» という一本の線でつながります。","実朝の死で源氏の将軍は三代で絶えました。この寺は、源氏将軍家の終わりを見届けた母の祈りの記念碑でもあります。"],"look":["国宝の多宝塔（とくに屋根の反りと組物）","重要文化財の経蔵と四所明神社","春のシャクナゲ（例年5月ごろ）","宿坊としての客殿のたたずまい"],"q":["金剛三昧院の多宝塔は、高野山で何番目に古い建物?","いちばん古い建物です。1223年の建立で、たび重なる大火をまぬがれました。"],"koji":[{"w":"尼将軍","m":"出家した身でありながら幕府を実質的に動かした北条政子のよび名"}],"myth":"寺名の改称の時期や、多宝塔がどちらの菩提のためかには諸説がある。","img":["北条政子","源実朝","高野山"],"wp":"金剛三昧院","rel":{"ev":[],"grave":[]},"ph":[["c:c/cd/Kongosanmaiin_Tahoto.JPG",4288,2848,"金剛三昧院"],["c:8/8e/Kongosanmaiin_Temple_Main_Hall.jpg",4248,3186],["c:7/7f/Kongozanmaiin_Koyasan02bs3200.jpg",3945,2630],["c:c/cb/Kongozanmaiin_Koyasan04n3200.jpg",3870,2580],["c:4/44/Kongosanmaiin_shishomyojinsha.jpg",3264,2448],["c:c/c6/Kongosanmaiin_kyozo.jpg",3264,2448],["c:6/6d/Daimonzaka8618.JPG",1200,1600],["c:4/4e/Kongouzanmaiin02.jpg",1400,1049]]},{"id":"30_jisonin","n":"慈尊院（«女人高野»）","yomi":"じそんいん","cat":"寺社","rank":"A","y":816,"era":["heian"],"sh":"国宝（弥勒仏坐像）","ad":"伊都郡九度山町慈尊院","st":"南海高野線 九度山駅から歩いて約25分","la":34.3003,"lo":135.5598,"hook":"«九度山» という町の名は、母に会うため空海が月に九度山を下りたことから ── そう語り継がれる寺。","lead":"慈尊院は、空海が高野山を開いたときに、ふもとの «表玄関» として置いた寺務所が始まりです。女性が高野山に登れなかった時代、女性はここまでお参りできたため «女人高野» と呼ばれました。本尊の弥勒仏は国宝です。","story":["高野山を開いた空海は、山のふもと、紀の川のほとりに寺の事務や物資の運び入れを行う «政所（まんどころ）» を置きました。山の上の寺を支える、いわば基地です。ここから山上まで続く道が、のちの町石道になりました。","ある日、讃岐（今の香川県）から年老いた母が息子を訪ねてきたと伝わります。しかし高野山は女人禁制。母は山に登れません。«それなら私が下りてこよう» ── 空海は月に九度、山を下りて母を訪ねたといわれ、これが «九度山» の地名の由来と語り継がれています。","母はこの地で亡くなりました。空海は、母が夢の中で弥勒菩薩になったのを見たとして、弥勒仏を祀るお堂を建てたと伝わります。弥勒菩薩は慈尊（じそん）とも呼ばれることから、寺の名も «慈尊院» になりました。","それ以来、慈尊院は女性の祈りの寺になりました。境内には乳房の形をした絵馬がたくさん奉納されています。«子どもを授かりますように»«お乳がよく出ますように»«病気が治りますように» ── 女性たちのさまざまな願いが込められています。","本尊の弥勒仏坐像は平安時代の作で国宝。ふだんは秘仏で、ご開帳は限られた機会だけです。弥勒堂も鎌倉時代の建物で国の重要文化財。寺の石段は町石道の出発点で、ここから山上の聖地への約20kmの道が始まります。"],"tl":[["816年","空海が高野山を開き、ふもとに政所を置く"],["835年","空海が高野山で入定（伝承では母の没後まもなく）"],["平安時代","本尊・弥勒仏坐像が造られる（国宝）"],["鎌倉時代","弥勒堂が建てられる（重要文化財）"],["2004年","世界遺産の構成資産に登録"]],"who":[["空海","寺の開創者。母を訪ねて山を下りたと伝わる"],["空海の母","讃岐から訪ねてきてこの地で亡くなったと伝わる。名は玉依御前と伝承"]],"deep":["«政所» は荘園の管理や年貢の受け取りも行う高野山の経営の中心でした。紀の川の水運と、ふもとの農地を押さえる場所に置かれたことに意味があります。","弥勒仏坐像は一本の木を中心に彫る技法による平安前期〜中期の像とされ、どっしりした体つきが特徴です。ご開帳の機会は限られるので、事前の確認が大切です。","隣の丹生官省符神社は、高野山の守り神・丹生都比売の神をまつる社で、慈尊院と一体の信仰の場でした。石段を上るとすぐに行けます。","«九度山» の由来は «月に九度» 説が有名ですが、地名の本当の起こりは確かではありません。伝承として楽しむのがよいでしょう。","乳房型の絵馬は、布で作ったふくらみのある形が特徴。女人禁制の時代から続く、女性の祈りの歴史を目に見える形で伝えています。","慈尊院のある九度山は、紀の川と丹生川が合流する場所で、船で運ばれてきた物資を高野山へ運び上げる中継地にぴったりの地形でした。"],"look":["乳房型の絵馬が並ぶ弥勒堂","町石道の出発点となる «百八十町石»","丹生官省符神社への石段","紀の川の流れを感じる寺の立地"],"q":["慈尊院が «女人高野» と呼ばれたのはなぜ?","女人禁制の高野山に登れない女性が、代わりにここへお参りできたからです。"],"koji":[],"myth":"空海が月に九度下りた話、母の名や夢の話は伝承。","img":["空海","九度山町","丹生官省符神社"],"wp":"慈尊院","rel":{"ev":[],"grave":[]},"ph":[["c:3/3a/Jisonin_hondo.jpg",3264,2448,"慈尊院"],["c:3/3f/Jisonin_tahoto.jpg",2448,3264],["c:e/ed/Jisonin_sanmon.jpg",2448,3264],["c:8/8b/Jisonin_kobodaishido.jpg",3264,2448],["c:4/4a/Jisonin_Kishibojindo.jpg",3264,2448],["c:9/96/Jison-in_Two-storey_pagoda.jpg",3264,2448],["c:6/6d/Daimonzaka8618.JPG",1200,1600],["c:e/ed/Kobodaishi.jpg",1280,960]]},{"id":"30_reihokan","n":"高野山霊宝館","yomi":"こうやさんれいほうかん","cat":"学び","rank":"A","y":1921,"era":["heian","kamakura","taisho"],"sh":"国の登録有形文化財（本館など）","ad":"伊都郡高野町高野山","st":"南海りんかんバス «霊宝館前» からすぐ","la":34.2125,"lo":135.583,"hook":"山の上の宝物庫には、運慶の少年像から空海が唐から持ち帰ったと伝わる小さな仏まで、1200年分の祈りが眠っている。","lead":"高野山霊宝館は、高野山の寺々に伝わる仏像や仏画、古文書を守り、公開するために1921年につくられた博物館です。国宝や重要文化財がたくさんあり、日本の仏教美術を学ぶには欠かせない場所です。建物そのものも大正時代の文化財です。","story":["高野山には、1200年のあいだに数えきれない宝物が集まりました。けれど山の上の寺は木造で、火事のたびに多くの宝が失われてきました。«このままでは大切なものが消えてしまう» ── 明治から大正にかけて、宝物を安全に守る建物をつくろうという声が高まりました。","こうして1921年、霊宝館が開館しました。宇治の平等院鳳凰堂を思わせる、左右に翼を広げたような木造の建物です。耐火の建物ではない木造の本館は大正時代の姿をそのまま残し、後に新しい収蔵庫が加えられました。","館の人気者は、運慶が手がけた «八大童子立像» です。不動明王に仕える童子たちで、とくに制吒迦（せいたか）童子は、口をきゅっと結んだいたずらっぽい少年の顔。«本当に生きているみたい!» と見る人を驚かせます。鎌倉時代の写実的な彫刻の傑作で、国宝です。","ほかにも、極楽から阿弥陀仏がたくさんの菩薩と迎えに来る様子を描いた «阿弥陀聖衆来迎図»、空海が唐から持ち帰ったと伝わる手のひらサイズの «諸尊仏龕（しょそんぶつがん）» など、国宝がずらり。展示は季節ごとに入れかわるので、何度行っても新しい出会いがあります。","山の上の博物館は、たんなる倉庫ではありません。寺で祈られてきた仏たちを、次の千年へ手渡すための場所なのです。"],"tl":[["816年","空海が高野山を開く"],["1197年ごろ","運慶の工房が不動堂の八大童子像をつくったとされる"],["1921年","高野山霊宝館が開館"],["1998年","本館などが国の登録有形文化財に"],["2004年","高野山が世界遺産に登録"]],"who":[["運慶","八大童子立像の作者とされる鎌倉時代の仏師"],["快慶","運慶と並ぶ仏師。館には快慶作の仏像も伝わる"],["空海","高野山の開祖。ゆかりの品が多く伝わる"]],"deep":["八大童子は8体のうち6体が鎌倉時代の運慶工房の作、残り2体は後の時代の補作と考えられています。どれが後補か見くらべるのも面白い点です。","«諸尊仏龕» は白檀を彫った小さな携帯用の仏龕で、中国・唐の作とされます。空海が持ち帰ったという伝承から «枕本尊» とも呼ばれます。","本館の設計は大正期の建築家によるもので、正面の中央と左右の翼廊の構成が平等院鳳凰堂を思わせます。木造の博物館建築として大正の姿を残す例は多くありません。","収蔵品は高野山内の寺院から預けられたものが中心で、所有者は金剛峯寺をはじめ各寺院。霊宝館は «山全体の宝物庫» の役割を担っています。","展示は季節ごとの企画展が中心で、見たい作品が出ているとは限りません。事前に展示予定を確認するのが歴オタの鉄則です。","高野山の宝物は、明治時代の «廃仏毀釈» の混乱の中でも、山内の寺々が守り抜いてきたものが多くふくまれます。霊宝館の設立は、そうした宝を未来へ残すための大きな一歩でした。"],"look":["運慶の八大童子立像（展示時期を確認）","平等院を思わせる大正時代の本館の外観","新収蔵庫の大きな仏像の展示","近くの壇上伽藍とあわせた見学"],"q":["運慶の «八大童子» は、どの仏に仕える童子たち?","不動明王です。高野山の不動堂に安置されていました。"],"koji":[],"myth":"諸尊仏龕を空海が持ち帰ったという話は伝承。八大童子の作者比定にも一部諸説。","img":["運慶","金剛峯寺","不動明王"],"wp":"高野山霊宝館","rel":{"ev":["kukai"],"grave":[]},"ph":[["c:0/0a/Autumn_Koyasan_Reihokan02n3200.jpg",3200,2133,"高野山霊宝館"],["c:8/88/%E9%81%8B%E6%85%B6.jpg",1284,1616,"運慶"],["c:e/e1/Danjogaran_Koyasan16n4272.jpg",4272,2848,"金剛峯寺"],["c:a/a1/Fud%C5%8D_My%C5%8D%C5%8D.jpg",3433,5046,"不動明王"]]},{"id":"30_sanadaan","n":"真田庵（善名称院・九度山の真田昌幸・幸村）","yomi":"さなだあん（ぜんみょうしょういん）","cat":"寺社","rank":"A","y":1600,"era":["azuchi","edo"],"sh":"","ad":"伊都郡九度山町九度山","st":"南海高野線 九度山駅から歩いて約10分","la":34.2945,"lo":135.5728,"hook":"関ヶ原で敗れた父子は、この山里で14年を過ごした。そして息子は、ある夜ここを抜け出して大坂城へ向かった。","lead":"真田庵は、関ヶ原の戦いのあとに九度山へ流された真田昌幸・信繁（幸村）父子が住んだ屋敷の跡に建つお寺です。正式には善名称院といいます。昌幸の墓と伝わる塔があり、真田ファンの聖地になっています。","story":["1600年の関ヶ原の戦い。信濃・上田城の真田昌幸と次男の信繁は西軍につき、徳川秀忠の大軍を上田城で足止めしました。ところが西軍は本戦で敗北。本来なら死罪のところ、東軍についた長男・信之の必死の願いで、父子は命を助けられ、紀伊の九度山へ流されました。","はじめは高野山にいましたが、まもなくふもとの九度山に屋敷を構えました。生活は楽ではなく、国元の信之や家臣からの仕送りが頼りでした。昌幸は手紙で «年をとってくたびれた» ともらしています。かつて徳川を二度も退けた名将は、1611年、この地で亡くなりました。","息子の信繁は、九度山で10年以上をすごしました。1614年、豊臣方から大坂城へ入るよう誘いが届きます。«ここで一生を終えるのか、それとも…»。信繁は見張りの目をぬけて九度山を抜け出し、大坂へ向かったといわれます。翌年、大坂夏の陣で家康の本陣に迫った戦いぶりは、敵からも «日本一の兵» とたたえられました。","父子が去ったあと、屋敷の跡は大切に守られ、江戸時代の中ごろに大安上人がここに寺を開きました。それが善名称院、通称 «真田庵» です。屋根には真田家の家紋・六文銭が輝き、境内には昌幸の墓と伝わる宝篋印塔が立っています。","九度山には、真田父子が作ったとされる平たいひも «真田紐» の話や、大坂城へ通じていたという «真田の抜け穴» の伝説も残ります。近くには真田ミュージアムもあり、町全体で真田の物語を語り継いでいます。"],"tl":[["1600年","関ヶ原の戦い。昌幸・信繁父子が九度山へ流される"],["1611年","真田昌幸が九度山で亡くなる"],["1614年","信繁が九度山を出て大坂城に入る"],["1615年","大坂夏の陣で信繁が戦死"],["1741年","大安上人が屋敷跡に善名称院を開く"]],"who":[["真田昌幸","信繁の父。九度山で晩年をすごし、この地で没した"],["真田信繁（幸村）","昌幸の次男。九度山から大坂城へ向かった"],["真田信之","昌幸の長男。東軍について父と弟の助命を願った"],["大安上人","屋敷跡に善名称院を開いた僧"]],"deep":["«幸村» の名は江戸時代の軍記物などで広まったもので、本人が使った確かな史料は見つかっていません。同時代の史料では «信繁»。","九度山での暮らしぶりは、昌幸や信繁が国元に送った手紙からわかります。焼酎を送ってほしいと頼む信繁の手紙など、人間くさい姿が残っています。","«真田の抜け穴» は、実際には古墳の横穴式石室だと考えられています。大坂まで通じていたというのは伝説です。","«真田紐» は丈夫な平織りのひもで、父子が作って売り、生活の足しにしたという話が有名ですが、これも伝承の域を出ません。","監視役は紀伊の大名・浅野家でしたが、信繁の脱出をどう防げなかったのかははっきりしません。村人を酒宴でもてなしてその隙に出たという話は後世の物語です。"],"look":["屋根や門に輝く六文銭の家紋","昌幸の墓と伝わる宝篋印塔","真田宝物資料室（公開日を確認）","近くの真田ミュージアムと «真田の抜け穴»"],"q":["真田父子が九度山へ流されるきっかけになった戦いは?","1600年の関ヶ原の戦い。西軍についたため流罪になりました。"],"koji":[{"w":"日本一の兵（ひのもといちのつわもの）","m":"大坂夏の陣での信繁の戦いぶりをたたえたことば。島津家の記録に見えるといわれる"}],"myth":"真田紐・抜け穴・脱出の方法は伝承。«幸村» の名は後世に広まった呼び名。","img":["真田昌幸","真田信繁","九度山町"],"wp":"善名称院","rel":{"ev":[],"grave":[]},"ph":[["c:4/4a/Zenmyoshoin_hondo.jpg",3264,2448,"善名称院"],["c:f/f2/Sanada-kofun.JPG",1280,960],["c:0/0b/Sanada-Masayuki.jpg",1400,1750,"真田昌幸"],["c:b/b3/Sanada_Yukimura.jpg",658,630,"真田信繁"],["c:3/3a/Jisonin_hondo.jpg",3264,2448,"九度山町"]]},{"id":"30_suda_hachiman","n":"隅田八幡神社（人物画像鏡）","yomi":"すだはちまんじんじゃ","cat":"寺社","rank":"A","y":503,"era":["kofun","heian"],"sh":"国宝（人物画像鏡）","ad":"橋本市隅田町垂井","st":"JR和歌山線 隅田駅から歩いて約10分","la":34.3285,"lo":135.6365,"hook":"直径20cmほどの銅の鏡に刻まれた48の文字。そこには、1500年前の «大王» と «百済の王» の名が眠っているかもしれない。","lead":"隅田八幡神社は、紀の川の上流、橋本市の隅田（すだ）にある八幡さまです。この神社に伝わった «人物画像鏡» には、日本でもっとも古い部類の漢字の文章が刻まれていて、国宝になっています。いつ、だれが、なぜ作ったのか、今も研究者が議論を続けている謎の鏡です。","story":["隅田八幡神社は、平安時代の859年に、京都の石清水八幡宮から神さまを分けてまつったのが始まりと伝わります。このあたりは石清水八幡宮の荘園 «隅田荘» で、地元の武士・隅田党が神社を大切に守ってきました。","神社に伝わったのが、青銅の鏡です。裏側には馬に乗った人や神々の姿が浮き彫りにされ、そのまわりにぐるりと48の漢字が刻まれています。«癸未年八月…» で始まり、«大王»«男弟王»«意柴沙加宮»«斯麻» といった名前が読みとれます。","«癸未年» は60年に一度めぐってくる年です。443年か、503年か。«男弟王» は、のちの継体天皇ではないか。«斯麻» は、百済の武寧王（本名が斯麻）ではないか。«意柴沙加宮» は奈良の忍坂（おさか）の宮ではないか ── 一文字ごとに、古代史の大きな謎につながっていきます。","なぜこんな鏡が紀伊の山あいにあったのでしょう? 紀の川は、大和と海をつなぐ古代の大動脈でした。朝鮮半島からの人や技術もこの川をさかのぼってきたと考えられています。鏡は、そうした交流の証しなのかもしれません。","いま鏡の実物は東京国立博物館に預けられていますが、神社は変わらず地域の氏神です。秋祭りには «だんじり» ならぬ «屋台» の行列が出て、にぎわいます。小さな鏡が、1500年の時をこえて古代の国際関係を語っているのです。"],"tl":[["443年または503年","«癸未年»。人物画像鏡がつくられた年とされる（諸説）"],["859年","石清水八幡宮から神を分けてまつったと伝わる"],["平安〜鎌倉時代","隅田荘の武士団・隅田党が神社を守る"],["1971年","韓国で武寧王の墓誌が見つかり、«斯麻» 説が注目される"],["現在","鏡は東京国立博物館に寄託"]],"who":[["男弟王","鏡の銘文に登場。継体天皇とする説がある"],["斯麻","鏡の銘文に登場。百済の武寧王とする説が有力"],["隅田党","中世に神社を守った地元の武士団"]],"deep":["銘文は48字（数え方には異説）。«癸未年» を443年とみる説と503年とみる説があり、503年説では継体天皇が即位前に忍坂宮にいた時期にあたるとされます。","«斯麻» を百済の武寧王とみる説は、1971年に韓国で武寧王の墓誌が見つかり、王の名が «斯麻» と確かめられたことで注目されました。","文様は中国製の «画像鏡» をまねた倭（日本）製とされ、文字には誤りや逆字も含まれます。そこから作った工人の文字への理解度も議論されています。","埼玉県の稲荷山古墳の鉄剣、熊本県の江田船山古墳の鉄刀とならび、5〜6世紀の «大王» の時代を知る数少ない文字資料です。","鏡がいつから神社にあったのかは、はっきりしていません。古墳から出たものが神社に納められたという見方もあります。"],"look":["落ち着いた本殿と境内の森","境内の説明板（人物画像鏡の銘文の解説）","秋祭りの行列（例年10月）","近くの紀の川の流れ"],"q":["人物画像鏡に刻まれた «斯麻» は、どこの国の王ではないかと考えられている?","百済の武寧王です。本名が «斯麻» だったことが墓誌で確かめられています。"],"koji":[],"myth":"銘文の年代・人物比定はすべて諸説。創建年は社伝。","img":["隅田八幡神社人物画像鏡","武寧王","継体天皇"],"wp":"隅田八幡神社","rel":{"ev":[],"grave":[]},"ph":[["c:9/9b/Suda-hachiman-jinja%2C_haiden-2.jpg",5976,3938,"隅田八幡神社"],["c:1/11/Suda-hachiman-jinja%2C_torii.jpg",5990,3960],["c:9/9b/Suda-hachiman-jinja%2C_shinmon.jpg",6016,4000],["c:f/fc/Suda-hachiman-jinja%2C_sekihi-1.jpg",6016,4000],["c:5/5e/Suda-hachiman-jinja%2C_honden.jpg",6010,3990],["c:8/83/Sumida_Hatiman_Mirror.JPG",723,730],["c:9/99/Baekje-monarchs%2820-26%29.PNG",300,200,"武寧王"],["c:e/ee/Statue_of_Emperor_Keitai.jpg",960,1280,"継体天皇"]]},{"id":"30_kokawadera","n":"粉河寺","yomi":"こかわでら","cat":"寺社","rank":"A","y":770,"era":["nara","heian","edo"],"sh":"国の重要文化財（本堂・大門など）","ad":"紀の川市粉河","st":"JR和歌山線 粉河駅から歩いて約15分","la":34.283,"lo":135.4065,"hook":"猟師が見た不思議な光、そして7日間こもったまま消えた少年。その正体は観音さまだった ── 絵巻に描かれた寺。","lead":"粉河寺は、西国三十三所観音霊場の第3番札所として知られる大きなお寺です。寺の始まりを描いた «粉河寺縁起絵巻» は国宝。江戸時代に建てられた本堂は、西国の札所の中でもとくに大きな建物です。","story":["奈良時代の770年、この地の猟師・大伴孔子古（おおとものくじこ）が、山の中で光を放つ場所を見つけたと伝わります。«ここは尊い場所にちがいない»。孔子古は猟師をやめ、小さな庵をつくりました。","ある日、ひとりの少年が現れ、«一晩泊めてください» と頼みました。少年は泊めてもらったお礼に仏像をつくると言い、7日間こもったまま出てきません。8日目に戸を開けると、少年の姿はなく、金色に輝く千手観音が立っていました。少年の正体は観音さまだったのです。","その後、河内の長者のひとり娘が重い病にかかりました。そこへ少年が現れ、祈ると娘の病はすっかり治りました。お礼をしようとすると «紀伊の粉河にいます» と言い残して消えます。長者一家がたずねると、そこには観音像が…。一家は出家して寺を支えたといいます。この二つの話を描いたのが、平安時代の «粉河寺縁起絵巻» です。","寺は中世に大きな勢力となりましたが、1585年、豊臣秀吉の紀州攻めで焼けてしまいます。江戸時代に紀州藩の保護で再建され、1720年に完成した本堂は、重なった屋根が迫力ある大建築です。","本堂の前には «粉河寺庭園» があり、石を大きく組んだ豪快な庭は国の名勝。巡礼者は大門をくぐり、中門、そして本堂へと、少年観音の物語をたどるように進みます。"],"tl":[["770年","大伴孔子古が寺を開いたと伝わる"],["平安時代末〜鎌倉時代","«粉河寺縁起絵巻» がつくられる"],["中世","寺の勢力が大きくなる"],["1585年","豊臣秀吉の紀州攻めで焼失"],["1720年","現在の本堂が完成"]],"who":[["大伴孔子古","寺を開いたと伝わる猟師"],["童男行者","観音の化身とされる少年"],["河内の長者","娘の病が治り、寺を支えたと伝わる"],["豊臣秀吉","紀州攻めで寺が焼けた"]],"deep":["«粉河寺縁起絵巻» は京都国立博物館に寄託されています。火災で焼けた跡が残り、絵巻の端がこげているのも歴史の証しです。","本堂は礼堂と本堂が一体になった形で、屋根が二重に重なって見える独特の外観です。西国札所の本堂の中でも最大級といわれます。","大門・中門・千手堂なども国の重要文化財。江戸時代の寺院建築がまとまって残る点が見どころです。","粉河寺庭園は、本堂前の斜面に石を大胆に組んだ枯山水風の庭で、桃山時代の作風を伝えるとされます。","本尊の千手観音は «絶対秘仏» とされ、一般には公開されません。縁起の物語を通して姿を想像するしかない仏さまです。","粉河は、紀の川沿いの大和街道の宿場町としても栄えました。寺の門前町の町並みとあわせて歩くと、巡礼者でにぎわった昔の姿が想像できます。","西国三十三所の札所は第1番の青岸渡寺（那智）から始まり、第2番紀三井寺、第3番粉河寺と、紀伊の国に最初の三つが集まっています。"],"look":["大門（重要文化財）の堂々とした構え","本堂の二重に見える大屋根","本堂前の粉河寺庭園の石組","童男堂など、縁起にちなむお堂"],"q":["粉河寺の観音さまが最初に姿を現したとき、どんな姿だった?","少年（童男行者）の姿でした。7日間こもったあと、千手観音の像を残して消えたと伝わります。"],"koji":[],"myth":"開創の話、童男行者の話は縁起による伝承。","img":["粉河寺縁起","西国三十三所","紀の川市"],"wp":"粉河寺","rel":{"ev":[],"grave":[]},"ph":[["c:c/c9/Kokawadera13s3872.jpg",3872,2592,"粉河寺"],["c:a/a9/Kokawa-dera_Temple_-_Yakushi-d%C3%B4.jpg",4128,3096],["c:7/7a/Kokawa-dera_Temple_-_Taishi-d%C3%B4.jpg",4128,3096],["c:5/50/Kokawa-dera_Temple_-_Shutsugen-ike_Pond.jpg",4128,3096],["c:a/ae/Kokawa-dera_Temple_-_Rokkaku-d%C3%B4.jpg",4128,3096],["c:1/18/Kokawa-dera_Temple_-_Gy%C3%B4ja-d%C3%B4.jpg",4128,3096],["c:3/3d/Kokawa-dera_Temple_-_D%C3%B4nan-d%C3%B4.jpg",4128,3096],["c:0/06/Kokawa-dera_Temple_-_Dai-mon_Gate_-_Kong%C3%B4rikishi_-_Agy%C3%B4.jpg",3096,4128]]},{"id":"30_seishu","n":"華岡青洲の里（春林軒・世界初の全身麻酔）","yomi":"はなおかせいしゅうのさと（しゅんりんけん）","cat":"学び","rank":"A","y":1804,"era":["edo"],"sh":"","ad":"紀の川市西野山","st":"JR和歌山線 名手駅から車で約10分（バス便は少ない）","la":34.286,"lo":135.4665,"hook":"1804年、紀州の村医者が世界で初めて «全身麻酔» による手術を成功させた。欧米より約40年も早かった。","lead":"華岡青洲は、江戸時代の紀州の医師です。自分で作った麻酔薬 «通仙散» を使い、1804年に全身麻酔で乳がんの手術を成功させました。«青洲の里» には、青洲が住み、患者を治療し、弟子を育てた «春林軒» が復元されています。","story":["青洲は1760年、紀伊の平山（今の紀の川市）に医者の子として生まれました。京都で学んだあと故郷にもどり、父の跡をついで村の医者になります。«苦しむ患者を、痛みなく手術できたら…»。青洲は麻酔薬の研究に打ちこみました。","手がかりは、中国の名医・華佗が使ったという麻酔薬 «麻沸散» の話でした。青洲はチョウセンアサガオ（曼陀羅華）などの薬草を組み合わせ、動物で試しながら少しずつ改良していきます。けれど人間に効くかどうかは、実際に試すしかありません。","そこで名乗り出たのが、母の於継（おつぎ）と妻の加恵（かえ）だったと伝わります。実験はくり返され、母は亡くなり、妻は目が見えなくなったといわれます。家族の大きな犠牲の上に、薬は完成へと近づきました。«なぜそこまで?» ── 医術にかける青洲の思いを、家族が支えたのでしょう。","1804年10月、青洲は完成した «通仙散» を60歳の女性・藍屋勘（あいやかん）に飲ませ、眠っているあいだに乳がんを切り取る手術を行いました。欧米で麻酔を使った手術が知られるようになるのは1840年代のこと。紀州の山里で、世界に先がけた医療が生まれていたのです。","青洲の評判は全国に広まり、春林軒には各地から患者と弟子が集まりました。青洲は «内外合一»、つまり内科と外科の両方を学ぶことの大切さを説きました。いまも青洲の里では、診察室や薬の調合室、門人たちの部屋を見ることができます。"],"tl":[["1760年","華岡青洲が紀伊の平山に生まれる"],["1782年","京都へ出て医学を学ぶ"],["1785年","故郷にもどり、父の跡をつぐ"],["1804年","通仙散による全身麻酔で乳がんの手術に成功"],["1835年","青洲が亡くなる"],["1966年","有吉佐和子の小説『華岡青洲の妻』が出版される"]],"who":[["華岡青洲","医師。通仙散を開発し、全身麻酔手術に成功"],["於継","青洲の母。麻酔薬の実験に協力したと伝わる"],["加恵","青洲の妻。実験に協力し、視力を失ったと伝わる"],["藍屋勘","1804年の手術を受けた女性患者"]],"deep":["通仙散はチョウセンアサガオとトリカブト（草烏頭）などを組み合わせた飲み薬です。量をまちがえると命にかかわる強い薬で、その配合が青洲の研究の核心でした。","1804年の手術は、アメリカで1846年にエーテル麻酔の公開手術が行われるより40年以上前です。青洲の業績は海外の麻酔の歴史でも紹介されています。","母と妻の «競うような献身» は、有吉佐和子の小説『華岡青洲の妻』で広く知られましたが、嫁姑の確執などの描写は小説の創作を含みます。","春林軒は住居と診療所、医学校を兼ねた建物で、青洲の里ではその主屋などが復元・移築されています。近くには青洲の墓所もあります。","門人は全国から集まり、その数は1000人をこえたともいわれます。彼らが各地で医療を広め、日本の外科の発展につながりました。"],"look":["春林軒の主屋と診察室の再現","麻酔薬の原料になったチョウセンアサガオの花（季節による）","フラワーヒルミュージアムの展示","近くの華岡家墓所"],"q":["華岡青洲が開発した麻酔薬の名前は?","«通仙散»（麻沸散とも）です。チョウセンアサガオなどの薬草から作られました。"],"koji":[{"w":"内外合一","m":"内科と外科は一つのもので、両方を深く学ぶべきだという青洲の考え"}],"myth":"母と妻の実験の詳細、家族の関係のドラマは小説による部分が大きい。門人数は諸説。","img":["通仙散","チョウセンアサガオ","華岡青洲の妻"],"wp":"華岡青洲","rel":{"ev":[],"grave":[]},"ph":[["c:e/e3/Seishu_Hanaoka01n.jpg",3872,2592],["c:d/d2/Image_from_%22Surgical_Casebook%22_by_Hanaoka_Seishu.jpg",1200,1726],["c:e/e2/DaturaMetel-plant.jpg",1704,2272,"チョウセンアサガオ"],["c:a/a5/Chunichi1967-04-06-1.jpg",2202,2409,"華岡青洲の妻"]]},{"id":"30_kimiidera","n":"紀三井寺","yomi":"きみいでら","cat":"寺社","rank":"A","y":770,"era":["nara","muromachi"],"sh":"国の重要文化財（楼門・鐘楼・多宝塔）","ad":"和歌山市紀三井寺","st":"JR紀勢本線 紀三井寺駅から歩いて約10分","la":34.1888,"lo":135.1905,"hook":"231段の石段を登りきると、和歌浦の海が目の前に。«早咲きの桜» で春を告げる観音の寺。","lead":"紀三井寺は、西国三十三所観音霊場の第2番札所で、正式な名前は «紀三井山金剛宝寺護国院» といいます。境内にわく三つの井戸 «三井水» が名前の由来です。和歌山の桜の開花を知らせる «標本木» があることでも知られます。","story":["奈良時代の770年、唐から来た僧・為光（いこう）上人が、この山で観音さまを感じて寺を開いたと伝わります。山のあちこちから清らかな水がわき出していて、寺は «紀伊の国の三つの井戸の寺»、つまり紀三井寺と呼ばれるようになりました。","寺の入口の楼門をくぐると、目の前に急な石段がそびえます。その数、231段。この坂は «結縁坂（けちえんざか）» と呼ばれ、ある青年の物語が伝わっています。","江戸時代、母を背負ってこの坂を登っていた青年のわらじの鼻緒が切れてしまいました。そこへ通りかかった娘が、さっと鼻緒をすげかえてくれたのです。これが縁で二人は結ばれ、娘の父の助けを得た青年は、のちに大商人になりました。その青年こそ紀伊国屋文左衛門だった ── と伝わります。«親孝行はめぐりめぐって幸せになる» という話です。","石段を登りきると、本堂の前から和歌浦の海と町が一望できます。境内には室町時代の多宝塔や鐘楼も残り、春には500本ともいわれる桜が咲きほこります。和歌山地方気象台の桜の標本木もここにあり、«紀三井寺で咲いたら春» というのが地元の合言葉です。","2008年には、新しいお堂 «新仏殿» に、高さ約12mの大きな千手十一面観音像がまつられました。古い歴史と新しい祈りが、ひとつの山に重なっています。"],"tl":[["770年","唐僧・為光上人が寺を開いたと伝わる"],["1449年","多宝塔が建てられる（重要文化財）"],["1509年","楼門が建てられる（重要文化財）"],["江戸時代","紀州藩の保護を受ける"],["2008年","新仏殿に大千手十一面観音像がまつられる"]],"who":[["為光上人","寺を開いたと伝わる唐の僧"],["紀伊国屋文左衛門","結縁坂の話の主人公と伝わる江戸の豪商"],["紀州藩主","江戸時代、寺を保護した"]],"deep":["三井水は «清浄水»«楊柳水»«吉祥水» の三つ。環境省の «名水百選» にも選ばれています。","多宝塔（1449年）は室町時代の様式をよく伝える塔で、楼門（1509年）とあわせて中世の建物が境内に残ります。","大千手十一面観音像は木造の立像として日本最大級で、多くの人が一本一本の木材を寄進してつくられました。","紀伊国屋文左衛門は実在の人物ですが、出身地や若いころの話には不明な点が多く、結縁坂の話は伝承です。","桜の標本木があるのは、全国でも寺の境内では珍しい例です。気象台の職員が花の数を数えて開花を判断します。","西国三十三所の巡礼は、第1番の那智・青岸渡寺から海沿いに北上し、第2番の紀三井寺、第3番の粉河寺へと進むのが古くからの順路です。紀州は巡礼の «出発の国» でした。"],"look":["231段の石段 «結縁坂»","三井水の一つ «清浄水» の滝","本堂前からの和歌浦の眺め","室町時代の多宝塔と楼門","新仏殿の大千手十一面観音"],"q":["紀三井寺の «三井» とは何のこと?","境内にわく三つの井戸（清浄水・楊柳水・吉祥水）のことです。"],"koji":[],"myth":"開山の話と、結縁坂の紀伊国屋文左衛門の話は伝承。","img":["西国三十三所","紀伊国屋文左衛門","和歌浦"],"wp":"紀三井寺","rel":{"ev":[],"grave":[]},"ph":[["c:7/7c/Kimiidera_Wakayama03n4272.jpg",2848,4272,"紀三井寺"],["c:0/01/Kimiidera_Wakayama11n4272.jpg",4272,2848],["c:0/09/Kimiidera_Wakayama10n4272.jpg",4272,2848],["c:1/1a/Kimiidera_Wakayama06n3200.jpg",4272,2848],["c:9/9a/Kimiidera_Tah%C5%8Dt%C5%8D.jpg",2736,3648],["c:2/27/Kimiidera_Rokkakudo.jpg",3648,2736],["c:4/45/Kimii_temple_funicular_car.jpg",3648,2736],["c:4/45/Kimiidera_shoro.jpg",3264,2448]]},{"id":"30_toshogu","n":"紀州東照宮（和歌祭）","yomi":"きしゅうとうしょうぐう","cat":"寺社","rank":"A","y":1621,"era":["edo"],"sh":"国の重要文化財（本殿・拝殿・唐門・楼門など）","ad":"和歌山市和歌浦西","st":"JR和歌山駅からバスで約25分、«権現前» 下車すぐ","la":34.1775,"lo":135.172,"hook":"108段の急な石段を登ると、極彩色の社殿が現れる。«関西の日光» と呼ばれる、家康をまつる社。","lead":"紀州東照宮は、紀州藩の初代藩主・徳川頼宣が、父の徳川家康をまつるために1621年に建てた神社です。朱色の楼門と、色あざやかな彫刻で飾られた社殿は国の重要文化財。毎年5月の «和歌祭» は、400年の歴史をもつ祭りです。","story":["1619年、家康の十男・徳川頼宣が紀州55万石の藩主としてやってきました。家康はすでに亡くなり、日光東照宮に神としてまつられていました。«父上を、この紀州でもおまつりしたい» ── 頼宣が選んだのは、和歌浦を見下ろす雑賀山の中腹でした。","1621年、社殿が完成します。参道には108段の石段がそびえ、«侍坂（さむらいざか）» と呼ばれます。息を切らして登りきると、朱塗りの楼門、その奥に金や極彩色で飾られた唐門と本殿が現れます。日光に負けないほどの華やかさから、«関西の日光» と呼ばれるようになりました。","社殿の彫刻は名工・左甚五郎、ふすま絵などは狩野探幽の作と伝わります。ひとつひとつの彫刻に鳥や花、霊獣が生き生きと刻まれ、見ていると時間を忘れてしまいます。","完成の翌年、1622年から始まったのが «和歌祭» です。神輿が108段の石段を一気にかけ下りる «神輿おろし» は、祭り最大の見せ場。武者行列や雑賀踊など、紀州の町人文化を伝える行列が続きます。«紀州の祭りの中の祭り» といわれました。","頼宣の死後、頼宣も «南龍公» として一緒にまつられました。家康を慕った息子が、いまは父とともにここで和歌浦の海を見守っています。"],"tl":[["1619年","徳川頼宣が紀州藩主となる"],["1621年","紀州東照宮が完成"],["1622年","和歌祭が始まる"],["1671年","頼宣が亡くなり、のちに合わせてまつられる"],["現在","5月の和歌祭で神輿おろしが行われる"]],"who":[["徳川家康","まつられている神。頼宣の父"],["徳川頼宣","紀州藩初代藩主。東照宮を建てた"],["左甚五郎","社殿の彫刻の作者と伝わる名工"],["狩野探幽","社殿の絵の作者と伝わる絵師"]],"deep":["社殿は本殿・石の間・拝殿がつながる «権現造» で、日光東照宮と同じ形式です。江戸初期の東照宮建築の姿をよく残しています。","«侍坂» の名は、武士が参拝のために登った坂だからとも、祭りの行列にちなむともいわれます。石段は急なので足元に注意が必要です。","和歌祭の «神輿おろし» は、重い神輿を担いだまま108段を一気に下る勇壮なもので、見物人も多く集まります。","左甚五郎・狩野探幽の作という話は伝承で、実際の作者は確定していません。「伝」がつく作品として見るのがよいでしょう。","社殿の内部は通常の参拝で見られる範囲が限られます。拝観の範囲や時間は事前に確認しましょう。","頼宣は «南海の龍» とも呼ばれた気性の激しい大名で、紀州藩の城下町づくりや藩の基礎を築きました。「南龍公」はその死後のよび名です。","東照宮は全国に数多くつくられましたが、紀州東照宮は御三家がつくったものとして格式が高く、尾張・水戸の東照宮と並べて語られることもあります。"],"look":["108段の侍坂と、上から振り返る和歌浦","朱塗りの楼門","極彩色の唐門の彫刻","5月の和歌祭の神輿おろし"],"q":["紀州東照宮の石段 «侍坂» は何段?","108段です。和歌祭では神輿がこの石段を一気にかけ下ります。"],"koji":[],"myth":"左甚五郎・狩野探幽の作という話は伝承。","img":["徳川頼宣","和歌祭","紀州藩"],"wp":"紀州東照宮","rel":{"ev":[],"grave":[]},"ph":[["c:7/72/Kisyu_Toshogu_tomon.jpg",3264,2448,"紀州東照宮"],["c:8/8d/%E7%B4%80%E5%B7%9E%E6%9D%B1%E7%85%A7%E5%AE%AE_%E5%85%A5%E5%8F%A3.jpg",4032,3024],["c:8/8e/%E7%B4%80%E5%B7%9E%E6%9D%B1%E7%85%A7%E5%AE%AE_%E4%BE%8D%E5%9D%82.jpg",3024,4032],["c:1/1a/Kisyu_Toshogu_Torii.jpg",3740,2704],["c:f/fc/Kisyu_Toshogu_sando2.jpg",3264,2448],["c:9/94/Kisyu_Toshogu_romon2.jpg",3264,2448],["c:3/31/Kisyu_Toshogu_Benzaitensha.jpg",3264,2448],["c:0/0a/Tokugawa_Yorinobu.jpg",588,607,"徳川頼宣"]]},{"id":"30_tamatsushima","n":"玉津島神社（和歌の聖地）","yomi":"たまつしまじんじゃ","cat":"寺社","rank":"A","y":724,"era":["nara","heian"],"sh":"","ad":"和歌山市和歌浦中","st":"JR和歌山駅からバスで約25分、«玉津島神社前» 下車すぐ","la":34.181,"lo":135.1748,"hook":"聖武天皇がその景色に心を奪われ、«この浦を守れ» と命じた。和歌の神がすむ、万葉の入り江の社。","lead":"玉津島神社は、和歌浦の入り江にある神社です。まつられている衣通姫（そとおりひめ）は和歌の神として知られ、住吉大社・柿本神社とならんで «和歌三神» の一つとされました。奈良時代から多くの歌人があこがれた «和歌の聖地» です。","story":["大昔、このあたりは海にいくつもの小さな島が浮かぶ、美しい入り江でした。島々は «玉津島» と呼ばれ、まるで宝石（玉）が海に並んでいるようだったといいます。","724年、即位したばかりの聖武天皇がこの地を訪れました。潮が満ちたり引いたりする入り江、飛びかう鶴、緑の島々。天皇はその景色に深く感動し、«この浦の景色を守り、神をまつれ» と命じて、番人を置いたと『続日本紀』に記されています。天皇はこの地を «明光浦（あかのうら）» と名づけました。","このとき同行した歌人・山部赤人がよんだのが、«若の浦に潮満ち来れば潟を無み葦辺をさして鶴鳴き渡る» という歌です。潮が満ちて干潟がなくなると、鶴が葦の岸辺をめざして鳴きながら飛んでいく ── 目に浮かぶような情景は、『万葉集』の名歌として今も親しまれています。","平安時代になると、玉津島の神は «和歌の神» として都の歌人たちにあがめられました。まつられている衣通姫は、美しさが衣を通して輝くほどだったと伝わる伝説の姫で、歌にもすぐれていたとされます。歌人たちは歌の上達を願ってここへお参りし、多くの歌を奉納しました。","神社の裏手の小さな山 «奠供山（てんぐやま）» は、聖武天皇が登って景色を眺めたと伝わる場所です。潮の満ち引きは今も変わらず、赤人が見た風景の名残が、和歌浦の干潟に残っています。"],"tl":[["724年","聖武天皇が行幸し、この地を守るよう命じる"],["724年","山部赤人が «若の浦に…» の歌をよむ"],["平安時代","和歌の神として歌人たちにあがめられる"],["2010年","和歌浦が国の名勝に指定される"],["2017年","«絶景の宝庫 和歌の浦» が日本遺産に"]],"who":[["聖武天皇","724年にこの地を訪れ、景観を守るよう命じた"],["山部赤人","行幸に同行した万葉歌人"],["衣通姫","まつられている伝説の姫。和歌の神"]],"deep":["«和歌三神» の組み合わせには諸説あり、玉津島神社（衣通姫）・住吉大社（住吉明神）・柿本人麻呂をあげるのがよく知られた形です。","祭神は稚日女尊・息長足姫尊（神功皇后）・衣通姫尊・明光浦霊の四柱とされます。衣通姫は後から加えられたとも考えられています。","聖武天皇が «守戸（しゅこ）» を置いて景観の保護を命じたことは、日本で最も古い «景観を守る» 取り組みの一つともいわれます。","奠供山には、明治時代の末に旅館が設けたエレベーターがあり、日本で初めての屋外エレベーターだったともいわれます。今は残っていません。","境内には、小野小町が袖を掛けたと伝わる «袖掛稲荷» もあります。これは伝承です。","神社のそばを流れる入り江は、もとは海に浮かぶ島々の間の水路でした。江戸時代以降の埋め立てや砂の堆積で地形が大きく変わり、«玉津島» の島々は今では陸続きの小山になっています。"],"look":["玉津島神社の本殿と鳥居","奠供山（登れる。和歌浦を見わたせる）","山部赤人の歌碑","周辺の干潟の潮の満ち引き"],"q":["山部赤人の歌で、潮が満ちたとき鳴きながら飛んでいった鳥は?","鶴です。«葦辺をさして鶴鳴き渡る» とよまれました。"],"koji":[{"w":"若の浦に潮満ち来れば潟を無み葦辺をさして鶴鳴き渡る","m":"山部赤人の歌。潮が満ちて干潟がなくなり、鶴が葦の岸辺へ鳴き渡っていく情景"}],"myth":"衣通姫の伝説、小野小町の袖掛の話、奠供山のエレベーターが «日本初» かどうかは伝承・諸説を含む。","img":["山部赤人","聖武天皇","衣通姫"],"wp":"玉津島神社","rel":{"ev":[],"grave":[]},"ph":[["c:f/f4/Tamatsushima-shrine.jpg",576,460,"玉津島神社"],["c:8/80/250830_Tamatsushima-jinja%2C_Wakayama%2C_Japan04s3.jpg",3648,5472],["c:0/06/Tamatsushima-jinja1.jpg",3264,2448],["c:3/35/Sanj%C5%ABrokkasen-gaku_-_6_-_Kan%C5%8D_Tan%E2%80%99y%C5%AB_-_Yamabe_no_Akahito.jpg",450,640,"山部赤人"],["c:3/3f/Emperor_Shomu.jpg",1876,3132,"聖武天皇"],["c:8/83/ChinunoMiyaAto.jpg",4288,2848,"衣通姫"]]},{"id":"30_wakanoura","n":"和歌浦（万葉の «若の浦»）","yomi":"わかのうら","cat":"町","rank":"A","y":724,"era":["nara","heian","edo"],"sh":"国指定名勝","ad":"和歌山市和歌浦","st":"JR和歌山駅からバスで約25分、«不老橋» 下車","la":34.1795,"lo":135.176,"hook":"«若の浦» は、やがて «和歌の浦» と書かれるようになった。歌人があこがれ、殿さまが愛した、日本の «絶景» の原点。","lead":"和歌浦は、和歌山市の南にある入り江とその周辺の景勝地です。奈良時代に聖武天皇が訪れ、『万葉集』に歌われてから、1300年にわたって人々に愛されてきました。干潟や小島、江戸時代の石橋などが残り、国の名勝に指定されています。","story":["和歌浦は、紀の川の南、片男波（かたおなみ）という細長い砂州に守られた入り江です。潮が引くと広い干潟が現れ、満ちると一面の海になります。この変化する景色が、古代の人々の心をとらえました。","724年、聖武天皇がこの地を訪れ、山部赤人が «若の浦に潮満ち来れば…» と歌いました。もともと «若の浦» と書かれていたこの地は、平安時代になると «和歌の浦» と書かれるようになります。«和歌の神がいる浦» というイメージが重なったのです。都の歌人たちは、実際に来たことがなくても和歌浦を歌によみました。","江戸時代、和歌浦は紀州藩の «名所» として整えられました。初代藩主・徳川頼宣は、母の養珠院（お万の方）のために、入り江に浮かぶ妹背山に多宝塔を建てました。10代藩主・徳川治宝（はるとみ）のころには、アーチ形の石橋 «不老橋» がかけられます。","不老橋は1851年の完成。東照宮の祭りのとき、殿さまや神さまが通るための特別な橋だったといわれます。石の欄干には、雲のような模様がきざまれています。«なぜ海辺にこんな立派な橋が?» ── それは、和歌浦が紀州徳川家にとって大切な祭りの舞台だったからです。","2010年に国の名勝、2017年に日本遺産に選ばれた和歌浦。潮の満ち引きの中に、万葉の歌と殿さまの祭りの記憶が重なっています。"],"tl":[["724年","聖武天皇が行幸、山部赤人が歌をよむ"],["平安時代","«和歌の浦» と書かれ、歌枕として有名に"],["江戸時代初め","徳川頼宣が妹背山に多宝塔を建てる"],["1851年","不老橋がかけられる"],["2010年","国の名勝に指定"],["2017年","日本遺産 «絶景の宝庫 和歌の浦» に認定"]],"who":[["山部赤人","万葉歌人。和歌浦を歌った"],["聖武天皇","724年に行幸"],["徳川頼宣","紀州藩初代藩主。妹背山の多宝塔などを整えた"],["養珠院（お万の方）","頼宣の母。妹背山に題目石を奉納したと伝わる"]],"deep":["«歌枕» とは歌によまれる名所のこと。和歌浦は実際の景色よりも、歌の世界の中で理想化された «風景のイメージ» として広まりました。","不老橋は «御成道» の一部で、東照宮の和歌祭の際に使われたと考えられています。アーチ形の石橋は九州の技術の影響ともいわれます。","妹背山の «海禅院» の多宝塔と、お万の方が経文を刻ませたと伝わる題目石は、徳川家の信仰を伝える遺構です。","片男波は砂州で、今は海水浴場や公園になっています。«片男波» の名は、赤人の歌の «潟を無み» から来たという説があります。","和歌浦の範囲には、玉津島神社・紀州東照宮・和歌浦天満宮・紀三井寺など、ほかのカードの場所もふくまれます。まとめて歩くと物語がつながります。"],"look":["アーチ形の不老橋","妹背山と三断橋","片男波の干潟（潮の引いた時間）","和歌浦天満宮や東照宮からの眺め"],"q":["«若の浦» は、平安時代にどんな字で書かれるようになった?","«和歌の浦»。和歌の神がまつられる浦というイメージが重なりました。"],"koji":[],"myth":"片男波の名の由来、不老橋の用途には諸説がある。","img":["不老橋","片男波","妹背山 (和歌山市)"],"wp":"和歌浦","rel":{"ev":[],"grave":[]},"ph":[["c:b/b4/Wakanoura_viewed_from_Mount_Takozushi.jpg",6016,4000],["c:e/ee/Kankaikaku_Wakanoura_Wakayama_Japan01n.jpg",4912,3264],["c:9/94/Kaizenin_Wakanoura_Wakayama_Japan01n.jpg",4800,3200],["c:f/f2/Imoseyama_Wakanoura_Wakayama_Japan01bs5.jpg",4650,3100],["c:a/a1/250830_Wakanoura-Ashibe-an_Wakayama_Wakayama_pref_Japan02s3.jpg",5472,3648],["c:4/4f/250830_Tamatsushima-jinja%2C_Wakayama%2C_Japan02s3.jpg",5472,3648],["c:0/0d/250830_Shiogama-jinja%2C_Wakayama%2C_Japan02s3.jpg",5472,3648],["c:9/9b/250830_Shiogama-jinja%2C_Wakayama%2C_Japan01s3.jpg",5472,3648]]},{"id":"30_yosuien","n":"養翠園（紀州藩主の別邸庭園）","yomi":"ようすいえん","cat":"大名屋敷","rank":"A","y":1818,"era":["edo"],"sh":"国指定名勝","ad":"和歌山市西浜","st":"JR和歌山駅からバスで約20分、«養翠園前» 下車すぐ","la":34.2123,"lo":135.156,"hook":"池の水は海の水。潮の満ち引きで水面が上下する、殿さまの海辺の庭。","lead":"養翠園は、紀州藩の10代藩主・徳川治宝（はるとみ）が江戸時代の1818年につくった別邸の庭園です。池に海水を引き入れた «汐入りの池» が特徴で、国の名勝に指定されています。池に三つの橋がかかった景色は、中国の名所をまねたものといわれます。","story":["紀州藩10代藩主の徳川治宝は、学問や芸術を愛した殿さまでした。茶の湯や焼き物にも深い関心をもち、藩の文化を大きく育てました。その治宝が、城の南の海辺に別邸をつくりました。それが養翠園です。","庭の中心は、大きな池です。この池、じつは海水が引きこまれています。潮の満ち引きにあわせて水位が少し変わり、海の魚が泳いでいることもあります。«なぜわざわざ海水を?» ── 海辺の土地の特性をいかし、海とつながる景色を楽しもうとしたのでしょう。","池には、石の橋を三つつないだ «三ツ橋» がかかっています。中国・杭州の西湖にある堤をまねたものといわれ、当時の大名たちがあこがれた中国趣味が感じられます。池のまわりには松が植えられ、その緑が水面に映る様子が «養翠» の名にふさわしい景色をつくっています。","庭の一角には、治宝が使った茶室や数寄屋風の建物も残ります。殿さまはここで茶を楽しみ、海の風に吹かれながら客をもてなしたのでしょう。","明治以降、別邸は民間の手にわたり、今も所有者が大切に守りながら公開しています。海水を引きこんだ大名庭園は、東京の浜離宮恩賜庭園など数少なく、とても貴重です。"],"tl":[["1818年","徳川治宝が別邸と庭園の造営を始める"],["江戸時代後期","治宝が茶や文化の場として使う"],["明治時代","民間の所有となる"],["1985年","国の名勝に指定される"]],"who":[["徳川治宝","紀州藩10代藩主。養翠園をつくった"],["所有者の家","明治以降、庭園を守り続けている"]],"deep":["汐入りの池は、干満の差を使って水を入れかえる仕組みで、景色だけでなく池の水質を保つ役割もあります。","«三ツ橋» は西湖の «蘇堤» を写したものとされ、江戸時代の大名庭園に多い «縮景（有名な景色を小さく写す）» の手法です。","治宝は «偕楽園焼» などのお庭焼きを始めたことでも知られ、紀州に京都の陶工を招くなど、文化の保護に熱心でした。","庭園は現在も個人の所有で、入園は有料。公開日や時間は季節で変わることがあるので確認が必要です。","近くには紀州藩の «湊御殿» もあり、城下町と海をつなぐこの一帯は、殿さまの海辺の遊びの舞台でした。","池の護岸や飛び石には青石（緑色片岩）が使われています。紀州は青石の産地として知られ、大名庭園の石にも地元の石がよく使われました。","«養翠» という名は、松の翠（みどり）を養う、という意味にとれることばで、松の緑と水面の景色を大切にした庭の性格を表しています。","庭は池のまわりを歩きながら景色の変化を楽しむ «池泉回遊式»。歩く場所によって、橋や松、遠くの山の見え方が次々と変わるように計算されています。","茶室や建物は江戸時代の姿をよく残し、大名の別邸の暮らしを知る手がかりにもなっています。"],"look":["海水を引き入れた大きな池","池にかかる三ツ橋","池を囲む松林と遠くの山の «借景»","治宝ゆかりの茶室や建物"],"q":["養翠園の池の水は、どこから来ている?","海です。海水を引き入れた «汐入りの池» になっています。"],"koji":[],"myth":"三ツ橋が西湖を写したという話はいわれ。造営年・完成年には諸説。","img":["徳川治宝","浜離宮恩賜庭園","大名庭園"],"wp":"養翠園","rel":{"ev":[],"grave":[]},"ph":[["c:0/04/Wakayama_Yosuien07bs4272.jpg",4272,2848,"養翠園"],["c:e/ea/Wakayama_Yosuien16n4272.jpg",4272,2848],["c:c/c5/Wakayama_Yosuien13n4272.jpg",4272,2848],["c:6/6b/Wakayama_Yosuien09bs4272.jpg",4272,2848],["c:b/b2/Wakayama_Yosuien06bs4272.jpg",4272,2848],["c:7/76/Wakayama_Yosuien03bs4272.jpg",4272,2848],["c:9/9f/Tokugawa_Harutomi.jpg",1278,1638,"徳川治宝"],["c:c/cf/2018_Hama-riky%C5%AB_Garden_02.jpg",2500,1682,"浜離宮恩賜庭園"]]},{"id":"30_awashima","n":"淡嶋神社（加太）","yomi":"あわしまじんじゃ","cat":"寺社","rank":"A","y":400,"era":["kofun","edo"],"sh":"","ad":"和歌山市加太","st":"南海加太線 加太駅から歩いて約20分","la":34.2757,"lo":135.059,"hook":"境内をうめつくす、何万体もの人形たち。ひな人形を海へ流す «ひな流し» の神社。","lead":"淡嶋神社は、和歌山市の北西、加太の海辺にある神社です。全国にある淡島神社・粟島神社の総本社とされ、女性の病気や安産の神として信仰されてきました。毎年3月3日には、ひな人形を小舟にのせて海へ流す «ひな流し» が行われます。","story":["加太の沖には、友ヶ島という島々が浮かんでいます。昔、神功皇后が朝鮮半島からの帰り道、嵐にあいました。«どうか助けたまえ» と祈って苫（とま）を海に投げると、それが流れ着いた島に船が導かれ、無事だったと伝わります。その島が友ヶ島で、そこにまつったのが始まりとされます。","その後、仁徳天皇のころに、神社は島から加太の浜に移されたと伝わります。まつられている少彦名命（すくなひこなのみこと）は、医薬の神。とくに女性の病気を治してくれる神として、各地から女性たちが参拝しました。","江戸時代には、«淡島願人» と呼ばれる人たちが、小さな社を背負って全国を回り、淡島の神の御利益を広めました。こうして淡島信仰は日本中に広まり、各地に淡島神社ができていきました。","境内を歩くと、驚くほどたくさんの人形が並んでいます。ひな人形、市松人形、招き猫、たぬき…。«捨てられないけれど、どうしよう» という人形が全国から納められ、その数は約2万体ともいわれます。","3月3日の «ひな流し» では、納められたひな人形を白木の小舟にのせ、海へと送り出します。子どもの健やかな成長と、人形への感謝をこめた祈りです。海に消えていく小舟を、多くの人が見送ります。"],"tl":[["神功皇后のころ","友ヶ島に神をまつったと伝わる"],["仁徳天皇のころ","加太の浜に社を移したと伝わる"],["江戸時代","淡島願人が全国に信仰を広める"],["現在","毎年3月3日にひな流しが行われる"]],"who":[["少彦名命","まつられている神。医薬の神"],["神功皇后","神社の始まりの伝承に登場"],["淡島願人","江戸時代に信仰を全国に広めた人々"]],"deep":["«淡嶋» と «淡島»«粟島» は表記がさまざま。全国に千以上あるともいわれる淡島系の神社の中心がここだとされています。","ひな流しは、人形に災いを移して流す古い «流し雛» の風習と結びついています。人形は儀式のあと、海で回収して供養されるとも聞かれます。","淡島信仰は、とくに女性の病気・安産・子授けに御利益があるとされ、江戸時代の女性たちの切実な願いを受けとめてきました。","3月3日は旧暦の上巳の節句にあたり、もともと水辺で身を清める日でした。ひな祭りと海辺の神社が結びついた形です。","友ヶ島の «神島» は、淡嶋神社の元の場所と伝わる島で、ふだんは上陸できない場所とされます。","少彦名命は大国主命とともに国づくりをしたとされる小さな神で、医薬やまじないの神として信仰されてきました。淡島信仰では、とくに女性の守り神の性格が強くなりました。","人形供養は一年を通して受けつけていますが、方法や費用は神社の案内に従う必要があります。","加太は古代から紀淡海峡を渡る海の道の要所で、淡路島や四国へ向かう港でもありました。神社が海の守り神としてもあがめられたのはそのためです。"],"look":["境内をうめつくす人形たち","本殿の前の人形供養の場所","3月3日のひな流しの小舟","加太の港と友ヶ島の眺め"],"q":["淡嶋神社で毎年3月3日に行われる行事は?","«ひな流し»。ひな人形を小舟にのせて海へ送り出します。"],"koji":[],"myth":"神功皇后の話・仁徳天皇のころの遷座は社伝による伝承。人形の数は目安。","img":["加太 (和歌山市)","流し雛","少名毘古那神"],"wp":"淡嶋神社","rel":{"ev":[],"grave":[]},"ph":[["c:5/58/Awashima-jinja%2C_haiden.jpg",5976,3938,"淡嶋神社"],["c:9/92/Awashima-jinja%2C_torii.jpg",6016,4000],["c:7/7a/%E6%B7%A1%E5%B3%B6%E7%A5%9E%E7%A4%BE%E4%BA%BA%E5%BD%A2%E3%83%BB%E7%BE%A4%E3%82%8C_204.jpg",1280,960],["c:4/41/%E6%B7%A1%E5%B3%B6%E7%A5%9E%E7%A4%BE%E4%BA%BA%E5%BD%A2%E3%83%BB%E5%A4%A9%E7%8B%97%E3%81%AE%E9%9D%A2_206.jpg",1280,960],["c:5/5b/%E6%B7%A1%E5%B3%B6%E7%A5%9E%E7%A4%BE%E4%BA%BA%E5%BD%A2up_209.jpg",1280,960],["c:8/86/%E6%B7%A1%E5%B3%B6%E7%A5%9E%E7%A4%BE%E4%BA%BA%E5%BD%A2_203.jpg",1280,960],["c:e/e1/%E6%B7%A1%E5%B3%B6%E7%A5%9E%E7%A4%BE%E4%BA%BA%E5%BD%A22%E4%B8%87%E4%BD%93_207.jpg",1280,960],["c:e/e9/%E6%B7%A1%E5%B3%B6%E7%A5%9E%E7%A4%BE_197.jpg",960,1280]]},{"id":"30_tomogashima","n":"友ヶ島の砲台跡（由良要塞）","yomi":"ともがしまのほうだいあと","cat":"島","rank":"A","y":1890,"era":["meiji","showa"],"sh":"","ad":"和歌山市加太（友ヶ島・沖ノ島）","st":"南海加太線 加太駅から歩いて約10分の加太港から、船で約20分（季節運航・天候で欠航あり）","la":34.28,"lo":135.0,"hook":"レンガの壁にツタがからむ、森の中の砲台跡。一度も敵を撃つことのなかった «要塞の島»。","lead":"友ヶ島は、和歌山市の加太の沖、紀淡海峡に浮かぶ四つの島の総称です。明治時代、大阪湾を守るための «由良要塞» の一部として砲台が造られました。今はレンガ造りの砲台跡が森の中に残り、不思議な雰囲気の島として人気です。","story":["友ヶ島は、古くから修験道の行場でした。役行者（えんのぎょうじゃ）が修行したと伝わり、葛城修験の «一番目の行場» とされてきました。島には今も «序品窟（じょぼんくつ）» という修行の場が残ります。","明治時代、日本は外国の軍艦から大阪湾や大阪・神戸を守るため、海峡の両岸と島々に砲台を造ることにしました。紀淡海峡は大阪湾の入口。«ここを守れば大阪を守れる»。こうして明治20〜30年代に、友ヶ島・淡路島・加太などに砲台が次々と築かれ、«由良要塞» とよばれました。","島に残る第3砲台跡は、とくに大きな砲台です。赤いレンガのトンネルや弾薬庫、兵士が使った部屋が、森の中に静かに並んでいます。ひんやりとした暗い通路を歩くと、ここで大砲を守っていた兵士たちの姿が思い浮かびます。","けれど、友ヶ島の砲台は一度も実戦で砲弾を撃つことはありませんでした。1945年に戦争が終わると要塞は廃止され、島は静けさを取りもどしました。«使われなかった要塞» は、戦争のない時代がつづくことの大切さを、無言で語っているようです。","いまはハイキングやキャンプの島として多くの人が訪れます。森にのみこまれていくレンガの建物は、アニメ映画の世界のようだと話題になりました。訪れるときは、ここがかつて兵士たちの持ち場だったことにも思いを寄せたいものです。"],"tl":[["飛鳥時代","役行者が修行したと伝わる"],["1872年","友ヶ島灯台が点灯したとされる"],["明治20〜30年代","由良要塞の砲台が次々と造られる"],["1945年","終戦にともない要塞が廃止される"],["現在","瀬戸内海国立公園の一部として公開"]],"who":[["役行者","修験道の開祖。友ヶ島で修行したと伝わる"],["陸軍の兵士たち","由良要塞の砲台を守った"]],"deep":["由良要塞は、淡路島の由良（洲本市）にちなむ名前で、紀淡海峡をはさむ淡路島・友ヶ島・和歌山側の加太や深山に砲台が配置されていました。","第3砲台跡には、大砲を置いた砲座、その下の弾薬庫、兵舎などが残り、レンガの積み方の «イギリス積み» なども観察できます。","砲台跡は整備されていない部分も多く、暗く足元の悪い場所があります。懐中電灯を持ち、立入禁止の場所には入らないようにしましょう。","友ヶ島灯台は明治初期の洋式灯台の一つで、今も現役です。灯台の歴史と要塞の歴史が一つの島に重なっています。","沖ノ島・地ノ島・虎島・神島の四島のうち、観光で上陸するのはおもに沖ノ島です。神島は淡嶋神社ゆかりの島とされます。","明治時代の日本は、東京湾・大阪湾・下関海峡など、重要な海の入口に次々と要塞を築きました。由良要塞もその一つで、当時の国防の考え方を今に伝える戦争遺跡です。"],"look":["第3砲台跡のレンガのトンネルと弾薬庫","第2砲台跡（海辺の砲台）","友ヶ島灯台","タカノス山展望台からの紀淡海峡の眺め"],"q":["友ヶ島の砲台は、何を守るために造られた?","大阪湾（大阪・神戸）を外国の軍艦から守るためです。由良要塞の一部でした。"],"koji":[],"myth":"役行者の修行の話は伝承。灯台の点灯年は目安。","img":["由良要塞","役小角","紀淡海峡"],"wp":"友ヶ島","rel":{"ev":[],"grave":[]},"ph":[["c:1/18/%E5%8F%8B%E3%81%8C%E5%B3%B6%E3%83%BB%E7%B4%80%E6%B7%A1%E6%B5%B7%E5%B3%A1PA071003.jpg",1280,960,"友ヶ島"],["c:4/4c/Tomoga-shima_Islands_Aerial_photograph.2022.jpg",10801,5735],["c:5/5b/Tomogashima_tonikaku.jpg",1200,1600],["c:6/60/Tomogashima_kottida.jpg",1600,1200],["c:a/ad/Tomogashima_Nandakono.jpg",1600,1200],["c:a/a4/Tomogashima_Kaidan_Uekara_kuruzo.jpg",1600,1200],["c:b/b1/%E5%8A%A0%E5%A4%AA%E7%A0%B2%E5%8F%B0%E7%94%B1%E8%89%AF%E8%A6%81%E5%A1%9E_%E3%83%AC%E3%83%B3%E3%82%AC%E5%80%89%E5%BA%ABPA070938.jpg",1280,960,"由良要塞"],["c:f/fe/En_no_Gy%C5%8Dja%2C_Kamakura_period%2C_polychromed_wood.JPG",3017,4760,"役小角"]]},{"id":"30_chohoji","n":"長保寺（紀州藩主 歴代の墓所）","yomi":"ちょうほうじ","cat":"墓所","rank":"A","y":1666,"era":["heian","kamakura","edo"],"sh":"国宝（本堂・多宝塔・大門）／国指定史跡（紀州藩主徳川家墓所）","ad":"海南市下津町上","st":"JR紀勢本線 下津駅から歩いて約30分（車が便利）","la":34.109,"lo":135.173,"hook":"本堂・塔・門のすべてが国宝。その裏山には、紀州徳川家の殿さまたちが静かに眠っている。","lead":"長保寺は、平安時代の1000年に開かれたと伝わるお寺です。鎌倉〜南北朝時代に建てられた本堂・多宝塔・大門がそろって国宝になっている、全国でもめずらしい寺です。江戸時代には紀州藩の菩提寺となり、歴代藩主の墓所が山の斜面に広がっています。","story":["寺の名前 «長保» は、平安時代の年号です。一条天皇の願いによって、性空（しょうくう）上人が1000年（長保2年）に開いたと伝わります。紀州の山あいの小さな谷に、都の天皇とつながる寺が生まれたのです。","山門をくぐると、まず出迎えるのが大門（1388年）。その奥に、本堂（1311年）と多宝塔（1357年）が並びます。いずれも鎌倉〜南北朝時代の建物で、国宝です。«一つの寺の本堂・塔・門がそろって国宝» ── これほどの寺は全国でもほとんどありません。","江戸時代の1666年、紀州藩初代藩主・徳川頼宣は、この寺を徳川家の菩提寺と定めました。«なぜ城下から遠いこの寺を?» ── 山に囲まれた静かな地形が、墓所にふさわしいと考えられたのかもしれません。","本堂の裏山には、頼宣をはじめ歴代藩主の墓がならび、その広さは約1万坪ともいわれます。石の鳥居、灯籠、そして大きな墓石。どの墓にも、殿さまを慕った家臣たちの思いがこめられています。ただし、将軍になった5代・吉宗と13代・慶福（14代将軍家茂）の墓は江戸にあります。","ひっそりとした山の中で、国宝の建物と殿さまたちの墓が同じ時を過ごしています。訪れる人は少なく、鳥の声だけが響く ── そんな静けさこそ、長保寺のいちばんの魅力かもしれません。"],"tl":[["1000年","一条天皇の勅願で性空上人が開いたと伝わる"],["1311年","本堂が建てられる（国宝）"],["1357年","多宝塔が建てられる（国宝）"],["1388年","大門が建てられる（国宝）"],["1666年","徳川頼宣が紀州徳川家の菩提寺とする"],["2008年","紀州藩主徳川家墓所が国の史跡に指定"]],"who":[["性空上人","寺を開いたと伝わる平安時代の僧"],["一条天皇","寺の創建を願ったと伝わる天皇"],["徳川頼宣","紀州藩初代藩主。長保寺を菩提寺とした"],["徳川吉宗","紀州藩5代藩主から8代将軍に。墓は江戸にある"]],"deep":["本堂は和様を基本とした落ち着いた建物で、鎌倉時代後期の様式をよく伝えます。多宝塔も均整のとれた美しい塔です。","大門は三間一戸の八脚門で、鎌倉時代以来の和様の力強さを見せます。門・本堂・塔の三つがそろって国宝という例は全国でもごく少なく、長保寺の大きな特徴です。","墓所には藩主だけでなく、夫人や一族の墓もあります。墓の形や大きさの変化から、藩の財政や時代の移り変わりを読み取る研究もあります。","藩主の墓所は国の史跡「紀州藩主徳川家墓所」に指定されています。見学には寺の許可や拝観料が必要で、ルールを守ることが大切です。","寺は天台宗で、紀州徳川家の菩提寺となったあとも、藩の手厚い保護を受けました。"],"look":["国宝の大門（入口）","国宝の本堂と多宝塔が並ぶ景色","裏山の紀州藩主の墓所","秋の紅葉（年によって見ごろが変わる）"],"q":["長保寺で国宝になっている三つの建物は?","本堂・多宝塔・大門です。そろって国宝になっている寺は全国でもめずらしいです。"],"koji":[],"myth":"開創の年と開山は寺伝。","img":["徳川頼宣","紀州藩","性空"],"wp":"長保寺","rel":{"ev":[],"grave":[]},"ph":[["c:3/3e/Chohoji03s3200.jpg",3872,2592,"長保寺"],["c:f/fc/Chohoji_%28Kainan%29%2C_daimon.jpg",5568,3712],["c:6/69/Chohoji05s3200.jpg",2500,2650],["c:4/4d/061105_Choho-ji_Kainan_Wakayama_pref_Japan06s8.jpg",3300,2200],["c:e/ef/Chohoji14s3200.jpg",2142,3200],["c:0/02/Chohoji13s3200.jpg",2142,3200],["c:1/18/Chohoji12s3200.jpg",2142,3200],["c:3/30/Chohoji04s3200.jpg",3200,2142]]},{"id":"30_fujishiro","n":"藤白神社と藤白坂（有間皇子の悲劇）","yomi":"ふじしろじんじゃとふじしろざか","cat":"事件","rank":"A","y":658,"era":["asuka","heian"],"sh":"","ad":"海南市藤白","st":"JR紀勢本線 海南駅から歩いて約20分","la":34.1445,"lo":135.2075,"hook":"«天と赤兄と知らむ。吾全ら解らず»。19歳の皇子が命を落とした坂に、いまも歌碑が立つ。","lead":"藤白神社は、熊野への参詣道・熊野古道の «藤白王子» として知られる神社です。すぐ南の藤白坂は、飛鳥時代に有間皇子（ありまのみこ）が処刑された悲しい場所でもあります。坂の途中には皇子の墓碑と、『万葉集』の歌碑が立っています。","story":["658年、飛鳥の都。孝徳天皇の子・有間皇子は19歳でした。父を失い、叔母にあたる斉明天皇と、その子の中大兄皇子が力をもつ時代。皇子は身を守るため、病気のふりをしていたともいわれます。","ある日、蘇我赤兄（そがのあかえ）が皇子に近づき、«天皇の政治には三つの失敗がある» と語りかけました。皇子は «わたしが兵を挙げる時が来た» と応じたといいます。ところが赤兄は、すぐに皇子を捕らえさせたのです。わなだったのでしょうか?","皇子は、斉明天皇と中大兄皇子のいる紀の湯（今の白浜温泉）へ送られました。取り調べで、中大兄に «なぜ謀反を?» と問われた皇子は、«天と赤兄と知らむ。吾全ら解らず»（天と赤兄が知っているでしょう。わたしは何もわかりません）と答えたと『日本書紀』は伝えます。","紀の湯へ向かう途中、皇子は二首の歌をよみました。«家にあれば笥に盛る飯を草枕旅にしあれば椎の葉に盛る»。家ならば器に盛るご飯も、旅の身では椎の葉に盛る ── 心細さのにじむ歌です。そして都へ帰される途中、藤白坂で命を絶たれました。","藤白坂には «有間皇子之墓» の碑と歌碑があり、今も花が手向けられています。坂の上の藤白神社は、のちに熊野へ向かう上皇や貴族たちがお参りする王子社として栄えました。若い皇子の無念を思いながら、静かに坂を歩いてみてください。"],"tl":[["658年","有間皇子が謀反の疑いで捕らえられ、藤白坂で処刑される"],["平安時代","熊野詣が盛んになり、藤白王子が重要な王子社に"],["平安〜鎌倉時代","上皇・貴族の熊野御幸で参拝される"],["江戸時代","藤白坂に丁石地蔵が置かれる"],["現在","熊野古道紀伊路の見どころとして歩かれる"]],"who":[["有間皇子","孝徳天皇の子。藤白坂で処刑された"],["中大兄皇子","のちの天智天皇。皇子を取り調べた"],["蘇我赤兄","皇子を誘い、捕らえさせた人物"],["斉明天皇","当時の天皇。紀の湯に滞在していた"]],"deep":["«天と赤兄と知らむ» の言葉は『日本書紀』斉明天皇4年の条に見えます。赤兄が中大兄の意を受けたわなだったのかどうかは、昔から議論があります。","«磐代の浜松が枝を引き結び…» の歌も有間皇子の作として『万葉集』巻2に残り、«結び松» は旅の無事を祈るまじないでした。","藤白王子は熊野九十九王子の中でも格の高い «五体王子» の一つとされました。近くの «鈴木屋敷» は、全国の鈴木姓の発祥地と伝わります。","藤白坂には、江戸時代に全長を丁ごとに示す地蔵（丁石地蔵）が置かれたと伝わり、坂道を登る目安になりました。","処刑の方法は『日本書紀』に «絞» と記されています。皇子の墓碑は後世に建てられた記念碑で、実際の墓所ではありません。"],"look":["藤白神社の本殿と大きなクスノキ","藤白坂の «有間皇子之墓» の碑と歌碑","坂の途中の丁石地蔵","隣接する鈴木屋敷（公開状況を確認）"],"q":["有間皇子が取り調べで答えた有名な言葉は?","«天と赤兄と知らむ。吾全ら解らず»。天と赤兄が知っている、自分は何もわからない、という意味です。"],"koji":[{"w":"家にあれば笥に盛る飯を草枕旅にしあれば椎の葉に盛る","m":"有間皇子の歌。家なら器に盛るご飯も、旅では椎の葉に盛るという、旅の心細さを詠んだ"}],"myth":"赤兄のわなかどうか、仮病の話は諸説。鈴木姓発祥の話は伝承。","img":["有間皇子","熊野九十九王子","鈴木屋敷"],"wp":"藤白神社","rel":{"ev":[],"grave":[]},"ph":[["c:6/6c/241006_Fujishiro-jinja_Kainan_Wakayama_pref_Japan02s3.jpg",5472,3648,"藤白神社"],["c:4/4f/241006_The_Suzuki-homestead_Kainan_Wakayama_pref_Japan01s3.jpg",5472,3648],["c:7/79/241006_Fujishiro-jinja_Kainan_Wakayama_pref_Japan30s3.jpg",5472,3648],["c:b/b8/241006_Fujishiro-jinja_Kainan_Wakayama_pref_Japan26s3.jpg",5472,3648],["c:a/aa/241006_Fujishiro-jinja_Kainan_Wakayama_pref_Japan15s3.jpg",5472,3648],["c:8/8c/241006_Fujishiro-jinja_Kainan_Wakayama_pref_Japan14s3.jpg",5472,3648],["c:a/ab/241006_Fujishiro-jinja_Kainan_Wakayama_pref_Japan12s3.jpg",5472,3648],["c:b/b7/241006_Fujishiro-jinja_Kainan_Wakayama_pref_Japan09s3.jpg",5472,3648]]},{"id":"30_yuasa_machi","n":"湯浅の町並み（醤油発祥の地）","yomi":"ゆあさのまちなみ","cat":"産業","rank":"A","y":1254,"era":["kamakura","edo"],"sh":"重要伝統的建造物群保存地区","ad":"有田郡湯浅町湯浅","st":"JR紀勢本線 湯浅駅から歩いて約10分","la":34.033,"lo":135.178,"hook":"味噌の桶の底にたまった一滴の汁。それが «醤油» の始まりだった ── そう語り継がれる港町。","lead":"湯浅は、和歌山県中部の海辺の町で、醤油発祥の地といわれています。醤油蔵や古い町家が残る町並みは、国の «重要伝統的建造物群保存地区» に選ばれ、日本遺産にもなっています。今も昔ながらの方法で醤油をつくる蔵があります。","story":["鎌倉時代、紀州由良の興国寺を開いた僧・心地覚心（法燈国師）は、中国の宋で修行して、寺で作られていた «径山寺（きんざんじ）味噌» の作り方を持ち帰ったと伝わります。野菜を刻んで入れた、おかずになる味噌です。","その作り方が近くの湯浅に伝わりました。ある日、味噌を仕込んだ桶の底に、茶色い汁がたまっていることに気づきます。なめてみると «これはうまい!»。この汁を料理に使ったのが、醤油の始まりだと伝わっています。","湯浅には良い水があり、原料の大豆や塩を運ぶ船の港もありました。江戸時代になると、湯浅の醤油づくりは紀州藩の保護を受けて大きな産業になり、たくさんの醤油蔵が並びました。醤油は船で大坂や江戸へ運ばれ、湯浅の職人は千葉の銚子などにも技術を伝えたといわれます。","町を歩くと、格子のある町家、虫籠窓（むしこまど）、そして醤油の香りがただよう蔵に出会います。醤油の原料を運び入れた運河 «大仙堀» の石垣も残っています。細い路地の «小路（しょうじ）» が迷路のように続き、江戸時代の町の形がそのまま残っているのです。","今も老舗の醤油蔵では、木の桶で時間をかけて醤油を仕込んでいます。«最初の一滴» の町は、800年近い時を経ても、醤油の香りに包まれています。"],"tl":[["1254年ごろ","心地覚心が宋から帰国し、径山寺味噌を伝えたとされる"],["鎌倉時代以後","湯浅で醤油づくりが始まったと伝わる"],["江戸時代","紀州藩の保護で醤油産業が栄える"],["1841年","現在も続く老舗醤油蔵の一つが創業"],["2006年","重要伝統的建造物群保存地区に選定"],["2017年","日本遺産 «最初の一滴 醤油醸造の発祥の地 紀州湯浅» に認定"]],"who":[["心地覚心（法燈国師）","径山寺味噌の製法を伝えたとされる僧"],["湯浅の醤油職人","醤油づくりを産業に育て、各地へ技術を伝えた"],["紀州藩","醤油づくりを保護した"]],"deep":["«醤油の起源は湯浅» という話は伝承の性格が強く、醤（ひしお）のような調味料はそれ以前からありました。«溜（たまり）から醤油へ» という流れの一つの物語として理解しましょう。","湯浅の町並みは、醤油醸造にかかわる町家や土蔵が集まる «醸造町» として重伝建に選ばれた点が特徴です。","大仙堀は醤油蔵の裏に接する運河で、船から直接、原料や樽を積み下ろしできました。石垣と蔵が並ぶ景色が残ります。","千葉県の銚子の醤油づくりには、紀州からの移住者が関わったと伝わります。紀州と関東の醤油のつながりは、江戸時代の海の交流を物語ります。","町並みの中には、江戸時代から続く銭湯の建物を公開する資料館などもあり、町の暮らしぶりを知ることができます。"],"look":["醤油蔵が並ぶ北町通り・中町","大仙堀の石垣と蔵","路地の «小路» と虫籠窓の町家","老舗醤油蔵の見学（公開日を確認）"],"q":["醤油の始まりは、何を作る桶の底にたまった汁だったと伝わる?","径山寺味噌の桶です。底にたまった汁が醤油の始まりといわれます。"],"koji":[],"myth":"醤油発祥の話と、銚子への技術伝来の話は伝承の性格が強い。","img":["醤油","径山寺味噌","心地覚心"],"wp":"湯浅町","rel":{"ev":[],"grave":[]},"ph":[["c:6/68/260516_Kadocho_Yuasa_Wakayama_pref_Japan02s3.jpg",5472,3648,"湯浅町"],["c:2/21/260516_Kadocho_Yuasa_Wakayama_pref_Japan04s3.jpg",5472,3648],["c:6/64/Yuasa_Mikan_field_ac.jpg",4080,2720],["c:9/92/Wakayama_Prefectural_Taikyu_High_School_ac.jpg",3957,2638],["c:1/11/Jinsen-ji_Yuasa_main_hall_ac_%281%29.jpg",3953,2635],["c:3/32/Yuasa_Ekikura_ac.jpg",3870,2580],["c:2/26/%E4%BE%8B%E5%A4%A7%E7%A5%AD%E3%81%AE%E6%B8%A1%E5%BE%A1.jpg",2048,1536],["c:6/63/Soy_sauce_2.jpg",1062,889,"醤油"]]},{"id":"30_kokokuji","n":"興国寺（由良・普化尺八と径山寺味噌）","yomi":"こうこくじ","cat":"寺社","rank":"A","y":1258,"era":["kamakura"],"sh":"","ad":"日高郡由良町門前","st":"JR紀勢本線 紀伊由良駅から歩いて約25分（車が便利）","la":33.971,"lo":135.126,"hook":"宋から帰った一人の僧が、味噌と尺八と禅を紀州にもたらした。その三つの «ルーツ» がこの寺にある。","lead":"興国寺は、鎌倉時代に開かれた臨済宗の禅寺です。開山の心地覚心（法燈国師）は中国の宋で修行し、禅の教えとともに、径山寺味噌の製法や、虚無僧が吹く尺八の音楽を伝えたといわれます。«味噌・醤油のふるさと»、«尺八の本山» とも呼ばれる寺です。","story":["始まりは、鎌倉の三代将軍・源実朝の死でした。実朝に仕えていた葛山景倫（かずらやまかげとも）は、主君が討たれると出家して «願性（がんしょう）» と名のり、この由良の地に実朝の菩提をとむらう寺を建てました。1227年のことと伝わります。","願性は、宋で修行していた僧・心地覚心の帰国を待ち、寺に迎えました。覚心は宋で名僧・無門慧開に学び、禅の奥義を身につけていました。1258年、覚心を開山として寺は禅寺となり、やがて «興国寺» の名がつけられます。","覚心が宋から持ち帰ったものは、禅の教えだけではなかったと伝わります。ひとつは、径山寺味噌の作り方。これが近くの湯浅に伝わり、醤油の起こりになったといわれます。もうひとつは尺八の曲。覚心とともに来日した人々が伝えた曲が、のちに虚無僧の吹く «普化尺八» の源流になったとされます。","«なぜ一人の僧がこんなにたくさんのものを?» ── 中世の寺は、学問だけでなく、食べ物や音楽、技術が集まる «文化の窓口» だったのです。","興国寺には、天狗が一夜で寺を建てたという伝説もあり、大きな天狗の面がまつられています。尺八を吹く虚無僧の供養の行事も行われ、禅と音楽と味の歴史が、静かな山門の奥に息づいています。"],"tl":[["1219年","源実朝が鶴岡八幡宮で討たれる"],["1227年","葛山景倫（願性）が実朝の菩提のため寺を建てたと伝わる"],["1254年","心地覚心が宋から帰国"],["1258年","覚心を開山に迎え、禅寺となる"],["南北朝時代","«興国寺» の寺名がつけられたと伝わる"],["1585年","豊臣秀吉の紀州攻めで焼失し、のちに再建"]],"who":[["心地覚心（法燈国師）","開山。宋で修行し、禅・味噌・尺八を伝えたとされる"],["葛山景倫（願性）","源実朝の家臣。出家して寺を建てた"],["源実朝","寺がまず菩提をとむらった将軍"],["無門慧開","宋の禅僧。覚心の師"]],"deep":["覚心は1249年に入宋し、無門慧開の『無門関』を日本に伝えたとされます。『無門関』は日本の禅で広く読まれる公案集です。","«普化尺八» は、禅の一派・普化宗の僧（虚無僧）が修行として吹いた尺八です。興国寺は普化尺八の «根源» とされ、尺八の歴史をたどる人が訪れます。","«興国» の寺名は、南朝の年号 «興国»（1340〜1346年）にちなむとする説があります。","金剛三昧院と同じく、この寺も源実朝の死をきっかけに生まれました。鎌倉の悲劇が紀州の文化を育てたのは興味深いつながりです。","天狗が一夜で伽藍を建てたという話は伝説で、寺の天狗堂にはそれにちなむ大きな天狗面がまつられています。"],"look":["山門と本堂","大きな天狗面をまつる天狗堂","尺八の祖をたたえる碑など","境内の静かな禅寺のたたずまい"],"q":["心地覚心が宋から伝えたとされるもののうち、醤油のもとになったといわれるのは?","径山寺味噌です。その製法が湯浅に伝わり、醤油の起こりになったといわれます。"],"koji":[],"myth":"味噌・尺八の伝来、寺名の由来、天狗の伝説は伝承・諸説。","img":["心地覚心","普化宗","虚無僧"],"wp":"興国寺 (和歌山県由良町)","rel":{"ev":[],"grave":[]},"ph":[["c:6/65/%E8%88%88%E5%9B%BD%E5%AF%BA_-_%E6%9C%AC%E5%A0%82.JPG",2848,2136,"興国寺 (和歌山県由良町)"],["c:7/7a/%E6%B3%95%E7%81%AF%E5%86%86%E6%98%8E%E5%9B%BD%E5%B8%AB.jpg",768,1024,"心地覚心"],["c:a/a3/Myoanji.jpg",1530,1378,"普化宗"],["c:b/b6/A_begging_criminal-J._M._W._Silver.jpg",733,1025,"虚無僧"]]},{"id":"30_dojoji","n":"道成寺（安珍・清姫伝説）","yomi":"どうじょうじ","cat":"伝承","rank":"A","y":701,"era":["asuka","nara","heian"],"sh":"国宝（本尊 千手観音像など）","ad":"日高郡日高川町鐘巻","st":"JR紀勢本線 道成寺駅から歩いて約5分","la":33.909,"lo":135.188,"hook":"恋に破れた娘は大蛇になり、鐘の中に隠れた若い僧を焼きつくした ── 1000年語り継がれる «安珍・清姫» の寺。","lead":"道成寺は、飛鳥時代の701年に開かれたと伝わる、紀州で最も古い寺の一つです。«安珍・清姫» の伝説の舞台として知られ、能や歌舞伎の «道成寺もの» のもとになりました。本尊の千手観音などは国宝です。","story":["寺の始まりには、もう一つの物語があります。この地の海女の娘は、髪がないことに悩んでいましたが、海から拾った観音像に祈ると、美しく長い髪がはえてきました。娘は «髪長姫» と呼ばれ、都にのぼって天皇の后になったといわれます。姫の願いで文武天皇が寺を建てさせ、それが道成寺だと伝わります。","そして、もっと有名なのが «安珍・清姫» の伝説です。平安時代、熊野詣の途中の若い僧・安珍は、泊まった家の娘・清姫に一目ぼれされます。«帰りに必ず寄ります» ── 安珍はそう言って、じつは約束を守らずに逃げてしまいました。","だまされたと知った清姫は、安珍を追いかけます。怒りと悲しみのあまり、日高川を渡るときにはとうとう大蛇の姿になってしまいました。安珍は道成寺に逃げこみ、寺の僧たちは大きな釣り鐘を下ろして、その中に安珍をかくまいます。","大蛇は鐘に七重に巻きつき、炎をはいて鐘ごと安珍を焼きつくしてしまいました。清姫もまた、川に身を投げたといわれます。のちに二人は蛇の姿で寺の僧の夢にあらわれ、法華経の供養を受けて天にのぼったと語られます。«人を思う心の強さ» と «約束の重さ» を伝える物語です。","いま道成寺では、絵巻物を広げて物語を語る «絵とき説法» が行われています。62段の石段を上がると、南北朝時代に建てられた本堂が迎えてくれます。境内には、安珍が隠れた鐘があった «鐘巻の跡» と伝わる場所もあります。"],"tl":[["701年","文武天皇の勅願で寺が開かれたと伝わる"],["平安時代","安珍・清姫の伝説の原型が語られる"],["南北朝時代","現在の本堂が建てられる（重要文化財）"],["室町時代","能 «道成寺» が演じられるようになる"],["1694年","仁王門が建てられる（重要文化財）"],["1753年","歌舞伎 «京鹿子娘道成寺» が初演"]],"who":[["安珍","伝説の若い僧"],["清姫","伝説の娘。大蛇となって安珍を追った"],["宮子（髪長姫）","寺の創建伝説に登場する后。文武天皇の夫人・藤原宮子と結びつけられる"],["文武天皇","寺の創建を命じたと伝わる天皇"]],"deep":["安珍・清姫の話の原型は、平安時代の『大日本国法華経験記』や『今昔物語集』に見られます。そこでは名前はまだなく、«安珍»«清姫» の名は後の時代に定まりました。","寺の境内の発掘で、奈良時代の伽藍の跡が確認されており、古い寺であることが考古学からも裏づけられています。","«道成寺縁起» 絵巻（重要文化財）は室町時代の作とされ、寺では写しを使った絵とき説法が続けられています。","伝説の鐘は焼けたあと再びつくられ、その鐘がまた災いをもたらしたので京都の寺に移された、という続きの話も伝わります。","本尊の千手観音と、その脇の日光・月光菩薩は国宝で、奈良〜平安時代の作とされます。宝仏殿で拝観できます。"],"look":["62段の石段と仁王門","本堂（重要文化財）","宝仏殿の国宝仏","絵とき説法（時間を確認）","安珍塚と鐘巻の跡"],"q":["安珍が逃げこんだ道成寺で、僧たちは安珍をどこに隠した?","釣り鐘の中です。大蛇となった清姫が鐘に巻きつき、焼きつくしたと伝わります。"],"koji":[],"myth":"安珍・清姫、髪長姫の話はいずれも伝説。創建年は寺伝。","img":["安珍・清姫伝説","娘道成寺","藤原宮子"],"wp":"道成寺","rel":{"ev":[],"grave":[]},"ph":[["c:d/dd/Dojoji_Gobo_Wakayama15s3200.jpg",3200,2133,"道成寺"],["c:7/79/Dojoji_Gobo_Wakayama06n4272.jpg",2848,4272],["c:c/ce/Dojoji_Gobo_Wakayama02n4272.jpg",4272,2848],["c:e/e1/Standing_Bishamonten.JPG",2776,4078],["c:6/65/Dojoji_Gobo_Wakayama10n4272.jpg",4272,2403],["c:6/61/Dojoji_Gobo_Wakayama23n3200.jpg",3200,2130],["c:d/d7/Dojoji_Gobo_Wakayama21n3200.jpg",3200,2130],["c:2/2e/Thousand_armed_Kannon_Dojoji.JPG",858,1000]]},{"id":"30_tokei","n":"闘雞神社（熊野水軍・湛増と源平）","yomi":"とうけいじんじゃ","cat":"寺社","rank":"A","y":1185,"era":["heian"],"sh":"国の重要文化財（本殿など）","ad":"田辺市東陽","st":"JR紀勢本線 紀伊田辺駅から歩いて約8分","la":33.73,"lo":135.3775,"hook":"源氏につくか、平家につくか。熊野水軍の運命は、紅白の鶏の «けんか» で決まった。","lead":"闘雞神社は、紀伊田辺の町の中にある神社です。源平の戦いのとき、熊野の別当（長官）湛増（たんぞう）が、源氏と平家のどちらにつくかを、紅白の鶏を闘わせて占ったと伝わります。その話から «闘雞» の名がつきました。2016年に世界遺産に追加登録されました。","story":["平安時代の終わり、源氏と平家の戦いは最終盤をむかえていました。熊野の神社を治める別当・湛増は、強力な水軍（海の武士団）をしたがえていました。«熊野水軍がどちらにつくかで、戦の行方が変わる» ── 源氏も平家も、湛増を味方にしようとしました。","湛増は、もともと平家と関係が深い立場でした。けれど源氏の勢いも無視できません。迷った湛増は、神の意志にゆだねることにしました。社の前で、源氏の色である白の鶏と、平家の色である赤の鶏を闘わせたのです。","境内が静まりかえる中、二羽の鶏がぶつかりあいます。結果は ── 白い鶏の勝ち。«神は源氏を選ばれた!» 湛増は源氏につくことを決め、200艘あまりの船をひきいて壇ノ浦へ向かったと『平家物語』は伝えます。1185年、平家は壇ノ浦で滅びました。","この話にちなんで、神社は «闘雞権現» と呼ばれるようになりました。境内には、闘った鶏をかたどった像も置かれています。また、弁慶は湛増の子だったという言い伝えもあり、田辺には «弁慶生誕の地» の碑も立っています。","闘雞神社は熊野三山の神々をまとめてまつり、熊野へ行けない人が代わりにお参りする場所でもありました。2016年、熊野参詣道とのつながりが認められ、世界遺産に追加登録されました。"],"tl":[["419年","允恭天皇のころに熊野の神をまつったと伝わる（社伝）"],["1185年","湛増が紅白の鶏を闘わせて源氏につくと決めたと伝わる"],["1185年","壇ノ浦の戦いで平家が滅びる"],["江戸時代","田辺の町の守り神として信仰される"],["2016年","世界遺産 «紀伊山地の霊場と参詣道» に追加登録"]],"who":[["湛増","熊野別当。紅白の鶏で源平の行方を占ったと伝わる"],["弁慶","湛増の子とする伝承がある"],["源義経","壇ノ浦で平家を破った源氏の大将"]],"deep":["鶏合せの話は『平家物語』巻11 «鶏合 壇浦合戦» に見えます。史実かどうかは確かめられませんが、熊野水軍が源氏方についたことは他の史料からもうかがえます。","湛増が率いた船の数は『平家物語』では «二百余艘» とされます。物語の数字なので、誇張もふくまれていると考えられます。","本殿をはじめとする社殿は江戸時代の建物で、熊野三山の神々を横一列にまつる配置が特徴です。","弁慶を湛増の子とする話は『義経記』などの物語に由来し、史実とは考えにくいとされています。","境内の裏の «仮庵山（かりおやま）» は神域とされる森で、古い信仰の形を伝えています。","«田辺» の地名は古くから熊野詣の道筋にあり、紀伊路（海沿いの道）から中辺路（山の道）へ入る分かれ道として栄えました。闘雞神社はその玄関口の社でした。"],"look":["紅白の鶏の像","熊野三山の神々をまつる並んだ社殿","神域の仮庵山の森","近くの «弁慶生誕の地» の碑や弁慶松"],"q":["湛増が占いで闘わせた鶏の色は、何色と何色?","白（源氏）と赤（平家）です。白が勝ち、源氏につきました。"],"koji":[],"myth":"鶏合せ、弁慶が湛増の子という話は物語・伝承。創建年は社伝。","img":["湛増","壇ノ浦の戦い","熊野水軍"],"wp":"闘雞神社","rel":{"ev":[],"grave":[]},"ph":[["c:2/2f/251011_Tokei-jinja_Tanabe_Wakayama_prefecture_Japan03s3.jpg",5472,3648,"闘雞神社"],["c:7/76/251011_Tokei-jinja_Tanabe_Wakayama_prefecture_Japan16s3.jpg",5472,3648],["c:5/53/251011_Tokei-jinja_Tanabe_Wakayama_prefecture_Japan13s3.jpg",5472,3648],["c:6/6c/251011_Tokei-jinja_Tanabe_Wakayama_prefecture_Japan12s3.jpg",5472,3648],["c:c/c2/251011_Tokei-jinja_Tanabe_Wakayama_prefecture_Japan07s3.jpg",5472,3648],["c:9/99/251011_Tokei-jinja_Tanabe_Wakayama_prefecture_Japan04s3.jpg",5472,3648],["c:7/70/251011_Daufuku-in_Tanabe_Wakayama_prefecture_Japan02s3.jpg",5472,3648],["c:6/6d/Daimonzaka8618.JPG",1200,1600]]},{"id":"30_takijiri","n":"滝尻王子（熊野の神域の入口）","yomi":"たきじりおうじ","cat":"街道","rank":"A","y":1201,"era":["heian","kamakura"],"sh":"国指定史跡（熊野参詣道の一部）","ad":"田辺市中辺路町栗栖川","st":"JR紀伊田辺駅からバスで約40分、«滝尻» 下車すぐ","la":33.796,"lo":135.52,"hook":"川を渡ったら、そこはもう神の国。上皇も貴族も、ここから熊野の山へ一歩をふみ出した。","lead":"滝尻王子は、熊野古道・中辺路にある王子社の一つです。«ここから先は熊野の神の領域» とされた入口にあたり、熊野九十九王子の中でもとくに格式の高い «五体王子» に数えられます。世界遺産の一部で、ここから本格的な山道が始まります。","story":["平安時代の終わりから鎌倉時代にかけて、上皇や貴族たちは何度も熊野へお参りしました。これを «熊野詣» といいます。京都から熊野までは片道およそ半月以上。道の途中には、熊野の神の分身をまつる «王子» がいくつも置かれました。","滝尻は、富田川と石船川が合流する場所です。参詣者は川の水で身を清め、«いよいよ神の国へ入る» と気持ちを新たにしました。ここから熊野本宮までは、山また山の道が続きます。","1201年、後鳥羽上皇の熊野御幸に、歌人の藤原定家が同行しました。定家は日記『熊野御幸記』に、滝尻での出来事や、険しい山道のつらさを書き残しています。«道は極めて険しく…» ── 都の貴族にとって、熊野の山道は想像以上だったようです。一行は王子の前で歌会を開き、神に歌を奉納しました。","王子の裏山には «胎内くぐり» という大きな岩のすき間があり、ここをくぐると生まれ変わるといわれます。近くの «乳岩» には、奥州の藤原秀衡の夫婦が熊野詣の途中で子を産み、岩屋に残したところ、狼が守って育てたという伝説があります。","いまも滝尻からは、熊野古道の石畳の道が山へとのびています。«熊野古道館» で道の情報を集めてから歩き出す人も多く、上皇たちと同じ入口から、神の山へ向かう旅が始まるのです。"],"tl":[["平安時代後期","熊野詣が盛んになり、王子社が整えられる"],["1201年","後鳥羽上皇の熊野御幸に藤原定家が同行"],["鎌倉時代","多くの上皇・貴族が熊野詣を行う"],["2000年","熊野参詣道として国の史跡に指定"],["2004年","世界遺産 «紀伊山地の霊場と参詣道» に登録"]],"who":[["後鳥羽上皇","何度も熊野詣を行った上皇"],["藤原定家","1201年の御幸に同行し『熊野御幸記』を書いた歌人"],["藤原秀衡","乳岩の伝説に登場する奥州の武将"]],"deep":["«五体王子» は、藤代・切目・稲葉根・滝尻・発心門の五つとする見方が一般的で、格の高い王子として特別に扱われました。","『熊野御幸記』は定家自筆の記録が残り、国宝に指定されています。滝尻の記事は中世の熊野詣の実態を知る第一級の史料です。","後鳥羽上皇は生涯に熊野詣を28回行ったとされ、滝尻は何度も通った場所でした。","«王子» は熊野の神の御子神をまつる社で、中世には数多く置かれ «九十九王子» と総称されましたが、実際の数が99だったわけではありません。","乳岩の伝説は藤原秀衡にまつわる話で、中辺路の «秀衡桜» など、秀衡ゆかりの伝承地が道沿いに点在します。","熊野詣の人々は、王子ごとに奉幣や読経、歌会、里神楽などを行いました。王子社は、長い道のりの «休けい所» であり、祈りの «区切り» でもあったのです。"],"look":["滝尻王子の社殿と川の合流点","裏山の «胎内くぐり» と «乳岩»","王子から続く熊野古道の石畳","熊野古道館の展示"],"q":["滝尻での出来事を日記に書いた、1201年の御幸に同行した歌人は?","藤原定家です。『熊野御幸記』に記録を残しました。"],"koji":[],"myth":"乳岩の秀衡の話、胎内くぐりの御利益は伝承。","img":["熊野古道","藤原定家","熊野九十九王子"],"wp":"滝尻王子","rel":{"ev":[],"grave":[]},"ph":[["c:1/1f/Takijiri-oji_shrine_2.jpg",1024,768,"滝尻王子"],["c:4/4b/Takijiri-oji_shrine_1.JPG",1024,768],["c:0/00/Sacred_arch_of_TAKIJIRI-oji_shrine.JPG",1024,768],["c:2/2d/Teika%283%29.jpg",832,848,"藤原定家"],["c:f/fc/Daimonzaka17_1024.jpg",768,1024,"熊野九十九王子"]]},{"id":"30_minakata","n":"南方熊楠顕彰館と南方熊楠邸","yomi":"みなかたくまぐすけんしょうかんとみなかたくまぐすてい","cat":"学び","rank":"A","y":1916,"era":["meiji","taisho","showa"],"sh":"","ad":"田辺市中屋敷町","st":"JR紀勢本線 紀伊田辺駅から歩いて約10分","la":33.7335,"lo":135.376,"hook":"英語の科学誌に論文を次々に載せ、天皇に粘菌を献上した «歩く百科事典»。その書斎が、田辺の町にそのまま残る。","lead":"南方熊楠は、和歌山市生まれの博物学者・民俗学者です。キノコや粘菌（変形菌）を研究し、海外の科学誌にも多くの論文を発表しました。晩年の約25年を過ごした田辺の家と、その隣の南方熊楠顕彰館で、熊楠の研究と暮らしにふれることができます。","story":["熊楠は1867年、和歌山城下の商家に生まれました。子どものころから記憶力がすさまじく、百科事典『和漢三才図会』を友人の家で読んでは、家に帰って書き写したといわれます。«一度読んだら忘れない» ── そんな伝説がいくつもあります。","東京の学校をやめて、アメリカ、そしてイギリスへ渡りました。ロンドンでは大英博物館で本を読みあさり、科学誌『ネイチャー』に論文を投稿して、イギリスの学者たちを驚かせました。お金はなくても、知りたい気持ちは誰にも負けませんでした。","帰国後、熊楠は紀伊の田辺に落ち着き、1916年からこの家に住みました。庭の柿の木で見つけた粘菌は新種と認められ、熊楠の名をとって «ミナカテラ・ロンギフィラ» と名づけられました。«なぜ粘菌に夢中に?» ── 動物でも植物でもない不思議な生き物に、熊楠は生命のなぞを見ていたのです。","熊楠は、明治政府が進めた «神社合祀»（小さな神社をまとめて森を切ること）に強く反対しました。«神社の森は、生き物と人の暮らしを守る宝だ»。この運動は、いまの自然保護運動の先がけといわれます。","1929年、熊楠は田辺湾の神島の沖で、昭和天皇に粘菌について講義しました。献上した標本は、なんとキャラメルの箱に入っていたと伝わります。のちに天皇は熊楠をしのぶ歌をよみました。書斎には今も机や標本の棚が残り、知の巨人の息づかいを感じさせます。"],"tl":[["1867年","和歌山城下に生まれる"],["1886年","アメリカへ渡る"],["1892年","イギリス・ロンドンへ。大英博物館で研究"],["1900年","帰国"],["1916年","田辺の現在の邸宅に住む"],["1929年","昭和天皇に神島沖で粘菌について進講"],["1941年","田辺の自宅で亡くなる"],["2006年","南方熊楠顕彰館が開館"]],"who":[["南方熊楠","博物学者・民俗学者。この家で研究した"],["昭和天皇","生物学者でもあり、熊楠の進講を受けた"],["柳田國男","民俗学者。熊楠と手紙で議論を交わした"]],"deep":["熊楠が『ネイチャー』に寄せた論文は50本をこえるとされ、一人の日本人としては群を抜く数です。","«ミナカテラ・ロンギフィラ» は熊楠の家の柿の木で見つかった粘菌で、属名に熊楠の名がつけられています。","神社合祀反対運動は、生態系を守るという考え方をいち早く示したものとして «エコロジー» の先駆とも評価されます。熊楠は明治末に «エコロギー» という言葉を使ったことでも知られます。","昭和天皇は1962年に白浜を訪れた際、神島を望んで熊楠をしのぶ歌をよみました。天皇が民間の学者をしのぶ歌をよむのは異例とされます。","顕彰館には熊楠の蔵書や標本、日記、手紙などの資料が保存されています。邸宅は公開日・時間が限られるため確認が必要です。"],"look":["熊楠の書斎と研究の道具","新種の粘菌が見つかった庭の柿の木","南方熊楠顕彰館の資料展示","田辺湾の神島（遠くから）"],"q":["熊楠が昭和天皇に献上した粘菌標本は、何の箱に入っていた?","キャラメルの箱だったと伝わります。"],"koji":[],"myth":"記憶力の伝説やキャラメル箱の話は逸話。論文数は数え方で異なる。","img":["神島 (和歌山県)","神社合祀","粘菌"],"wp":"南方熊楠","rel":{"ev":[],"grave":[]},"ph":[["c:b/b5/Minakata-Kumagusu.jpg",900,1300,"南方熊楠"],["c:7/7a/251011_Minakata_Kumagusu_Archives_Tanabe_Wakayama_prefecture_Japan04s3.jpg",5472,3648],["c:7/73/Gluecksklee.jpg",2458,2301],["c:f/f6/British_Museum_from_NE.JPG",2560,1920],["c:f/fa/Sun_Yat_Sen_in_Wakayama_Japan_1901.png",2112,1672],["c:9/93/%E5%8D%97%E6%96%B9%E7%86%8A%E6%A5%A0%E8%83%B8%E5%83%8F.JPG",1536,2048],["c:3/36/Sunyatsen1.jpg",1059,1462],["c:c/c7/Minakata-to-Koaze.jpg",1450,1000]]},{"id":"30_yunomine","n":"湯の峰温泉 つぼ湯（小栗判官蘇生の湯）","yomi":"ゆのみねおんせん つぼゆ","cat":"伝承","rank":"A","y":1400,"era":["heian","muromachi"],"sh":"世界遺産（熊野参詣道の一部）","ad":"田辺市本宮町湯峯","st":"JR紀伊田辺駅または新宮駅からバスで約1時間半〜2時間、«湯の峰温泉» 下車すぐ","la":33.8255,"lo":135.7435,"hook":"一度死んだ男が、土車に乗せられて熊野へ。49日この湯につかり、元の姿によみがえった ── 世界遺産の小さな湯船。","lead":"湯の峰温泉は、熊野本宮大社の近くにある、とても古い温泉です。川のほとりの岩をくりぬいたような小さな湯船 «つぼ湯» は、世界遺産の一部で、実際に入ることができる珍しい場所です。«小栗判官（おぐりはんがん）» がよみがえった湯として語り継がれています。","story":["湯の峰温泉は、4世紀ごろに見つかったと伝わる、日本でも最も古い部類の温泉です。熊野本宮大社にお参りする人は、ここで湯につかって体を清め（湯垢離）、神の前に向かいました。温泉そのものが、祈りの一部だったのです。","この湯には、ふしぎな物語が伝わります。常陸の国の小栗判官は、照手姫という美しい姫と結ばれますが、姫の一族に毒を盛られて命を落としました。地獄の閻魔大王は、判官をこの世にもどしますが、その姿は目も耳も口もきかない «餓鬼阿弥（がきあみ）» でした。","«この者を熊野の湯へ連れて行けば、元にもどる»。判官は土車（つちぐるま）に乗せられ、多くの人に引かれて熊野をめざしました。その中には、判官だと知らずに車を引く照手姫の姿もありました。«一引き引いたは千僧供養、二引き引いたは万僧供養» ── 車を引くことは功徳になるとされたのです。","ようやくたどりついた湯の峰で、判官はつぼ湯に49日間つかりました。すると、みるみる元の姿にもどったといいます。«なぜ湯でよみがえるの?» ── 熊野は «よみがえりの地» と信じられていたのです。","つぼ湯は、大人が2人ほど入れば一杯の小さな湯船です。湯の色は一日に何度も変わるといわれ、神秘的な雰囲気を漂わせます。すぐそばの «湯筒» では、温泉の熱で卵や野菜をゆでることもできます。"],"tl":[["4世紀ごろ","温泉が見つかったと伝わる"],["平安時代","熊野詣の人々が湯垢離をする"],["室町時代","説経節 «小栗判官» の物語が広まる"],["江戸時代","浄瑠璃や歌舞伎でも小栗判官が演じられる"],["2004年","つぼ湯が世界遺産の一部として登録"]],"who":[["小栗判官","つぼ湯でよみがえったと伝わる物語の主人公"],["照手姫","判官の妻。土車を引いたと語られる"]],"deep":["小栗判官の物語は、中世の語り物 «説経節» で広まりました。モデルは常陸の小栗氏ともいわれますが、物語の多くは創作です。","つぼ湯は «世界遺産に登録された入れる温泉» として知られ、一回30分ほどの交代制で入浴します。","湯の峰の源泉は高温で、硫黄の香りがします。湯の色が一日に7回変わるといわれるのは、成分や光の具合によるものと考えられます。","近くの東光寺は、温泉の源泉の上に建つとされ、本尊の薬師如来は湯の花が固まってできたものと伝わります。","湯の峰から熊野本宮大社へは «大日越» という古道が通じ、昔の参詣者と同じ道を歩いて本宮へ向かえます。","熊野本宮大社はもともと熊野川の中州（大斎原）にありましたが、1889年の大水害のあと、今の高台に移されました。湯の峰から大日越で本宮へ向かうと、この歴史も感じられます。"],"look":["世界遺産のつぼ湯（小さな湯船）","温泉卵ができる湯筒","東光寺（湯の峰薬師）","小栗判官ゆかりの «車塚» や «力石» の伝承地"],"q":["小栗判官は、つぼ湯に何日つかってよみがえったと伝わる?","49日間です。"],"koji":[{"w":"一引き引いたは千僧供養","m":"小栗判官の土車を一度引くと、千人の僧を供養したのと同じ功徳があるという物語のことば"}],"myth":"温泉の発見年、小栗判官の話、湯の色が7回変わる話は伝承。","img":["小栗判官","熊野本宮大社","熊野古道"],"wp":"湯の峰温泉","rel":{"ev":[],"grave":[]},"ph":[["c:f/f1/Tsuboyu_yunomineonsen1.JPG",4608,3456],["c:a/af/Yunomineonsen_yutou.jpg",3072,2304],["c:6/6d/Daimonzaka8618.JPG",1200,1600],["c:c/c3/Tuboyu.jpg",1500,1125],["c:6/6a/Unomineonsenkousyuyokuzyou.jpg",1000,750],["c:b/b3/Inside_the_Kumano_Hongu_Taisha.jpg",2272,1704,"熊野本宮大社"]]},{"id":"30_shirahama_onsen","n":"白浜温泉 崎の湯（«牟婁の湯»）","yomi":"しらはまおんせん さきのゆ","cat":"伝承","rank":"A","y":658,"era":["asuka","nara"],"sh":"","ad":"西牟婁郡白浜町湯崎","st":"JR紀勢本線 白浜駅からバスで約20分、«湯崎» 下車、歩いて約5分","la":33.681,"lo":135.335,"hook":"波しぶきを浴びながらつかる露天風呂。1300年前、天皇たちも «牟婁の湯» の湯けむりを見ていた。","lead":"白浜温泉は、道後温泉・有馬温泉とならぶ «日本三古湯» の一つといわれます。古代には «牟婁（むろ）の湯» や «紀の湯» と呼ばれ、斉明天皇や持統天皇など多くの天皇が訪れました。海に面した岩場の露天風呂 «崎の湯» は、その歴史を今に伝える湯です。","story":["飛鳥時代、紀伊の南の海辺にわく温泉は、都の人々にも知られていました。657年、若い有間皇子がこの湯を訪れ、都にもどって斉明天皇に «あの湯に行けば、病もたちまち治ります» と話したと『日本書紀』は伝えます。","その話に心を動かされたのか、翌658年、斉明天皇は中大兄皇子らをつれて «紀の湯» を訪れました。ところがその滞在中、都に残った有間皇子は謀反の疑いで捕らえられ、この紀の湯へ送られて取り調べを受けます。そして帰り道の藤白坂で命を落としました。«この湯を天皇にすすめたのは皇子自身だったのに…» ── 歴史の皮肉を感じさせる出来事です。","その後も、持統天皇が690年に、文武天皇が701年にこの地を訪れたことが記録に残ります。『万葉集』にも、紀の湯への行幸のときの歌が収められています。都から遠く離れた海辺の湯は、天皇たちにとって特別な «旅の地» でした。","崎の湯は、湯崎の海岸の岩場にある露天風呂です。目の前には太平洋が広がり、大きな波が来るとしぶきがかかることもあります。天皇たちがつかった «行幸湯» がこのあたりだったと伝わり、1350年以上の歴史をもつといわれます。","いまの白浜は、白い砂浜やアドベンチャーワールドで知られる観光地です。けれど湯崎の古い湯に身をひたせば、飛鳥の天皇や、悲劇の皇子が見た海と同じ景色が広がっています。"],"tl":[["657年","有間皇子が牟婁の湯を訪れ、斉明天皇にすすめる"],["658年","斉明天皇が紀の湯に行幸。有間皇子の事件が起こる"],["690年","持統天皇が紀伊に行幸"],["701年","文武天皇が紀伊に行幸"],["昭和時代","白浜が全国的な観光地になる"]],"who":[["斉明天皇","658年に紀の湯を訪れた天皇"],["有間皇子","紀の湯をすすめ、この地で取り調べを受けた皇子"],["中大兄皇子","斉明天皇に同行し、有間皇子を取り調べた"],["持統天皇","690年に紀伊に行幸"]],"deep":["«日本三古湯» の組み合わせには別の説もありますが、『日本書紀』に登場する道後・有馬・白浜（牟婁の湯）をあげるのが一般的です。","«牟婁の湯» の «牟婁» は紀伊南部の郡名で、古代の «牟婁郡» にあたる広い地域を指しました。温泉の正確な場所は湯崎付近と考えられています。","有間皇子の事件は、藤白坂のカードと一続きの物語です。紀の湯と藤白坂をあわせてたどると、事件の流れがよくわかります。","『万葉集』巻1・巻9などには、紀の湯への行幸に関わる歌が収められ、白浜周辺の地名が古代の旅の記憶を伝えています。","崎の湯は潮の満ち引きや波の高さによって、入浴できない日もあります。脱衣所は簡素で、せっけんは使えません。"],"look":["太平洋に面した岩場の崎の湯","湯崎の «行幸湯» ゆかりの碑","近くの白良浜と円月島","有間皇子の歌碑など万葉ゆかりの碑"],"q":["白浜温泉は、古代の書物の中で何と呼ばれた?","«牟婁の湯» や «紀の湯» です。"],"koji":[],"myth":"崎の湯が行幸の湯そのものかどうかは伝承。«1350年» は目安。","img":["有間皇子","斉明天皇","日本三古湯"],"wp":"白浜温泉","rel":{"ev":[],"grave":[]},"ph":[["c:4/45/Arimanomiko01_1024.jpg",1024,768,"有間皇子"],["c:e/e3/Empress_Kogyoku-Saimei.jpg",610,775,"斉明天皇"],["c:a/a5/Shirahama_montages.JPG",433,714,"近く: 白浜町"],["c:c/c1/%E5%8D%97%E6%96%B9%E7%86%8A%E6%A5%A0%E8%A8%98%E5%BF%B5%E9%A4%A8.JPG",2048,1536,"近く: 南方熊楠記念館"],["c:0/01/131222_Engetsu_Island_Shirahama_Wakayama_pref_Japan01bs.jpg",3660,2440,"近く: 高嶋 (和歌山県)"],["c:d/d0/131221_Shirarahama_Beach_Shirahama_Wakayama_pref_Japan07s3bs.jpg",4290,2860,"近く: 白良浜"],["c:6/62/%E7%99%BD%E6%B5%9C%E3%82%A8%E3%83%8D%E3%83%AB%E3%82%AE%E3%83%BC%E3%83%A9%E3%83%B3%E3%83%89.JPG",2048,1536,"近く: 白浜エネルギーランド"],["c:a/ae/131221_Senjojiki_Shirahama_Wakayama_pref_Japan03s3.jpg",4912,3264,"近く: 千畳敷 (和歌山県)"]]},{"id":"30_shingu_jo","n":"新宮城（丹鶴城）","yomi":"しんぐうじょう（たんかくじょう）","cat":"城","rank":"A","y":1633,"era":["edo"],"sh":"国指定史跡","ad":"新宮市丸山町","st":"JR新宮駅から歩いて約10分","la":33.7298,"lo":135.9912,"hook":"熊野川の河口を見下ろす丘に、天守のない石垣だけが残る。この城を支えたのは «炭» だった。","lead":"新宮城は、江戸時代に紀州藩の家老・水野家が治めた城です。建物は明治のはじめに取りこわされ、今は «跡» として石垣が残っています。すぐ下を流れる熊野川は、山の木や炭を運ぶ大動脈でした。","story":["新宮駅から少し歩くと、こんもりした丘に高い石垣が見えてきます。ここが新宮城跡。丘の下には熊野川がゆったりと海へ流れこんでいます。«なぜこんな川べりに城を?» ——答えは、この川こそが新宮の富の通り道だったからです。","城づくりが始まったのは江戸時代のはじめ。紀伊国をおさめた浅野氏の重臣・浅野忠吉が工事にとりかかりましたが、幕府の «一国一城令» で中断したともいわれます。1619年、浅野氏が広島へ移ると、かわって紀州藩主・徳川頼宣の «付家老»（お目付け役の家老）として水野重央（しげなか）が新宮に入りました。工事は水野家に引きつがれ、寛永10年（1633年）ごろ完成したとされます。","水野家は紀州藩の家臣でありながら、3万5千石の城を持つ特別な家でした。«大名なみなのに大名ではない»。この微妙な立場は幕末まで続き、明治元年（1868年）になってようやく «新宮藩» として独立が認められます。けれどそのわずか数年後、廃藩置県と廃城で、城の建物は姿を消しました。","発掘調査で見つかったのが、川ぞいの «炭納屋（すみなや）» の跡です。熊野の山で焼いた炭を川で運び、ここに積んで、船で江戸や大坂へ送り出しました。城の足もとに倉庫がずらりと並ぶ——お城と商売がこんなに近かった例はめずらしく、新宮の城は «炭の城» でもあったのです。","別名の «丹鶴城» は、この場所にかつて «丹鶴姫» という女性が住んだという言い伝えから。源為義の娘とされ、熊野の別当家に嫁いだ人物と結びつけて語られます。石垣の上に立つと、熊野川の向こうに三重県の山々、河口には太平洋。四百年前の人も、この同じ景色の中で船の出入りを見張っていたのでしょう。"],"tl":[["1619年","浅野氏が広島へ移り、水野重央が紀州藩の付家老として新宮に入る"],["1633年ごろ","新宮城が完成したとされる（寛永10年）"],["江戸時代","熊野の炭や木材を川で運び、城下の炭納屋から積み出す"],["1868年","水野家が «新宮藩» として独立を認められる"],["1873年ごろ","廃城令を受けて建物が取りこわされる"],["2003年","国の史跡に指定される"]],"who":[["水野重央","紀州藩の付家老として新宮に入った水野家の初代"],["水野重良","重央の子。城を完成させたとされる"],["浅野忠吉","浅野氏の重臣。新宮で最初に城づくりを始めた"],["丹鶴姫","城の別名の由来となった伝説の女性。源為義の娘と伝わる"]],"deep":["«付家老» は、徳川家康が息子たちの藩につけた重臣。紀州藩には安藤家（田辺）と水野家（新宮）がつき、どちらも城を持ちながら藩主の家来という二重の立場でした。明治元年に両家とも藩として独立しています。","城は本丸・二の丸・松の丸などが段になって並ぶ «平山城»。石垣には自然の石をあまり加工せずに積んだ部分と、角を整えて積んだ部分があり、工事の時期のちがいを読み取る手がかりになっています。","炭納屋跡は、熊野川に面した低い場所で見つかりました。いくつもの倉庫の礎石が並び、水野家が炭の取り引きを重視していたことを物語ります。熊野の炭は良質で、都市の燃料として需要が大きかったのです。","一国一城令（1615年）は «一つの国に城は一つ» という決まり。紀伊国には和歌山城があるのに、なぜ新宮と田辺にも城が許されたのか。付家老という特別な立場への配慮と考えられていますが、細かい経緯は諸説あります。","城跡は «丹鶴城公園» として整備され、春は桜の名所。展望のよい本丸からは、熊野川の河口と、川をはさんだ三重県側（紀宝町）が一望できます。","新宮は熊野速玉大社の門前町でもあり、城下町と門前町が重なってできた町です。城跡から速玉大社までは歩いて15分ほどで、両方をめぐると町の成り立ちがよくわかります。"],"look":["本丸・松の丸に残る高い石垣","熊野川ぞいの炭納屋跡（礎石の並び）","本丸から見る熊野川河口と太平洋","石垣の積み方のちがい（時期の差を探してみる）"],"q":["新宮城の足もとにあった «炭納屋» は何のための建物？","熊野の山で焼いた炭をたくわえ、船で積み出すための倉庫。水野家の財政を支えました。"],"koji":[{"w":"一国一城","m":"江戸幕府が出した «一つの国に城は一つだけ» という決まり。大名の力をおさえるためのもの"}],"myth":"浅野氏時代の築城開始と中断の年、丹鶴姫の人物像には諸説・伝承を含む。","img":["水野重央","熊野川","新宮藩"],"wp":"新宮城","rel":{"ev":["jinmu"],"grave":[]},"ph":[["c:e/e8/171008_Shingu_Castle_Shingu_Wakayama_pref_Japan22n.jpg",6000,4000,"新宮城"],["c:2/26/%E6%96%B0%E5%AE%AE%E5%9F%8E%E6%A8%A1%E6%93%AC%E5%9F%8E%E9%96%80.JPG",5184,3456],["c:8/83/%E6%96%B0%E5%AE%AE%E5%9F%8E%E6%9C%AC%E4%B8%B8%E7%9F%B3%E5%9E%A3.JPG",5184,3456],["c:7/78/%E6%96%B0%E5%AE%AE%E5%9F%8E%E6%9C%AC%E4%B8%B8%E6%90%A6%E6%89%8B%E8%99%8E%E5%8F%A3.JPG",5184,3456],["c:7/7c/%E6%96%B0%E5%AE%AE%E5%9F%8E%E5%87%BA%E4%B8%B8.JPG",5184,3456],["c:e/e7/171008_Shingu_Castle_Shingu_Wakayama_pref_Japan37n.jpg",6000,4000],["c:3/36/171008_Shingu_Castle_Shingu_Wakayama_pref_Japan19n.jpg",6000,4000],["c:1/18/171008_Shingu_Castle_Shingu_Wakayama_pref_Japan14n.jpg",6000,4000]]},{"id":"30_jofuku","n":"徐福公園（徐福の墓）","yomi":"じょふくこうえん（じょふくのはか）","cat":"伝承","rank":"A","y":-219,"era":["yayoi","edo"],"sh":"","ad":"新宮市徐福1丁目","st":"JR新宮駅から歩いて約2分","la":33.7262,"lo":135.9918,"hook":"不老不死の薬を探しに海を渡った男は、熊野に住みついた——駅前の中華風の門の奥に、その «墓» がある。","lead":"徐福は、2200年以上前の中国・秦の始皇帝の命令で、不老不死の薬を探しに東の海へ船出したと伝わる人物です。新宮には «徐福がここにたどり着いた» という伝説があり、江戸時代に墓碑が建てられました。本当に来たかどうかはわかりませんが、長く語りつがれてきた物語の場所です。","story":["中国を初めて統一した秦の始皇帝は、晩年 «死なない方法» を求めていました。そこへ徐福という方士（仙術の専門家）が申し出ます。«東の海に、蓬莱・方丈・瀛洲（えいしゅう）という三つの神山があり、仙人が住んでいます»。この話は、司馬遷の歴史書『史記』に書かれています。","『史記』によると、徐福はたくさんの若い男女を連れ、さまざまな技術者と五穀の種を積んで船出しました。そして «広い平野と湿地を得て王となり、帰らなかった» ——。では彼はどこへ行ったのか? この問いに、日本各地が «うちに来た» と名乗りをあげました。新宮もその一つです。","新宮の伝えでは、徐福の一行は熊野の海岸に上陸し、河口の小山 «蓬莱山»（今の阿須賀神社）を目印にしたといいます。探していた薬は、熊野に生える «天台烏薬（てんだいうやく）» という木だったとも。けれど徐福は国へ帰らず、この地に住んで、土地の人に農業や漁、紙すきなどを教えたと語られてきました。","公園の奥にある苔むした墓碑には «秦徐福之墓» の文字。元文元年（1736年）に建てられたもので、文字は紀州藩の儒学者・李梅渓の書と伝わります。そばには、徐福に従った重臣たちの墓とされた «七塚» の碑も。かつてこの近くに、北斗七星の形に塚が並んでいたといわれます。","今の公園は1994年に整備され、鮮やかな中華風の楼門が駅前の風景をいろどっています。«本当に来たの?» と聞かれたら、答えは «わからない»。でも、海の向こうから新しい技術を持った人々がやってきたという記憶が、徐福という名前に託されて残った——そう考えると、この小さな墓がぐっと味わい深くなります。"],"tl":[["前221年","秦の始皇帝が中国を統一"],["前219年ごろ","徐福が始皇帝に仙人の山のことを申し出たと『史記』に記される"],["前210年ごろ","徐福がふたたび船出し、帰らなかったとされる（年は諸説）"],["1736年","新宮に «秦徐福之墓» の墓碑が建てられる"],["1915年","地元の青年会が «七塚之碑» を建てる"],["1994年","徐福公園として整備される"]],"who":[["徐福","秦の方士。不老不死の薬を求めて東へ船出したと伝わる"],["始皇帝","秦の初代皇帝。徐福に薬探しを命じた"],["司馬遷","前漢の歴史家。『史記』に徐福の船出を記した"],["李梅渓","紀州藩の儒学者。墓碑の文字を書いたと伝わる"]],"deep":["『史記』の中でも、徐福の話は «秦始皇本紀» と «淮南衡山列伝» に出てきます。後者には、若い男女三千人や技術者、五穀の種を与えられて出航し、平原広沢を得て王となったとあり、«王になって帰らなかった» 点が日本伝説の出発点になりました。","徐福の上陸伝説は、佐賀県、三重県熊野市、山梨県富士吉田市など全国に20か所以上あるといわれます。新宮はその中でも墓碑と公園がそろい、もっとも知られた場所のひとつです。","墓碑は1736年の建立とされますが、誰が建てたかについては資料によって書き方が異なり、はっきりしない点があります。碑の文字そのものより «江戸時代にはすでに徐福の墓とされていた» ことが歴史としては重要です。","«天台烏薬» はクスノキ科の低木で、根が漢方薬に使われます。中国の天台山にちなむ名前で、熊野に自生していることが «徐福が探した薬» 説の根拠にされてきました。公園の墓の脇にも植えられています。","阿須賀神社の «蓬莱山» 周辺では弥生時代の住居跡が見つかっています。徐福の時代（紀元前3世紀）はちょうど日本の弥生時代にあたり、大陸から稲作や金属器が伝わった時期と重なるのが、伝説を面白くしている点です。","新宮と中国の徐福ゆかりの地との交流も続いており、公園は日中友好の象徴としても大切にされています。毎年夏には徐福をしのぶ催しが行われます。"],"look":["«秦徐福之墓» の墓碑","七塚之碑","墓の脇の天台烏薬の木","中華風の楼門（駅から見える）"],"q":["徐福が探したとされる «不老不死の薬» の正体とされる熊野の木は？","«天台烏薬（てんだいうやく）»。根が薬として使われるクスノキ科の木です。"],"koji":[{"w":"不老不死","m":"年をとらず、死なないこと。始皇帝が最後まで求めた夢"}],"myth":"徐福が熊野に来たという話は伝説で、史実としては確かめられていない。墓碑の建立者についても資料により記述が異なる。","img":["徐福公園","始皇帝","阿須賀神社"],"wp":"徐福","rel":{"ev":[],"grave":[]},"ph":[["c:a/a0/Jo-Fuku.jpg",842,2024,"徐福"],["c:0/05/La_expedici%C3%B3n_de_Xu_Fu%2C_por_Utagawa_Kuniyoshi.jpg",2000,971],["c:d/dd/Jofukukoen1.jpg",800,600],["c:b/bf/Jofuku_Park01n4200.jpg",4200,2800,"徐福公園"],["c:3/3f/QinShiHuang19century.jpg",2188,2944,"始皇帝"],["c:3/3b/171008_Asuka-jinja_Shingu_Wakayama_pref_Japan01n.jpg",6000,4000,"阿須賀神社"]]},{"id":"30_taiji","n":"太地（古式捕鯨発祥の地）","yomi":"たいじ（こしきほげいはっしょうのち）","cat":"産業","rank":"A","y":1606,"era":["edo","meiji"],"sh":"","ad":"東牟婁郡太地町太地","st":"JR太地駅から町営じゅんかんバスで約10分（くじらの博物館方面）","la":33.594,"lo":135.943,"hook":"«鯨一頭捕れば七浦潤う»。熊野灘の小さな浦で、日本の組織捕鯨は生まれた。","lead":"太地は、江戸時代のはじめに «組» をつくってクジラをとる組織的な捕鯨が始まった町です。何百人もの人が役割を分け、山の見張りから船、網、解体まで協力しました。今も町のあちこちに、捕鯨の歴史を伝える場所が残っています。","story":["冬の朝、岬の上の見張り小屋 «山見（やまみ）» で、男がじっと沖を見つめています。黒い背中、白い潮吹き——«クジラだ!» のろしが上がり、旗がふられると、浦から何十そうもの船がいっせいにこぎ出しました。これが江戸時代の太地の風景です。","太地で捕鯨の «組» がつくられたのは慶長11年（1606年）。和田忠兵衛頼元が、もりで突いてクジラをとる «突き取り法» の組織を始めたと伝わります。さらに延宝3年（1675年）ごろ、孫の和田角右衛門頼治（のちの太地角右衛門）が、大きな網でクジラの動きを止めてから突く «網取り法» を考え出しました。","網取り法では、勢子船（せこぶね）がクジラを網へ追いこみ、網船が網を張り、もりを打つ «刃刺（はざし）» がとどめを刺します。いちばん勇敢な刃刺は、弱ったクジラの背に飛び乗って作業したといいます。陸では解体する人、油をしぼる人、骨や皮を加工する人……。一つの組で数百人が働く、大きな産業でした。","«なぜクジラ一頭で七つの浦がうるおうのか?» 肉は食べ物に、油は明かりや田んぼの害虫よけに、骨やひげは道具や工芸品に。捨てるところがないといわれ、周りの村まで恵みが行きわたったのです。紀州藩もこの産業を大切にしました。","けれど、海はいつもやさしくはありません。明治11年（1878年）12月、子連れのセミクジラを追った船団が嵐に巻きこまれ、百人を超える人が帰らぬ人となりました。«大背美流れ（おおせみながれ）» と呼ばれるこの海難で、太地の古式捕鯨は大きな打撃を受けます。町には今もクジラと海で亡くなった人々をとむらう碑があり、静かに手を合わせる場所になっています。"],"tl":[["1606年","和田忠兵衛頼元が突き取り法による捕鯨の組を始めたと伝わる"],["1675年ごろ","和田角右衛門頼治が網取り法を考え出す"],["江戸時代","紀州藩の保護のもと、太地の鯨方が栄える"],["1878年12月","«大背美流れ» の海難で多くの人が亡くなる"],["明治時代後半","ノルウェー式の近代捕鯨が広まり、古式捕鯨は姿を消していく"],["1969年","太地町立くじらの博物館が開館"]],"who":[["和田忠兵衛頼元","太地で捕鯨の組を始めたとされる人物"],["太地角右衛門（和田頼治）","網取り法を考え出し、太地の捕鯨を大きく発展させた"],["刃刺","もりを打つ花形の役。組の中でもっとも尊敬された"],["紀州藩","捕鯨を産業として保護した"]],"deep":["網取り法の網は、わらや麻でつくった大きなもので、何枚もつないでクジラの進路をふさぎました。網にからんで動きがにぶったところを突くため、突き取り法より成功率が大きく上がったとされます。","見張り場 «山見» は燈明崎や梶取崎などの岬に置かれ、のろしや旗の合図で沖の船団に指示を出しました。燈明崎には江戸時代の灯明台（常夜灯）が復元されています。","勢子船は色あざやかな模様で塗られていたことで知られ、速さを競うように細長い形をしていました。くじらの博物館では、船や道具の復元、捕鯨の様子を描いた絵巻を見ることができます。","«背美の子持ちは夢にも見るな» という言い伝えがあります。子連れのセミクジラは母クジラが子を守ろうとして非常に荒れるため危険だ、という戒めで、大背美流れの悲劇と重ねて語られます。","太地の捕鯨は明治以降、近代捕鯨や南極海での捕鯨へつながり、多くの捕鯨船員を送り出しました。町が «くじらの町» を名乗る背景には、この長い歴史があります。","現在、クジラやイルカの漁は国際的に議論のある問題でもあります。歴史を学ぶときは、地域の暮らしを支えた産業としての面と、今日の議論の両方を知っておくと理解が深まります。"],"look":["太地町立くじらの博物館（古式捕鯨の資料）","燈明崎の山見台と復元された灯明台","梶取崎のくじら供養碑","町なかの古い家並みと浦の地形"],"q":["太地で考え出された、網でクジラの動きを止めてから突く方法を何という？","«網取り法»。1675年ごろ、和田角右衛門頼治が考え出したと伝わります。"],"koji":[{"w":"鯨一頭捕れば七浦潤う","m":"クジラ一頭で、まわりの七つの村までうるおうほど恵みが大きいこと"}],"myth":"捕鯨の組の開始年や創始者名は太地に伝わる記録による。大背美流れの犠牲者数は資料により差がある。","img":["太地町立くじらの博物館","捕鯨","熊野灘"],"wp":"太地町","rel":{"ev":[],"grave":[]},"ph":[["c:d/d1/Taiji_Town_Whale_Museum.jpg",4903,3503,"太地町"],["c:1/17/Taiji_town_Kominkan.jpg",4130,3097],["c:1/10/Taiji_Station-2023-01.jpg",6016,4000],["c:a/a2/Taiji_Post_office.jpg",4145,3109],["c:2/28/Kyo_Maru_No.1_-01.jpg",4928,3264],["c:3/3b/Taiji_town_hall.JPG",3648,2736],["c:e/e6/Michinoeki_Taiji_01.jpg",3648,2736],["c:0/0f/JA_Mikumano_Taiji_branch.jpg",3552,2664]]},{"id":"30_kashino_todai","n":"樫野埼灯台（日本最初の石造灯台）","yomi":"かしのざきとうだい","cat":"近代","rank":"A","y":1870,"era":["meiji"],"sh":"","ad":"東牟婁郡串本町樫野","st":"JR串本駅からバスで約40分«樫野灯台口»下車、歩いて約10分（本数が少ない。車が便利）","la":33.4722,"lo":135.8622,"hook":"幕末の約束から生まれた、日本で最初の石の灯台。その光は、嵐の夜に異国の船乗りたちを救う道しるべにもなった。","lead":"樫野埼灯台は、明治3年（1870年）に明かりがともった、日本で最初の石造りの灯台です。イギリス人技師ブラントンが設計にかかわりました。1890年には、すぐ近くの海でトルコの軍艦が遭難し、灯台と村の人々が救助に力をつくしました。","story":["紀伊大島の東のはし、断崖の上に白い灯台がすっと立っています。まわりは水仙の咲く原っぱ、足もとは太平洋の荒波。«なぜこんな島のはずれに?» ——ここは黒潮にのって船が行き交う航路の曲がり角で、昔から船乗りたちが恐れた難所でした。","灯台の始まりは幕末です。慶応2年（1866年）、江戸幕府はイギリスなどと «改税約書» を結び、外国船が安全に航海できるよう全国8か所に灯台を建てることを約束しました。樫野埼は、すぐ西の潮岬とともにその一つに選ばれます。幕府がたおれたあと、約束は明治政府に引きつがれました。","設計にかかわったのは、イギリスから招かれた技師リチャード・ヘンリー・ブラントン。«日本の灯台の父» と呼ばれる人です。明治3年6月10日（1870年7月8日）、石を積み上げた灯台に明かりがともりました。これが日本最初の石造灯台です。そばには灯台で働く人の官舎もつくられました。","それから20年後の明治23年（1890年）9月、台風の夜。オスマン帝国（今のトルコ）の軍艦 «エルトゥールル号» が、灯台の近くの岩礁に乗り上げて沈みました。命からがら崖をよじのぼった乗組員が、灯台の明かりをたよりに助けを求めてきたのです。灯台守と樫野の村人たちは、けが人を手当てし、自分たちの食べ物を分けて看病しました。","この遭難では500人をこえる人が亡くなり、救われたのは69人でした。灯台の近くには、亡くなった人々の慰霊碑とトルコ記念館があります。この日の出来事はトルコで長く語りつがれ、日本とトルコの友情の出発点といわれています。灯台の光は今も、同じ海を照らしつづけています。"],"tl":[["1866年","改税約書で、全国8か所に灯台を建てることが約束される"],["1868年","明治政府が灯台建設を引きつぐ"],["1870年7月8日","樫野埼灯台が初点灯（明治3年6月10日）。日本初の石造灯台"],["1890年9月16日","エルトゥールル号が近くの岩礁で遭難。灯台守と村人が救助"],["1891年","遭難者の慰霊碑が建てられる"]],"who":[["リチャード・ヘンリー・ブラントン","イギリス人技師。日本各地の灯台の設計・建設を指導した"],["樫野の村人たち","エルトゥールル号の生存者を救助し看病した"],["灯台守","灯台で働いた人。遭難者の最初の知らせを受けた"]],"deep":["改税約書（江戸条約）で約束された8灯台は、観音埼・野島埼・樫野埼・神子元島・剱埼・伊王島・佐多岬・潮岬。条約の «おまけ» のような項目が、日本の近代的な航路標識のスタートになりました。","初点灯の日付は旧暦で明治3年6月10日、新暦で1870年7月8日です。日本最初の洋式灯台は観音埼灯台（1869年）ですが、これはレンガ造り。石造としては樫野埼が最初とされます。","ブラントンは約8年間の日本滞在で、20以上の灯台の建設にかかわったといわれます。灯台だけでなく、横浜の都市計画にも助言した技術者でした。","エルトゥールル号の遭難では、生存者たちがまず灯台に助けを求めたことが記録されています。言葉が通じない中、身ぶりや国旗の絵などでやりとりしたと伝わります。この件については別のカード «エルトゥールル号遭難の地と慰霊碑» も参照を。","1985年、イラン・イラク戦争のさなかにテヘランに取り残された日本人を、トルコ航空機が救出しました。この背景にエルトゥールル号の恩があったと語られることが多く、樫野の灯台はその物語の出発点に立っています。","灯台のまわりは «樫野埼灯台と水仙の群生地» として知られ、冬から早春にかけて花が咲きます。明治の官舎（旧官舎）も残り、当時の灯台の暮らしをしのぶことができます。"],"look":["白い石造の灯台（外観）","明治につくられた旧官舎","灯台の前からの太平洋と断崖の眺め","近くのエルトゥールル号殉難将士慰霊碑とトルコ記念館"],"q":["樫野埼灯台は «日本最初の○○造灯台»。○○に入る言葉は？","«石»。明治3年（1870年）に初点灯した、日本最初の石造灯台です。"],"koji":[],"myth":"トルコ航空機による1985年の救出とエルトゥールル号の結びつきは、トルコ側の証言などで語られているが、救出の理由をそれだけに限るものではない。","img":["リチャード・ヘンリー・ブラントン","エルトゥールル号遭難事件","紀伊大島"],"wp":"樫野埼灯台","rel":{"ev":[],"grave":[]},"ph":[["c:e/ee/%E6%A8%AB%E9%87%8E%E5%B4%8E%E7%81%AF%E5%8F%B0%282021%29.jpg",4032,3024,"樫野埼灯台"],["c:4/4d/Kasinosaki-Lighthouse_zenkei.JPG",3072,2304],["c:4/41/Kasinosaki-Lighthouse_kansya.JPG",3072,2304],["c:5/50/Richard_Henry_Brunton.jpg",200,259,"リチャード・ヘンリー・ブラントン"],["c:c/ca/%E3%82%A8%E3%83%AB%E3%83%88%E3%82%A5%E3%83%BC%E3%83%AB%E3%83%AB%E5%8F%B7%E6%AE%89%E9%9B%A3%E5%B0%86%E5%A3%AB%E6%85%B0%E9%9C%8A%E7%A2%91_%282022.1.2%29.jpg",4032,3024,"エルトゥールル号遭難事件"],["c:3/36/Kii_oshima_zenkei.JPG",3072,2304,"紀伊大島"]]},{"id":"30_tanabe_jo","n":"田辺城 水門","yomi":"たなべじょう すいもん","cat":"城","rank":"A","y":1619,"era":["edo"],"sh":"市指定史跡","ad":"田辺市上屋敷2丁目","st":"JR紀伊田辺駅から歩いて約15分","la":33.7268,"lo":135.3718,"hook":"城は消えても、舟が出入りした «水の門» だけが残った。石段の下には、今も会津川の水が寄せる。","lead":"田辺城は、江戸時代に紀州藩の家老・安藤家が治めた城です。会津川の河口につくられ、舟が直接出入りできる «水門» がありました。明治に建物はなくなり、この水門の石垣と石段だけが «跡» として残っています。","story":["田辺の町を流れる会津川が、海へそそぐ手前。川べりの住宅地に、石を積んだ小さな門の跡がぽつんとあります。石段は水の中へと下りていく——ここが田辺城の水門です。«なぜお城に水の入り口が?» ——城の主が、川と海を使って人や物を動かしていたからです。","田辺に城が築かれたのは江戸時代のはじめ、浅野氏が紀伊国を治めていたころといわれます。元和5年（1619年）、徳川家康の十男・頼宣が紀州藩主になると、その «付家老» として安藤直次が田辺に入りました。直次は家康の信頼があつい武将で、若いころ長久手の戦いで手柄を立てたことで知られます。","安藤家は、紀州藩の家臣でありながら3万8千石の城を持つ特別な家でした。田辺城は «錦水城（きんすいじょう）» という美しい別名でも呼ばれます。天守のような高い建物はなく、川と海を堀がわりにした、水辺の城でした。","水門は、城の中から直接舟に乗り降りするための門です。殿様や家臣たちはここから舟を出し、川をくだって海へ。年貢や物資も水の道で運ばれました。石段が水面まで続いているのは、潮の満ち引きで水位が変わっても舟を着けられるようにするためと考えられます。","明治時代、廃藩置県ののちに城は取りこわされ、堀も埋められて町になりました。けれど水門の石垣だけは残され、今は市の史跡になっています。近くには熊野水軍ゆかりの闘雞神社もあります。水門の石段に腰をおろして川をながめれば、舟をこぐ音が聞こえてくるようです。"],"tl":[["江戸時代はじめ","浅野氏の時代に田辺に城が築かれたといわれる"],["1619年","安藤直次が紀州藩の付家老として田辺に入る"],["江戸時代","安藤家が田辺を治め、城下町が栄える"],["1868年","安藤家が «田辺藩» として独立を認められる"],["明治時代","城が取りこわされ、水門の石垣が残る"]],"who":[["安藤直次","徳川家康の家臣。紀州藩の付家老として田辺に入った安藤家の初代"],["徳川頼宣","紀州藩の初代藩主。家康の十男"],["安藤家の歴代当主","幕末まで田辺を治めた"]],"deep":["紀州藩の付家老は、田辺の安藤家と新宮の水野家。どちらも城を持ち、藩主の家来でありながら小さな大名のような存在でした。明治元年（1868年）に両家とも «藩» として独立しますが、数年で廃藩置県を迎えます。","水門の石段は、水辺に向かって斜めに下りる構造です。城の «水門» がこれほどはっきり残る例は全国的にも多くなく、水城（みずじろ）の姿を伝える貴重な遺構とされます。","«錦水城» という名は、会津川の水面に城が映る美しさから来たともいわれますが、由来ははっきりしません。","安藤直次は、小牧・長久手の戦い（1584年）で活躍したことで知られます。家康から頼宣の後見役を任されたのは、その実直さを見こまれたためといわれます。","城の跡地は住宅地になっていて、ほかの遺構はほとんど見えません。町名の «上屋敷» は、城と武家屋敷の記憶を今に伝える地名です。","田辺は熊野古道・中辺路の出発点でもあり、城下町と参詣道の宿場町の二つの顔を持っていました。水門から闘雞神社までは歩いて行ける距離です。"],"look":["水面まで下りる石段","水門の両わきの石垣","会津川の河口の地形（堀がわりの川）","近くの闘雞神社"],"q":["田辺城の水門は何のためにつくられた？","城から直接舟に乗り降りし、川から海へ出たり物資を運んだりするため。"],"koji":[],"myth":"築城の最初の時期（浅野氏時代）や «錦水城» の名の由来には諸説ある。","img":["安藤直次","田辺藩","闘雞神社"],"wp":"田辺城 (紀伊国)","rel":{"ev":[],"grave":[]},"ph":[["c:0/0d/Tanabe_castle_in_wakayama001.JPG",3264,2000,"田辺城 (紀伊国)"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:6/68/Myogenji4.jpg",6000,3992,"安藤直次"],["c:2/2f/251011_Tokei-jinja_Tanabe_Wakayama_prefecture_Japan03s3.jpg",5472,3648,"闘雞神社"]]},{"id":"30_kohechi","n":"熊野古道 小辺路（高野山〜本宮）","yomi":"くまのこどう こへち","cat":"街道","rank":"A","y":1700,"era":["heian","edo"],"sh":"国指定史跡（熊野参詣道）・世界遺産","ad":"伊都郡高野町高野山〜田辺市本宮町（途中は奈良県十津川村など）","st":"起点の高野山は南海高野線・極楽橋駅からケーブルカーとバス。終点の熊野本宮大社へはJR紀伊田辺駅・新宮駅からバス。山中は宿も少なく、健脚向け","la":34.2135,"lo":135.585,"hook":"二つの聖地を最短で結ぶ道は、いちばん険しい道だった。標高1,000mを超える峠を三つ越えて、高野山から熊野へ。","lead":"小辺路は、真言密教の聖地・高野山と、熊野本宮大社を南北にまっすぐ結ぶ約70kmの参詣道です。紀伊山地のまん中を突っ切るため、1,000mをこえる峠を三つも越えなければなりません。2004年に世界遺産 «紀伊山地の霊場と参詣道» の一部になりました。","story":["高野山の奥、女人道の入口から山道が南へのびています。«ここから熊野まで、およそ70km»。地図で見ると、高野山と熊野本宮は紀伊半島のまん中でほぼ南北に並んでいます。«なら、まっすぐ行けばいい» ——そう考えて歩き出した人を待っていたのが、紀伊山地の深い山なみでした。","小辺路には、伯母子峠（おばこ）、三浦峠、果無峠（はてなし）という、いずれも標高1,000mをこえる三つの大きな峠があります。登っては谷へ下り、また登る。ふつうは3泊4日ほどかけて歩く道です。«果無» という名前には、«どこまでも果てしない» 山道への実感がこもっているようです。","この道を歩いたのは、弘法大師と熊野の神仏の両方にお参りしたい巡礼者たちでした。とくに江戸時代には、庶民の参詣がさかんになり、高野山から熊野へ、あるいはその逆へと人が行き交いました。途中の村々は、旅人に宿を貸し、食べ物を売ってくらしを立てました。","山の中の小さな集落にとって、小辺路は «生活の道» でもありました。塩や海産物、日用品を背負って運ぶ人、山の産物を町へ届ける人。荷物を背負って峠を越える人々の姿は、昭和の初めごろまで見られたといいます。","果無峠を越えて下ると、やがて熊野川の流れが見えてきます。峠の下の «果無集落» は、石垣の上に家と畑が並ぶ «天空の里»。そして川をわたれば、熊野本宮。«ついた» ——何日も山を越えてきた巡礼者の安堵が、今も道の石段にしみこんでいるようです。"],"tl":[["816年","空海が高野山を開く（嵯峨天皇から下賜）"],["平安時代","熊野信仰が高まり、上皇・貴族の熊野詣が始まる"],["江戸時代","庶民の巡礼が増え、高野山と熊野を結ぶ道として小辺路が使われる"],["昭和初期","山村の生活道としても使われつづける"],["2004年","«紀伊山地の霊場と参詣道» として世界遺産に登録"]],"who":[["空海（弘法大師）","高野山を開いた真言宗の開祖。小辺路の北の起点の聖地"],["巡礼者たち","高野山と熊野の両方を参るために山を越えた"],["山村の人々","宿や荷運びで旅人を支えた"]],"deep":["三つの峠の標高はおおよそ、伯母子峠が約1,200m台、三浦峠と果無峠が約1,000m台とされます。山の上は平地より気温がかなり低く、冬は雪も降ります。季節や天気を選んで歩くことが大切です。","小辺路の大部分は奈良県（野迫川村・十津川村）を通ります。和歌山県内なのは、北の高野山側と、南の熊野本宮側の端の部分です。県境をまたいで世界遺産が広がっている例です。","熊野参詣道には中辺路・大辺路・小辺路・伊勢路・紀伊路などがあり、世界遺産には中辺路・大辺路・小辺路・伊勢路と、大峯奥駈道・高野山町石道などが含まれます。«辺路» の «へち» は «海辺・はし» を意味するとも考えられます。","小辺路の石畳や道しるべ（道標）、峠の茶屋跡・旅籠跡などが、江戸時代の巡礼のにぎわいを伝えます。峠の近くには、行き倒れた旅人をとむらう墓や地蔵もあり、旅のきびしさを物語っています。","果無集落（奈良県十津川村）は、小辺路の風景を代表する場所としてよく写真に登場します。今も人が住む集落なので、通るときは静かに、敷地に入らないよう注意が必要です。","«小» 辺路という名前ですが、道が小さいという意味ではなく、中辺路・大辺路と比べた呼び分けと考えられます。距離は短くても、高低差では熊野古道の中でもっともきびしい道の一つです。"],"look":["果無峠からの山なみと、峠下の果無集落","伯母子峠の旅籠跡・茶屋跡","道ばたの石仏や道標","終点の熊野本宮大社と大斎原"],"q":["小辺路にある、標高1,000mをこえる三つの峠のうち、«どこまでも続く» という意味をもつ名前の峠は？","«果無峠（はてなしとうげ）»。峠の下には果無集落があります。"],"koji":[],"myth":"«小辺路» の呼び名の由来や成立時期ははっきりしない。峠の標高は資料で多少ことなる。","img":["熊野古道","高野山","熊野本宮大社"],"wp":"小辺路","rel":{"ev":["kukai"],"grave":[]},"ph":[["c:3/37/The_upper_reaches_of_Kawarabigawa_%28near_Omata%2C_Totsukawa_vil.%29.jpg",3590,3543],["c:1/1d/The_lower_reaches_of_Nishikawa_%28from_Shiidaira_to_Yagimoto%2C_Warabio%29.jpg",3590,3560],["c:7/7e/%E6%9E%9C%E7%84%A1%E9%9B%86%E8%90%BD_%E7%86%8A%E9%87%8E%E5%8F%A4%E9%81%93_%E6%9E%9C%E7%84%A1%E5%B3%A0%E8%B6%8A_-_panoramio.jpg",4288,2848],["c:c/c6/Stone_wall_of_Yamagutis%27_remain.jpg",3072,2304],["c:9/94/Sciadopitys_verticillata.jpg",1536,2048],["c:2/20/Doudaira-buna-6.4.JPG",1600,1200],["c:7/7d/Terrace%2C_Miuraguti.jpg",1024,768],["c:2/21/Stone_wall%2C_Uenisi_remain.jpg",1024,768]]},{"id":"30_ohechi","n":"熊野古道 大辺路","yomi":"くまのこどう おおへち","cat":"街道","rank":"A","y":1700,"era":["edo"],"sh":"国指定史跡（熊野参詣道）・世界遺産（一部区間）","ad":"田辺市〜西牟婁郡白浜町・すさみ町〜東牟婁郡串本町・那智勝浦町","st":"JRきのくに線の周参見駅・見老津駅などから峠道の入口まで歩ける区間がある（区間ごとに確認を）","la":33.548,"lo":135.521,"hook":"山の中辺路に対して、こちらは «海の熊野古道»。峠の上から黒潮の海を見下ろしながら、那智をめざす。","lead":"大辺路は、田辺から紀伊半島の海ぞいを南へまわり、那智・新宮へと向かう熊野への参詣道です。上皇たちが通った中辺路にくらべ、江戸時代に文人や庶民に好まれた «海の道» です。一部の区間が世界遺産になっています。","story":["田辺から熊野三山へ向かう道は二つに分かれます。山の中をまっすぐ本宮へ向かう «中辺路» と、海ぞいを南へまわる «大辺路»。«遠回りなのに、なぜ海の道を選ぶの?» ——その答えは、峠の上に立つとわかります。目の前に広がる青い太平洋。大辺路は、景色を楽しみながら歩く道でもあったのです。","大辺路は、平安時代の上皇たちの熊野御幸ではあまり使われなかったと考えられています。にぎわったのは江戸時代。庶民の旅がさかんになり、名所めぐりや温泉を楽しみながら熊野をめざす人が増えました。途中には白浜の湯、周参見や串本の港町があり、旅の楽しみにこと欠きませんでした。","とはいえ、ずっと浜辺を歩けるわけではありません。岬や断崖が海にせまるところでは、道は山へ上がって峠を越えます。富田坂、仏坂、長井坂——こうした峠道に、石畳や古い道しるべが残っています。長井坂の尾根道からは、すさみの海岸線が絵のように見わたせます。","串本をすぎ、太地や勝浦の浦々を通ると、やがて那智の山が見えてきます。浜の宮で海からの道と合流し、大門坂をのぼって那智の滝へ。はるばる海ぞいを歩いてきた巡礼者にとって、白い滝の姿はどれほどまぶしかったことでしょう。","明治以降、鉄道や道路ができると、大辺路はしだいに忘れられ、山にうもれた区間もありました。それを地元の人々が草を刈り、道を掘り起こして、ふたたび歩ける道にしてきました。世界遺産の登録は、そうした努力の上に実ったものです。"],"tl":[["平安時代","熊野詣がさかんになるが、上皇たちは主に中辺路を通った"],["江戸時代","庶民や文人の旅がさかんになり、大辺路が使われる"],["明治以降","鉄道・道路の開通で、しだいに歩かれなくなる"],["2004年","富田坂・仏坂・長井坂などが世界遺産に登録される"],["2016年","追加登録で世界遺産の区間が広がる"]],"who":[["江戸時代の巡礼者・文人","名所や温泉を楽しみながら大辺路を歩いた"],["地元の保存会の人々","うもれた道を掘り起こし、歩ける道に戻してきた"],["那智の神仏","大辺路の旅のゴール。熊野那智大社・青岸渡寺・那智の滝"]],"deep":["大辺路の距離は、田辺から那智・新宮まで100km余りといわれます。中辺路より長く、海岸の町を結ぶため宿や港が多いのが特徴です。","世界遺産の範囲は大辺路全体ではなく、古い道の姿がよく残る区間に限られます。2004年の登録には富田坂・仏坂・長井坂が入り、その後の追加登録でも区間が加わりました。","長井坂は、すさみ町の見老津から和深方面へ越える峠道で、尾根から太平洋を見下ろす眺めのよさで知られます。大辺路でもっとも人気のある区間のひとつです。","大辺路ぞいには、熊野九十九王子と呼ばれる王子社の跡が中辺路ほど多くありません。これは、王子社が主に上皇たちの御幸路（紀伊路・中辺路）に整えられたためと考えられます。","«大辺路» の «へち» は «海辺» をさす言葉とも考えられ、海ぞいを行くこの道にふさわしい名前です。ただし、名前の成り立ちについては諸説あります。","大辺路の終わり近く、那智勝浦の浜の宮には補陀洛山寺があり、観音浄土をめざして小舟で海へ出た «補陀落渡海» の歴史が伝わります。海の道のゴールにふさわしい場所です。"],"look":["長井坂の尾根道から見る太平洋","富田坂・仏坂の石畳","道ばたの石仏や道標","ゴールの那智・浜の宮と補陀洛山寺"],"q":["海ぞいを通って那智へ向かう熊野古道を何という？","«大辺路（おおへち）»。江戸時代に文人や庶民に好まれた道です。"],"koji":[],"myth":"大辺路の距離や «へち» の語源には諸説ある。世界遺産の追加登録の区間は公式資料で確認を。","img":["熊野古道","熊野那智大社","補陀洛山寺"],"wp":"大辺路","rel":{"ev":[],"grave":[]},"ph":[["c:6/6d/Daimonzaka8618.JPG",1200,1600],["c:9/9c/Shrine_Kumano_nachi01.jpg",600,450,"熊野那智大社"],["c:4/41/Fudarakusanji03s2010.jpg",2010,1340,"補陀洛山寺"]]},{"id":"30_kiiji","n":"熊野古道 紀伊路（藤白坂〜切目）","yomi":"くまのこどう きいじ（ふじしろざか〜きりめ）","cat":"街道","rank":"A","y":1201,"era":["asuka","heian","kamakura"],"sh":"","ad":"海南市藤白〜日高郡印南町西ノ地","st":"藤白坂の入口（藤白神社）はJR海南駅から歩いて約20分。切目王子はJR切目駅から歩いて約10分","la":34.1468,"lo":135.2,"hook":"都から熊野へ、上皇たちが何度も歩いた海ぞいの道。峠には、十九歳の皇子の悲しい歌が残る。","lead":"紀伊路は、京都や大阪から紀伊国に入り、海ぞいを南へ田辺まで進む熊野参詣道です。平安時代の上皇や貴族はこの道を通って熊野へ向かいました。途中の藤白坂や切目には、歴史に残る大きな出来事がありました。","story":["平安時代の終わりから鎌倉時代にかけて、都の上皇たちは «熊野へ行こう» と何十回も旅に出ました。京都を出て淀川を船で下り、大阪から紀伊へ。そこから熊野本宮まで、行き帰りでおよそ一か月の大旅行です。その前半、紀伊国の海ぞいを南へ進む道が «紀伊路» でした。","道ぞいには «王子» と呼ばれる小さな社が次々に置かれ、上皇たちはそのたびにお参りし、歌を詠んだり舞を奉納したりしました。とくに格の高い «五体王子» のうち、藤代（藤白）王子と切目王子の二つが紀伊路にあります。","海南市の藤白神社から始まる藤白坂は、紀伊路でも最初の大きな峠です。ここは飛鳥時代の悲劇の舞台でもあります。658年、孝徳天皇の子・有間皇子は謀反の疑いをかけられ、紀の湯（今の白浜温泉）にいた斉明天皇のもとへ連れていかれました。その帰り道、この坂で命をうばわれたのです。まだ19歳でした。『万葉集』には、連行される途中に詠んだとされる «家にあれば 笥（け）に盛る飯を 草枕 旅にしあれば 椎の葉に盛る» の歌が残っています。","さらに南の切目王子（印南町）では、平安時代の終わりに歴史が動きました。平治元年（1159年）、熊野詣の途中だった平清盛のもとに «都で源義朝らが兵をあげた» という知らせが届いたのです。これが平治の乱。清盛は旅を切りあげて都へとって返し、乱をしずめて平家の天下を築いていきました。","建仁元年（1201年）には、歌人の藤原定家が後鳥羽上皇の熊野御幸にお供し、その旅日記『後鳥羽院熊野御幸記』を残しました。雨にぬれ、体調をくずしながら先を急ぐ定家のぼやきは、800年前の旅のたいへんさを生き生きと伝えてくれます。紀伊路は、そんな人々の足あとが重なった道なのです。"],"tl":[["658年","有間皇子が藤白坂で命をうばわれる"],["907年","宇多法皇が熊野へ詣でる（上皇の熊野御幸の始まりとされる）"],["1159年","熊野詣の途中の平清盛が切目で平治の乱の知らせを受ける"],["1201年","藤原定家が後鳥羽上皇の熊野御幸に随行し、日記を残す"],["江戸時代","紀州藩の熊野街道として整えられ、道標や丁石地蔵が並ぶ"]],"who":[["有間皇子","孝徳天皇の皇子。謀反の疑いで藤白坂で命を落とした"],["平清盛","熊野詣の途中、切目で平治の乱の知らせを受けた"],["藤原定家","後鳥羽上皇の熊野御幸に随行し、旅日記を残した歌人"],["後鳥羽上皇","熊野御幸を数多く重ねた上皇"]],"deep":["上皇の熊野御幸は、白河上皇・鳥羽上皇・後白河上皇・後鳥羽上皇などが何度も行い、後白河上皇は30回以上におよんだといわれます。紀伊路はその往復に使われた «御幸の道» でした。","五体王子は、藤代（藤白）・切目・稲葉根・滝尻・発心門の五つとされます。王子の中でも特に格式が高く、上皇が歌会や里神楽を奉納した場所でもありました。","有間皇子の事件の真相については、蘇我赤兄にそそのかされたのではないかという見方など、古くから議論があります。藤白坂の入口近くには、皇子をしのぶ墓碑と歌碑が建っています。","藤白坂には、一町（約109m）ごとに «丁石地蔵» が置かれ、峠までの道のりを示しています。坂の上の «筆捨松» には、絵師が景色の美しさに筆を投げたという伝説があります。","紀伊路は、世界遺産 «紀伊山地の霊場と参詣道» には含まれていません。古い道の多くが町の中の道路になっているためで、そのぶん街なかに歴史が溶けこんでいる道ともいえます。","『後鳥羽院熊野御幸記』は、上皇の熊野御幸の具体的な行程や王子での行事を伝える一級の史料です。定家が水垢離や雨の中の歩行に疲れはてる様子も記され、貴族の旅の実態がわかります。"],"look":["藤白神社（藤代王子）と境内の大楠","藤白坂の丁石地蔵と有間皇子の墓碑・歌碑","坂の上の筆捨松あたりからの海の眺め","切目王子（印南町）"],"q":["熊野詣の途中、切目で都の反乱の知らせを受け、引き返して平家の天下を築いた人物は？","«平清盛»。1159年の平治の乱のときのことです。"],"koji":[{"w":"家にあれば笥に盛る飯を 草枕 旅にしあれば椎の葉に盛る","m":"家ならちゃんとした器に盛るご飯も、旅の途中なので椎の葉に盛っている——有間皇子が連行される途中で詠んだと伝わる歌"}],"myth":"有間皇子の歌が詠まれた場所や事件の真相、筆捨松の話には伝承・諸説を含む。後白河上皇の御幸回数は資料で差がある。","img":["藤白神社","有間皇子","切目王子"],"wp":"紀伊路","rel":{"ev":[],"grave":[]},"ph":[["c:0/0d/Kiiji_Wood_bridge_01.jpg",4320,3240],["c:b/ba/Kiiji_Cobblestones_02.jpg",4320,3240],["c:f/f3/Kiiji_-_Shikagase_toge_02.jpg",4320,3240],["c:7/76/Kiiji_-_Shikagase_toge_01.jpg",4320,3240],["c:d/d0/Kiiji_-_Kotoge_01.jpg",4320,3240],["c:8/8b/Kiiji_-_Fujishiro_saka_Stone_Treasure_Pagoda.jpg",4320,3240],["c:9/9b/Kiiji_-_Fujishiro_saka_Jizo_choseki_01.jpg",4320,3240],["c:3/3f/Kiiji_-_Fujishiro_saka_02.jpg",4320,3240]]},{"id":"30_nankai_eq","n":"昭和南海地震の津波の跡と碑","yomi":"しょうわなんかいじしんのつなみのあととひ","cat":"昭和","rank":"A","y":1946,"era":["showa"],"sh":"","ad":"有田郡広川町広（広村堤防・稲むらの火の館）ほか県内各地","st":"広川町の稲むらの火の館へはJR湯浅駅から歩いて約15分","la":34.029,"lo":135.176,"hook":"戦争が終わってわずか1年あまりの冬の夜明け前、紀伊半島の海がふたたび牙をむいた。","lead":"昭和21年（1946年）12月21日の明け方、紀伊半島の南の海で大きな地震が起き、和歌山県の海岸を津波がおそいました。県内だけでも270人ほどが亡くなりました。沿岸の町には、この地震と津波を伝える碑や記録が残されています。","story":["1946年12月21日、午前4時19分。まだ暗い冬の朝、紀伊半島の人々は激しいゆれで目をさましました。震源は潮岬の沖合、マグニチュード8.0とされる巨大地震。«昭和南海地震» です。戦争が終わってまだ1年4か月。空襲で焼けた町の復興が始まったばかりのころでした。","ゆれがおさまってまもなく、海が動き出します。串本や田辺、海南、湯浅、広など、県内の海ぞいの町々に津波がおしよせました。新宮では地震のあとに大きな火事が起き、市街の広い範囲が焼けました。和歌山県内の死者はおよそ270人にのぼったとされます。","このとき、有田郡の広村（今の広川町）では、ある古い堤防が町を守りました。92年前の安政南海地震（1854年）のあと、村の商人・浜口梧陵がお金を出して村人たちとつくった «広村堤防» です。堤防の内側の家々は大きな被害をまぬかれたといわれます。«昔の人の備えが、孫の世代を救った» ——広の人々はそう語りついできました。","とはいえ、堤防の外側や、ほかの町々では多くの家が流され、尊い命が失われました。海南市や湯浅町など各地の寺や海辺には、犠牲になった人々をとむらい、«地震が来たら津波を思え» と後の世代に呼びかける碑が建てられています。碑の文字は、同じことをくり返さないでほしいという願いでもあります。","広川町の «稲むらの火の館» では、安政と昭和の二つの南海地震の記録を学ぶことができます。南海トラフの地震は、およそ100年から150年ごとにくり返し起きてきました。碑の前に立つと、«次» に備えることが、亡くなった人々への何よりの供養なのだと気づかされます。"],"tl":[["1854年","安政南海地震。広村で浜口梧陵が稲むらに火をつけ村人を導いたと伝わる"],["1855〜1858年","浜口梧陵らが広村堤防を築く"],["1946年12月21日","昭和南海地震（M8.0）。県内の沿岸を津波がおそい、新宮では大火"],["1946年","広村堤防が町の中心部を守ったといわれる"],["2007年","広川町に «稲むらの火の館» が開館"],["2015年","11月5日が国連の «世界津波の日» に定められる"]],"who":[["浜口梧陵","広村の商人。安政南海地震のあと広村堤防を築いた"],["昭和南海地震で亡くなった人々","県内でおよそ270人。各地の碑でとむらわれている"],["地域の語り部","地震と津波の体験を次の世代へ伝えてきた"]],"deep":["南海トラフでは、1707年の宝永地震、1854年の安政南海地震、1946年の昭和南海地震など、大きな地震がくり返し起きてきました。前の地震の2年前には昭和東南海地震（1944年）も起きています。","昭和南海地震は、戦後の混乱期に起きたため記録が十分でない面もあります。被害の数字は資料によって差があり、県内の死者は約270人とされることが多いです。","広村堤防は長さ約600m、高さ約5mの土の堤防で、海側に松、陸側にはぜの木が植えられました。国の史跡に指定されています。詳しくは別のカード «広村堤防» を参照。","«世界津波の日» の11月5日は、安政南海地震が起きた日（旧暦）にちなみます。浜口梧陵の «稲むらの火» の話が、国際的にも防災の象徴になっています。","«稲むらの火» の話は、小泉八雲が英語で紹介した物語をもとに、地元の教師・中井常蔵が書き直したもので、戦前の小学校の国語教科書にのりました。物語には脚色があり、史実とは細かい点が異なります。","県内の各地には、江戸時代の宝永・安政の地震から昭和南海地震まで、さまざまな時代の津波碑が残っています。碑には津波の高さや避難の教えが刻まれていることが多く、«石に刻んだ防災マニュアル» ともいえます。"],"look":["広村堤防（松並木の土手）","稲むらの火の館の展示","各地の寺や海辺に残る津波碑（刻まれた文字）","海ぞいの避難路・避難場所の案内"],"q":["毎年11月5日の «世界津波の日» は、どの地震にちなむ？","1854年の «安政南海地震»（旧暦11月5日）。浜口梧陵の «稲むらの火» の話で知られます。"],"koji":[{"w":"稲むらの火","m":"刈り取った稲の束に火をつけて村人を高台へ導き、津波から救ったという浜口梧陵の話。防災教育の物語として知られる"}],"myth":"«稲むらの火» の物語は脚色を含む。昭和南海地震の被害の数字や、広村堤防が守った範囲については資料により差がある。","img":["広村堤防","浜口梧陵","南海トラフ巨大地震"],"wp":"昭和南海地震","rel":{"ev":[],"grave":[]},"ph":[["c:e/ea/1946_Nankai_Earthquake_%2812%29.jpg",1024,705,"昭和南海地震"],["c:0/0b/%E6%9D%B1%E6%B8%A9%E5%B8%82%E7%AB%8B%E6%AD%B4%E5%8F%B2%E6%B0%91%E4%BF%97%E8%B3%87%E6%96%99%E9%A4%A8%E3%81%AB%E3%81%82%E3%82%8B%E6%98%AD%E5%92%8C%E5%8D%97%E6%B5%B7%E5%9C%B0%E9%9C%87%E5%BD%93%E6%99%82%E3%81%AE%E8%A8%98%E9%8C%B2.jpg",4032,3024],["c:b/ba/%E6%98%AD%E5%92%8C%E5%8D%97%E6%B5%B7%E5%A4%A7%E5%9C%B0%E9%9C%872.jpg",4032,3024],["c:d/de/%E6%91%82%E6%B4%A5_%E4%BD%8F%E5%90%89%E5%85%AC%E5%9C%92_%E5%A4%A7%E9%B3%A5%E5%B1%85.jpg",1648,1060],["c:7/7f/1946_Nankai_earthquake_intensity.png",512,512],["c:f/f3/Hiromura_Teibo_Seawall_Aerial_photograph.jpg",1105,782,"広村堤防"],["c:f/f4/Hamaguchi_Goryo.jpg",730,1129,"浜口梧陵"],["c:3/3b/%E9%81%8E%E5%8E%BB%E3%81%AB%E7%99%BA%E7%94%9F%E3%81%97%E3%81%9F%E5%8D%97%E6%B5%B7%E3%83%88%E3%83%A9%E3%83%95%E5%9C%B0%E9%9C%87%E3%81%AE%E9%9C%87%E6%BA%90%E5%9F%9F%E3%81%AE%E6%99%82%E7%A9%BA%E9%96%93%E5%88%86%E5%B8%83.png",963,1171,"南海トラフ巨大地震"]]},{"id":"30_saika_jo","n":"雑賀城跡（雑賀衆の拠点）","yomi":"さいかじょうあと","cat":"城","rank":"A","y":1577,"era":["muromachi","azuchi"],"sh":"","ad":"和歌山市和歌浦中（妙見山・養珠寺付近）","st":"JR和歌山駅・南海和歌山市駅からバスで和歌浦方面へ（約25分）、下車して歩いて数分（目安）","la":34.1905,"lo":135.1745,"hook":"信長を何度も手こずらせた «鉄砲の傭兵集団»。そのリーダーの城は、和歌浦の小さな丘にあったと伝わる。","lead":"雑賀城は、戦国時代に紀ノ川の河口一帯で力をもった «雑賀衆» の中心人物・鈴木氏の城と伝わります。雑賀衆は鉄砲の名手ぞろいで、石山本願寺を助けて織田信長と戦いました。今は城の建物はなく、丘の上に寺が建っています。","story":["和歌浦の海に近い小さな丘、妙見山。石段をのぼると、静かな寺の境内に出ます。ここに戦国時代、雑賀城があったと伝わります。«こんな小さな丘が、信長と戦った集団の拠点?» ——雑賀衆の強さは、城の大きさではなく、鉄砲と人のつながりにありました。","雑賀衆は、紀ノ川の河口あたりの村々の人々が集まった集団でした。一人の殿様にしたがうのではなく、村の代表たちが話し合って物事を決めたといわれます。海に面した土地柄から船の扱いがうまく、貿易にもかかわっていました。そして何より、いち早く鉄砲を手に入れ、使いこなしたのです。","元亀元年（1570年）、織田信長と大坂の石山本願寺との戦い（石山合戦）が始まると、浄土真宗の門徒の多かった雑賀衆は本願寺に味方しました。高い射撃の腕をもつ雑賀の鉄砲隊は、信長軍を何度も苦しめます。そのリーダーとして名を知られたのが «雑賀孫一（孫市）» と呼ばれる人物で、鈴木氏の一族とされます。","天正5年（1577年）、信長は大軍で紀州に攻めこみました（雑賀攻め）。雑賀衆は抵抗のすえ誓いの書を出して和睦しますが、実質的には独立を保ったともいわれます。けれど、本能寺の変のあと天下をにぎった豊臣秀吉が、天正13年（1585年）に紀州へ攻めこむと、雑賀衆の力はついにくずれていきました。","城の跡には、江戸時代に紀州藩主・徳川頼宣が母のために建てた養珠寺が立ち、はっきりした遺構はほとんど残っていません。けれど、丘から見下ろす和歌浦の海と町並みは、船と鉄砲で戦国の世を生きた人々の舞台そのもの。«雑賀» の名は、今も地名や人々の誇りの中に生きています。"],"tl":[["1543年","鉄砲が種子島に伝わる。まもなく紀州にも広まる"],["戦国時代","雑賀の鈴木氏が妙見山に城を構えたと伝わる"],["1570年","石山合戦が始まり、雑賀衆が本願寺方として戦う"],["1577年","織田信長の雑賀攻め"],["1580年","本願寺が信長と和睦し、石山合戦が終わる"],["1585年","豊臣秀吉の紀州攻め。雑賀衆の勢力が衰える"]],"who":[["雑賀孫一（孫市）","雑賀衆の鉄砲隊のリーダーとして知られる。鈴木氏の一族とされる"],["鈴木佐大夫","雑賀城の城主と伝わる人物。孫一の父とされることが多い"],["織田信長","石山本願寺と戦い、雑賀衆を攻めた"],["豊臣秀吉","1585年に紀州を攻め、雑賀衆の力をおさえた"]],"deep":["«雑賀孫一» は一人の名前ではなく、鈴木氏の当主が代々名のった通称とする説があります。鈴木孫一重秀が有名ですが、人物像には不明な点が多く、諸説あります。","雑賀衆は «雑賀荘・十ヶ郷・中郷・南郷・宮郷» の五つの地域の集まりとされ、«雑賀五組» と呼ばれることもあります。それぞれの考えが一致しないこともあり、信長に味方したグループもいました。","紀州では根来寺（岩出市）の僧兵集団 «根来衆» も鉄砲で知られ、雑賀衆とならぶ鉄砲集団でした。種子島から紀州へ鉄砲が早く伝わったのは、海の交易路でつながっていたためと考えられます。","城のあった妙見山には、今は養珠寺が建っています。養珠寺は、紀州藩初代藩主・徳川頼宣の母である養珠院（お万の方）ゆかりの寺です。戦国の城跡が、江戸時代の藩主家の寺に変わったことになります。","近くの雑賀崎には、幕末に外国船に備えた台場（砲台）の跡もあります。戦国の鉄砲集団と幕末の砲台——同じ «雑賀» の地に二つの時代の «戦い» の跡が残っているのは面白い点です。","雑賀衆の旗印は «八咫烏» だったと語られることがありますが、確かな史料で確かめられるものではなく、後世のイメージによる部分が大きいとされます。"],"look":["妙見山の丘と養珠寺の境内","丘から見下ろす和歌浦の海","周辺に残る «雑賀» の地名","足をのばして雑賀崎の町並みと台場跡"],"q":["雑賀衆が得意とした武器は？","«鉄砲»。石山合戦で本願寺方として織田信長の軍勢を苦しめました。"],"koji":[],"myth":"雑賀城の城主や築城時期、雑賀孫一の人物像、八咫烏の旗印の話には諸説・伝承を含む。","img":["雑賀衆","雑賀孫一","石山合戦"],"wp":"雑賀城","rel":{"ev":[],"grave":[]},"ph":[["c:c/cd/Saika_castle_04.jpg",2048,1536,"雑賀城"],["c:2/24/Saika_castle_03.jpg",3072,1728],["c:b/b7/Saika_castle_01.jpg",1789,1536],["c:0/0d/Saika_castle_09.jpg",1810,1474],["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:0/00/Saika_castle_11.jpg",716,579],["c:e/e0/Suzuki_Magoichi.jpg",673,893,"雑賀孫一"],["c:6/61/Ishiyama10.jpg",2797,1893,"石山合戦"]]},{"id":"30_nishihama_air","n":"和歌山大空襲の記憶（和歌山城天守の焼失）","yomi":"わかやまだいくうしゅうのきおく（わかやまじょうてんしゅのしょうしつ）","cat":"昭和","rank":"A","y":1945,"era":["edo","showa"],"sh":"国指定史跡（和歌山城）","ad":"和歌山市一番丁（和歌山城）","st":"南海和歌山市駅から歩いて約10分。JR和歌山駅からバスで約10分«公園前»下車","la":34.2272,"lo":135.1714,"hook":"«お城が燃えている»——1945年7月の夜、市民は炎の中に、町のシンボルが崩れ落ちるのを見た。","lead":"1945年（昭和20年）7月9日の夜から10日にかけて、アメリカ軍の爆撃機が和歌山市を空襲し、町の大部分が焼け、1,000人をこえる人が亡くなりました。江戸時代の天守閣もこのとき焼け落ちました。いまの天守は、戦後に市民の願いで再建されたものです。","story":["和歌山城の天守は、虎伏山（とらふすやま）と呼ばれる丘の上に建ち、町のどこからでも見えるシンボルでした。江戸時代の嘉永3年（1850年）に再建されたこの天守は、昭和10年（1935年）に当時の国宝に指定されています。«和歌山の人にとって、お城は毎日見上げる家族のようなものだった» と語る人もいます。","太平洋戦争の終わりが近づいた1945年、日本の都市はつぎつぎに空襲を受けていました。7月9日の夜、和歌山市の上空にB-29爆撃機の編隊があらわれ、焼夷弾（火をつけるための爆弾）を雨のように落としていきます。木造の家が多い町はたちまち炎につつまれました。","人々は火からのがれようと、川や公園、広い場所へ走りました。けれど、炎と熱風は逃げ場をうばっていきます。汀公園（みぎわこうえん）の周辺など、避難した先で多くの人が命を落とした場所もありました。この空襲で亡くなった人は1,000人をこえ、市街地の大部分が焼け野原になりました。","そして夜明けが近づくころ、城の天守にも火がまわります。«お城が燃えている»。三百年近く町を見守ってきた天守は、炎の中で崩れ落ちました。焼けあとで城山を見上げた人々の目に映ったのは、石垣だけの寂しい丘だったといいます。","戦後、«もう一度、お城を» という市民の声が高まり、寄付も集まって、昭和33年（1958年）に鉄筋コンクリートで天守が再建されました。今、天守を見上げるとき、その後ろにある町の悲しみと再生の物語を思い出してください。毎年7月には犠牲者を悼む行事が行われています。"],"tl":[["1585年","豊臣秀長の命で和歌山城が築かれ始める"],["1619年","徳川頼宣が入り、紀州徳川家の居城となる"],["1846年","落雷で天守などが焼失"],["1850年","天守が再建される（嘉永3年）"],["1935年","天守などが当時の国宝に指定される"],["1945年7月9〜10日","和歌山大空襲。天守が焼失し、市街地の大部分が焼ける"],["1958年","天守が鉄筋コンクリートで再建される"]],"who":[["和歌山市の人々","空襲で家族や家を失い、戦後の復興と天守の再建をになった"],["空襲で亡くなった人々","1,000人をこえる。各地の碑で悼まれている"],["徳川頼宣","紀州藩初代藩主。和歌山城を大きく整えた"]],"deep":["焼け落ちる前の天守は、大天守と小天守を渡櫓などでつないだ «連立式» と呼ばれる形でした。再建された天守もこの形を外観で再現しています。","江戸時代、天守の再建は幕府の許可が必要で、1846年の落雷焼失のあと再建が認められたのは、徳川御三家という特別な家柄だったためと考えられます。","空襲で焼けなかった建物もあります。«岡口門» は江戸時代の門として残り、国の重要文化財です。空襲の炎をくぐりぬけた数少ない証人といえます。","和歌山大空襲の死者数は資料によって差があり、1,100人前後とされることが多いです。7月9日という日付は、和歌山市では «平和を考える日» として大切にされています。","空襲でなくなったのは天守だけではありません。江戸時代の町家や寺社の多くも焼け、和歌山の町並みは戦後に大きく姿を変えました。","天守の再建は、全国の城の中でも比較的早い時期のもので、市民の寄付が大きな力になりました。戦後の «復興のシンボル» として天守を建て直した町は各地にあり、和歌山もその一つです。"],"look":["再建された天守（連立式の外観）","空襲をくぐりぬけた岡口門（重要文化財）","天守台や石垣に残る焼けあとの痕跡をさがす","空襲の犠牲者を悼む碑"],"q":["和歌山城の天守が空襲で焼けたあと、再建されたのは何年？","1958年（昭和33年）。鉄筋コンクリートで再建されました。"],"koji":[],"myth":"死者数や天守が焼け落ちた時刻については資料により差がある。","img":["和歌山城","日本本土空襲","B-29 (航空機)"],"wp":"和歌山大空襲","rel":{"ev":[],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:5/51/%E5%92%8C%E6%AD%8C%E5%B1%B1%E5%9F%8E_%E5%A4%A9%E5%AE%88%E9%96%A3%EF%BC%882024%E5%B9%B4%EF%BC%89.jpg",3024,4032,"和歌山城"],["c:c/c6/B-29s_dropping_bombs.jpg",576,896,"日本本土空襲"],["c:8/8c/B-29_Bomber_on_a_long_range_mission_in_late_1945.jpg",2048,1492,"B-29 (航空機)"]]},{"id":"30_mutsu","n":"陸奥宗光 生誕地の碑","yomi":"むつむねみつ せいたんちのひ","cat":"幕末","rank":"A","y":1844,"era":["edo","meiji"],"sh":"","ad":"和歌山市小松原通5丁目付近（生誕地の碑）。銅像は和歌山市岡山丁の岡公園","st":"生誕地の碑はJR和歌山駅からバスで«小松原通»方面、下車すぐ（目安）。岡公園の銅像は南海和歌山市駅から歩いて約20分","la":34.221,"lo":135.178,"hook":"«カミソリ大臣» と呼ばれた外交官は、紀州藩の武家屋敷町で生まれ、没落した家から身を起こした。","lead":"陸奥宗光は、明治時代に外務大臣として活躍し、幕末に結ばれた不平等条約の改正を大きく前に進めた人物です。和歌山城の近くの武家屋敷町で生まれました。生誕地には碑が建ち、城の南の岡公園には銅像があります。","story":["天保15年（1844年）、紀州藩の重臣・伊達宗広の家に男の子が生まれました。のちの陸奥宗光です。父の宗広は藩の財政を任された有能な役人で、歌人・国学者としても知られていました。ところが宗光が9歳のころ、父は藩内の争いに敗れて失脚し、家は一気に苦しい立場に追いこまれます。","«このまま紀州にいても先はない»。10代の宗光は江戸へ出て学問にはげみ、やがて勝海舟の神戸海軍操練所で学び、坂本龍馬とともに行動するようになります。龍馬の «海援隊» では、頭の回転の速さと理屈の強さで知られました。龍馬が «刀を差さなくても食べていけるのは、俺と陸奥だけだ» と言ったという話が伝わっています。","明治維新のあと、宗光は新政府で働きますが、薩摩・長州の出身者が力をもつ政府に不満を抱きます。西南戦争のころ、土佐の人々による政府転覆の計画にかかわったとされ、明治11年（1878年）から数年間、獄中で過ごしました。けれど彼は牢の中でも西洋の本を読み、翻訳にはげんだといいます。","出獄後、ヨーロッパで政治や外交を学んだ宗光は、駐米公使として明治21年（1888年）にメキシコとの間で、日本にとって初めての対等な条約を結びます。そして第2次伊藤博文内閣の外務大臣となり、明治27年（1894年）、イギリスとの間で領事裁判権（治外法権）をなくす «日英通商航海条約» の調印にこぎつけました。幕末以来の «不平等» に、大きな穴をあけたのです。","同じ年に始まった日清戦争では、下関で講和条約をまとめましたが、直後の三国干渉で遼東半島を返すことになり、苦い経験もしました。その外交の記録を書いたのが『蹇蹇録（けんけんろく）』です。明治30年（1897年）、病のため53歳で亡くなりました。生まれ故郷の碑の前に立つと、没落した武家の少年が、知恵ひとつで国の外交を背負うまでになった道のりが見えてきます。"],"tl":[["1844年","紀州藩士・伊達宗広の子として和歌山城下に生まれる"],["1852年ごろ","父・宗広が藩内の争いで失脚"],["1867年","坂本龍馬の海援隊に加わる"],["1878年","政府転覆計画への関与で投獄される（のち特赦）"],["1888年","駐米公使としてメキシコと対等条約を結ぶ"],["1894年","外務大臣として日英通商航海条約に調印し、領事裁判権の撤廃を実現"],["1895年","伊藤博文とともに下関条約を結ぶ"],["1897年","53歳で死去"]],"who":[["陸奥宗光","明治の外務大臣。条約改正を進めた «カミソリ大臣»"],["伊達宗広（千広）","宗光の父。紀州藩の重臣で、国学者・歌人"],["坂本龍馬","海援隊で宗光とともに活動した"],["伊藤博文","宗光を外務大臣に起用した首相"],["勝海舟","宗光が学んだ神戸海軍操練所をひらいた"]],"deep":["«陸奥» という姓は、宗光が自分で名のったものです。伊達家の祖先が陸奥国（東北）の伊達氏につながるという意識から選んだと考えられています。","日英通商航海条約は1894年に調印され、施行は1899年です。関税自主権の完全な回復は、のちの1911年、小村寿太郎外務大臣の時代まで待たなければなりませんでした。","メキシコとの «日墨修好通商条約»（1888年調印）は、日本が欧米以外の国とだけでなく、初めて相手と対等な立場で結んだ条約とされ、条約改正の足がかりになりました。","『蹇蹇録』は、日清戦争と三国干渉をめぐる外交の内幕を記した記録です。書名は中国の古典『易経』の言葉 «蹇蹇匪躬（けんけんひきゅう）»（身を顧みず主君に尽くす）から取られています。","生誕地の碑は、かつて武家屋敷が並んでいた地区に立っています。2017年には、功績を紹介する新しい石碑と看板が整えられました。","龍馬が陸奥を高く評価したという言葉は、後年の回想や伝聞によるもので、表現はいくつかのバージョンがあります。確かな一次史料で裏づけられるものではない点に注意が必要です。"],"look":["生誕地の石碑と功績の案内板","岡公園の陸奥宗光銅像","碑のまわりの旧武家屋敷町の区画","近くの和歌山城（宗光の故郷の景色）"],"q":["陸奥宗光が外務大臣として1894年に結び、領事裁判権（治外法権）をなくした条約は？","«日英通商航海条約»。不平等条約の改正に大きく前進しました。"],"koji":[{"w":"蹇蹇匪躬（けんけんひきゅう）","m":"自分の身をかえりみず、主君や国のために苦労してつくすこと。陸奥の『蹇蹇録』の書名の由来"}],"myth":"龍馬の «刀を差さなくても…» の言葉は伝聞・回想による。父の失脚の年や生誕地の正確な位置には資料により差がある。","img":["蹇蹇録","日英通商航海条約","海援隊"],"wp":"陸奥宗光","rel":{"ev":[],"grave":[]},"ph":[["c:0/08/Mutsu_Munemitsu.jpg",1024,1339,"陸奥宗光"],["c:c/c3/Bronze_statue_of_Munemitsu_Mutsu.jpg",1167,1616],["c:4/47/Furukawajunkici.jpg",976,1192],["c:8/8a/Mutsu_family.jpg",600,898],["c:9/9a/Munemitsu_Mutsu.jpg",582,881],["c:b/b9/Anglo_Japanese_Treaty_of_Commerce_and_Navigation_16_July_1894.jpg",2126,1656,"日英通商航海条約"]]},{"id":"30_hosshinmon","n":"発心門王子","yomi":"ほっしんもんおうじ","cat":"街道","rank":"B","y":1201,"era":["heian","kamakura"],"sh":"国指定史跡（熊野参詣道）・世界遺産","ad":"田辺市本宮町三越","st":"JR紀伊田辺駅・新宮駅からバスで«本宮大社前»、乗り換えて«発心門王子»下車すぐ（本数が少ないので時刻表の確認を）","la":33.86,"lo":135.744,"hook":"«ここから先は神の国»。熊野本宮へ向かう巡礼者は、この門で心を新たにした。","lead":"発心門王子は、熊野古道・中辺路にある王子社で、とくに格の高い «五体王子» の一つです。昔はここに大きな鳥居があり、熊野本宮大社の神域の入口とされていました。ここから本宮大社までは歩いて約2時間の人気のコースです。","story":["山あいの道を歩いていくと、朱色の小さな社が杉木立の中にあらわれます。発心門王子。«発心» とは、仏の道を歩もうと心を起こすこと。«なぜこんな名前がついたの?» ——ここを越えると、いよいよ熊野本宮大社の神聖な領域に入る、と考えられていたからです。","平安時代から鎌倉時代にかけて、上皇や貴族たちは長い旅のすえにここにたどりつきました。当時は «発心門» と呼ばれる大鳥居が立っていたといわれ、巡礼者はその門をくぐって心をあらため、本宮へ向かったのです。","建仁元年（1201年）の秋、後鳥羽上皇の熊野御幸に従った歌人・藤原定家も、この地に泊まりました。定家は旅日記『後鳥羽院熊野御幸記』に発心門のことを書き残しています。雨や寒さ、体調不良と戦いながら歩いてきた定家にとって、本宮を目の前にしたこの場所は、ほっと息をつける所だったに違いありません。","今、発心門王子から本宮大社までの約7kmは、熊野古道の中でも歩きやすく人気のある区間です。途中には水呑王子、伏拝王子、祓殿王子が並びます。伏拝王子からは、木々のあいだに本宮の旧社地 «大斎原（おおゆのはら）» の大鳥居が見え、昔の巡礼者はここで思わず伏して拝んだといわれます。","«ここまで来た»。発心門は、長い旅の終わりの始まりです。道ばたの苔むした石、谷をわたる風、遠くの鳥の声。900年前の人々と同じように、ここで一度立ち止まり、深呼吸をしてから本宮への最後の道を歩いてみてください。"],"tl":[["平安時代","熊野本宮の神域の入口として発心門が置かれたとされる"],["1201年","藤原定家が後鳥羽上皇の熊野御幸に随行し、発心門に泊まる"],["鎌倉時代","上皇・貴族の熊野詣が続く"],["明治時代","神社合祀で王子社の多くが近くの神社にまとめられる"],["2004年","熊野参詣道の一部として世界遺産に登録"]],"who":[["藤原定家","後鳥羽上皇に随行し、発心門のことを旅日記に書いた歌人"],["後鳥羽上皇","熊野御幸を何度も行った上皇"],["和泉式部","伏拝王子にゆかりの歌の伝説が残る平安時代の歌人"]],"deep":["五体王子は、藤代（藤白）・切目・稲葉根・滝尻・発心門。発心門王子は、そのうちもっとも本宮に近い王子です。","«発心門» の大鳥居は今は残っていません。どのような鳥居だったかは史料から詳しくはわからず、現在の社は後世に整えられたものです。","定家の『後鳥羽院熊野御幸記』には、発心門での宿泊の様子が記されています。この日記は、上皇の熊野御幸の行程を具体的に知ることができる貴重な史料です。","伏拝王子には、和泉式部が熊野詣の途中で月のさわりになり参拝をためらっていたところ、夢に熊野権現があらわれて参拝を許したという伝説があります。熊野が «女性にも開かれた聖地» だったことを語る話として知られます。","大斎原は、明治22年（1889年）の大水害まで熊野本宮大社の社殿があった熊野川の中洲です。流されずに残った社殿が今の場所に移され、旧社地には日本最大級の大鳥居が建っています。","発心門王子の周辺は «三越（みこし）» と呼ばれる山里で、茶畑や棚田の風景が広がります。古道歩きの途中で、今も人が暮らす里の暮らしにふれられるのも魅力です。"],"look":["朱色の発心門王子の社","王子から本宮へ向かう古道の石畳","伏拝王子から見下ろす大斎原の大鳥居","三越の山里の風景"],"q":["«五体王子» のうち、熊野本宮大社にもっとも近い王子は？","«発心門王子»。本宮の神域の入口とされました。"],"koji":[{"w":"発心","m":"仏の道を志す心を起こすこと。新しいことを始めようと決意する意味でも使う"}],"myth":"発心門の大鳥居の姿は不明。和泉式部の伏拝の歌は伝説で、作者を疑う説もある。","img":["熊野古道","伏拝王子","大斎原"],"wp":"発心門王子","rel":{"ev":[],"grave":[]},"ph":[["c:2/29/Sacred_arch%2C_HOSSHINMON-oji.JPG",768,1024,"発心門王子"],["c:7/77/HOSSHINMON-oji_shrine.jpg",768,1024],["c:c/c1/HOSSHINMON-oji.JPG",1024,768]]},{"id":"30_tsugizakura","n":"継桜王子と野中の一方杉","yomi":"つぎざくらおうじとのなかのいっぽうすぎ","cat":"街道","rank":"B","y":1906,"era":["heian","kamakura","meiji"],"sh":"国指定史跡（熊野参詣道）・世界遺産","ad":"田辺市中辺路町野中","st":"JR紀伊田辺駅からバスで約1時間10分«野中一方杉»下車すぐ（目安）","la":33.8225,"lo":135.6245,"hook":"大杉の枝は、なぜかみな南へのびている。その先にあるのは熊野那智大社——そして、この杉を守った一人の学者がいた。","lead":"継桜王子は、熊野古道・中辺路の野中の里にある王子社です。境内には、枝がいっせいに南を向いてのびる巨大な «一方杉» が立ち並びます。明治時代にこの杉が切られそうになったとき、博物学者の南方熊楠が反対の声を上げました。","story":["中辺路の野中の里。石段をのぼったところに、ひっそりと継桜王子の社があります。まわりを囲むのは、幹の太さが大人数人でもかかえきれないほどの大杉たち。見上げると、ふしぎなことに気づきます。«どの枝も、南にばかりのびている»——。","南の方角には熊野那智大社があります。そのため地元では «那智の神さまを拝んでいる杉» とも言われてきました。実際には、北側の谷や日当たりの関係で枝の向きがそろったと考えられていますが、何百年もその向きを守ってきた姿には、思わず手を合わせたくなる迫力があります。","«継桜» という名前にも言い伝えがあります。平安時代の終わり、奥州の藤原秀衡が熊野詣をしたとき、ヒノキに桜の枝を継いだところ、それが根づいて花を咲かせた、というものです。この «秀衡桜» は、代を重ねて今も王子の近くで春に花を咲かせます。","明治39年（1906年）、政府は «神社合祀» を進め、小さな神社を大きな神社にまとめていきました。継桜王子も合祀され、境内の大杉は売られて切られそうになります。«森を切れば、そこにすむ生き物も、村の人々の心のよりどころも失われる»。田辺に住む博物学者・南方熊楠は、新聞や手紙で激しく反対しました。","熊楠たちの努力もあって、一方杉のうち何本かは切られずに残りました。今、杉の根元に立つと、熊楠の怒りと願いが聞こえてくるようです。すぐ下の «野中の清水» は、旅人がのどをうるおした名水。杉と清水と古道が、昔のままの熊野の姿を今に伝えています。"],"tl":[["平安時代","熊野詣の道に継桜王子が置かれる"],["平安時代末","藤原秀衡が桜の枝を継いだという «秀衡桜» の伝説"],["1906年","神社合祀令が出され、王子社が合祀の対象となる"],["明治時代末","南方熊楠が合祀と森林伐採に反対し、一方杉の一部が残る"],["1985年","«野中の清水» が名水百選に選ばれる"],["2004年","熊野参詣道の一部として世界遺産に登録"]],"who":[["南方熊楠","博物学者。神社合祀と森林の伐採に反対し、一方杉を守ろうとした"],["藤原秀衡","奥州藤原氏。熊野詣で桜を継いだという伝説がある"],["野中の里の人々","王子社と大杉を守り、古道の宿場として旅人を迎えた"]],"deep":["一方杉は樹齢800年ほどとされる大杉が何本も立ち、最大のものは幹周り8m前後といわれます。県の天然記念物に指定されています。","神社合祀は、一つの村に神社を一つにまとめ、財政を安定させることを目的に進められました。和歌山県と三重県ではとくに激しく行われ、多くの小さな社と鎮守の森が失われました。","熊楠の合祀反対運動は、植物学者・松村任三あての書簡などを柳田国男が «南方二書» として印刷して配ったことで広く知られるようになりました。日本の自然保護運動の先がけといわれます。","«秀衡桜» の伝説は、秀衡とその妻が熊野詣の途中、滝尻の乳岩に赤ん坊を置いていったという話と結びついて語られることがあります。いずれも史実としては確かめられない伝承です。","«野中の清水» は環境庁（当時）の名水百選の一つで、昔から旅人や里の人々の生活を支えてきました。石組みの水場の姿もよく保たれています。","継桜王子の近くには、旅籠のあった宿場の雰囲気も残ります。野中は近露と並ぶ中辺路の宿場で、ここから本宮まではさらに山を越えて進みます。"],"look":["南に枝をのばす一方杉の大木","石段の上の継桜王子の社","春に咲く秀衡桜","坂を下りた先の野中の清水"],"q":["明治時代、神社合祀に反対して継桜王子の一方杉を守ろうとした博物学者は？","«南方熊楠»。日本の自然保護運動の先がけとされます。"],"koji":[],"myth":"«那智を拝む杉» や «秀衡桜» は伝承。杉の本数・樹齢・大きさは資料で差がある。","img":["南方熊楠","神社合祀","中辺路"],"wp":"継桜王子","rel":{"ev":[],"grave":[]},"ph":[["c:6/62/Tsugizakura-oji_and_Ippo_Sugi.JPG",1024,768,"継桜王子"],["c:3/38/Nonaka_spring_water.jpg",4896,3672],["c:c/c7/Nonaka_no_shimizu.jpg",4896,3672],["c:8/89/Tugizakura-oji_shrine.jpg",2903,3582],["c:4/42/Monument_TSUGIZAKURA-oji_remains.JPG",768,1024],["c:b/b5/Minakata-Kumagusu.jpg",900,1300,"南方熊楠"]]},{"id":"30_asuka","n":"阿須賀神社（徐福伝承と弥生の遺跡）","yomi":"あすかじんじゃ","cat":"寺社","rank":"B","y":-100,"era":["yayoi","heian"],"sh":"","ad":"新宮市阿須賀1丁目","st":"JR新宮駅から歩いて約10分","la":33.733,"lo":135.9965,"hook":"熊野川の河口にぽこんと盛り上がる小山。熊野の神がここに降り立ったとも、徐福がこの山をめざしたとも語られる。","lead":"阿須賀神社は、熊野川の河口近くの «蓬莱山» という小さな山のふもとにある神社です。熊野の神々の信仰の始まりにかかわる古い社といわれ、徐福の伝説でも知られます。境内からは、弥生時代の人々の住まいの跡が見つかっています。","story":["新宮の町の北、熊野川が海へ流れこむ手前に、お椀をふせたような形の小山があります。これが «蓬莱山»。«蓬莱» とは、中国の伝説で仙人が住むという海上の山のこと。その麓に鎮まるのが阿須賀神社です。","«なぜ、この小さな山が大切にされてきたの?» ——熊野川の河口は、海から来る人にも川を下る人にもよく目立つ場所でした。熊野の神々がどのようにこの地に迎えられたかを語る古い縁起（由来の物語）にも、阿須賀の名があらわれます。熊野速玉大社がある新宮の町の信仰の «ふるさと» の一つとも言われるのはそのためです。","蓬莱山は、秦の徐福の伝説とも深く結びついています。不老不死の薬を求めて船出した徐福の一行が、この山を目印に上陸した——と新宮では語りつがれてきました。境内には «徐福之宮» がまつられ、徐福公園とあわせて伝説の舞台になっています。","この場所の古さは、伝説だけではありません。境内の発掘調査で、弥生時代の竪穴住居の跡や土器が見つかっているのです。二千年ほど前、この川べりの小山のまわりで人々が暮らし、米をつくり、海と川の恵みを受けていたのでした。","伝説の徐福がやってきたとされるのも、ちょうど弥生時代にあたります。«大陸から新しい技術をもった人々がやってきた» という記憶と、実際に見つかった弥生の暮らしの跡。その二つがこの小山で重なっているのが、阿須賀神社のいちばんの面白さです。"],"tl":[["弥生時代","蓬莱山のまわりに人々が暮らす（竪穴住居跡が見つかる）"],["前3世紀ごろ","徐福が船出したと『史記』に記される（熊野上陸は伝説）"],["平安時代","熊野信仰が高まり、阿須賀社も崇敬を集める"],["江戸時代","紀州藩・新宮の人々の信仰を受ける"],["昭和時代","境内の発掘調査で弥生時代の遺構が確認される"]],"who":[["徐福","秦の方士。蓬莱山を目印に熊野に上陸したと伝わる"],["熊野の神々","阿須賀の地にまつられたと古い縁起に語られる"],["弥生時代の人々","蓬莱山のまわりで暮らしていた"]],"deep":["蓬莱山は標高50mに満たない小さな山で、熊野川の河口の平地にぽつんとそびえます。その形から、古くから神が宿る «神奈備（かんなび）» の山として信仰されてきたと考えられます。","熊野の神々の由来を語る縁起には、神が各地を移ったのち熊野に降り立ったという話があり、その中に阿須賀の名が出てきます。どの縁起を重視するかで解釈が異なり、阿須賀と神倉山・速玉大社の関係には諸説あります。","境内の遺跡は «阿須賀神社境内遺跡» と呼ばれ、弥生時代の竪穴住居跡のほか、古墳時代以降の遺物も見つかっています。長い時代にわたって人が集まった場所だったことがわかります。","蓬莱山からは、平安時代以降の信仰を物語る遺物（経塚にかかわるものなど）も見つかったといわれ、熊野信仰の歴史を考える上で重要な場所です。","阿須賀神社の境内には、新宮市立歴史民俗資料館があり、周辺の遺跡の出土品や新宮の歴史を知ることができます（開館日は事前に確認を）。","新宮の «新宮» という名は、熊野速玉大社を «新しい宮» と呼んだことに由来するといわれ、それに対する «古い宮» がどこかについては、神倉神社とする説が一般的です。阿須賀もまた、新宮の信仰の源流を考えるときに欠かせない場所です。"],"look":["お椀をふせたような蓬莱山の姿","境内の徐福之宮","弥生時代の遺跡の案内板","境内の歴史民俗資料館"],"q":["阿須賀神社の背後にある、中国の伝説の仙人の山と同じ名前の小山は？","«蓬莱山»。徐福がこの山を目印に上陸したと伝わります。"],"koji":[{"w":"蓬莱","m":"中国の伝説で、東の海にあり仙人が住むという山。めでたいものの象徴"}],"myth":"徐福の上陸は伝説。熊野の神々の降臨をめぐる縁起の解釈や、阿須賀と «元宮» の関係には諸説ある。","img":["徐福","熊野速玉大社","神倉神社"],"wp":"阿須賀神社","rel":{"ev":[],"grave":[]},"ph":[["c:3/3b/171008_Asuka-jinja_Shingu_Wakayama_pref_Japan01n.jpg",6000,4000,"阿須賀神社"],["c:c/cf/171008_Asuka-jinja_Shingu_Wakayama_pref_Japan14n.jpg",6000,4000],["c:4/4f/171008_Asuka-jinja_Shingu_Wakayama_pref_Japan13n.jpg",6000,4000],["c:a/a9/171008_Asuka-jinja_Shingu_Wakayama_pref_Japan12n.jpg",5550,3700],["c:3/35/171008_Asuka-jinja_Shingu_Wakayama_pref_Japan11n.jpg",6000,4000],["c:0/0e/171008_Asuka-jinja_Shingu_Wakayama_pref_Japan10n.jpg",6000,4000],["c:7/7e/171008_Asuka-jinja_Shingu_Wakayama_pref_Japan09n.jpg",6000,4000],["c:8/8a/171008_Asuka-jinja_Shingu_Wakayama_pref_Japan06n.jpg",6000,4000]]},{"id":"30_taigyaku","n":"大逆事件の犠牲者顕彰碑（新宮）","yomi":"たいぎゃくじけんのぎせいしゃけんしょうひ","cat":"事件","rank":"B","y":1911,"era":["meiji","heisei"],"sh":"","ad":"新宮市丹鶴1丁目（旧西村家住宅＝西村記念館の庭）","st":"JR新宮駅から歩いて約5分","la":33.7285,"lo":135.99,"hook":"«毒取る（ドクトル）さん» と慕われた町医者は、なぜ死刑になったのか。百年かけて取りもどされた名誉の碑。","lead":"1910年（明治43年）、天皇の暗殺を計画したとして多くの社会主義者などが捕らえられ、翌年12人が死刑になりました。これを «大逆事件» といいます。新宮からも6人が罪に問われましたが、戦後の研究で、多くは無実の罪（冤罪）だったと考えられるようになりました。碑は、この6人の名誉回復を願って建てられたものです。","story":["明治時代の新宮に、大石誠之助という医者がいました。アメリカやカナダで医学を学んで帰り、町で医院を開いた彼は、貧しい人からはお金を取らないこともあったといいます。«ドクトル（毒取る）さん» ——町の人々は親しみをこめてそう呼びました。彼はまた、社会の不平等に心を痛め、新しい思想にも関心を寄せていました。","1910年、長野県で爆弾をつくっていた人々が捕まったことをきっかけに、政府は全国で社会主義者や無政府主義者をつぎつぎに逮捕しました。«天皇を殺そうとした» という罪で、裁判はたった一度の非公開の審理。翌1911年1月、24人に死刑の判決が下り、そのうち12人は無期懲役に減刑されましたが、12人は判決からわずか数日で処刑されました。","新宮からは、大石誠之助のほか、成石平四郎、高木顕明、峯尾節堂、崎久保誓一、成石勘三郎の6人が罪に問われました。大石と成石平四郎は処刑され、浄泉寺の住職だった高木顕明は獄中で亡くなり、峯尾も獄中で病死しました。«なぜ、この小さな町から6人も?» ——大石のまわりで語り合った仲間であったことが、そのまま «謀議» とされてしまったのです。","事件のあと、新宮では長いあいだ、彼らの名を口にすることさえはばかられました。けれど戦後、裁判の記録が調べられ、多くの人が計画とは関係なかったことが明らかになっていきます。平成の時代になって、新宮市議会は大石らの名誉回復を宣言し、市民の手で顕彰碑が建てられました。2018年には、大石誠之助が新宮市の名誉市民に選ばれています。","碑が立つのは、大石の甥で、建築家・教育者として知られる西村伊作が建てた旧西村家住宅（西村記念館）の庭です。碑には6人の名前が刻まれています。静かな庭で碑の前に立つとき、思想や言葉が罪とされた時代があったこと、そしてその名誉を取りもどすのに百年近い時間がかかったことを、心に刻みたいと思います。"],"tl":[["1896年","大石誠之助が新宮で医院を開く"],["1910年","大逆事件の一斉検挙。新宮の6人も逮捕される"],["1911年1月","24人に死刑判決（12人は無期に減刑）。12人が処刑され、新宮の大石・成石平四郎も含まれる"],["1914年","高木顕明が獄中で亡くなる"],["2001年","新宮市議会が6人の名誉回復を宣言"],["2003年","西村記念館の庭に犠牲者顕彰碑が建てられる"],["2018年","大石誠之助が新宮市名誉市民に"]],"who":[["大石誠之助","新宮の医師。«ドクトルさん» と慕われた。大逆事件で処刑"],["成石平四郎","本宮出身。大逆事件で処刑"],["高木顕明","浄泉寺の住職。差別や戦争に反対し、獄中で死去"],["峯尾節堂","臨済宗の僧。獄中で病死"],["崎久保誓一・成石勘三郎","無期懲役となった新宮グループの二人"],["西村伊作","大石の甥。碑が立つ旧西村家住宅を建てた"]],"deep":["大逆事件の裁判は大審院（今の最高裁判所にあたる）だけで行われ、一審で終わる «一審終審»。非公開で、弁護側の証人もほとんど認められませんでした。判決から約1週間で処刑が行われたことも、国内外から批判を受けました。","事件の中心人物とされた幸徳秋水は、大石と交流があり、1908年ごろ新宮を訪れています。この訪問時の集まりが «謀議» の場とされたことが、新宮の人々が巻きこまれる原因になりました。","高木顕明は真宗大谷派の僧で、部落差別や日露戦争に反対したことで知られます。事件後に宗派から処分されましたが、1996年に真宗大谷派は処分を取り消し、名誉を回復しました。","作家・佐藤春夫は新宮出身で、大石の死を «愚者の死» という詩にうたいました。表向きは皮肉のようでいて、じつは権力への抗議が込められていると読まれています。与謝野鉄幹も大石の死を悼む詩を書きました。","大石誠之助は、ことば遊びをこめて自分で «ドクトル（毒取る）» と名のったともいわれます。料理や西洋文化にも通じ、新宮に洋食やハイカラな暮らしを広めた人物でもありました。","事件の «首謀者» とされた人々の中にも、実際に爆弾の計画にかかわった人は数人だけだったと考えられています。国家が思想をどう扱ったかを考える上で、今も議論の続く事件です。"],"look":["6人の名前が刻まれた顕彰碑","旧西村家住宅（国の重要文化財・西村記念館）","近くの大石誠之助の宅跡の案内","南谷墓地や浄泉寺など、ゆかりの場所"],"q":["新宮の町の人々が、医師・大石誠之助を呼んだ親しみをこめた呼び名は？","«ドクトル（毒取る）さん»。貧しい人から治療費を取らないこともあったといいます。"],"koji":[],"myth":"事件の全体像や一人ひとりの関与の程度には研究上の議論がある。碑の建立年は和歌山県の資料による。","img":["大石誠之助","高木顕明","西村伊作"],"wp":"大逆事件","rel":{"ev":["jinmu"],"grave":[]},"ph":[["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:e/e0/Shingu-taigyaku-1024.jpg",1024,768],["c:7/72/%E5%A4%A7%E7%9F%B3%E8%AA%A0%E4%B9%8B%E5%8A%A9.jpg",188,268,"大石誠之助"],["c:9/98/Takagi_Kenmyo.png",507,752,"高木顕明"]]},{"id":"30_haruo","n":"佐藤春夫記念館","yomi":"さとうはるおきねんかん","cat":"近代","rank":"B","y":1927,"era":["taisho","showa"],"sh":"","ad":"新宮市新宮（熊野速玉大社の境内）","st":"JR新宮駅から歩いて約15分","la":33.7302,"lo":135.9845,"hook":"«あはれ 秋風よ»——秋刀魚の詩人の東京の家が、まるごと故郷の神社の森へ引っこしてきた。","lead":"佐藤春夫は、新宮生まれの詩人・小説家で、«秋刀魚の歌» などで知られます。記念館は、東京・文京区にあった春夫の自宅を、ふるさと新宮の熊野速玉大社の境内に移して建て直したものです。1989年に開館しました。","story":["熊野速玉大社の朱色の社殿のそばに、洋風の窓と八角形の塔をもつ、ちょっと不思議な家があります。これが佐藤春夫記念館。«なぜ神社の中に洋館が?» ——じつはこの家、もとは東京の関口（文京区）に建っていた春夫の住まいで、それを丸ごと解体して新宮まで運び、建て直したものなのです。","佐藤春夫は明治25年（1892年）、新宮の医者の家に生まれました。熊野の山と川と海にかこまれて育った少年は、やがて東京に出て文学の道へ進みます。大正時代に小説『田園の憂鬱』で注目され、『殉情詩集』などで詩人としても大きな人気を集めました。","春夫の詩でいちばん有名なのが «秋刀魚の歌» です。«あはれ 秋風よ 情（こころ）あらば伝へてよ»。夕ぐれに一人で秋刀魚を食べる男の、切ない思いをうたった詩です。この詩の背景には、友人の作家・谷崎潤一郎の妻・千代をめぐる、複雑な恋の物語がありました。のちに千代は春夫の妻となり、この出来事は «細君譲渡事件» として世間をさわがせました。","東京の家は、昭和2年（1927年）に建てられました。設計したのは、同じ新宮出身の西村伊作だといわれます。春夫はこの家で多くの作品を書き、たくさんの弟子や文学者が出入りしました。«門弟三千人» といわれたほど、春夫を慕う若者は多かったのです。","春夫は昭和39年（1964年）に亡くなりました。その後、家は故郷の新宮に移され、記念館として生まれ変わります。原稿や愛用の品々が展示された部屋の窓からは、熊野速玉大社の森が見えます。熊野の緑の中に帰ってきた詩人の家——その姿は、ふるさとを生涯愛した春夫にぴったりかもしれません。"],"tl":[["1892年","新宮に生まれる"],["1918〜1919年","小説『田園の憂鬱』を発表し注目される"],["1921年","『殉情詩集』を刊行。«秋刀魚の歌» もこのころの作"],["1927年","東京・関口に自宅を建てる"],["1930年","谷崎潤一郎と千代の離婚、千代との結婚が公表される"],["1960年","文化勲章を受章"],["1964年","72歳で死去"],["1989年","東京の自宅を移築し、佐藤春夫記念館が開館"]],"who":[["佐藤春夫","新宮出身の詩人・小説家。«秋刀魚の歌» の作者"],["谷崎潤一郎","作家。春夫の友人で、妻・千代をめぐって春夫と関係がこじれた"],["佐藤千代","谷崎の元妻。のちに春夫の妻となる"],["西村伊作","新宮出身の建築家・教育者。春夫の家を設計したといわれる"]],"deep":["«秋刀魚の歌» は1921年ごろに発表された詩で、«さんま苦いか塩っぱいか» の一節も有名です。谷崎家の食卓の思い出がもとになっているといわれます。","«細君譲渡事件» では、谷崎・千代・春夫の三人連名で «千代は春夫と結婚する» というあいさつ状を知人に送り、新聞でも大きく報じられました。当時としては非常に異例な出来事でした。","春夫は、新宮出身の大石誠之助が大逆事件で処刑されたとき、詩 «愚者の死» を書きました。ふるさとの事件への複雑な思いが込められた作品です。","建物の特徴は、八角形の塔屋やベランダ、洋風と和風が混ざった間取りです。移築にあたっては、東京の家の姿をできるだけ忠実に再現したとされています。","春夫の門下には、井伏鱒二、太宰治、檀一雄、吉行淳之介などがいたといわれます。太宰治が芥川賞を切望して春夫に手紙を送った話はよく知られています。","記念館は熊野速玉大社の境内にあり、参拝とあわせて訪ねることができます。休館日（月曜日など）があるので、訪ねる前に確認すると安心です。"],"look":["八角形の塔屋をもつ洋風の外観","春夫の書斎や応接間","原稿・愛用品の展示","となりの熊野速玉大社の社殿と «梛（なぎ）» の大木"],"q":["佐藤春夫の有名な詩で、秋の夕ぐれに一人で食べる魚をうたったものは？","«秋刀魚の歌»。«あはれ 秋風よ» で始まります。"],"koji":[{"w":"あはれ 秋風よ 情あらば伝へてよ","m":"«秋刀魚の歌» の冒頭。心があるなら、この思いを伝えてくれ、と秋風に呼びかけることば"}],"myth":"東京の家の設計者を西村伊作とすることや、門下生の範囲には資料により書き方の差がある。","img":["佐藤春夫","秋刀魚の歌","谷崎潤一郎","熊野速玉大社"],"wp":"佐藤春夫記念館","rel":{"ev":[],"grave":[]},"ph":[["c:b/b6/Sato_Haruo_Memorial_Museum05s2000.jpg",2000,1500],["c:4/44/Sato_Haruo_Memorial_Museum02s2040.jpg",1360,2040],["c:5/53/Sato_Haruo_Memorial_Museum03s1800.jpg",1350,1800],["c:2/28/Sato_Haruo_Memorial_Museum01s1650.jpg",1650,1100],["c:e/e9/Haruo_Sato_01.jpg",550,530,"佐藤春夫"],["c:1/1b/Portrait_of_Tanizaki_Jun%27ichir%C5%8D_-_Atami_-_1950_-_Kimura_Ihei.png",1656,2461,"谷崎潤一郎"],["c:f/fa/Kumanohayatama-taisha12s5s4200.jpg",4200,2800,"熊野速玉大社"]]},{"id":"30_shionomisaki","n":"潮岬灯台","yomi":"しおのみさきとうだい","cat":"近代","rank":"B","y":1873,"era":["meiji"],"sh":"","ad":"東牟婁郡串本町潮岬","st":"JR串本駅からバスで約20分«潮岬灯台前»下車すぐ（目安）","la":33.436,"lo":135.756,"hook":"本州のいちばん南、黒潮がぶつかる岬に、白い灯台は150年立ちつづけている。","lead":"潮岬灯台は、本州最南端の潮岬に立つ灯台です。幕末に外国と約束した8つの灯台の一つで、明治のはじめに明かりがともりました。今も現役で、中にのぼって海を見わたせる «参観灯台» です。","story":["串本の町から橋をわたったような細い土地の先に、潮岬があります。ここは本州のいちばん南。目の前の海には、黒潮が速い流れとなって東へ走っています。«なぜここに灯台が?» ——黒潮にのって行き交う船にとって、潮岬は必ず回らなければならない、そして荒れやすい岬だったからです。","慶応2年（1866年）、江戸幕府はイギリスなどとの «改税約書» で、全国8か所に西洋式灯台を建てることを約束しました。潮岬は、すぐ東の樫野埼とともにその一つに選ばれます。明治政府は約束を受けつぎ、イギリス人技師リチャード・ヘンリー・ブラントンの指導で工事が進められました。","最初にともったのは、明治2年から3年にかけて建てられた仮の木造の灯台でした。そして明治6年（1873年）、石造りの本格的な灯台が完成し、明かりがともります。岬の上で夜ごと回る光は、遠い海の上からも見え、船乗りたちに «ここが潮岬だ» と知らせました。","灯台守たちは、家族とともにこの岬に住み、雨の日も嵐の日も光を守りました。燃料を運び、レンズをみがき、夜通し見張る。«灯台の灯を消さない» ——それが彼らの誇りでした。今は自動化され、灯台守はいなくなりましたが、その仕事ぶりは資料館で知ることができます。","灯台の中の階段をのぼると、ぐるりと太平洋が広がります。晴れた日には水平線が丸く見え、«地球は丸い» と実感できるほど。すぐ近くの «潮岬望楼の芝» の広い芝生もあわせて、明治から続く海の守り人の物語にふれてみてください。"],"tl":[["1866年","改税約書で、潮岬を含む全国8か所の灯台建設が約束される"],["1870年ごろ","仮の木造灯台が点灯する"],["1873年","石造の灯台が完成し、初点灯"],["昭和時代","灯台の設備が改良される"],["現在","中にのぼれる参観灯台として公開"]],"who":[["リチャード・ヘンリー・ブラントン","イギリス人技師。潮岬など日本各地の灯台の建設を指導"],["灯台守とその家族","岬に住み、灯台の光を守りつづけた"],["明治政府","幕府の約束を受けつぎ、灯台を完成させた"]],"deep":["潮岬の仮灯台は、日本で最初期に明かりがともった洋式灯台の一つとされます。本格的な石造の灯台に建てかえられたのは1873年です。","改税約書で約束された8灯台は、観音埼・野島埼・樫野埼・神子元島・剱埼・伊王島・佐多岬・潮岬。そのうち紀伊半島の二つが、黒潮の通り道にある潮岬と樫野埼でした。","潮岬灯台は、灯台の中にのぼって見学できる全国に十数か所の «参観灯台» の一つです。敷地内の資料館では、灯台の歴史やレンズなどの展示が見られます。","潮岬の沖は、黒潮が陸に近づく場所で、流れの速さや向きが大きく変わることがあります。そのため昔から海の難所として知られていました。","潮岬は、陸続きに見えますが、もともとは島で、砂州によって本州とつながった «陸繋島（りくけいとう）» の地形とされています。串本の町はその砂州の上に広がっています。","灯台のすぐ近くには «本州最南端» の碑があり、東には樫野埼灯台のある紀伊大島が見えます。二つの明治の灯台をめぐると、黒潮と航海の歴史がよくわかります。"],"look":["白い灯台と、中の階段から見る太平洋","灯台資料館の展示","本州最南端の碑","潮岬望楼の芝の広い芝生"],"q":["潮岬灯台のように、中にのぼって見学できる灯台を何という？","«参観灯台»。全国に十数か所あります。"],"koji":[],"myth":"仮灯台の点灯年月は資料により差がある。","img":["潮岬","リチャード・ヘンリー・ブラントン","串本町"],"wp":"潮岬灯台","rel":{"ev":[],"grave":[]},"ph":[["c:2/23/Shionomisaki-lighthouse_Jul2006.jpg",4368,2912,"潮岬灯台"],["c:1/10/ShionoMisakilighthouseView2.JPG",4000,3000],["c:8/83/ShionoMisakilighthouseView1.JPG",4000,3000],["c:7/75/ShionoMisakilighthouseOldLens.JPG",3000,4000],["c:e/e0/ShionoMisakilighthouseIndoor1.JPG",3000,4000],["c:5/50/ShionoMisakilighthouseGate.JPG",4000,3000],["c:0/06/ShionoMisakilighthouseEntrance.JPG",3000,4000],["c:6/67/ShionoMisakilightOffice.JPG",4000,3000]]},{"id":"30_shuko","n":"日米修交記念館（1791年のレディ・ワシントン号）","yomi":"にちべいしゅうこうきねんかん","cat":"近代","rank":"B","y":1791,"era":["edo"],"sh":"","ad":"東牟婁郡串本町樫野","st":"JR串本駅からバスで約40分«樫野灯台口»付近、歩いてすぐ（本数が少ない。車が便利）","la":33.4705,"lo":135.8575,"hook":"ペリーの黒船より62年も前、アメリカの帆船が紀伊大島にやってきていた。","lead":"寛政3年（1791年）、アメリカの商船 «レディ・ワシントン号» と «グレイス号» が紀伊大島に来航しました。記録に残る日本とアメリカの最初の出会いといわれます。記念館は、その出来事を伝えるために建てられました。","story":["日本とアメリカの出会いといえば、1853年のペリーの黒船が有名です。でも、それより62年も前に、アメリカの船が日本にやってきていたことを知っていますか? その場所が、ここ紀伊大島の樫野です。","1791年、アメリカのジョン・ケンドリック船長が率いる帆船 «レディ・ワシントン号» と、もう一隻の «グレイス号» が紀伊大島の沖にあらわれました。彼らは北アメリカの太平洋岸でラッコなどの毛皮を手に入れ、それを中国で売る商売をしていました。«日本でも毛皮が売れるかもしれない» ——そう考えて日本の沿岸にやってきたのです。","当時の日本は、外国との行き来を厳しく制限していました（いわゆる鎖国）。島の人々は、見たこともない大きな異国の船に驚いたことでしょう。船は島の近くにしばらくとどまり、水や薪を求めたといわれますが、結局毛皮は売れず、やがて去っていきました。","«なぜ、この出来事はあまり知られていないの?» ——幕府にとっては «異国船がやってきた» という小さな事件で、大きな交渉にもならなかったからです。けれど、アメリカ側の記録や地元の伝えにより、これが日米の最初の接触だったと考えられるようになりました。","記念館は、その歴史を伝えるために串本町がつくったものです。館内では船の模型や当時の資料が展示されています。すぐ近くには樫野埼灯台やトルコ記念館もあり、紀伊大島が «海の向こうの国々との出会いの島» だったことがよくわかります。"],"tl":[["1787年","ケンドリックらがアメリカ・ボストンを出航し、太平洋の毛皮交易へ"],["1791年","レディ・ワシントン号とグレイス号が紀伊大島に来航"],["1853年","ペリーが浦賀に来航"],["1854年","日米和親条約"],["昭和時代","串本町が日米修交記念館を建てる"]],"who":[["ジョン・ケンドリック","アメリカの船長。レディ・ワシントン号を率いて紀伊大島に来航"],["紀伊大島の人々","異国の船を目撃し、その記憶を伝えた"],["ペリー","62年後に浦賀に来航したアメリカ海軍の提督"]],"deep":["ケンドリックは、ボストンの商人たちが出資した «コロンビア号» の遠征隊の指揮官でした。途中で船を乗りかえ、小型の帆船レディ・ワシントン号で太平洋を航海しました。","当時アメリカは独立してまだまもない国で、中国との貿易に活路を求めていました。北西海岸で手に入れたラッコの毛皮は、中国で高く売れる人気商品でした。","来航の日数やくわしい様子については、資料によって書き方に差があります。紀伊大島にしばらく停泊したことは記録に残るとされますが、細かい点には不明なところもあります。","1791年の来航は、日本側では藩の記録などにわずかに残る程度で、長く忘れられていました。それが «日米最初の接触» として注目されたのは、主に昭和になってからです。","紀伊大島の東端には、1870年の樫野埼灯台、1890年のエルトゥールル号遭難の地とトルコ記念館、そしてこの日米修交記念館がそろい、小さな島に三つの国際交流の物語が集まっています。","ペリー来航よりも前に日本にやってきた外国船は、ほかにもロシアのラクスマン（1792年）、イギリスのフェートン号（1808年）などがあります。18世紀末から、日本の周りの海はしだいに騒がしくなっていました。"],"look":["船の模型と当時の航海の資料","記念館の前から見る熊野灘","近くの樫野埼灯台","近くのトルコ記念館とエルトゥールル号の慰霊碑"],"q":["1791年に紀伊大島に来航したアメリカの船の名前は？（2隻のうち1つ）","«レディ・ワシントン号»（もう1隻は «グレイス号»）。ペリー来航の62年前です。"],"koji":[],"myth":"来航の日数・目的・島の人々とのやりとりの細部は資料により差がある。記念館の開館年は要確認。","img":["紀伊大島","樫野埼灯台","串本町"],"wp":"日米修交記念館","rel":{"ev":[],"grave":[]},"ph":[["c:e/ea/180428_United_States%E2%80%93Japan_Friendship_Memorial_Museum02s10.jpg",6000,4000,"日米修交記念館"],["c:3/36/Kii_oshima_zenkei.JPG",3072,2304,"紀伊大島"],["c:e/ee/%E6%A8%AB%E9%87%8E%E5%B4%8E%E7%81%AF%E5%8F%B0%282021%29.jpg",4032,3024,"樫野埼灯台"],["c:3/31/ShionoMisakiMonument2.JPG",4000,3000,"串本町"]]},{"id":"30_america_mura","n":"アメリカ村（三尾・カナダ移民の村）","yomi":"あめりかむら（みお）","cat":"近代","rank":"B","y":1888,"era":["meiji","taisho","showa"],"sh":"","ad":"日高郡美浜町三尾","st":"JR御坊駅からバスで約30分«三尾»付近（本数が少ない。車が便利）","la":33.895,"lo":135.072,"hook":"«カナダには、川がまっ黒になるほど鮭がいる»——一人の大工の手紙が、漁村の人々を太平洋のむこうへ呼んだ。","lead":"美浜町の三尾は、明治時代から多くの人がカナダへ移民した村です。カナダで働いてお金をためて帰ってきた人たちが、洋風の家を建て、洋服を着て暮らしたことから、いつしか «アメリカ村» と呼ばれるようになりました。","story":["日ノ岬のふもと、小さな漁村の三尾。明治時代、この村は土地がせまく、漁だけで家族を養うのはたいへんでした。そんな村から、明治21年（1888年）、一人の男が海をわたります。大工の工野儀兵衛（くの ぎへえ）です。","儀兵衛がたどりついたのは、カナダの西海岸、バンクーバー近くのフレーザー川。そこで彼が見たのは、川を埋めつくすほどの鮭の群れでした。«ここなら、村の者たちが食べていける»。儀兵衛は三尾に手紙を送り、村の人々を呼びよせます。こうして三尾の人々は、次々とカナダへわたり、鮭漁や缶詰工場で働くようになりました。","遠い異国での暮らしは楽ではありませんでした。言葉の壁、厳しい労働、そして日本人移民への差別。それでも人々は助けあって働き、ためたお金を故郷に送りました。やがて帰国した人々は、村に洋風の家を建て、ベッドで眠り、パンやコーヒーを楽しむようになります。«三尾に行くとアメリカみたいだ» ——いつしか、そう呼ばれるようになったのです。","しかし、太平洋戦争が始まると、カナダに住んでいた日系人は «敵国の人» とされ、財産を取り上げられ、内陸の収容所へ移されました。三尾ゆかりの人々もその苦しみを味わいました。戦後、帰国した人、カナダに残った人、それぞれの道を歩むことになります。","今も三尾には、下見板張りの壁や上げ下げ窓をもつ洋風の家が残り、«カナダミュージアム» で移民の歴史を知ることができます。狭い路地を歩きながら、太平洋のむこうとこちらを行き来した人々の、たくましくも切ない物語に思いをはせてみてください。"],"tl":[["1888年","工野儀兵衛がカナダへわたり、フレーザー川の鮭漁を知る"],["明治〜大正時代","三尾から多くの人がカナダへ移民する"],["大正〜昭和初期","帰国者が洋風の家を建て、«アメリカ村» と呼ばれる"],["1942年","太平洋戦争中、カナダの日系人が強制移動の対象となる"],["2018年","移民の歴史を伝える «カナダミュージアム» が開館"]],"who":[["工野儀兵衛","三尾出身の大工。カナダ移民の先がけとなり、村人を呼びよせた"],["三尾の移民たち","カナダで鮭漁や缶詰工場で働き、故郷に送金した"],["日系カナダ人","戦争中に強制移動などの苦難を経験した"]],"deep":["フレーザー川の河口の町スティーブストンは、日系移民の漁師町として知られ、三尾出身の人々も多く暮らしました。今もスティーブストンと美浜町には交流があります。","三尾からの移民は、最盛期には村の人口の大きな割合をしめたといわれます。家族や親せきをたよって次々とわたる «呼び寄せ» が、移民の広がりを生みました。","«アメリカ村» という呼び名ですが、実際の移民先はほとんどがカナダでした。当時の日本では、北アメリカ全体を «アメリカ» とひとまとめに呼ぶことが多かったためと考えられます。","カナダ政府は1988年、戦時中の日系人への強制移動や財産没収について正式に謝罪し、補償を行いました。三尾の歴史は、こうした国際的な人権の歩みともつながっています。","カナダミュージアムは、移民の家として使われた古い洋館を利用した施設です。当時の暮らしの道具や写真、カナダからの品々が展示されています。","三尾の洋風住宅は、日本の伝統的な漁村の家並みの中に、外国の建築の要素がとけこんでいるのが特徴です。全部が洋館なのではなく、和風の家に洋風の窓やペンキ塗りの外壁を取り入れた «和洋折衷» の家も多く見られます。"],"look":["下見板張りやペンキ塗りの洋風住宅","カナダミュージアムの展示","狭い路地の漁村の町並み","近くの日ノ岬からの海の眺め"],"q":["三尾の人々が明治時代に多く移民した国はどこ？","«カナダ»。«アメリカ村» と呼ばれますが、移民先の多くはカナダでした。"],"koji":[],"myth":"移民の人数や村の人口にしめる割合は資料により差がある。","img":["日系カナダ人","美浜町 (和歌山県)","日ノ岬"],"wp":"アメリカ村 (美浜町)","rel":{"ev":[],"grave":[]},"ph":[["c:6/63/Mihama_mio.jpg",4608,3456,"アメリカ村 (美浜町)"],["c:1/13/Mihama_canada_museum.jpg",4608,3456],["c:a/a5/Enjugahama.jpg",4608,3456,"美浜町 (和歌山県)"],["c:7/75/Mihama_hinomisaki.jpg",4608,3456,"日ノ岬"]]},{"id":"30_sandanbeki","n":"三段壁洞窟（熊野水軍の舟隠し）","yomi":"さんだんべきどうくつ","cat":"伝承","rank":"B","y":1185,"era":["heian","kamakura"],"sh":"","ad":"西牟婁郡白浜町三段","st":"JR白浜駅からバスで約20分«三段壁»下車すぐ","la":33.6645,"lo":135.3395,"hook":"高さ50mの断崖の真下に、海へ口をあけた洞窟がある。ここに熊野水軍が舟を隠していた——と伝わる。","lead":"三段壁は、白浜の海岸に約2kmにわたって続く、高さ50〜60mほどの断崖です。その下の洞窟は、源平合戦のころ活躍した «熊野水軍» が舟を隠した場所だったと言い伝えられています。エレベーターで地下の洞窟に降りて見学できます。","story":["白浜の海岸を南へ行くと、まるで巨大な壁のような崖が海からそそり立っています。三段壁。波が打ちつけるたび、ドーンという音とともに白いしぶきが舞い上がります。この崖の足もとに、海へ向かって口をあけた大きな洞窟があるのです。","«なぜ、ここが水軍の隠れ家だと言われるの?» ——洞窟は海から直接舟を入れられるうえ、崖の上からは見えません。見張りを立て、敵を待ちかまえるには絶好の場所です。平安時代の終わり、熊野の海で力をもった «熊野水軍» が、ここを舟の番所として使ったと伝えられてきました。","熊野水軍をひきいたのは、熊野三山をたばねる «熊野別当»。なかでも有名なのが湛増（たんぞう）です。源氏と平家の戦いが激しくなったとき、湛増は «どちらにつくべきか» 迷いました。『平家物語』によると、田辺の新熊野（いまの闘雞神社）で紅白の鶏を戦わせて神意を占い、白い鶏（源氏）が勝ったので源氏に味方した、といいます。","元暦2年（1185年）の壇ノ浦の戦いでは、熊野水軍の船団が源氏方として加わったと『平家物語』は語ります。海の戦いを得意とした熊野の人々の力が、源氏の勝利を後押ししたのかもしれません。洞窟の奥には、今も水軍の番所を再現した展示があります。","洞窟の中には、牟婁大辯才天（むろだいべんざいてん）がまつられ、海の安全を守る神として信仰されています。エレベーターで地下約36mまで降りると、暗い洞窟の中に波が激しく打ちこむ «潮吹き» の迫力。歴史と伝説と自然の力が一度に味わえる場所です。"],"tl":[["平安時代末","熊野別当のもとで熊野水軍が力をもつ"],["1180年ごろ","源平の争乱が始まる"],["1185年","壇ノ浦の戦い。熊野水軍が源氏方として加わったと『平家物語』に記される"],["鎌倉時代以降","熊野の海の勢力が各地の水軍として活躍"],["昭和時代","洞窟が観光地として整備され、エレベーターが設けられる"]],"who":[["湛増","熊野別当。闘鶏で占い源氏に味方したと『平家物語』に語られる"],["熊野水軍","熊野の海を拠点にした海の武士団"],["源義経","壇ノ浦の戦いで源氏を勝利に導いた"]],"deep":["«熊野水軍» という言葉は、特定の一つの組織の名前というより、熊野の沿岸の海の勢力を広くさす呼び方です。熊野別当家とのつながりが強かったと考えられます。","三段壁の洞窟が実際に水軍の舟隠しだったことを示す確かな史料はなく、あくまで言い伝えです。ただし、熊野の海の勢力がこうした地形を利用したことは十分に考えられます。","«三段壁» の名は、崖の上から見下ろすと棚のような段があるように見えることや、漁師が魚群を見張る «見段» から来たともいわれますが、はっきりしません。","闘雞神社（田辺市）は、湛増の闘鶏の伝承の舞台で、2016年に世界遺産 «紀伊山地の霊場と参詣道» に追加登録されました。三段壁とあわせて訪ねると物語がつながります。","三段壁の岩は、新第三紀の砂岩や泥岩の地層で、波に削られて断崖と洞窟ができました。白浜の千畳敷も同じ地層で、南紀熊野ジオパークの見どころの一つです。","洞窟内の牟婁大辯才天は、海の守り神として地元の漁師などから信仰されてきました。洞窟の入場は有料で、見学時間が決まっています。"],"look":["海からそそり立つ断崖と展望台","エレベーターで降りる地下の洞窟","水軍の番所を再現した展示","洞窟内の牟婁大辯才天と潮吹き"],"q":["『平家物語』で、熊野別当・湛増が源氏と平家のどちらにつくかを決めるために使った方法は？","紅白の «鶏を戦わせる»（闘鶏）占い。白い鶏が勝ち、源氏に味方したと語られます。"],"koji":[],"myth":"洞窟が熊野水軍の舟隠しだったことは伝承で、確かな史料はない。湛増の闘鶏も『平家物語』の語りによる。","img":["熊野水軍","湛増","闘雞神社"],"wp":"三段壁","rel":{"ev":[],"grave":[]},"ph":[["c:a/ad/131221_Sandanbeki_Shirahama_Wakayama_pref_Japan07bs12.jpg",4770,3180,"三段壁"],["c:b/b1/%E5%B1%95%E6%9C%9B%E5%8F%B0%E6%A8%AA%E3%81%AE%E3%83%8F%E3%83%BC%E3%83%88%E3%83%A2%E3%83%8B%E3%83%A5%E3%83%A1%E3%83%B3%E3%83%88.jpg",3024,4032],["c:f/f1/131221_Sandanbeki_Shirahama_Wakayama_pref_Japan01bs5.jpg",4800,3200],["c:6/64/%E3%83%8F%E3%83%BC%E3%83%88%E3%81%AE%E3%83%97%E3%83%AC%E3%83%BC%E3%83%88.jpg",2870,2870],["c:a/a7/%E3%83%94%E3%83%B3%E3%82%AF%E3%81%AE%E3%83%9D%E3%82%B9%E3%83%88.jpg",2379,2910],["c:6/61/Sandanbeki.JPG",1280,960],["c:3/36/RIMG0067.JPG",1280,960],["c:2/2f/251011_Tokei-jinja_Tanabe_Wakayama_prefecture_Japan03s3.jpg",5472,3648,"闘雞神社"]]},{"id":"30_kozanji_tanabe","n":"高山寺（田辺・南方熊楠の墓と貝塚）","yomi":"こうざんじ（たなべ）","cat":"墓所","rank":"B","y":1941,"era":["jomon","showa"],"sh":"国指定史跡（高山寺貝塚）","ad":"田辺市稲成町","st":"JR紀伊田辺駅から歩いて約25分（バスも利用できる）","la":33.7405,"lo":135.383,"hook":"「知の巨人」と「合気道の開祖」が眠る寺。その裏山は、8000年以上前の縄文人の暮らしの跡だった。","lead":"田辺の高山寺には、博物学者・南方熊楠と、合気道をひらいた植芝盛平の墓があります。境内の丘には、縄文時代のはじめごろの «高山寺貝塚» があり、国の史跡になっています。一つの寺で、何千年もの時をこえた出会いができる場所です。","story":["会津川を見下ろす丘の上に、高山寺の多宝塔が見えます。寺伝では聖徳太子が開き、弘法大師が再び興したといわれる古い寺です。この寺の墓地の一角に、大きな自然石の墓があります。刻まれた名は «南方熊楠»。世界にその名を知られた博物学者です。","熊楠は慶応3年（1867年）、和歌山城下の商家に生まれました。アメリカやイギリスで独学を重ね、大英博物館で研究した後、日本に戻ります。そして明治37年（1904年）から、田辺に住みつきました。«なぜ田辺に?» ——熊野の深い森には、彼が夢中になった粘菌（変形菌）や菌類、植物が数えきれないほどあったからです。","熊楠は、明治の神社合祀に反対し、鎮守の森を守るために声をあげました。昭和4年（1929年）には、昭和天皇に田辺湾の神島で粘菌について進講し、標本をキャラメルの箱に入れて献上したという話が有名です。昭和16年（1941年）、熊楠は田辺の自宅で亡くなり、この高山寺に葬られました。","同じ墓地には、田辺出身の武道家・植芝盛平の墓もあります。合気道の開祖として世界に知られる盛平は、若いころ熊楠とともに神社合祀反対運動にかかわったといわれます。«知» と «武»、二人の偉人が同じ寺に眠っているのは、田辺という町の不思議な豊かさを感じさせます。","そして、この丘にはもっと古い歴史が眠っています。境内の «高山寺貝塚» は、縄文時代の早いころ（早期）の貝塚です。ここで見つかった土器は «高山寺式土器» と名づけられ、全国の縄文土器の年代をはかる目じるしの一つになっています。丘の上で貝を食べていた縄文人から、熊楠と盛平まで——時の流れの大きさに、思わず空を見上げたくなります。"],"tl":[["縄文時代早期","高山寺の丘に貝塚が残される"],["1867年","南方熊楠、和歌山城下に生まれる"],["1883年","植芝盛平、田辺に生まれる"],["1904年","熊楠が田辺に住みはじめる"],["1929年","熊楠が昭和天皇に神島で粘菌について進講"],["1941年","熊楠が死去し、高山寺に葬られる"],["1969年","植芝盛平が死去。高山寺に墓がある"]],"who":[["南方熊楠","博物学者・民俗学者。粘菌研究と神社合祀反対で知られる"],["植芝盛平","田辺出身。合気道の開祖"],["昭和天皇","1929年に熊楠の進講を受けた"],["縄文時代の人々","高山寺の丘で貝塚を残した"]],"deep":["高山寺式土器は、表面に棒に刻みを入れて転がした «押型文（おしがたもん）» のある縄文早期の土器です。近畿地方の縄文早期の土器の型式名として使われています。","熊楠が1929年に進講した神島（かしま）は田辺湾に浮かぶ小島で、熊楠の努力で森が保護され、のちに国の天然記念物になりました。昭和天皇は1962年の南紀行幸の折、熊楠をしのぶ歌を詠んでいます。","熊楠の研究は、粘菌学だけでなく民俗学・宗教学にもおよび、柳田国男との往復書簡は日本の民俗学の成立に大きな影響をあたえました。","植芝盛平は、若いころ北海道開拓にも加わり、各地で武術を学んで合気道を大成しました。合気道は現在、世界の多くの国で稽古されています。","高山寺には多宝塔などの堂宇が残り、寺の文化財も伝わります。境内からは田辺の町と会津川、遠くに田辺湾が見わたせます。","熊楠の自宅（南方熊楠邸）と南方熊楠顕彰館は田辺の町なかにあり、高山寺の墓とあわせて訪ねると、熊楠の生活と研究の場を立体的に感じられます。"],"look":["南方熊楠の墓","植芝盛平の墓","高山寺貝塚の案内（丘の地形）","多宝塔と境内からの田辺の眺め"],"q":["高山寺に墓がある、合気道の開祖はだれ？","«植芝盛平»。田辺出身で、南方熊楠とも交流がありました。"],"koji":[],"myth":"寺の創建（聖徳太子・弘法大師）は寺伝。熊楠がキャラメル箱で標本を献上した話は有名だが、細部には伝聞を含む。","img":["南方熊楠","植芝盛平","高山寺貝塚"],"wp":"高山寺 (田辺市)","rel":{"ev":[],"grave":[]},"ph":[["c:4/47/251011_Kozan-ji_Tanabe_Wakayama_prefecture_Japan01s3.jpg",5472,3648,"高山寺 (田辺市)"],["c:0/01/251011_Kozan-ji_Tanabe_Wakayama_prefecture_Japan36s3.jpg",5472,3648],["c:b/ba/251011_Kozan-ji_Tanabe_Wakayama_prefecture_Japan34s3.jpg",5472,3648],["c:c/cc/251011_Kozan-ji_Tanabe_Wakayama_prefecture_Japan28s3.jpg",3648,5472],["c:7/71/251011_Kozan-ji_Tanabe_Wakayama_prefecture_Japan27s3.jpg",5472,3648],["c:4/4e/251011_Kozan-ji_Tanabe_Wakayama_prefecture_Japan24s3.jpg",5472,3648],["c:2/22/251011_Kozan-ji_Tanabe_Wakayama_prefecture_Japan22s3.jpg",5472,3648],["c:2/27/251011_Kozan-ji_Tanabe_Wakayama_prefecture_Japan21s3.jpg",5472,3648]]},{"id":"30_zenpukuin","n":"善福院 釈迦堂（鎌倉の禅宗様）","yomi":"ぜんぷくいん しゃかどう","cat":"寺社","rank":"B","y":1327,"era":["kamakura"],"sh":"国宝","ad":"海南市下津町梅田","st":"JR加茂郷駅から歩いて約20分（目安）。車が便利","la":34.1115,"lo":135.174,"hook":"みかん畑の里に、700年前の «禅の建築» がひっそり立つ。国宝なのに、訪れる人はまばらだ。","lead":"善福院の釈迦堂は、嘉暦2年（1327年）に建てられた鎌倉時代の仏堂で、国宝に指定されています。中国から伝わった «禅宗様» という建築様式の、日本に残る古い例の一つです。栄西禅師が開いたと伝わる寺の一院でした。","story":["海南市下津町の梅田。みかん畑の広がる山あいの静かな里に、どっしりとした瓦屋根のお堂があります。善福院の釈迦堂。«こんな所に国宝が?» と驚く人も多いでしょう。でもこの建物は、鎌倉時代の «新しいデザイン» を今に伝える、とても貴重な建築なのです。","鎌倉時代、中国（宋）から禅宗が伝わると、それといっしょに新しい建築のスタイルもやってきました。«禅宗様（唐様）» です。細かい部材をびっしり組み上げた軒下、花のような形の窓、放射状に広がる垂木（たるき）。それまでの日本のお寺とはまるでちがう、きりっとした美しさがありました。","寺の言い伝えでは、この地にはもともと、日本に臨済宗を伝えた栄西禅師が開いた «広福寺» という寺があり、善福院はその中の一院でした。創建は建保2年（1214年）、そして今の釈迦堂は嘉暦2年（1327年）に建て直されたものとされています。","釈迦堂は、正面・側面とも3間の本体のまわりに «裳階（もこし）» という差しかけ屋根をめぐらせた造りで、外から見ると二重の屋根に見えます。部材は太く、全体にがっしりとした印象です。禅宗様がまだ日本に定着しきる前の姿がよく表れていて、建築史の上で大切な建物とされています。","寺はその後、宗派がいくつか変わり、明治のはじめまであった院も次々となくなって、今は善福院だけが残りました。700年の風雪にたえてきたお堂の前に立ち、軒下の細かな組物を見上げてみてください。遠い宋の国から海をわたってきた建築の工夫が、この小さな里で生きつづけています。"],"tl":[["1191年","栄西が宋から帰国し、臨済宗を伝える"],["1214年","広福寺の一院として善福院が創建されたと伝わる"],["1327年","釈迦堂が建てられる（嘉暦2年）"],["江戸時代〜明治初期","宗派が変わり、院が減っていく"],["現在","釈迦堂が国宝として守られている"]],"who":[["栄西","日本に臨済宗を伝えた僧。広福寺を開いたと伝わる"],["鎌倉時代の大工","宋から伝わった禅宗様の技術で釈迦堂を建てた"],["梅田の里の人々","お堂を守りつづけてきた"]],"deep":["釈迦堂は «桁行三間・梁間三間、一重、裳階付、寄棟造、本瓦葺»。裳階があるため外観は二重に見えますが、構造上は一重の建物です。","禅宗様の特徴には、柱の上だけでなく柱と柱の間にも組物を置く «詰組（つめぐみ）»、花頭窓（かとうまど）、扇垂木、桟唐戸（さんからと）などがあります。善福院釈迦堂はこれらを観察するのに適した建物です。","禅宗様の現存する古い仏堂としては、鎌倉の円覚寺舎利殿（国宝）などが知られ、善福院釈迦堂はそれらとならぶ鎌倉時代後期の貴重な例とされます。","下津町には、紀州徳川家の菩提寺・長保寺（本堂・多宝塔・大門が国宝）もあり、この地域は «国宝の里» ともいえます。あわせて訪ねると、時代のちがう建築を見くらべられます。","«栄西が開いた広福寺» という話は寺伝によるもので、同時代の史料で確かめられているわけではありません。","釈迦堂の内部は通常非公開で、外観を見学するのが基本です。周辺は住宅やみかん畑なので、静かに見学しましょう。"],"look":["裳階のある二重に見える屋根","軒下の詰組（びっしり並ぶ組物）","花頭窓や桟唐戸などの禅宗様の細部","周囲のみかん畑の里の風景"],"q":["善福院釈迦堂に見られる、中国の宋から伝わった建築様式を何という？","«禅宗様（唐様）»。詰組や花頭窓が特徴です。"],"koji":[],"myth":"栄西による広福寺開創と1214年創建は寺伝。","img":["善福院 (海南市)","禅宗様","栄西","長保寺"],"wp":"善福院","rel":{"ev":[],"grave":[]},"ph":[["c:e/ea/Zenpukuin_shakado01s3200.jpg",3200,2133,"善福院 (海南市)"],["c:0/04/Kozanji_Temple_%28Shimonoseki%29.JPG",1280,960,"禅宗様"],["c:5/5c/Myoan-Eisai-Kennin-ji-Portrait.png",800,1414,"栄西"],["c:3/3e/Chohoji03s3200.jpg",3872,2592,"長保寺"]]},{"id":"30_kuroe","n":"黒江の町並み（紀州漆器）","yomi":"くろえのまちなみ（きしゅうしっき）","cat":"産業","rank":"B","y":1600,"era":["muromachi","edo"],"sh":"","ad":"海南市黒江","st":"JR黒江駅から歩いて約10分","la":34.16,"lo":135.208,"hook":"家々がみな道に対して斜めに建つ、ギザギザの町並み。そこは漆の香りがただよう職人の町だった。","lead":"海南市の黒江は、«紀州漆器» の産地として栄えた町です。漆器の職人や問屋の家が並び、家が道に対してななめに建つ «のこぎり歯» のような町並みが残っています。紀州漆器は、会津・山中・越前などと並ぶ日本の代表的な漆器の一つです。","story":["黒江の川端通りを歩くと、ふしぎなことに気づきます。家の正面が、道に対してまっすぐではなく、少しずつななめにずれて並んでいるのです。上から見ると、まるでのこぎりの歯のよう。«なぜこんな並び方に?» ——その答えは、この町の成り立ちにかくれています。","黒江は、昔は入江に面した小さな港町でした。入江をうめ立てて土地をつくったとき、もとの田んぼや塩田の区画の向きのまま家を建てたため、あとからできた道と家の向きがずれた——と考えられています。家と家のすき間にできた三角形の空き地は、漆器を干したり、道具を置いたりするのに使われたといいます。","黒江で漆器づくりが始まったのは、室町時代ごろといわれます。紀州の山でとれる木を使い、お椀などの日用品をつくりました。江戸時代になると紀州藩の保護を受け、船で全国に運ばれて、黒江の漆器は庶民の食卓に広まっていきました。","紀州漆器には «根来塗（ねごろぬり）» と呼ばれる技法があります。黒い漆の上に朱の漆を塗り、使ううちに朱がすれて下の黒がのぞく、味わい深い器です。岩出の根来寺の僧たちがつくった器が始まりとされ、1585年に豊臣秀吉の紀州攻めで根来寺が焼かれたとき、職人たちが黒江などへ移り住んだ——という言い伝えもあります。","明治以降も黒江は漆器の町として発展し、戦後はプラスチックの素材を使った製品なども取り入れて、大量生産にも対応しました。今も町には漆器店や工房が並び、«紀州漆器伝統産業会館（うるわし館）» では歴史を学び、蒔絵などの体験もできます。ななめの家並みの間を歩けば、職人たちの息づかいが聞こえてきそうです。"],"tl":[["室町時代","黒江で椀などの漆器づくりが始まったといわれる"],["1585年","秀吉の紀州攻めで根来寺が焼かれる（職人移住の伝承）"],["江戸時代","紀州藩の保護のもと、黒江の漆器が全国に広まる"],["明治〜昭和","漆器の町として発展し、新しい素材も取り入れる"],["1978年","紀州漆器が国の伝統的工芸品に指定される"]],"who":[["黒江の漆器職人","木地づくり・下地・塗り・蒔絵などの工程を分担した"],["根来寺の僧たち","根来塗の始まりとされる器をつくった"],["紀州藩","漆器産業を保護し、流通を後押しした"]],"deep":["«日本三大漆器» には、紀州・会津・山中を挙げる説や、輪島・越前などを挙げる説があり、決まった一つの組み合わせがあるわけではありません。","黒江の «のこぎり歯状の町並み» は、入江や塩田の地割にそって家を建てたためと説明されることが多いですが、成り立ちについては諸説あります。","根来塗の «朱の下から黒がのぞく» 景色は、本来は使いこむうちに自然に生まれたもので、今ではそれを意識してつくる技法も生まれています。","紀州漆器は、日常づかいの器を安く大量につくることに強みがありました。江戸時代には «渋地椀（しぶじわん）» と呼ばれる、柿渋を下地に使った安価なお椀が広まったといわれます。","黒江の町では毎年11月ごろに «紀州漆器まつり» が開かれ、多くの人でにぎわいます。","町並みの中には、江戸時代から続く漆器問屋の建物も残り、格子戸や虫籠窓（むしこまど）など、古い町家の意匠を見ることができます。"],"look":["のこぎり歯のように並ぶ家並み（川端通り）","家と家のすき間の三角形の空き地","紀州漆器伝統産業会館（うるわし館）","漆器店や工房の店先"],"q":["黒い漆の上に朱の漆を塗り、使ううちに黒がのぞく漆器を何という？","«根来塗（ねごろぬり）»。根来寺の僧たちがつくった器が始まりとされます。"],"koji":[],"myth":"根来の職人の移住、漆器づくりの始まりの時期、町並みの成り立ちには諸説・伝承を含む。","img":["根来塗","根来寺","海南市"],"wp":"紀州漆器","rel":{"ev":[],"grave":[]},"ph":[["c:1/18/Kainan_kuroe01s3200.jpg",3200,2200,"紀州漆器"],["c:7/7f/Negoro_Lackware.jpg",962,962],["c:0/03/Ewer_%28Yuto%29.jpg",1126,1500,"根来塗"],["c:2/24/Negoroji_spring.JPG",1500,997,"根来寺"],["c:f/fd/241006_Kuroe_Nurimono-kan_cafe_shop_Kainan_Wakayama_pref_Japan01s3.jpg",5472,3648,"海南市"]]},{"id":"30_suzuki_yashiki","n":"鈴木屋敷（全国の鈴木さんのルーツ）","yomi":"すずきやしき","cat":"伝承","rank":"B","y":1189,"era":["heian","kamakura","edo"],"sh":"","ad":"海南市藤白（藤白神社のとなり）","st":"JR海南駅から歩いて約20分","la":34.1467,"lo":135.1995,"hook":"日本でいちばん多い名字の一つ «鈴木»。そのふるさとは、熊野古道の小さな神社の横にあった。","lead":"鈴木屋敷は、熊野信仰を広めた神官の家柄・藤白鈴木氏の屋敷の跡です。全国の «鈴木» という名字のルーツといわれ、源義経の家来として知られる鈴木三郎重家もこの家の出身とされます。建物は修復され、見学できるようになりました。","story":["熊野古道・紀伊路の入口、藤白神社のとなりに、古い屋敷があります。ここが鈴木屋敷。«全国の鈴木さんのふるさと» と聞くと、思わず «えっ、本当?» と言いたくなりますね。日本に百数十万人いるといわれる鈴木さん。その名字の広がりには、熊野信仰が深くかかわっていました。","鈴木氏は、もともと熊野の神官の一族で、«穂積（ほづみ）» という古い氏の流れをくむといわれます。平安時代の終わりごろ、その一族が熊野から藤白へ移り、藤白神社（藤代王子）に仕えました。熊野詣の上皇や貴族たちを迎える、紀伊路の重要な拠点だったのです。","«鈴木» という名前の由来にも言い伝えがあります。熊野では刈り取った稲を積み上げたものを «すずき» と呼び、稲穂を積むことから «穂積» の一族が «鈴木» を名のった、というのです。鈴木氏は熊野信仰を各地に広める役目もにない、そのゆかりで全国に «鈴木» の名が広まっていったと考えられています。","この家から出た有名な人物が、源義経の家来・鈴木三郎重家です。重家は義経とともに戦い、最期は奥州の衣川で義経に殉じたと伝えられます。弟の亀井六郎重清も、義経の家来として知られています。義経が熊野にゆかりの深い武将だったことも、この話に重みを加えています。","屋敷は長い年月の間に傷み、一時はくずれかけていました。それを地元や全国の «鈴木さん» たちが支え、修復が進められて、見学できるようになりました。となりの藤白神社の大楠は、南方熊楠がその名前の «楠» の字をいただいたことでも知られます。一つの屋敷から、名字と信仰の壮大な物語が広がっているのです。"],"tl":[["平安時代末","熊野の鈴木氏の一族が藤白に移り、藤白神社に仕えたと伝わる"],["1189年","鈴木三郎重家が衣川で義経とともに亡くなったと伝わる"],["鎌倉〜室町時代","熊野信仰とともに鈴木氏が各地に広がる"],["江戸時代","藤白鈴木氏の屋敷が引きつがれる"],["令和時代","修復が進み、屋敷が公開される"]],"who":[["鈴木三郎重家","藤白鈴木氏の出身。源義経の家来で、衣川で義経に殉じたと伝わる"],["亀井六郎重清","重家の弟とされる。義経の家来"],["源義経","鈴木氏と深いつながりがあったと伝わる武将"],["南方熊楠","藤白神社の楠神から名前の «楠» をもらった"]],"deep":["鈴木氏の祖とされる «穂積» 氏は古代の有力な氏族で、熊野の神官の家もその流れをくむと伝えられます。ただし古い系図には後世の手が加わっている部分もあり、慎重に扱う必要があります。","全国の鈴木さんがすべて藤白の鈴木氏の子孫というわけではありません。名字は江戸時代の終わりから明治にかけて広く名のられるようになったものも多く、«鈴木屋敷がルーツ» というのは、名字の広がりの出発点の一つという意味で理解するのがよいでしょう。","熊野信仰を各地に広めた «熊野御師（おし）» や «先達（せんだつ）» の活動とともに、鈴木氏も全国に分かれていったと考えられています。とくに東日本（静岡・愛知・関東など）に鈴木姓が多いのは、この広がりと関係があるという説があります。","藤白神社は熊野九十九王子のうち、格式の高い «五体王子» の一つ «藤代王子» です。後鳥羽上皇が歌会を開いたことでも知られ、紀伊路の要所でした。","南方熊楠は、藤白神社の楠神から «熊» と «楠» の字をもらって名づけられたといわれます。熊野の «熊» と、藤白の «楠»——熊楠の名そのものが紀州の信仰の産物なのです。","鈴木屋敷の建物は江戸時代以降のもので、平安時代の建物がそのまま残っているわけではありません。今の建物は、残っていた屋敷を修理・整備したものです。"],"look":["修復された屋敷の建物","となりの藤白神社（藤代王子）","南方熊楠ゆかりの大楠（子守楠神社）","藤白坂の入口と有間皇子の墓碑"],"q":["«鈴木» という名字の由来になったといわれる、熊野で稲を積み上げたものの呼び名は？","«すずき»。稲穂を積む «穂積» の一族が «鈴木» を名のったといわれます。"],"koji":[],"myth":"全国の鈴木氏のルーツ説、名字の由来、重家・重清の兄弟関係や最期には伝承・諸説を含む。","img":["藤白神社","鈴木氏","南方熊楠"],"wp":"鈴木屋敷","rel":{"ev":[],"grave":[]},"ph":[["c:3/3b/241006_The_Suzuki-homestead_Kainan_Wakayama_pref_Japan02s3.jpg",5472,3648,"鈴木屋敷"],["c:5/5a/241006_The_Suzuki-homestead_Kainan_Wakayama_pref_Japan12s3.jpg",5472,3648],["c:1/19/241006_The_Suzuki-homestead_Kainan_Wakayama_pref_Japan06s3.jpg",5472,3648],["c:a/aa/241006_The_Suzuki-homestead_Kainan_Wakayama_pref_Japan03s3.jpg",5400,3600],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:6/6c/241006_Fujishiro-jinja_Kainan_Wakayama_pref_Japan02s3.jpg",5472,3648,"藤白神社"],["c:b/b5/Minakata-Kumagusu.jpg",900,1300,"南方熊楠"]]},{"id":"30_semuiji","n":"施無畏寺（明恵上人ゆかり）","yomi":"せむいじ","cat":"寺社","rank":"B","y":1231,"era":["kamakura"],"sh":"県指定有形文化財（本堂など4棟）","ad":"有田郡湯浅町栖原","st":"JR紀勢本線・湯浅駅から車で約10分。坂道が続くので車が便利","la":34.0476,"lo":135.1621,"hook":"海を見下ろす山寺で、若き明恵は仏の道を思いつめ、みずから右耳を切り落とした——その修行の山のふもとに建つ寺。","lead":"施無畏寺は、湯浅湾を見下ろす白上山のふもとにあるお寺です。鎌倉時代のはじめ、湯浅の武士たちが土地を寄進し、一族出身のお坊さん «明恵上人» を招いて1231年に落慶供養をしました。明恵が若いころに修行した場所が、すぐ上の山にあります。","story":["湯浅の海はおだやかで、沖には小さな島がぽつんと浮かびます。この景色を毎日ながめていた若いお坊さんがいました。のちに京都・栂尾の高山寺を開く «明恵»（1173〜1232）です。明恵の母は、有田一帯を治めた武士団 «湯浅党» のかしら、湯浅宗重の娘でした。つまり湯浅は、明恵にとって «母の里» だったのです。","両親を幼くして亡くした明恵は、京都の神護寺で学びました。けれど都の寺は、出世や争いでざわついていました。«ここでは本当の修行はできない»。20代のはじめ、明恵は紀州へもどり、湯浅の白上の峰に小さな庵を結びます。海と空しかない岩場で、明恵はひたすら座り、仏の姿を思いえがきました。","このころの明恵には、有名な逸話があります。仏の教えに身をささげる覚悟を示すため、自分の右耳を切り落としたというのです。«顔の形がそこなわれれば、人に見られることを気にせず修行に打ちこめる»——そう考えたといわれます。なんとはげしい決心でしょう。この体験は、明恵の生涯を変える大きな転機になったとみられています。","明恵は海の向こうの島にも渡って修行しました。のちに、その島あてに «手紙» を書いたという話が伝記に残ります。«島どの、お元気ですか» と、まるで友だちに話しかけるように。自然のすべてに仏を見た、明恵らしい話です。明恵は夢を細かく書き残した «夢記» でも知られています。","それから30年あまり。明恵のいとこにあたる湯浅景基らが、明恵ゆかりのこの地に寺を建てました。1231年、明恵を導師に招いて落慶供養。寄進の文書には、湯浅一門の47人が名前を連ね、«一家同心»（一族が心を一つにする）と誓っています。ばらばらになりがちな武士の一族を、お寺と信仰がつなぎとめていたのです。"],"tl":[["1173年","明恵、紀伊国有田郡に生まれる（母は湯浅宗重の娘）"],["1190年代","明恵、白上の峰に庵を結び修行。右耳を切ったと伝わる"],["1206年","明恵、後鳥羽上皇から京都・栂尾の地を与えられ高山寺を開く"],["1231年","湯浅景基らが寺地を寄進し、明恵を導師に落慶供養"],["1232年","明恵、高山寺で亡くなる"],["1236年","明恵ゆかりの修行地などに木の卒塔婆が建てられる"],["1345年","卒塔婆が石造に改められる（明恵紀州遺跡卒都婆）"],["1904年","寄進状・置文が重要文化財（旧国宝）に"]],"who":[["明恵（高弁）","鎌倉時代の華厳宗の僧。この地の山で若き日に修行し、寺の落慶の導師となった"],["湯浅宗重","湯浅党の祖。明恵の祖父"],["湯浅景基","宗重の孫。寺地を寄進した中心人物"],["後鳥羽上皇","明恵に高山寺の地を与えた"]],"deep":["寄進状の外題には寛喜3年（1231年）4月17日に落慶供養をしたと記され、湯浅一門47名と明恵・景基が連署しています。藤原姓のほか源姓・紀姓の署名もあり、婚姻で広がった一族の姿がわかります。","寺の文書のうち «施入状»（1233年）と «置文»（1231年）の2巻が国の重要文化財。ほかに鎌倉〜室町時代の «施無畏寺文書» 37通が県の文化財です。","山上の東白上・西白上には、明恵の修行地を示す石の卒塔婆があり、国の史跡 «明恵紀州遺跡卒都婆» の一部です。明恵の死後に木で建てられ、1345年に石に改められました。","最盛期には6つの坊（子院）を従えましたが、江戸時代までに多くが絶えました。いまの本堂・開山堂・鐘楼・鎮守社は17〜18世紀の再建で、県の文化財です。","境内の石造宝篋印塔は総高2.4メートルあまり、台座に観応2年（1351年）の銘。南北朝時代の石造物がほぼ完全に残る貴重な例です。","湯浅湾の沖の刈藻島（北島・南島）は明恵が渡って修行した島とされ、県の史跡。島への «手紙» の逸話は『明恵上人伝記』に見えます。"],"look":["境内から見下ろす湯浅湾と刈藻島の眺め","本堂・開山堂など江戸時代の堂舎","観応2年銘の石造宝篋印塔","山上の白上遺跡の石卒塔婆（山道なので足ごしらえを）"],"q":["明恵が修行中、覚悟を示すために切り落としたと伝わる体の一部は？","右の耳。«人に見られることを気にせず修行するため» だったといわれます。"],"koji":[{"w":"あるべきようは","m":"明恵が大切にしたことば。人それぞれ、その時その場で «あるべき姿» を求めて生きよ、という教え"}],"myth":"右耳を切った動機、島への手紙は伝記に基づく伝承。","img":["明恵","湯浅町","高山寺","湯浅党"],"wp":"施無畏寺","rel":{"ev":[],"grave":[]},"ph":[["c:5/50/Semui-ji%2C_Yuasa_202604-2.jpg",2432,1824,"施無畏寺"],["c:b/be/Myou-e.jpg",1379,1471,"明恵"],["c:6/68/260516_Kadocho_Yuasa_Wakayama_pref_Japan02s3.jpg",5472,3648,"湯浅町"],["c:8/8a/Kozanji_Kyoto_Kyoto11s5s4592.jpg",4592,3056,"高山寺"]]},{"id":"30_hiro_hachiman","n":"広八幡神社","yomi":"ひろはちまんじんじゃ","cat":"寺社","rank":"B","y":1413,"era":["muromachi","edo"],"sh":"国の重要文化財（本殿・楼門など）","ad":"有田郡広川町上中野","st":"JR紀勢本線・湯浅駅から車で約10分","la":34.0177,"lo":135.1753,"hook":"大津波の夜、燃える稲むらの炎をたよりに、村人たちが必死にかけ上がった «命の高台»。","lead":"広八幡神社は、室町時代の本殿や楼門が残る古い神社です。1854年の安政南海地震の津波のとき、濱口梧陵が稲むら（刈り取った稲の束）に火をつけて村人をこの高台へ導いた話 «稲むらの火» の舞台として知られます。","story":["境内に入ると、どっしりした楼門が迎えてくれます。1475年に建てられた門で、その奥の本殿は1413年の建立。600年以上前の建物が、ここではいまも «現役» です。«どうしてこんなに古い建物が残ったの?» 答えのひとつは、江戸時代に紀州藩主があつく信仰し、手あつく守られてきたからです。","1854年（嘉永7年）11月5日の夕方。紀伊半島の沖で巨大な地震が起こりました。安政南海地震です。広村（いまの広川町）で醤油づくりの家に生まれた濱口梧陵は、海の様子がおかしいことに気づきます。やがて大波が村をのみこみました。","日が暮れて真っ暗な中、逃げまどう人々。梧陵は、田に積んであった稲むらに火をつけました。«この火を目印に、高いところへ!» 炎の道しるべをたどって、人々はこの八幡さまの高台へと逃げのびたのです。大切な収穫物を燃やしてまで、命を優先した決断でした。","梧陵の偉さは、その後にもありました。津波で仕事を失った村人を雇い、自分のお金で大きな堤防を築いたのです。«また津波が来ても、村を守れるように»。この堤防はのちの昭和南海地震の津波のときにも村を守ったといわれます。","梧陵の話は、明治時代に作家の小泉八雲が英語で «生き神様» として世界に紹介しました。それを地元の先生・中井常蔵が子ども向けに書き直した «稲むらの火» が、昭和のはじめに国語の教科書にのります。境内には梧陵をたたえる碑も立っています。"],"tl":[["6世紀ごろ","欽明天皇のころ創建と伝わる"],["1413年","いまの本殿が建てられる"],["1475年","楼門が建てられる"],["1704年","拝殿が建てられる"],["1854年11月5日","安政南海地震の津波。稲むらの火で村人がこの高台へ"],["1855〜1858年","濱口梧陵が広村堤防を築く"],["1929・1947年","本殿・楼門などが重要文化財に"],["2015年","11月5日が国連の «世界津波の日» に決まる"]],"who":[["濱口梧陵","広村出身の実業家。津波の夜、稲むらに火を放って村人を高台へ導いた"],["小泉八雲","梧陵の話を «A Living God» として海外に紹介した作家"],["中井常蔵","八雲の作品をもとに教材 «稲むらの火» を書いた広村の小学校教員"],["紀州藩主","江戸時代、神社をあつく保護した"]],"deep":["本殿は三間社流造・檜皮葺で1413年の建立。楼門（1475年）、拝殿（1704年）、摂社の高良社（1502年）・若宮社（1493年）・天神社（1652年）の本殿もそろって重要文化財です。","鎌倉時代の短刀 «銘 来国光» も国の重要文化財。来派は京の名門刀工一派です。","明治の神仏分離より前は境内に多くの仏堂があり、それらは近くの三瀧寺などへ移されました。","実際の梧陵は、津波の後に稲むらへ火をつけ、逃げ遅れた人に高台の場所を知らせたと考えられています。物語では «津波の前に火をつけた» 形に脚色されています。","安政南海地震は、前日の安政東海地震と続いて起きた巨大地震です。日付の11月5日は、2015年に国連が定めた «世界津波の日» のもとになりました。","県指定の無形民俗文化財 «しっぱら踊り» や «乙田の獅子舞» が伝わり、地域の祭りの中心でもあります。"],"look":["室町時代の楼門（1475年）","本殿と摂社の古い社殿群","濱口梧陵をたたえる碑","高台から海の方角をながめ、津波の夜の避難をイメージする"],"q":["«稲むらの火» で梧陵が火をつけた «稲むら» とは何？","刈り取った稲を積み上げたもの。大切な収穫物を燃やして、避難の目印にしました。"],"koji":[],"myth":"創建年代は伝承。教材の «稲むらの火» は史実を脚色した物語。","img":["濱口梧陵","稲むらの火","安政南海地震","広村堤防"],"wp":"広八幡神社","rel":{"ev":[],"grave":[]},"ph":[["c:0/0c/Hiro_hachiman.jpg",4608,3456,"広八幡神社"],["c:f/f4/Hamaguchi_Goryo.jpg",730,1129,"濱口梧陵"],["c:0/06/1854_Ansei_Nankai_earthquake_intensity.PNG",512,512,"安政南海地震"],["c:f/f3/Hiromura_Teibo_Seawall_Aerial_photograph.jpg",1105,782,"広村堤防"]]},{"id":"30_hiro_jo","n":"広城跡（畠山氏）","yomi":"ひろじょうあと","cat":"城","rank":"B","y":1401,"era":["muromachi"],"sh":"","ad":"有田郡広川町名島・湯浅町別所","st":"JR紀勢本線・湯浅駅から登山口まで車で約10分。山城なので登山の準備を","la":34.0252,"lo":135.1869,"hook":"将軍家の重臣・畠山氏が紀伊支配の «司令塔» にした山城。応仁の乱は、この山でも火を噴いた。","lead":"広城は、標高147メートルの高城山にあった山城の跡です。室町幕府の重臣・畠山氏が紀伊国の守護として築いたとされ、ふもとの館とセットで国を治める拠点でした。いまは建物はなく、山に曲輪（平らな段）などが残ります。","story":["湯浅と広川の町の境に、こんもりした山があります。高城山。ここに城があったのは、いまから600年ほど前のことです。1401年、紀伊国の守護（国を治める役）に任じられた畠山基国が築いたとされます。畠山氏は、将軍を補佐する «管領» になる名門でした。","城は東と西の2つの峰にまたがり、«東の城»«西の城» と呼ばれました。ふだん守護が暮らし、政治をおこなったのは山のふもとの館です。いまの養源寺のあたりがその跡と考えられています。«ふだんは館、いざとなれば山城へ»。戦国時代によく見られるこの組み合わせでした。","やがて畠山家は、義就と政長の二人が家督をめぐって争い始めます。この争いは、やがて京の都を焼け野原にした «応仁の乱» の火種のひとつになりました。紀伊でも両派が戦い、広城は義就方に奪われ、1468年には政長方が取り返します。«城の主が一年で変わる» ほどのはげしさでした。","1493年の明応の政変のあと、政長の子・畠山尚順は紀伊にとどまり、この広を拠点に国を治めます。館のまわりには町ができたとみられ、湯浅・広のあたりは «守護の城下町» としてにぎわいました。","ところが1520年、家臣の野辺慶景が主君の尚順に反旗をひるがえします。敗れた尚順は堺へ逃れ、翌年に広城を攻めたものの勝てず、淡路島へ。その後、畠山氏は拠点を有田川上流の鳥屋城へ移しました。«家来に国を追われる»——まさに下剋上の時代でした。"],"tl":[["1401年","紀伊守護・畠山基国が築いたとされる"],["1457〜1466年ごろ","守護所が大野（海南市）から広へ移される"],["1467年","畠山義就方の政国が広城を攻め取る"],["1468年","政長方が広城を奪い返す"],["1493年","明応の政変。尚順が紀伊に在国し、広で国を治める"],["1520年","家臣の野辺慶景に敗れ、尚順が堺へ"],["1521年","尚順、広城を攻めるが敗れ淡路へ。のち拠点は鳥屋城へ"]],"who":[["畠山基国","紀伊守護。広城を築いたとされる"],["畠山政長","家督争いの一方。政長方が守護所を広に移した"],["畠山義就","政長のライバル。応仁の乱の主役の一人"],["畠山尚順","政長の子。広を拠点に紀伊を治めた"],["野辺慶景","畠山氏の家臣。主君尚順と戦い、追い出した"]],"deep":["標高147メートル、ふもととの高さの差は約120メートル。東西2つの峰にまたがる «一城別郭» 風の構造です。","守護所が大野から広へ移ったのは、紀北の大野と紀南の南部（みなべ）の中間にあり、紀南の敵対勢力にもにらみをきかせられたからと考えられています。","守護館は城の西約1キロの養源寺（広川町広）の寺域にあったと推定されています。","館のまわりの町並みは、明応の政変後に紀伊へ «在国» した尚順が直接支配したことで生まれた城下町だとする見方があります。","1521年以後、畠山氏は鳥屋城へ移りますが、地形の制約から広にも一定の政治機能が残ったと推測されています。","城主の交代が激しい紀伊では、湯河氏・野辺氏など国人（地元の武士）が力を強め、守護畠山氏は弱っていきました。"],"look":["東の城・西の城の曲輪（平らな段）","堀切・土塁などの山城の遺構","守護館があったとされる養源寺周辺","山頂付近からの湯浅湾・広川の眺め"],"q":["広城を拠点にした紀伊の守護は何氏？","畠山氏。室町幕府の管領も務めた名門です。"],"koji":[{"w":"下剋上","m":"下の身分の者が上の者をしのいで力をにぎること。家臣野辺氏が主君畠山尚順を追った広城の歴史はその一例"}],"myth":"築城者・築城年は «とされる»。山中の道は整備状況が変わるので事前確認を。","img":["畠山氏","畠山尚順","応仁の乱","鳥屋城"],"wp":"広城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:6/62/%E7%95%A0%E5%B1%B1%E5%B0%9A%E9%A0%86%E3%81%AE%E4%BD%8D%E7%BD%B2%E3%81%A8%E8%8A%B1%E6%8A%BC.jpg",1212,2213,"畠山尚順"],["c:a/a9/Shinnyod%C5%8D_engi%2C_vol.3_%28part%29.jpg",2000,807,"応仁の乱"]]},{"id":"30_yuasa_jo","n":"湯浅城跡（湯浅党）","yomi":"ゆあさじょうあと","cat":"城","rank":"B","y":1143,"era":["heian","kamakura","muromachi"],"sh":"国指定史跡（湯浅党城館跡）","ad":"有田郡湯浅町青木","st":"JR紀勢本線・湯浅駅から車で約10分。城跡へは山道を歩く","la":34.0356,"lo":135.1938,"hook":"平清盛を助け、のちに源頼朝に仕えた «湯浅党»。紀州最強の武士団がこもった山城。","lead":"湯浅城は、平安時代の終わりに湯浅宗重が青木山に築いたとされる山城の跡です。湯浅氏の一族は «湯浅党» とよばれ、鎌倉時代には紀伊でいちばん強い武士団になりました。2021年に «湯浅党城館跡» として国の史跡になりました。","story":["1143年、湯浅宗重は青木山に城を築いたといわれます。宗重は、有田の地をまとめあげた武士でした。«なぜ山の上に?» 平地の館だけでは、攻められたときに守りきれないからです。湯浅の町と海を見下ろすこの山は、見張りにもうってつけでした。","1159年の冬、宗重の名が歴史に大きく登場します。平清盛が熊野詣でに出かけたすきに、都で源義朝らが兵をあげました（平治の乱）。旅先で知らせを聞き、あわてる清盛。«兵がいない、どうする»。そこへ手勢を連れてかけつけたのが宗重だったと『平治物語』は伝えます。清盛は無事に都へもどり、勝利しました。","ところが時代は変わります。平家が滅びると、宗重たちは源頼朝の側につき、鎌倉幕府の御家人として生き残りました。宗重の娘が生んだ子（つまり孫）が、あの名僧・明恵です。一族は有田の各地に広がり、«湯浅党» という大きなまとまりになりました。","湯浅党の地頭がきびしかったことを伝える、有名な文書があります。1275年、阿氐河荘（いまの有田川町）の百姓たちが、地頭・湯浅氏のひどいしうちをカタカナで訴えた «言上状» です。«耳を切り、鼻をそぐぞ» と脅された、と書かれています。武士の強さの裏側に、苦しむ人々の声がありました。","南北朝時代、湯浅党は南朝方について戦い、しだいに力を失います。室町時代の1447年には守護畠山氏がこの城を攻め、三度目でようやく落としたといわれます。いま山には土塁や曲輪が残り、2012年には全国の «湯浅さん» が集まって宗重の顕彰碑を建てました。"],"tl":[["1143年","湯浅宗重が青木山に城を築いたとされる"],["1159年","平治の乱。熊野詣で中の平清盛を宗重が助けたと伝わる"],["1185年ごろ","平家滅亡後、源頼朝に従い御家人に"],["1275年","阿氐河荘の百姓が地頭湯浅氏の非法を訴える"],["南北朝時代","湯浅党は南朝方として戦う"],["1447年","畠山氏が三度攻めて落城させたとされる"],["2012年","城跡に湯浅宗重顕彰碑が建つ"],["2021年","«湯浅党城館跡» として国の史跡に"]],"who":[["湯浅宗重","湯浅党の祖。城を築いたとされる"],["平清盛","平治の乱のとき熊野詣での途中で、宗重らの助けを得た"],["源頼朝","平家滅亡後、湯浅氏を御家人として認めた"],["明恵","宗重の孫。湯浅で修行した名僧"],["阿氐河荘の百姓たち","湯浅氏の非法をカタカナの訴状で訴えた"]],"deep":["国の史跡の名前は «湯浅党城館跡»。山城の湯浅城跡と、有田川町の館跡とを合わせて指定されています。«山城と平地の館» のセットで中世武士の暮らしがわかる点が評価されました。","«阿氐河荘上村百姓等言上状»（1275年）は、中世の農民の声を直接伝える史料として教科書にもよく出ます。訴えられた地頭は湯浅宗親です。","湯浅党は宗重の子孫だけでなく、婚姻で結ばれた保田・石垣・藤並などの諸氏をふくむ連合体でした。","施無畏寺の寄進状（1231年）に47名が連署しているのは、湯浅党の結束の強さを示す資料です。","城跡の向かいには、城の形をまねた温泉施設 «湯浅城» があり、4階に湯浅氏の資料展示があります（本物の城跡ではありません）。","平治の乱の際に清盛が熊野詣での途中で知らせを受けた場所は、日高郡の切目王子付近と伝わります。"],"look":["山上に残る曲輪・土塁","湯浅宗重顕彰碑","城跡から見下ろす湯浅の町並み（醤油の町・重要伝統的建造物群保存地区）","向かいの温泉施設 «湯浅城» の資料展示"],"q":["阿氐河荘の百姓が湯浅氏を訴えた訴状は、何の文字で書かれていた？","カタカナ。«ミミヲキリ ハナヲソギ» という生々しい言葉が残っています。"],"koji":[],"myth":"築城年1143年と1447年の三度の攻防は «とされる» 伝承。清盛救援は『平治物語』による。","img":["湯浅党","湯浅宗重","平治の乱","阿氐河荘"],"wp":"湯浅城","rel":{"ev":[],"grave":[]},"ph":[["c:2/26/Heiji_no_ran.jpg",6064,2085,"平治の乱"],["c:3/32/Yuasa_Ekikura_ac.jpg",3870,2580,"近く: 湯浅駅"],["c:6/68/260516_Kadocho_Yuasa_Wakayama_pref_Japan02s3.jpg",5472,3648,"近く: 湯浅町"],["c:0/01/Yuasa_Postoffice.JPG",1632,1224,"近く: 湯浅郵便局"],["c:6/65/Yuasa_Town_Public_Library_2021-09_ac_%281%29.jpg",5863,3899,"近く: 湯浅町立図書館"],["c:8/8c/Yuasa_Town_Yuasa_Junior_High_School_ac.jpg",3747,2498,"近く: 湯浅町立湯浅中学校"],["c:4/4a/Yuasa_Elementary_School_ac.jpg",3788,2525,"近く: 湯浅町立湯浅小学校"]]},{"id":"30_saikazaki_daiba","n":"雑賀崎台場（幕末の砲台）","yomi":"さいかざきだいば","cat":"幕末","rank":"B","y":1860,"era":["edo"],"sh":"県指定史跡","ad":"和歌山市雑賀崎（トンガの鼻）","st":"JR和歌山駅・南海和歌山市駅からバスで雑賀崎方面へ、そこから岬まで歩く。車が便利","la":34.1936,"lo":135.1399,"hook":"黒船の時代、紀州藩が «トンガの鼻» にきずいた海の見張り台。石積みのなぞはいまも解けていない。","lead":"雑賀崎台場は、江戸時代の終わりに紀州藩が外国船にそなえて造った砲台（台場）の跡です。紀伊水道を見わたす岬 «トンガの鼻» にあり、土塁や石垣が残っています。2010年に和歌山県の史跡になりました。","story":["1853年、ペリーの黒船が浦賀にあらわれると、日本中の海辺の藩はあわてました。«外国の船が大阪湾に入ってきたらどうする?» 大阪湾の入口・紀伊水道を守るのは、御三家の紀州藩の大きな役目でした。","そこで紀州藩は、海岸のあちこちに «台場» を造りました。大砲をすえて海をにらむための土の陣地です。雑賀崎の先の岬 «トンガの鼻» は、紀伊水道を西に大きく見わたせる場所。«ここなら沖を通る船が一目でわかる» と選ばれたのでしょう。","台場は土塁（土の壁）でぐるりと囲まれ、下のほうは石垣で固められていました。2007年からの発掘調査では、土塁に囲まれた真ん中から、上から見ると «V字» の形をした石積みが見つかりました。«これは何のため?» 砲台に関係する施設らしいのですが、全国でも似た例がなく、いまもはっきりわかっていません。","雑賀崎といえば、戦国時代に鉄砲で織田信長を苦しめた «雑賀衆» の地でもあります。鉄砲の里の岬に、300年後、今度は大砲の台場ができたのです。歴史のめぐりあわせを感じませんか。","幕末の台場から実際に砲撃が行われたという記録は知られていません。使われずに終わったことは、平和の証でもあります。いまは地元の «トンガの鼻自然クラブ» が草を刈り、道を整えて守っています。夕日の名所としても人気の岬です。"],"tl":[["1853年","ペリー来航。各地で海防が急がれる"],["幕末","紀州藩が紀伊水道沿岸に台場を築く。雑賀崎台場もその一つ"],["2007年","第1次発掘調査。V字状の石積み遺構が見つかる"],["2010年4月20日","和歌山県の史跡に指定"],["2014年","3次にわたる発掘調査が終わる"]],"who":[["紀州藩","御三家の一つ。紀伊水道・大阪湾口の海防をになった"],["雑賀衆","戦国時代、雑賀の地を根拠にした鉄砲集団"],["トンガの鼻自然クラブ","台場跡の草刈りや道の整備をする市民団体"]],"deep":["2007〜2014年に3次の発掘調査が行われ、台場外縁の土塁と、その下の石垣が確認されました。","土塁に囲まれた中央部の «平面V字状の石積み» は類例がなく、砲座や火薬庫に関わる施設かとも考えられますが、用途は未解明です。","紀伊水道の対岸・友ヶ島や加太にも幕末の台場が築かれました。明治になると同じ海域に «由良要塞» の近代砲台が造られ、海防の拠点が受けつがれます。","岬の名 «トンガの鼻» の «鼻» は、海に突き出た岬を指すことばです。","台場跡は県の史跡で、市民団体が管理に協力しています。遺構を傷つけないよう、土塁の上に登らないようにしましょう。"],"look":["台場を囲む土塁と、その下の石垣","V字石積み遺構があった中央部（説明板）","紀伊水道と淡路島・四国方面の眺め","夕日の時間帯の岬の景色"],"q":["雑賀崎台場の中央部から見つかった、なぞの石積みはどんな形？","上から見ると «V字» の形。全国に似た例がなく、用途はまだわかっていません。"],"koji":[],"myth":"正確な築造年は未確認（幕末）。","img":["台場","雑賀崎","紀州藩","雑賀衆"],"wp":"雑賀崎台場","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:f/fd/Akashi-han_Maiko-daibaato01nt3200.jpg",3200,2130,"台場"],["c:6/6c/%E9%9B%91%E8%B3%80%E5%B4%8E%E9%9B%86%E8%90%BD.jpg",4032,3024,"雑賀崎"],["c:b/b7/Wakayama_Castle_2011_Kuruwa.jpg",1936,1296,"紀州藩"]]},{"id":"30_tokikanedo","n":"岡山の時鐘堂（紀州藩の時の鐘）","yomi":"おかやまのじしょうどう","cat":"町","rank":"B","y":1712,"era":["edo","showa"],"sh":"県指定史跡","ad":"和歌山市吹上1丁目","st":"JR和歌山駅・南海和歌山市駅からバスで «県庁前» 下車、歩いて約3分","la":34.2255,"lo":135.1726,"hook":"大坂の陣の «大砲» が生まれ変わった鐘。200年城下に時を告げ、戦後は «平和の鐘» になった。","lead":"岡山の時鐘堂は、和歌山城のすぐ西の丘に立つ、江戸時代の鐘つき堂です。1712年、紀州藩主・徳川吉宗の命令で建てられ、城下の人々に時刻や非常事態を知らせました。戦後の1948年からは «平和の鐘» をつく場所になっています。","story":["時計のない時代、人々はどうやって時間を知ったのでしょう。答えは «鐘の音» です。和歌山城の西、«岡山» とよばれた小高い丘の上に、2階建ての鐘つき堂が建てられたのは1712年。命じたのは、のちに8代将軍になる紀州藩主・徳川吉宗でした。","2階につるされた鐘には、おどろきの由来が伝わります。1615年の大坂夏の陣で豊臣方が使った青銅の大筒（大砲）を紀州藩が手に入れ、2代藩主・徳川光貞が粉河の鋳物師に命じて、鐘に鋳直させたというのです。«戦の道具が、人々に時を知らせる道具に»。なんとも象徴的な話です。","堂の前には «禁殺生»（生き物を殺すな）と刻まれた石碑があります。初代藩主・徳川頼宣の命で、藩に仕えた儒学者・李梅渓が書いたといわれます。鐘の音とともに、命を大切にする心も城下に伝えようとしたのでしょうか。","鐘は江戸時代が終わっても鳴りつづけ、1921年3月末まで時報として使われました。やがて鳴らなくなった鐘がふたたび響いたのは、終戦から3年目の1948年8月15日。和歌山のユネスコ協力会が «平和の鐘» をつく会を開いたのです。","この «平和の鐘» の取り組みは全国に広がり、2000年からは日本ユネスコ協会連盟の «平和の鐘を鳴らそう!» 運動へと発展しました。大みそかには除夜の鐘をつくこともできます。大砲から生まれた鐘が、平和を願う音を鳴らす——300年の物語がこの小さな堂につまっています。"],"tl":[["1615年","大坂夏の陣。豊臣方の青銅製大筒を紀州藩が入手したとされる"],["1705年まで","2代藩主徳川光貞が粉河の鋳物師に鐘へ改鋳させたとされる"],["1712年","5代藩主徳川吉宗の命で時鐘堂が建つ"],["1921年3月","時報としての打鐘を終える"],["1948年8月15日","«平和の鐘» 打鐘会が始まる"],["1958年","和歌山県の史跡に指定"],["2000年","全国運動 «平和の鐘を鳴らそう!» が始まる"]],"who":[["徳川吉宗","紀州藩5代藩主（のち8代将軍）。時鐘堂の建設を命じた"],["徳川光貞","紀州藩2代藩主。大筒を鐘に鋳直させたとされる"],["徳川頼宣","紀州藩初代藩主。«禁殺生» の碑を書かせたとされる"],["李梅渓","紀州藩に仕えた儒学者。碑の文字を書いたといわれる"],["和歌山ユネスコ協会","戦後、平和の鐘の打鐘会を始めた"]],"deep":["建物は木造2階建て、高さ約8.27メートル。間口・奥行きとも約6メートル。鐘は高さ約1.33メートル、直径約0.97メートルです。","鐘を鋳た蜂屋安右衛門は粉河（紀の川市）の鋳物師とされます。粉河は中世から鋳物づくりで知られた土地です。","大筒を管理していたのは砲術家の勝野五兵衛と伝わります。武器の青銅を鐘に鋳直す例は、平和の時代になった江戸時代らしい話です。","時鐘は時刻を知らせるだけでなく、火事などの非常事態も知らせました。城下町の «放送局» のような役割です。","現在地は和歌山県立近代美術館の東側。和歌山城の天守とあわせて歩ける距離にあります。"],"look":["江戸時代の2階建ての鐘楼","大筒から鋳直されたと伝わる梵鐘","«禁殺生» の石碑","大みそかの除夜の鐘（例年の開催は事前に確認を）"],"q":["時鐘堂の鐘は、もともと何だったと伝わる？","大坂夏の陣で豊臣方が使った青銅の大筒（大砲）。それを鋳直したとされます。"],"koji":[],"myth":"鐘の素材が大坂の陣の大筒であること、碑の筆者は «とされる» 伝承。","img":["徳川吉宗","和歌山城","徳川頼宣","梵鐘"],"wp":"岡山の時鐘堂","rel":{"ev":[],"grave":[]},"ph":[["c:1/10/Okayama-no-jishodo_Wakayama01n4272.jpg",4272,2848,"岡山の時鐘堂"],["c:e/e9/Okayama-no-jishodo_Wakayama03bs4272.jpg",2848,4272],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:5/50/Tokugawa_Yoshimune.jpg",2616,2550,"徳川吉宗"],["c:5/51/%E5%92%8C%E6%AD%8C%E5%B1%B1%E5%9F%8E_%E5%A4%A9%E5%AE%88%E9%96%A3%EF%BC%882024%E5%B9%B4%EF%BC%89.jpg",3024,4032,"和歌山城"],["c:0/0a/Tokugawa_Yorinobu.jpg",588,607,"徳川頼宣"],["c:f/f8/Miidera-BenkeiGane-M2057.jpg",1000,1500,"梵鐘"]]},{"id":"30_narutaki","n":"鳴滝遺跡（古墳時代の大倉庫群）","yomi":"なるたきいせき","cat":"遺跡","rank":"B","y":420,"era":["kofun"],"sh":"","ad":"和歌山市善明寺","st":"JR阪和線・紀伊駅付近から車で。現地に見学できる遺構はほとんどない","la":34.2672,"lo":135.1849,"hook":"5世紀、紀ノ川の河口に並んだ7棟の巨大倉庫。中には何が入っていたのか——古代豪族 «紀氏» の底力が見える遺跡。","lead":"鳴滝遺跡は、1982年に見つかった古墳時代中期（5世紀前半）の大倉庫群の跡です。高床の大きな建物7棟が整然と並び、たくさんの須恵器も出ました。紀ノ川河口を拠点にした豪族・紀氏にかかわる倉庫と考えられています。","story":["1982年、紀ノ川の北、和泉山脈のふもとの低い丘で発掘をしていた人たちは、目を疑いました。地面に、大きな柱の穴がきちんと列になって並んでいたのです。数えてみると、建物は7棟。西に5棟、東に2棟、まるで定規で引いたように整列していました。","建物はどれも高床で、屋根は切妻。妻側（三角の壁の側）の真ん中には、屋根を直接ささえる «棟持柱» がありました。ふつうの家ではなく、大切なものをしまう倉庫です。«なぜ高床?» 湿気やネズミから中身を守るためです。","では、中に何が入っていたのでしょう。米などの食料か、朝鮮半島から運ばれた品々か、それとも武器か。建物は残っていないので答えはわかりません。ただ、見つかった須恵器（かたい焼き物）は古い時期のもので、年代が5世紀前半に集中していました。短い期間、ある目的のために使われたようです。","紀ノ川の河口は、古代には大和と海外を結ぶ «表玄関» でした。大和の政権が朝鮮半島へ兵や物資を送るとき、この港を使ったと考えられています。そこで力をもったのが豪族・紀氏。『日本書紀』には、紀氏の一族が朝鮮半島へ渡って活躍した話がいくつも出てきます。","«紀氏の倉庫» だとすれば、それは一地方の豪族の倉ではなく、国の外交や軍事を支える «物資の基地» だったのかもしれません。大阪の法円坂遺跡でも同じころの巨大倉庫群が見つかっています。紀ノ川と大阪湾——二つの港の倉庫がならぶ姿を想像すると、5世紀の日本のにぎわいが見えてきます。"],"tl":[["5世紀前半","7棟の大型高床倉庫が建てられ、短期間使われる"],["1982年","発掘調査で倉庫群が見つかる"],["1984〜1990年","県立紀伊風土記の丘で出土品が特別陳列される"]],"who":[["紀氏","紀ノ川下流域を本拠にした古代豪族。倉庫の持ち主と推定される"],["紀小弓","『日本書紀』雄略天皇の条に、新羅へ遣わされたと記される紀氏の人物"],["発掘調査の担当者たち","1982年に倉庫群を掘り出した"]],"deep":["建物は桁行4間×梁間4間の切妻高床建物で、妻側中央に棟持柱をもつ構造。西側5棟・東側2棟の計7棟が整然と並んでいました。","出土した大量の須恵器は初期のもので、年代が5世紀前半に集中します。倉庫群は長く使われず、何かの目的で短期間に建てられた可能性があります。","同じ5世紀の大型倉庫群として、大阪市の法円坂遺跡（難波）が知られます。どちらも大和王権の物流・外交に関わる施設とみる説があります。","紀ノ川河口の港は古代に «紀水門»（きのみなと）とよばれたと考えられ、大和と瀬戸内・朝鮮半島を結ぶ要地でした。","倉庫の中身については、食料説・交易品説・軍事物資説など諸説があり、決め手はありません。"],"look":["遺跡の地形（和泉山脈南麓の低い丘と紀ノ川河口の位置関係）","紀伊風土記の丘の展示（出土品の展示状況は事前に確認を）","近くの大谷古墳など、紀ノ川北岸の古墳時代遺跡とあわせて"],"q":["鳴滝遺跡で見つかった大型倉庫は全部で何棟？","7棟。西に5棟、東に2棟が整然と並んでいました。"],"koji":[],"myth":"倉庫の持ち主（紀氏）や用途は推定・諸説。«紀水門» の位置も諸説。","img":["紀氏","須恵器","法円坂遺跡","高床倉庫"],"wp":"鳴滝遺跡","rel":{"ev":[],"grave":[]},"ph":[["c:c/c9/Narutaki_Site_in_2018.jpg",6016,4000,"鳴滝遺跡"],["c:b/b0/Middle_Jomon_Period_rope_pottery_5000-4000BC.jpg",727,1189],["c:4/47/131123_Hyogo_Prefectural_Museum_of_Archaeology_Japan24s5.jpg",4912,3264,"須恵器"],["c:b/bf/Houenzaka_Ruins-1.jpg",6002,3978,"法円坂遺跡"],["c:4/41/Yoshinogari-iseki_takayukashiki-souko.JPG",5619,3720,"高床倉庫"]]},{"id":"30_narukami","n":"鳴神貝塚（近畿で初めて見つかった貝塚）","yomi":"なるかみかいづか","cat":"遺跡","rank":"B","y":-3000,"era":["jomon"],"sh":"国指定史跡","ad":"和歌山市鳴神","st":"和歌山電鐵貴志川線・日前宮駅から北東へ約1キロ、歩いて約15分","la":34.2306,"lo":135.2121,"hook":"いまは海から離れた住宅地。でも縄文時代、ここは波打ちぎわだった——近畿で最初に見つかった «縄文人のごみ捨て場»。","lead":"鳴神貝塚は、縄文時代の人々が食べた貝のからや道具を捨てた «貝塚» です。1895年（明治28年）に見つかり、近畿地方で初めて確認された貝塚として知られます。1931年に国の史跡になりました。","story":["日前宮駅から北へ歩くと、住宅地の中にこんもりした斜面があります。«ここに海があったなんて» と思うかもしれません。でも縄文時代、いまより海面が高かったころ、和歌山の平野の多くは入り江でした。鳴神のあたりは、海辺の暮らしにぴったりの場所だったのです。","縄文の人々はここで、カキやハイガイ、ハマグリ、サザエなどをとって食べました。からを捨てた場所がつみ重なって «貝塚» になります。貝のほかに、クロダイやマダイの骨も見つかりました。«舟で沖へ出て、タイを釣っていたの?» 想像がふくらみます。","貝塚からは、土器や石の矢じり（石鏃）、穴をあける石錐、土を掘る打製石斧、するどい石刃なども出ています。貝塚は «ごみ捨て場» ですが、考古学者にとっては «縄文人の暮らしの記録帳» です。何を食べ、どんな道具を使ったかが、そのまま残るからです。","貝塚が見つかったのは1895年。東京の大森貝塚が明治のはじめに発掘されてから、日本各地で貝塚さがしが始まった時代でした。関東には貝塚がたくさんあるのに、近畿ではなかなか見つかりません。そこへ現れたのが鳴神貝塚でした。«近畿で初めて» の発見は大きな話題になりました。","出た土器は、縄文時代の早い時期から終わりごろまでの長い期間にわたります。何千年ものあいだ、人々はこの浜辺にくらしつづけたのです。いまは小さな史跡ですが、足もとには、縄文の海辺の暮らしがねむっています。"],"tl":[["縄文時代早期","このころから人が暮らし始める"],["縄文時代前期ごろ","海面が高く（縄文海進）、周辺は入り江だったと考えられる"],["縄文時代晩期","このころまで貝塚が使われる"],["1877年","東京で大森貝塚が発掘され、貝塚研究が始まる"],["1895年","鳴神貝塚が見つかる。近畿で初めて確認された貝塚"],["1931年7月31日","国の史跡に指定"]],"who":[["縄文時代の人々","この浜で貝や魚をとって暮らした"],["明治の研究者たち","近畿地方で初めて貝塚を確認した"],["エドワード・モース","大森貝塚を発掘し、日本の貝塚研究のきっかけを作った"]],"deep":["貝層からはカキ・ハイガイ・ハマグリ・サザエなど、魚骨ではクロダイ・マダイが見つかっています。内湾の干潟と外海の岩場、両方を利用していたことがうかがえます。","土器は縄文時代早期から晩期にわたり、長期間にわたって人が住んだ場所だとわかります。","ハイガイは暖かい内湾の泥干潟にすむ貝で、縄文時代の温暖な気候を示す手がかりとされます。","近畿地方は関東にくらべて貝塚が少なく、鳴神貝塚は近畿の縄文研究の出発点になりました。","発見者については資料によって記述が分かれるため、ここでは «明治の研究者» としています。"],"look":["史跡の標柱と説明板","住宅地の中に残る斜面（かつての海岸線を想像）","近くの日前宮（日前神宮・國懸神宮）もあわせて"],"q":["鳴神貝塚から骨が見つかった魚で、お祝いにも使われる魚は？","マダイ（クロダイも）。縄文人も沖の魚をとっていたことがわかります。"],"koji":[],"myth":"発見者名は資料により異なる。","img":["貝塚","縄文時代","縄文海進","大森貝塚"],"wp":"鳴神貝塚","rel":{"ev":[],"grave":[]},"ph":[["c:5/5c/Narukami_Kaizuka%2C_setsumeiban.jpg",5958,3912,"鳴神貝塚"],["c:8/83/Conchero_Arguin.jpg",2048,1536,"貝塚"],["c:1/1d/Post-Glacial_Sea_Level.png",1813,1088,"縄文海進"],["c:b/b0/Omori_Shell_Mound%2C_sekihi-3.jpg",5568,3712,"大森貝塚"]]},{"id":"30_otani_kofun","n":"大谷古墳（馬冑が出た古墳）","yomi":"おおたにこふん","cat":"遺跡","rank":"B","y":480,"era":["kofun"],"sh":"国指定史跡","ad":"和歌山市大谷","st":"南海本線の北部の駅（和歌山大学前駅など）から車で。駐車場の有無は事前に確認を","la":34.2618,"lo":135.1763,"hook":"日本でただ一つ、完全な形で見つかった «馬のかぶと»。紀ノ川の武人は、朝鮮半島と深くつながっていた。","lead":"大谷古墳は、5世紀後半から6世紀はじめに造られた全長67メートルの前方後円墳です。九州・阿蘇の石で作った石棺や、馬の顔を守る «馬冑»（ばちゅう）が見つかりました。完全な形の馬冑は日本でここだけです。","story":["1957年から翌年にかけて、和歌山市は京都大学に頼んで、紀ノ川の北にある古墳を調べました。後円部を掘ると、大きな石の棺があらわれます。屋根の形のふたをもつ «家形石棺»。調べてみると、石は遠い九州・熊本の阿蘇山の凝灰岩でした。«なぜ、わざわざ九州から?»","重い石を船で運ぶには、海の道を知りつくした力が必要です。紀ノ川の河口を押さえた豪族・紀氏は、瀬戸内海から九州、そして朝鮮半島までつながる航海のネットワークをもっていたと考えられています。石棺はその «証拠品» ともいえます。","石棺の外からは、世にもめずらしいものが見つかりました。鉄の板を鋲でとめて作った «馬冑»——馬の顔をすっぽりおおう、かぶとです。面をおおう部分、ひさし、ほほ当てまでそろっていました。このような馬の武具は朝鮮半島南部で多く見つかっていて、大陸の戦い方が伝わっていたことを示します。","棺の中には、20〜30歳くらいの人の骨と、小さな銅鏡、緑色のガラスの勾玉21個、鉄のかぶとがありました。«よろいを着た馬に乗る、若い武将»——そんな姿が浮かびます。この人は紀氏一族の武人だったと推定されています。","紀ノ川の南岸には、紀氏の首長たちの墓とされる岩橋千塚古墳群があります。北岸の大谷古墳の主は、それとは別の有力者だったと考えられています。出土品は国の重要文化財になり、和歌山市立博物館で保管されています。"],"tl":[["5世紀後半〜6世紀初頭","大谷古墳が造られる"],["1957〜1958年","京都大学による発掘調査"],["1978年","国の史跡に指定"],["1982年6月5日","出土品一括が国の重要文化財に指定"]],"who":[["被葬者（紀氏一族の武人と推定）","20〜30歳ほどの人骨が見つかった"],["紀氏","紀ノ川下流域の古代豪族。海の交易と軍事で力をもった"],["京都大学の調査団","1957〜58年に発掘を担当した"]],"deep":["規模は全長67メートル、後円部径30メートル、前方部幅48メートル。前方部を南西に向けています。","石棺は阿蘇溶結凝灰岩製の組合式家形石棺で、屋根形の蓋石は約2.96×1.6メートル、両側に縄掛突起を6個ずつもちます。","馬冑は数枚の鉄板を鋲留めしたもので、完成品の出土は日本で唯一。埼玉県の将軍山古墳からは一部が見つかっています。","棺内からは素文鏡3面（直径26・31・34ミリ）、ガラス勾玉21個、横矧板鋲留式の衝角付冑が出ました。","出土品は «紀伊大谷古墳出土品» として国の重要文化財（国有・和歌山市立博物館保管）です。","後円部の後方には円筒埴輪が並べられていました。調査で39個が出土しています。"],"look":["前方後円墳の墳丘の形","紀ノ川河口方面の眺め（古墳の主が見ていた海の道）","和歌山市立博物館の出土品展示（馬冑の展示状況は事前に確認を）"],"q":["大谷古墳から、完全な形では日本でただ一つ見つかった武具は？","«馬冑»（ばちゅう）。馬の顔を守る鉄のかぶとです。"],"koji":[],"myth":"被葬者が紀氏一族の武人というのは推定。","img":["馬冑","紀氏","岩橋千塚古墳群","家形石棺"],"wp":"大谷古墳 (和歌山市)","rel":{"ev":[],"grave":[]},"ph":[["c:b/be/Otani_Kofun%2C_funkyu.jpg",6016,4000,"大谷古墳 (和歌山市)"],["j:d/d6/%E5%A4%A7%E8%B0%B7%E5%8F%A4%E5%A2%B3%E5%87%BA%E5%9C%9F_%E9%A6%AC%E5%86%91_%28%E8%A4%87%E8%A3%BD%29.JPG",4008,3058],["j:7/7d/%E5%A4%A7%E8%B0%B7%E5%8F%A4%E5%A2%B3%E5%87%BA%E5%9C%9F_%E5%9E%82%E9%A3%BE%E4%BB%98%E8%80%B3%E9%A3%BE.JPG",4982,3304],["j:c/cc/%E5%A4%A7%E8%B0%B7%E5%8F%A4%E5%A2%B3%E5%87%BA%E5%9C%9F_%E9%A6%AC%E5%86%91.JPG",4637,3455],["j:d/d2/%E5%A4%A7%E8%B0%B7%E5%8F%A4%E5%A2%B3%E5%87%BA%E5%9C%9F_%E9%89%84%E5%88%80%E3%83%BB%E9%89%84%E7%9F%9B.JPG",5018,2620],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:e/ee/Wei%2C_Jin%2C_Nanbeichao_Armored_Horse_Rider.jpg",3888,2592,"馬冑"],["c:6/63/Iwase-senzuka-kofungun-1.JPG",6016,4000,"岩橋千塚古墳群"]]},{"id":"30_kokubunji","n":"紀伊国分寺跡","yomi":"きいこくぶんじあと","cat":"遺跡","rank":"B","y":750,"era":["nara","heian"],"sh":"国指定史跡","ad":"紀の川市東国分","st":"JR和歌山線・下井阪駅から歩いて約10分","la":34.2688,"lo":135.3392,"hook":"聖武天皇が «国ごとに寺を» と願った奈良時代の大寺院。七重塔がそびえた場所に、礎石がそのまま並ぶ。","lead":"紀伊国分寺跡は、奈良時代に聖武天皇の命令で全国に建てられた国分寺のうち、紀伊国の国分寺の跡です。約218メートル四方の広い境内に、金堂・講堂・七重塔などが並んでいました。いまは歴史公園として整備され、講堂跡には江戸時代の本堂が立っています。","story":["741年、聖武天皇は «国ごとにお寺を建てなさい» という詔を出しました。都では病気がはやり、反乱も起きていました。«仏の力で国を守りたい»。その願いから、全国60あまりの国に国分寺（僧寺）と国分尼寺が造られていきます。紀伊国の国分寺は、紀の川の北岸の高台に建てられました。","寺の広さは二町四方、約218メートル四方。南から南門・中門・金堂・講堂・僧房が一直線に並び、金堂の東の前には七重塔がそびえていたと考えられています。七重塔の高さはおそらく数十メートル。紀の川を行き来する人々は、遠くからその姿を見上げたことでしょう。","塔の跡には、一辺16.4メートルの基壇（土台）の上に、礎石がいまも元の位置に並んでいます。真ん中の心礎（中心の柱を受ける石）は、紀州らしい緑色の «緑泥片岩»。1200年以上前の石が、そのままの場所にあるのです。","平安時代の歴史書『日本三代実録』には、879年に «紀伊国金光明寺»（国分寺の正式名）が火事で焼けたとあります。«それで寺は終わったの?» いいえ、その後すぐに建て直されたようで、平安時代の法律の細則『延喜式』にも国分寺の運営費が記されています。しかし中世になると記録から姿を消していきました。","寺の法灯はとだえず、江戸時代には講堂の跡に本堂が再建されました。1970年代の発掘で伽藍の配置がはっきりし、いまは歴史公園として整備されています。隣の紀の川市歴史民俗資料館で、出土した瓦などを見ることもできます。"],"tl":[["741年","聖武天皇が国分寺建立の詔を出す"],["756年","『続日本紀』に紀伊国など26か国の国分寺へ法具を配った記事"],["879年","『日本三代実録』に «紀伊国金光明寺» 焼失の記事"],["10世紀","『延喜式』に紀伊国分寺料の記載"],["1700年","講堂跡にいまの本堂が再建される"],["1928年","国の史跡に指定"],["1970年代","発掘調査で伽藍配置が判明"],["1992年","本堂を講堂基壇の中央へ移築"]],"who":[["聖武天皇","国分寺建立の詔を出した天皇"],["光明皇后","聖武天皇の皇后。国分寺・国分尼寺の建立を後押ししたといわれる"],["行基","奈良時代の僧。各地の国分寺の開基と伝わる例が多いが、この寺との関係ははっきりしない"]],"deep":["伽藍配置は南門・中門・金堂・講堂・軒廊・僧房が一直線。塔は金堂の東前方、鐘楼と経蔵は金堂の後方。中門から出た回廊が金堂・塔などを囲み講堂につながる «国分寺式» の配置です。","塔は七重塔と推測され、一辺16.4メートルの瓦積基壇の上に心礎を含むすべての礎石が旧状を保っています。","『延喜式』には紀伊国分寺料として稲2万束が記されています。国の税でまかなわれた «国立寺院» でした。","国分尼寺の場所はわかっていません。西へ約800メートルの西国分廃寺跡（岩出市、塔心礎が残る国史跡 «西国分塔跡»）を尼寺とみる説があります。","現本堂は1700年の再建。外から見ると二階建てですが、中は一階の «重層» 屋根の建物で、紀の川市の文化財です。","付近の府守神社のあたりに、紀伊国府があったと推定されています。国府と国分寺が近くにセットで置かれた例です。"],"look":["七重塔跡の基壇と、元の位置に残る礎石（緑泥片岩の心礎）","講堂跡に立つ江戸時代の本堂","整備された回廊・金堂の跡","隣の紀の川市歴史民俗資料館"],"q":["国分寺の正式名称にふくまれる、お経の名前は？","«金光明経»。国分寺は «金光明四天王護国之寺» といいます。"],"koji":[],"myth":"創建年の記録はない。国分尼寺の位置は諸説。","img":["国分寺","聖武天皇","紀の川市","延喜式"],"wp":"紀伊国分寺","rel":{"ev":[],"grave":[]},"ph":[["c:0/0f/Kii_Kokubunji_kodo.JPG",6016,4000,"紀伊国分寺"],["c:a/a4/Nishi-kokubu-haiji.JPG",5315,3486],["c:1/12/Kii_Kokubunji_tou.JPG",6016,4000],["c:2/21/Kii_Kokubunji_sobo.JPG",6016,4000],["c:2/21/Kii_Kokubunji_shoumen.JPG",6016,4000],["c:9/95/Kii_Kokubunji_shoro.JPG",6016,4000],["c:0/03/Kii_Kokubunji_kyozo.JPG",6016,4000],["c:1/17/Kii_Kokubunji_kondo.JPG",6016,4000]]},{"id":"30_niu_kanshofu","n":"丹生官省符神社","yomi":"にうかんしょうぶじんじゃ","cat":"寺社","rank":"B","y":816,"era":["heian","muromachi"],"sh":"国の重要文化財（本殿3棟）・国指定史跡（高野参詣道）・世界遺産","ad":"伊都郡九度山町慈尊院","st":"南海高野線・九度山駅から歩いて約20分","la":34.2942,"lo":135.5494,"hook":"白と黒の犬が空海を高野山へ案内した——その道案内の神さまをまつる、高野山への «入口» の社。","lead":"丹生官省符神社は、高野山のふもと・慈尊院の上にある神社です。空海が高野山を開いたとき、山の神である丹生都比売大神と高野御子大神（狩場明神）をこの地にまつったと伝わります。室町時代の本殿3棟は国の重要文化財で、世界遺産 «紀伊山地の霊場と参詣道» の一部です。","story":["修行の場所をさがして歩いていた空海は、大和国（奈良県）で一人の猟師に出会ったといわれます。白と黒、二匹の犬を連れた猟師は言いました。«南の山に、あなたの求める霊地がある»。犬に導かれてたどりついたのが高野山でした。猟師の正体は、高野山の地主神・狩場明神だったと伝わります。","816年、空海は嵯峨天皇から高野山を賜ります。空海は、道を教えてくれた狩場明神と、その母神・丹生都比売大神を、高野山の入口にあたるこの地にまつりました。«山の神さまにあいさつしてから、山に入る»——それが高野山の作法になったのです。","石段の下には慈尊院があります。高野山の事務所（政所）として開かれ、空海の母が晩年をすごしたと伝わる寺です。高野山は長く女性が入れない山でした。空海は月に九度も山を下りて母に会いに来た——それが «九度山» の地名の由来だという話もあります。","神社は高野山の領地 «官省符荘» の守り神になり、神社の名前もそこから来ています。1517年に第一殿・第二殿、1541年に第三殿が再建され、いまも朱色の社殿が並びます。紀ノ川の洪水で昔の境内が沈み、いまの場所に移ったとも伝わります。","境内の北の石段を下ると、途中に «百八十町石» があります。ここから高野山の壇上伽藍まで、1町（約109メートル）ごとに石の道しるべが立つ «町石道» が続きます。約20キロの山道。昔の人たちは、この社で手を合わせてから、一歩一歩、祈りの道を登っていったのです。"],"tl":[["816年","空海、嵯峨天皇から高野山を賜る。このころ明神をまつったと伝わる"],["1396年","文書に «官省符鎮守・神通寺七社» と記される"],["1517年","本殿第一殿・第二殿が再建される"],["1541年","本殿第三殿が再建される"],["1910年","周辺の神社を合祀"],["1946年","社号を «丹生官省符神社» とする"],["1965年","本殿3棟が国の重要文化財に"],["2004年","世界遺産 «紀伊山地の霊場と参詣道» に登録"]],"who":[["空海（弘法大師）","高野山を開き、この地に地主神をまつったと伝わる"],["狩場明神（高野御子大神）","猟師の姿で空海を高野山へ導いたとされる神"],["丹生都比売大神","狩場明神の母神。紀ノ川流域の古い女神"],["嵯峨天皇","空海に高野山の地を与えた"],["空海の母（玉依御前）","慈尊院で晩年をすごしたと伝わる"]],"deep":["«官省符» とは、太政官と民部省が発行した «官省符» によって免税が認められた荘園のこと。高野山領 «官省符荘» の鎮守だったことが社名の由来です。","かつては七柱の神を祀り «神通寺七社明神» とよばれ、慈尊院と合わせて神仏習合の聖地でした。明治に慈尊院から独立しています。","本殿三棟はいずれも室町時代の再建で、宮殿4棟・棟札2枚とともに重要文化財（1965年指定）。","県の文化財に永正14年（1517年）銘の鼎、室町時代と推定される獅子頭2面があります。","町石は鎌倉時代に木の卒塔婆から石に建て替えられたもので、慈尊院から壇上伽藍まで180基が並びます（一部は後補）。","2015年に国の史跡名が «高野山町石道» から «高野参詣道» に改められ、境内はその «町石道» の一部として指定されています。"],"look":["朱塗りの本殿3棟（室町時代）","慈尊院から続く石段","百八十町石（町石道の起点付近）","境内からの紀ノ川と九度山の眺め"],"q":["空海を高野山へ案内したとされる犬は、何色と何色？","白と黒の二匹。狩場明神が連れていたと伝わります。"],"koji":[],"myth":"狩場明神の犬の話、空海の母、«九度山» の地名由来は伝承。","img":["慈尊院","高野参詣道","丹生都比売神社","空海"],"wp":"丹生官省符神社","rel":{"ev":[],"grave":[]},"ph":[["c:5/52/Niukanshobujinja_02.JPG",4235,2769,"丹生官省符神社"],["c:0/06/Niukanshoubu_jinja_honden.jpg",3264,2448],["c:9/98/Niukanshoubu_jinja_haiden.jpg",3264,2448],["c:6/6d/Daimonzaka8618.JPG",1200,1600],["c:3/3a/Jisonin_hondo.jpg",3264,2448,"慈尊院"],["c:b/b9/Niutsuhime-jinja_roumon-3.jpg",5514,3630,"丹生都比売神社"],["c:9/98/Kobo_Daishi_%28Taisanji_Matsuyama%29.jpg",260,270,"空海"]]},{"id":"30_tedori_jo","n":"手取城跡（玉置氏）","yomi":"てどりじょうあと","cat":"城","rank":"B","y":1585,"era":["muromachi","azuchi"],"sh":"","ad":"日高郡日高川町和佐","st":"JR紀勢本線・和佐駅付近から登山道へ。山城なので登山の準備を","la":33.929,"lo":135.212,"hook":"義理の父と娘むこが戦った紀州の山城。秀吉の大軍が迫るなか、城は炎に包まれた。","lead":"手取城は、日高川の下流を見下ろす城山にあった山城の跡です。南北朝時代に玉置氏が築いたと伝わり、日高地方を湯川氏と二分する勢力の拠点でした。1585年、豊臣秀吉の紀州攻めのとき、湯川氏に攻められて焼け落ちたといわれます。いまも石垣や堀の跡が残ります。","story":["日高川にそって山あいを上ると、和佐の集落の東に «城山» がそびえます。南北朝時代、日高川の上流一帯を治めていた玉置大宣が、下流の山崎城の川上氏を攻め滅ぼし、その東の山に新しい城を築いたと伝わります。それが手取城です。日高川の下流一帯をひと目で見わたせる、見張りに絶好の山でした。","玉置氏は、亀山城（御坊市）の湯川氏と並ぶ日高地方の二大勢力になりました。両家は婚姻でも結ばれ、戦国時代の終わりには、手取城主・玉置直和は湯川直春の娘むこになっていました。«親戚どうし、力を合わせよう»——そのはずでした。","1585年、豊臣秀吉が大軍で紀州に攻めこみます。湯川直春は «ともに秀吉と戦おう» と娘むこに呼びかけました。けれど直和は首を横にふります。«秀吉には勝てない»。玉置氏は秀吉方につき、湯川領に火を放ちました。義理の親子が、敵味方に分かれたのです。","怒った湯川勢は玉置勢と «坂の瀬» で激しくぶつかり、玉置勢は手取城にたてこもりました。攻防は三日三晩続いたと伝わります。そこへ秀吉方の仙石秀久・小西行長の水軍が迫ったため、湯川勢は急いで城を攻めて焼きはらい、手取城は落ちました。直和は城を逃れました。","紀州が秀吉のものになると、直和と息子の永直は新しい領主・羽柴秀長に仕え、領地を減らされながらも手取城主にもどります。しかし1600年の関ヶ原の戦いで西軍に味方したため、戦後に領地を取り上げられ、城は廃城となりました。石垣と堀だけが、戦国の日高の激しさを語っています。"],"tl":[["南北朝時代","玉置大宣が山崎城の川上氏を滅ぼし、城山に手取城を築いたと伝わる"],["戦国時代","湯川氏と日高地方を二分する勢力に"],["1585年3月","秀吉の紀州攻め。玉置氏は秀吉方につき、湯川勢と坂の瀬で合戦"],["1585年","湯川勢に攻められ落城、城は焼かれる"],["1585年以後","直和・永直父子が羽柴秀長に仕え、城主に復帰"],["1600年","関ヶ原の戦いで西軍につき改易。廃城"]],"who":[["玉置大宣","南北朝時代の武将。手取城を築いたと伝わる"],["玉置直和","戦国時代末の城主。義父湯川直春と対立し秀吉方についた"],["湯川直春","亀山城主。秀吉に抵抗し、手取城を攻め落とした"],["羽柴秀長","秀吉の弟。紀州平定後の領主"],["仙石秀久・小西行長","秀吉方の水軍を率いて日高へ迫ったと伝わる"]],"deep":["坂の瀬の合戦は «湯川勢8,000人、玉置勢1,600人、玉置方の討死83人» などと伝わりますが、軍記物による数字で、確かめるのは難しいものです。","遺構として石垣・堀の跡が残り、地元の «手取城址保存会» が整備や案内に取り組んでいます。","日高地方の戦国史は、湯川氏（亀山城）と玉置氏（手取城）の関係が軸です。婚姻で結ばれながら、秀吉の侵攻で決定的に分かれました。","玉置氏は南北朝時代、日高郡東部の鶴ヶ城を拠点に、大和国境から日高川上流にかけての地を治めていたと伝わります。そこから下流へ進出して築いたのが手取城です。","廃城は関ヶ原後の改易による。紀伊にはその後、浅野氏が入りました。"],"look":["山上に残る石垣","堀切・曲輪などの遺構","日高川と和佐の集落の眺め","登山道の案内板（保存会による）"],"q":["手取城主・玉置直和と、攻めた湯川直春の関係は？","義理の親子。直和は直春の娘むこでした。"],"koji":[],"myth":"築城者・築城時期、合戦の人数は伝承・軍記による。","img":["湯川直春","玉置直和","紀州征伐","亀山城 (紀伊国)"],"wp":"手取城","rel":{"ev":[],"grave":[]},"ph":[["c:d/dd/Dojoji_Gobo_Wakayama15s3200.jpg",3200,2133,"近く: 道成寺"],["c:5/5f/%E5%BA%83%E5%B7%9D%E7%94%BA%E7%AB%8B%E6%B4%A5%E6%9C%A8%E5%B0%8F%E5%AD%A6%E6%A0%A1.jpg",5184,3456,"近く: 広川町立津木小学校"],["c:2/24/Leonurus_japonicus_02.JPG",2448,3264,"近く: 和歌山薬用植物栽培試験場"]]},{"id":"30_iwamuro_jo","n":"岩室城跡（有田・畠山氏）","yomi":"いわむろじょうあと","cat":"城","rank":"B","y":1445,"era":["heian","muromachi","azuchi"],"sh":"有田市指定文化財","ad":"有田市宮原町東・有田郡有田川町田口","st":"JR紀勢本線・紀伊宮原駅付近から登山道へ。山城なので登山の準備を","la":34.0822,"lo":135.19,"hook":"平家の若武者が最後の抵抗をしたと語られる山。熊野街道と高野街道が交わる «道の十字路» を見張った城。","lead":"岩室城は、有田川のほとりにそびえる岩室山（標高276メートル）の山頂にあった山城の跡です。平家の平忠房がたてこもった «岩村城» はここだと考えられ、室町時代には守護・畠山氏の城になりました。1585年、豊臣秀吉の紀州攻めで落城したといわれます。","story":["有田川の下流、宮原のあたりは、昔から «道の十字路» でした。京から熊野へ向かう熊野街道と、高野山へ向かう道がここで交わっていたのです。鎌倉時代のはじめ、この地を本拠にしていたのは湯浅党の一族・宮原氏でした。","1185年、屋島の戦いに敗れた平家。平重盛の子・平忠房は、湯浅宗重をたよって紀州へ落ちのびました。『平家物語』（長門本）は、忠房が «岩村城» にこもって源氏と戦ったと語ります。この岩村城が、岩室城のことだと考えられています。«平家の生き残りが、この山で最後の意地を見せた»——想像するだけで胸が熱くなります。","その後、有田郡に力をのばしたのが守護の畠山氏でした。岩室城を築いたのは誰か、については «畠山持国が正長年間に築いた»«1445年に築いた»«畠山尚順の三男・政氏が築いた» など、史料によって説がばらばらです。«どれが本当?» 決め手はまだありません。","岩室城は、畠山氏の本拠である大野城（海南市）や広城、鳥屋城と比べると小さな «支城» でした。広城や鳥屋城と連絡を取りあい、熊野街道を見張るのが役目だったとみられます。山頂からは有田川の流れと、その先の海までを見わたすことができました。","1585年、豊臣秀吉の大軍が紀州に攻めこみます。畠山貞政がたてこもった岩室城も、秀吉軍の前に落ちたといわれます。鎌倉時代から続いた有田の武士の時代は、ここで幕を下ろしました。いまの有田はみかんの里。城跡の山のまわりにも、みかん畑が広がっています。"],"tl":[["鎌倉時代前期","湯浅党の宮原氏が宮原を本拠とする"],["1185年ごろ","平忠房が湯浅宗重をたより «岩村城» にこもったと語られる（『平家物語』長門本）"],["1428〜1429年","畠山持国が築いたとする説（『紀伊続風土記』）"],["1445年","畠山持国が築いたとする説（『花営三代記』）"],["1585年","秀吉の紀州攻めで、畠山貞政のこもる岩室城が落城したと伝わる"],["1983年","有田市の文化財に指定"]],"who":[["平忠房","平重盛の子。湯浅宗重をたより岩村城にこもったと語られる"],["湯浅宗重","湯浅党の祖。忠房をかくまったとされる"],["畠山持国","室町幕府の管領。岩室城を築いたとする説がある"],["畠山政氏","畠山尚順の三男。築城者とする説がある"],["畠山貞政","1585年に岩室城にこもった畠山氏の当主"]],"deep":["山頂は標高276メートル、ふもととの差は約250メートル。«岩村城»«岩室山城» ともよばれます。","築城者・築城年は『紀伊続風土記』『花営三代記』『寛永記』などで異なり、はっきりしません。","畠山氏の紀伊支配の拠点は大野城→広城→鳥屋城と移りました。岩室城はそれらと連携した支城と位置づけられます。","平忠房の籠城は『平家物語』の長門本に見える話で、ほかの諸本とは内容が異なります。忠房はのちに降伏し、処刑されたと伝わります。","宮原は熊野街道（紀伊路）の宿場としても栄え、有田川を渡る地点でした。"],"look":["山頂の曲輪跡","山頂からの有田川と有田の町・海の眺め","ふもとの熊野街道（紀伊路）の道筋"],"q":["岩室城がある宮原で交わっていた二つの道とは？","熊野街道と、高野山へ向かう道（高野街道）。交通の要所でした。"],"koji":[],"myth":"平忠房の籠城は『平家物語』長門本の記述。築城者・築城年は諸説。","img":["平忠房","湯浅党","畠山持国","紀州征伐"],"wp":"岩室城","rel":{"ev":[],"grave":[]},"ph":[["c:4/45/%E7%95%A0%E5%B1%B1%E6%8C%81%E5%9B%BD%E3%81%AE%E8%8A%B1%E6%8A%BC.jpg",1320,1658,"畠山持国"],["c:b/b1/Kibi_Dome%2C_Aridagawa.jpg",4608,3456,"近く: 吉備町 (和歌山県)"],["c:3/3f/Fujinami-Station_20100906.jpg",3072,2304,"近く: 藤並駅"],["c:7/77/Aragijima003.JPG",4032,3024,"近く: 有田川町"],["c:3/3e/Chohoji03s3200.jpg",3872,2592,"近く: 長保寺"],["c:5/54/Yuasa-Gobo_Road_Arida_IC_1.jpg",2851,2188,"近く: 有田インターチェンジ"],["c:d/d4/Shimotsuno-Sta.jpg",1024,768,"近く: 下津野駅"]]},{"id":"30_kinuga_jo","n":"衣笠城跡（三栖・愛洲氏）","yomi":"きぬがさじょうあと","cat":"城","rank":"B","y":1247,"era":["kamakura","muromachi","showa"],"sh":"","ad":"田辺市中三栖","st":"JR紀勢本線・紀伊田辺駅から車で約15分","la":33.764,"lo":135.415,"hook":"熊野古道を見下ろす愛洲氏の山城。戦国が終わるまで続いた一族の城は、太平洋戦争末期、特攻兵器の基地にもなった。","lead":"衣笠城は、田辺市中三栖の衣笠山にあった山城の跡です。鎌倉時代に地頭の愛洲経信が築き、その後は紀伊の愛洲氏の居城になりました。南に熊野古道（中辺路）と田辺湾、北に秋津野を見下ろす要所で、わずかに石垣が残ります。","story":["鎌倉時代、田辺の近くの南部・三栖・秋津の荘園をまとめて任された地頭がいました。愛洲経信です。«地頭» は、幕府から送りこまれて荘園を管理し、年貢を集める役目。経信は衣笠山に城を築いたといわれます。","1247年、鎌倉で北条氏と三浦氏が戦う «宝治合戦» が起こりました。その後、経信は地頭の職を辞し、晩年は南部の館から衣笠城に移り住んだと伝わります。«なぜ職を辞したのか?» 合戦のあおりがあったのかもしれませんが、くわしいことはわかっていません。","城の南には、京から熊野三山へ向かう熊野古道・中辺路が通っていました。上皇や貴族、名もない旅人までが行き来する道を、城はじっと見下ろしていたのです。北には秋津野の田畑が広がり、豊かな土地と交通の要をおさえる絶好の場所でした。","愛洲氏はその後も長くこの地に根を張りました。1615年、大坂夏の陣で愛洲直俊は紀州藩主・浅野長晟の軍に加わり、樫井の戦いで討ち死にします。その後、一族は武士をやめて農民になったとされ、城もこのころに役目を終えたと考えられています。","それから300年あまり。太平洋戦争の末期、この山に特攻兵器 «桜花» を打ち出すためのカタパルトが造られました。若い兵士が乗りこみ、敵艦に体当たりするための兵器です。中世の城跡には、戦争の悲しい記憶も重なっています。この場所を訪れるときは、命を落とした人々への思いも胸にとめておきたいものです。"],"tl":[["鎌倉時代","地頭・愛洲経信が衣笠山に城を築いたとされる"],["1247年","宝治合戦。のち経信が職を辞し、衣笠城に移る"],["室町・戦国時代","紀伊愛洲氏の居城として続く"],["1615年","愛洲直俊が樫井の戦いで討死。その後一族は帰農し、廃城もこのころと考えられる"],["1945年ごろ","特攻兵器桜花（43乙型）の発射基地が設けられる"]],"who":[["愛洲経信","南部・三栖・秋津荘の地頭。衣笠城を築いたとされる"],["愛洲直俊","浅野長晟に従い、1615年の樫井の戦いで討死"],["浅野長晟","当時の紀州藩主"],["田辺海兵団（第6特攻戦隊）","戦争末期、桜花の基地を設けた部隊"]],"deep":["城は南に熊野古道中辺路と田辺湾、北に秋津野をひかえる要衝で、田辺市立三栖小学校の北西にあたります。","愛洲氏は伊勢の愛洲氏と同族とされることがあります。剣術 «陰流» の祖・愛洲移香斎は伊勢の愛洲氏の出身と伝わります（紀伊愛洲氏との関係は諸説）。","廃城年ははっきりせず、1615年に直俊が討死し一族が帰農した前後と考えられています。","«桜花43乙型» は、陸上のカタパルトから発射することを想定した型で、実戦に使われる前に終戦を迎えたとされます。","遺構はわずかな石垣のみで、山中の道は整備状況によって歩きにくい場合があります。"],"look":["わずかに残る石垣","山上からの熊野古道・田辺湾方面の眺め","戦争遺跡としての基地跡（説明板など現地で確認を）"],"q":["衣笠城を築いたとされる愛洲経信の役職は？","地頭。南部・三栖・秋津の荘園を管理しました。"],"koji":[],"myth":"築城者・移住の時期は伝承。リスト名の «日高・湯川氏» とは異なり、Wikipedia記事の衣笠城は田辺市の愛洲氏の城。","img":["愛洲氏","宝治合戦","熊野古道","桜花 (航空機)"],"wp":"衣笠城 (紀伊国)","rel":{"ev":[],"grave":[]},"ph":[["c:6/68/Shihogokaibishi.png",4000,4000,"愛洲氏"],["c:9/99/Hokke-d%C5%8D_stele_-_Minamoto_no_Yoritomo_tomb_-_Kamakura%2C_Japan.JPG",3648,5472,"宝治合戦"],["c:7/73/Japanese_Ohka_rocket_plane.jpg",793,363,"桜花 (航空機)"]]},{"id":"30_toya_jo","n":"鳥屋城跡（石垣氏）","yomi":"とやじょうあと","cat":"城","rank":"B","y":1585,"era":["muromachi","azuchi"],"sh":"","ad":"有田郡有田川町中井原","st":"JR紀勢本線・藤並駅から車で約15分。山城なので登山の準備を","la":34.0625,"lo":135.27,"hook":"紀伊守護・畠山氏の «最後のとりで»。秀吉の大軍を前に、300メートルの山上で戦国の畠山家は力つきた。","lead":"鳥屋城は、有田川の中流、鳥屋城山（標高305メートル）に築かれた山城の跡です。この一帯は湯浅党の一族・石垣氏の本拠 «石垣荘» でした。戦国時代、紀伊守護・畠山氏が広城から拠点を移し、1585年の豊臣秀吉の紀州攻めで落城しました。","story":["有田川をさかのぼると、両側に山がせまり、みかん畑の段々が続きます。そのなかに、ひときわ高くそびえるのが鳥屋城山。鎌倉時代、このあたりは «石垣荘» とよばれ、湯浅党の一族・石垣氏が根を張る土地でした。のちに守護の畠山氏の領地となります。","1520年、紀伊守護・畠山尚順は、家臣の野辺慶景や国人の湯河氏・玉置氏に広城を追われました。«海辺の城はもう危ない»。畠山氏は拠点を、山深い鳥屋城へ移したといわれます。ふもとから250メートル以上も高い山の上。守りにはうってつけでした。","ふだん暮らしたのは、西へ2キロほどの «金屋土居» だったと考えられています。東西120メートル、南北100メートルの堀をめぐらせた大きな館で、畠山氏かその家臣・神保氏の館と伝わります。«ふだんは館、いざとなれば山城へ»。守護にふさわしい構えでした。","1585年3月、豊臣秀吉の紀州攻めが始まります。仙石秀久・中村一氏・小西行長らの軍勢が鳥屋城に押し寄せました。城は落ち、畠山式部太輔、村上六右衛門の親子3人、柏原父子、根来寺の法師・蓮蔵院らが討ち取られたと伝わります。根来の僧まで加わっていたのは、紀州の人々が力を合わせて秀吉に抵抗した証でしょう。","いま山に残る曲輪は、東西に細長く並ぶ素朴な造りです。«秀吉軍に備えて大改造した城にしては単純すぎる»。そう考える研究者は、遺構は1585年より前のものだと推測しています。紀伊守護として200年近く続いた畠山氏の歴史は、この山で終わりを告げました。"],"tl":[["鎌倉時代","一帯は湯浅党・石垣氏の拠点 «石垣荘»"],["室町時代","石垣荘が守護畠山氏の所領になる"],["1520年","畠山尚順が広城を追われ、のち拠点が鳥屋城へ移ったといわれる"],["1585年3月","秀吉の紀州攻め。仙石秀久・中村一氏・小西行長らにより落城"]],"who":[["畠山尚順","広城を追われた紀伊守護。以後、畠山氏の拠点が鳥屋城へ"],["神保氏","畠山氏の家臣。金屋土居の主と伝わる"],["仙石秀久・中村一氏・小西行長","1585年に鳥屋城を攻めた秀吉方の武将"],["畠山式部太輔","落城の際に討ち取られたと伝わる武将"],["石垣氏","湯浅党の一族。石垣荘を本拠とした"]],"deep":["標高305メートル、比高255メートル。東西に細長く続く曲輪群が西群・東群に分かれます。","縄張が単調で、秀吉軍に備えて整備したものとは考えにくいことから、遺構は1585年以前のものと推測されています。","西約2キロの金屋土居は東西120メートル・南北100メートルの堀をもつ館で、守護所にふさわしい規模。鳥屋城はその «詰城» とも考えられます。","拠点が広城から鳥屋城へ移った後も、地形の制約から広に一定の政治機能が残ったと推測されています。","読みは «とやじょう»。同名の城が讃岐・信濃・豊後にもあります。"],"look":["山上の東西に長い曲輪群","山頂からの有田川流域とみかん畑の眺め","金屋土居の推定地（ふもと）"],"q":["鳥屋城を攻め落とした秀吉方の武将を一人あげると？","仙石秀久（ほかに中村一氏・小西行長）。1585年3月のことです。"],"koji":[],"myth":"拠点移転の時期、討死者の名は伝承。金屋土居の主は «伝わる»。","img":["畠山尚順","紀州征伐","仙石秀久","広城"],"wp":"鳥屋城","rel":{"ev":[],"grave":[]},"ph":[["c:6/62/%E7%95%A0%E5%B1%B1%E5%B0%9A%E9%A0%86%E3%81%AE%E4%BD%8D%E7%BD%B2%E3%81%A8%E8%8A%B1%E6%8A%BC.jpg",1212,2213,"畠山尚順"],["c:e/e3/Sengoku_Hidehisa.jpg",644,1404,"仙石秀久"],["c:a/a6/%E6%98%A5%E3%81%AE%E7%94%9F%E7%9F%B3%E9%AB%98%E5%8E%9F.png",1700,1148,"近く: 金屋町"],["c:6/6f/R480-2020-056.jpg",1920,1078,"近く: 道の駅明恵ふるさと館"],["c:c/cf/Kanaya_Post_Office.jpg",3264,2448,"近く: 金屋郵便局"]]},{"id":"30_kinomoto","n":"木本八幡宮","yomi":"きもとはちまんぐう","cat":"寺社","rank":"B","y":1618,"era":["heian","edo"],"sh":"県指定無形民俗文化財（木ノ本の獅子舞）","ad":"和歌山市西庄","st":"南海加太線・八幡前駅から歩いて約10分","la":34.2658,"lo":135.1208,"hook":"高さ約5メートルの竹の上で、獅子が舞う。神話の神宝がいっとき置かれたと伝わる «木の本» の宮。","lead":"木本八幡宮は、和歌山市北西部・木本地区の氏神です。紀伊の古い神話では、日前宮の神宝がここにまつられたといわれ、地名 «木ノ本» の由来にもなりました。秋祭りの «梯子獅子» は県の無形民俗文化財です。","story":["むかし、神武天皇が東へ向かったとき、別の一隊を率いた天道根命が、大切な神宝の «鏡» と «矛» を守って紀伊の海にたどりついた——紀伊国造家の古い伝えは、そう語ります。天道根命は加太の浦に上陸し、次にこの地、さらに毛見の浦へと神宝を移したといいます。","社伝によれば、天道根命は神宝を厳橿山（いつかしやま）の «橿の木の根もと» にまつりました。そこから «木の本の宮»、地名も «木ノ本» になったといわれます。のちに神宝は和歌山市秋月の日前宮に落ち着きますが、その宮地を築くとき、木本の土を運んだという言い伝えも残っています。","八幡さまのほうにも伝説があります。神功皇后が朝鮮半島から帰る途中、都で反乱が起きました。幼い皇子（のちの応神天皇）は武内宿禰とともにこの地に上陸し、«しばらく» 身をかくしたといいます。その跡にまつられたのが «芝原八幡宮»。«しばらく» が «しばはら» になった、という語呂合わせのような話です。","実際には、奈良時代にこの一帯が大和の大安寺の領地になったこと、平安時代には東大寺系の寺が «木本庄» を治めたことから、その鎮守の八幡神を迎えたのだろう、という説があります。1585年、豊臣秀吉の紀州攻めで社殿は焼けてしまいました。","江戸時代のはじめに社殿が建て直され、1618年、木本の宮と芝原八幡宮が一つになって «木本八幡宮» となりました。秋祭りでは、だんじりの上およそ5メートルに渡した青竹の上で黒い獅子が舞います。«親獅子が子を谷に落として試す» 物語を演じる、はらはらする舞です。"],"tl":[["神話の時代","天道根命が神宝を厳橿山の橿の根もとにまつったと伝わる"],["8世紀中ごろ","一帯が大和・大安寺の寺領になったとされる"],["1111年","東大寺の木本庄所領目録に «八幡» が見える（これを当社とする説）"],["1585年","秀吉の紀州攻めで社殿焼失"],["1603年","両宮の仮殿を再建"],["1618年","芝原八幡宮を合わせて «木本八幡宮» に"],["1861年","孝明天皇が攘夷を祈願し、正一位を授ける"],["1875年","県社になる"]],"who":[["天道根命","紀伊国造家の祖とされる神。神宝を奉じて当地に来たと伝わる"],["応神天皇（誉田皇子）","幼いころ当地に «しばらく» 滞在したと伝わる祭神"],["神功皇后","応神天皇の母。祭神"],["武内宿禰","皇子を守って上陸したと伝わる"],["孝明天皇","幕末に攘夷を祈願した"]],"deep":["『紀伊続風土記』が引く «国造家旧記» には、神宝（のちの日前神宮・國懸神宮の神体）が加太浦→木本→毛見浦と移ったとあります。","『紀伊国名所図会』などは、日前国懸神宮の南の小丘を «当社から良い土を運んで築いた山» と伝え、宮域に不浄があるとその土で清めたといいます。","八幡の創祀について、大安寺の鎮守八幡を勧請した説と、東大寺の鎮守（手向山八幡宮）を勧請した説があります。","1月7日の «御田祭» は宮司がほぼ一人で耕作から収穫・計量までを演じる予祝の神事。牛耕の所作がある点が県内の他社と異なります。","例祭は10月14日以後の最初の日曜日。前日に山腹の本殿から山麓の権殿へ神霊を移し（下遷宮）、当日は3基の神輿が海岸まで渡御します。","昔は山のすぐ下まで海岸線が迫っていたといわれ、«海から神が来た» 伝承の背景とされます。"],"look":["厳橿山の中腹にある本殿と、山麓の権殿","秋祭りの梯子獅子（だんじり上の青竹で舞う）","1月7日の御田祭","境内からの紀淡海峡方面の眺め"],"q":["«芝原八幡宮» の名は、皇子がこの地にどうしたことから付いたと伝わる？","«しばらく» 滞在したことから。語呂合わせのような伝承です。"],"koji":[{"w":"獅子の子落とし","m":"獅子はわが子を深い谷に落とし、はい上がってきた子だけを育てるという話。わざと試練を与えて鍛えるたとえ。梯子獅子の舞の題材"}],"myth":"天道根命・応神天皇の来訪は伝承。八幡の起源は諸説。","img":["日前神宮・國懸神宮","天道根命","獅子舞","紀伊国造"],"wp":"木本八幡宮","rel":{"ev":[],"grave":[]},"ph":[["c:4/4d/Kimoto-hachimangu_2024-02_1.jpg",2432,1824,"木本八幡宮"],["c:3/35/Hinokuma-jingu_Kunikakasu-jingu%2C_entrance-2.jpg",6014,3998,"日前神宮・國懸神宮"],["c:7/7e/Lion_Dancers_-_Japan_035_%285081058619%29.jpg",2816,2112,"獅子舞"]]},{"id":"30_kiminotoge","n":"紀見峠（高野街道の峠）","yomi":"きみとうげ","cat":"街道","rank":"B","y":1700,"era":["edo","meiji"],"sh":"","ad":"橋本市柱本（紀見峠）","st":"南海高野線・紀見峠駅から歩いて約30分（坂道）","la":34.3775,"lo":135.6036,"hook":"河内から峠を越えると、眼下に紀ノ川——高野山まであと六里。参詣者がほっと息をついた国境の峠。","lead":"紀見峠は、和歌山県橋本市と大阪府河内長野市の境にある標高約400メートルの峠です。大阪から高野山へ向かう «高野街道» の通り道で、江戸時代には紀州藩の番所や宿場が置かれ、参詣者でにぎわいました。","story":["大阪から高野山へ向かう人たちは、河内長野を過ぎると山道にさしかかります。最後の上り坂を登りきった峠で、ぱっと南の景色がひらけます。眼下には紀ノ川、その向こうに高野山の山々。«紀の国が見える峠»、だから «紀見峠»（紀伊見峠）とよばれました。","峠は、河内国と紀伊国の国境でした。江戸時代、紀州藩はここに番所を置き、人や物の出入りに目を光らせました。峠の紀伊側には宿場ができ、旅籠や茶店が並びます。高野山へお参りする人々が、ひと休みしてから下っていったのです。","峠の旧街道わきには «高野山六里» と刻まれた道標石があります。ここから高野山の不動坂口女人堂まで六里、約24キロ。«まだ六里もあるのか» とため息をついたか、«もう六里だ» と元気を出したか。旅人の気持ちを想像してみてください。","明治時代の峠には約70軒の家があったといいます。ところが1900年、紀和鉄道（いまのJR和歌山線）が開通すると、峠を歩いて越える人は激減しました。1915年には大阪高野鉄道（いまの南海高野線）の紀見峠トンネルも完成。«歩く時代» の終わりが、峠の宿場をさびしくしていきました。","この峠の集落は、数学者・岡潔が少年時代をすごした土地としても知られます。静かな山の暮らしのなかで、世界的な研究へとつながる心が育まれたのかもしれません。いまは国道のトンネルができ、車は峠を通らなくなりましたが、旧道には宿場の面影がのこっています。"],"tl":[["中世","高野山参詣の道として使われる"],["江戸時代","紀州藩が峠に番所を置き、紀伊側に宿駅が設けられる"],["明治時代","峠に約70軒の人家があった"],["1900年","紀和鉄道（現JR和歌山線）開通。峠越えの参詣者が激減"],["1915年","大阪高野鉄道（現南海高野線）の紀見峠トンネル完成"],["1969年","国道の紀見トンネル開通"]],"who":[["高野山の参詣者","大阪・京方面から峠を越えて高野山をめざした"],["紀州藩","峠に番所を置き、国境を守った"],["岡潔","多変数関数論で知られる数学者。紀見峠で少年時代をすごした"]],"deep":["紀見峠は和泉山脈と金剛山地の境目にあたります。和歌山市・岬町から続く和泉山脈が、ここで金剛山地に切りかわります。","峠の «高野山六里道標石» は、高野山不動坂口女人堂までの距離を示します。高野街道には各地に «里石» が残ります。","旧街道の峠道は、戦後は府県道、1963年に二級国道170号となりましたが、1969年のトンネル開通で車の通り道ではなくなりました。","南海高野線の紀見峠トンネル（1915年）、新紀見トンネル（1976年、下り線用）と、鉄道も峠の下をくぐっています。","高野街道は東高野街道・西高野街道などが河内長野で合流し、紀見峠を越えて橋本へ下ります。"],"look":["峠の «高野山六里» 道標石","宿場の面影が残る旧街道の集落","峠から南へ見下ろす紀ノ川の谷","岡潔ゆかりの地を示す碑など（現地で確認を）"],"q":["紀見峠から高野山の女人堂までは何里と道標に刻まれている？","六里（約24キロ）。«高野山六里» の道標石があります。"],"koji":[],"myth":"«紀の国が見える» という名の由来は一般的な説明。","img":["高野街道","紀見峠駅","岡潔","和泉山脈"],"wp":"紀見峠","rel":{"ev":[],"grave":[]},"ph":[["c:d/da/Kimitouge01.JPG",1024,768,"紀見峠"],["c:f/fe/Koya_kaido_01.jpg",1504,1000,"高野街道"],["c:1/14/KIMITOGE_Station.jpg",2000,1500,"紀見峠駅"],["c:2/23/Kiyoshi_Oka.jpg",800,540,"岡潔"]]},{"id":"30_ohashi","n":"大日山35号墳","yomi":"だいにちやまさんじゅうごごうふん","cat":"遺跡","rank":"B","y":530,"era":["kofun"],"sh":"国指定特別史跡（岩橋千塚古墳群）","ad":"和歌山市岩橋・井辺","st":"JR和歌山駅からバスで «紀伊風土記の丘» 方面へ。そこから山道を歩いて山頂の古墳へ","la":34.2244,"lo":135.2208,"hook":"翼を広げた鳥、前後に顔をもつ人——«全国初» の埴輪が次々に出た、紀伊の王の山頂の墓。","lead":"大日山35号墳は、岩橋千塚古墳群の西の端、大日山（標高141メートル）の山頂にある6世紀前半の前方後円墳です。墳丘の長さは約86メートルで古墳群最大級。2003年からの発掘で、全国で初めての形の埴輪がいくつも見つかり、国の重要文化財になりました。","story":["和歌山市の東、岩橋山の尾根には、800基をこえる古墳がひしめいています。«岩橋千塚古墳群»。その西の端のいちばん高い峰・大日山の頂上に、ひときわ大きな前方後円墳があります。それが大日山35号墳です。«なぜ山のてっぺんに?» 和歌山平野と紀ノ川河口を見下ろし、また下からも見上げられる場所だからでしょう。","墳丘は盾の形をした土台の上に、2段に土を盛って造られています。全長約86メートル、土台をふくめると約105メートル。前方部のくびれの左右には «造出» という張り出しがあり、そこに埴輪がずらりと並べられていました。王の葬式の «舞台セット» のようなものです。","2003年からの発掘で、この造出から驚くべき埴輪が次々に出てきました。翼を大きく広げた鳥の埴輪、前と後ろの両方に顔がある «両面人物埴輪»、矢を入れる «胡籙» の埴輪——どれも全国で初めての発見でした。«両面の人は何を表しているの?» その答えはまだ出ていません。","後円部には横穴式の石室があり、緑色の結晶片岩の板石を積み上げて造られています。天井近くに «石棚» と «石梁» という棚や梁をわたすのは、岩橋千塚だけに見られる «岩橋型石室» の特徴で、この古墳はその初期の例です。石室からは銀の玉、よろいのかけら、馬具などが見つかりました。","岩橋千塚古墳群は、紀ノ川下流を治めた豪族・紀氏（紀国造家）の一族の墓と考えられています。家形埴輪や馬形埴輪には、大阪府の今城塚古墳（継体天皇の本当の陵ともいわれる古墳）とよく似た特徴があり、紀伊の王と大和の大王との深いつながりを感じさせます。"],"tl":[["6世紀前半","大日山35号墳が築かれる"],["1931年","岩橋千塚古墳群が国の史跡に指定"],["1952年","岩橋千塚古墳群が国の特別史跡に"],["1963〜1966年","関西大学などが測量・石室調査"],["2003〜2005年度","和歌山県教育委員会による発掘調査。全国初の埴輪が出土"],["2016年8月17日","出土した埴輪・須恵器が国の重要文化財に"]],"who":[["紀氏（紀国造家）","岩橋千塚古墳群を築いた一族と考えられる"],["被葬者（紀伊の首長）","この古墳に葬られた有力者。名前はわかっていない"],["継体天皇","今城塚古墳の被葬者とする説がある大王。埴輪の類似が指摘される"]],"deep":["墳丘長約86メートル（基壇を含めた総長約105メートル）。主軸は南北方向で、前方部を南に向けます。","円筒埴輪には紀伊型（明るい色の胎土、横ハケあり）と畿内型（黄褐色、横ハケなし）の2系統があり、置かれた場所で使い分けられていました。","形象埴輪は家・人物（盛装男子・武人・力士・巫女）・動物（馬・牛・猪・犬・水鳥・翼を広げた鳥）・器財（大刀・胡籙・靫・蓋）。両面人物、翼を広げた鳥、胡籙は全国初例です。","玄室は長さ4.33メートル、高さ2.85メートル。結晶片岩の板石を小口積みにし、石棚と石梁を備えます。床には玉石を敷き、排水溝もありました。","石室出土の須恵器はMT15〜TK10型式で、6世紀前半ごろの築造と推定されます。","造出の上では須恵器の甕を据えた場所と埴輪の場所が分かれており、儀式の空間の使い分けが指摘されています。","出土品は県立紀伊風土記の丘で保管・展示されています。"],"look":["山頂の墳丘と、整備された造出","岩橋型横穴式石室（公開状況は事前に確認を）","山頂からの和歌山平野・紀ノ川河口の眺め","紀伊風土記の丘資料館の埴輪展示"],"q":["大日山35号墳で全国初めて見つかった埴輪を一つあげると？","翼を広げた鳥の埴輪（ほかに両面人物埴輪、胡籙形埴輪も全国初）。"],"koji":[],"myth":"被葬者は不明。今城塚古墳との関係は研究者の指摘。","img":["岩橋千塚古墳群","和歌山県立紀伊風土記の丘","今城塚古墳","埴輪"],"wp":"大日山35号墳","rel":{"ev":[],"grave":[]},"ph":[["c:3/39/Dainichiyama_Kofun_Group-35%2C_zenkei.jpg",6016,4000,"大日山35号墳"],["c:0/05/Dainichiyama_Kofun_Group-35%2C_zenpoubu.jpg",6016,4000],["c:a/ae/Dainichiyama_Kofun_Group-35%2C_nishi-tsukuridashi.jpg",6016,4000],["c:4/45/Dainichiyama_Kofun_Group-35%2C_kouenbu.jpg",6016,4000],["c:9/94/Dainichiyama_Kofun_Group-35%2C_kouenbu-funkyu.jpg",6016,4000],["c:1/15/Dainichiyama_Kofun_Group-35%2C_higashi-tsukuridashi-1.jpg",6016,4000],["c:1/1e/Dainichiyama_Kofun_Group-35%2C_funcho.jpg",6016,4000],["j:1/1a/%E5%A4%A7%E6%97%A5%E5%B1%B135%E5%8F%B7%E5%A2%B3%E5%87%BA%E5%9C%9F_%E9%A6%AC%E5%BD%A2%E5%9F%B4%E8%BC%AA.JPG",3479,3783]]},{"id":"30_shingu_kaisen","n":"浜の宮王子","yomi":"はまのみやおうじ","cat":"街道","rank":"B","y":1109,"era":["heian","muromachi"],"sh":"国指定史跡（熊野参詣道）","ad":"東牟婁郡那智勝浦町浜ノ宮","st":"JR紀勢本線・那智駅から歩いて約3分","la":33.6449,"lo":135.9344,"hook":"この浜から、戻ることのない小舟が南の海へ出ていった——«補陀洛渡海» の伝承が残る熊野の王子。","lead":"浜の宮王子は、熊野古道の «九十九王子» のひとつで、那智の浜辺にあります。いまは熊野三所大神社が建ち、となりには補陀洛山寺があります。この浜は、南の海のかなたにある観音の浄土をめざして小舟で船出した «補陀洛渡海» の舞台として知られます。","story":["那智駅を出ると、目の前に青い海と白い砂浜。そのすぐそばに、こんもりとした森の中の神社があります。熊野三所大神社、昔の «浜の宮王子» の跡です。平安時代の貴族・藤原宗忠は1109年の熊野詣での日記『中右記』に «浜宮王子» と書き残しています。","«王子» とは、熊野の神さまの御子神をまつる小さな社のこと。京から熊野へ向かう道には «九十九王子» とよばれるほどたくさんの王子社があり、参詣者は一つひとつに祈りながら進みました。浜の宮王子は、那智の滝と那智大社へ向かう入口にあたります。","となりの補陀洛山寺には、こんな話が伝わります。南の海のかなたには観音さまの浄土 «補陀洛» がある。そこへ生きたまま渡ろうと、僧たちがこの浜から小舟で船出した——。舟には屋形が組まれ、外から戸を打ちつけられたともいいます。«帰れない旅に、なぜ出たの?» それは信仰の極みだったのか、それとも……。答えは一つではありません。","『平家物語』には、平清盛の孫・平維盛がこの那智の浜から小舟で沖へこぎ出し、海に身を投げた話があります。一門が滅びへ向かうなか、熊野で出家した維盛の最期でした。«那智参詣曼荼羅» という絵にも、この浜から渡海船が出てゆく場面が描かれています。","境内には «振分石» とよばれる石柱があります。熊野古道が «中辺路» と «大辺路» に分かれる地点については諸説あり、那智で分かれるとする説では、この石がその分かれ目だといわれます。海と山、この世とあの世の境目のような浜で、いまも波の音が聞こえます。"],"tl":[["1109年","『中右記』に «浜宮王子» と見える"],["平安時代後期（11世紀ごろ）","祭神像3躯（現・重要文化財）が作られる"],["平安末期","『平家物語』で平維盛が那智の沖で入水したと語られる"],["中世〜近世","補陀洛渡海の伝承。那智参詣曼荼羅に渡海船が描かれる"],["1873年","神仏分離で補陀洛山寺から独立し村社に"],["1982年","木造の男神・女神坐像3躯が重要文化財に"],["2000年","境内が国の史跡 «熊野参詣道» の一部に"]],"who":[["藤原宗忠","平安時代の貴族。日記『中右記』に浜宮王子を記した"],["平維盛","清盛の孫。『平家物語』で那智の沖に入水したと語られる"],["補陀洛渡海の僧たち","観音の浄土をめざしてこの浜から船出したと伝わる"],["井上靖","渡海僧を描いた小説『補陀落渡海記』の作者"]],"deep":["本殿に安置される木造の女神坐像1躯・男神坐像2躯はカヤの一木造、像高約60センチ。作風から11世紀ごろの作とされ、国の重要文化財です。","祭神の名は時代によって変わったらしく、江戸時代中期の地誌『熊野巡覧記』は別の神名をあげています。","摂社に地主神 «丹敷戸畔命» がまつられます。丹敷戸畔は『日本書紀』の神武東征で熊野の地に登場する名です。","補陀洛渡海は平安時代から江戸時代にかけて行われたと伝わり、補陀洛山寺には渡海した僧の名を刻んだ碑があります。人数や実態には諸説あります。","井上靖の小説『補陀落渡海記』は渡海僧の心の揺れを描いた創作で、史実そのものではありません。","中辺路と大辺路の分岐点には田辺説・那智説などがあり、那智説では境内の «振分石» が分岐点とされます。"],"look":["熊野三所大神社の社殿と森","境内の «振分石»","となりの補陀洛山寺と復元された渡海船","目の前の浜の宮海岸"],"q":["観音の浄土をめざして小舟で南の海へ船出したことを何という？","«補陀洛渡海»。この浜が船出の地と伝わります。"],"koji":[],"myth":"補陀洛渡海の実態・人数、維盛入水は伝承・軍記物による。『補陀落渡海記』は小説。","img":["補陀洛山寺","補陀落渡海","九十九王子","平維盛"],"wp":"浜の宮王子","rel":{"ev":[],"grave":[]},"ph":[["c:a/a3/Kumanosanshooomiwasha02s1920.jpg",1920,1280,"浜の宮王子"],["c:b/b7/Kumano_Kodo_Furiwake-ishi.jpg",1500,2000],["c:d/d2/Kumanosanshooomiwasha04s2040.jpg",2040,1360],["c:b/be/Kumanosanshooomiwasha01s1920.jpg",1920,1280],["c:4/41/Fudarakusanji03s2010.jpg",2010,1340,"補陀洛山寺"],["c:c/cb/Fudarakusanji02s1024.jpg",1024,768,"補陀落渡海"],["c:f/fc/Daimonzaka17_1024.jpg",768,1024,"九十九王子"],["c:6/6a/Taira_no_Koremori.jpg",283,283,"平維盛"]]},{"id":"30_kirime_oji","n":"切目王子（五体王子のひとつ）","yomi":"きりめおうじ","cat":"街道","rank":"B","y":1159,"era":["heian","kamakura"],"sh":"国指定史跡（熊野参詣道 紀伊路）","ad":"日高郡印南町西ノ地","st":"JR紀勢本線・切目駅から歩いて約15分","la":33.8026,"lo":135.2317,"hook":"熊野詣での途中、平清盛はここで «都で反乱» の急報を受けた——歴史の歯車が回った海辺の王子。","lead":"切目王子は、熊野古道の «九十九王子» のなかでも格の高い «五体王子» のひとつです。平治の乱のとき平清盛が京へ引き返した場所とされ、後鳥羽上皇が歌会を開いた記録も残ります。いまは切目神社として、ホルトノキの巨樹とともにまつられています。","story":["1159年12月。熊野へ向かっていた平清盛の一行は、切目の宿で思いもよらない知らせを受けます。«都で源義朝らが兵をあげ、上皇と天皇をおさえました»。清盛は熊野詣での装束のまま。兵もわずかです。«このまま四国へ逃げて兵を集めるべきか» と迷う清盛を、地元の武士・湯浅宗重らが助けたと『平治物語』は語ります。","清盛は急いで都へ引き返し、平治の乱に勝利しました。ここから平家の全盛時代が始まります。もし切目で知らせを聞かなかったら、もし引き返さなかったら——歴史は大きく変わっていたかもしれません。","切目王子は、平安時代の貴族の熊野詣で日記にたびたび登場します。1109年の『中右記』には «切部の水辺» でみそぎをしてから王子に参ったとあります。1200年12月3日には後鳥羽上皇がここで歌会を開き、そのとき人々が和歌を書いた «熊野懐紙» が今も京都の西本願寺に伝わります。","ちょっと変わった伝説もあります。むかし、罪を犯した «切部の王子» が、熊野帰りの人からご利益を奪うようになった。困った熊野権現がお稲荷さまと相談し、«きな粉で化粧した者には手を出さない» と約束させた——。室町時代の1427年の参詣記には、実際に額や鼻にきな粉をつけて王子の前を通ったと書かれています。","鎌倉時代の終わりには、後醍醐天皇の皇子・護良親王が追手を逃れて熊野へ落ちのびる途中、この王子に参ったと『太平記』は伝えます。1585年の兵火で社殿は焼けましたが、ある尼僧が7か月で建て直したと伝わり、江戸時代には紀州藩主の徳川頼宣も寄進をしました。"],"tl":[["1109年","『中右記』に切部の水辺での祓いと王子社への奉幣が記される"],["1159年","平治の乱。熊野詣で途中の平清盛がここで急報を受け引き返したとされる"],["1200年12月3日","後鳥羽上皇が歌会を開く（熊野懐紙）"],["1201年","藤原定家の熊野御幸記に、ここでの歌会が記される"],["1427年","参詣者がきな粉をつけて王子前を通ったと記録される"],["1585年","兵火で社殿焼失。尼僧が再興したと伝わる"],["1686年","社殿が再建される"],["2022年","国の史跡 «熊野参詣道 紀伊路» に追加指定"]],"who":[["平清盛","熊野詣での途中、ここで平治の乱の急報を受けたとされる"],["後鳥羽上皇","熊野御幸の途中、ここで歌会を開いた"],["藤原定家","後鳥羽院の熊野御幸に随行し、日記に歌会を記録した"],["護良親王（大塔宮）","熊野へ落ちのびる途中に参詣したと『太平記』に記される"],["徳川頼宣","紀州藩主。御戸帳・絵馬を寄進した"]],"deep":["«五体王子» は九十九王子の中でも格式の高い5社。切目王子を五体王子とするのは『紀伊続風土記』の記述です。","熊野懐紙は約30通が現存し、そのうち11通が1200年12月3日の切目王子の歌会のものといわれ、西本願寺に所蔵されています。","神木はナギ。鎌倉時代末の『熊野縁起』（仁和寺蔵）では本地仏を十一面観音としています。","境内の «切目神社のほるとのき» は幹周り約4メートル、高さ約16メートルの巨樹で、県の天然記念物です。","きな粉の伝説のもとは『宝蔵絵詞』。応永34年（1427年）の『熊野詣日記』にきな粉化粧の実例があるのが興味深い点です。","島根県の «石見神楽» には «切目（王子）» という演目があり、熊野信仰の広がりを示しています。"],"look":["切目神社の社殿（旧切目王子）","県天然記念物のホルトノキの巨樹","近くの切目の浜（中世の «切部の水辺»）","熊野懐紙の写し（公開状況は事前に確認を）"],"q":["切目王子の伝説で、参詣者が災いを避けるために顔につけたものは？","きな粉。1427年の参詣記に、実際にきな粉をつけて通った記録があります。"],"koji":[],"myth":"清盛が急報を受けた場所は『平治物語』による。きな粉の伝説・尼僧の再興は伝承。","img":["九十九王子","平治の乱","熊野懐紙","後鳥羽天皇"],"wp":"切目王子","rel":{"ev":[],"grave":[]},"ph":[["c:1/1e/%E5%88%87%E7%9B%AE%E7%8E%8B%E5%AD%90.jpg",3648,2736,"切目王子"],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:f/fc/Daimonzaka17_1024.jpg",768,1024,"九十九王子"],["c:2/26/Heiji_no_ran.jpg",6064,2085,"平治の乱"],["c:c/cd/Emperor_Go-Toba.jpg",2268,2301,"後鳥羽天皇"]]},{"id":"30_inabane_oji","n":"稲葉根王子（岩田川の水垢離場）","yomi":"いなばねおうじ","cat":"街道","rank":"B","y":1109,"era":["heian","kamakura"],"sh":"県指定史跡","ad":"西牟婁郡上富田町岩田","st":"JR紀勢本線・紀伊田辺駅から車で約20分。熊野本宮方面の路線バスもある","la":33.7128,"lo":135.4539,"hook":"«この川を渡れば、罪がきよめられる»——上皇も貴族も、冷たい岩田川に身をひたしてから山の奥へ進んだ。","lead":"稲葉根王子は、熊野古道・中辺路の入口近くにある王子社です。格の高い «五体王子» のひとつで、すぐそばを流れる岩田川（富田川）は、熊野詣での人々が水垢離（冷たい水で身をきよめること）をした場所として知られます。和歌山県の史跡です。","story":["田辺で海沿いの道と別れた熊野詣での一行は、いよいよ山の道・中辺路へ入ります。最初に待っているのが、岩田川のほとりの稲葉根王子。ここで人々は川に入り、冷たい水で体をきよめました。«熊野の神さまに会う前に、身も心もきれいに»——それが水垢離です。","岩田川は、熊野詣での中でもとくに大切な川でした。この川を渡ると罪が消えるとも考えられたのです。道は川にそって進み、ときに流れを渡らなければなりませんでした。1201年、後鳥羽上皇の熊野御幸にお供した藤原定家も、日記『明月記』にこのあたりの道中を書き残しています。冷たい水に衣をぬらしながら進む貴族の姿が目に浮かびます。","稲葉根王子の名は、1109年の藤原宗忠の日記『中右記』に «伊奈波禰王子社» として初めて登場します。鎌倉時代には «五体王子» として、とくに大切にまつられるようになりました。«稲葉根» の名のとおり、ここの神さまは稲荷神の姿をした «金剛童子» だと伝えられます。","稲の神・お稲荷さまにまつわる話も伝わります。天台宗の僧・円珍が、稲荷の老人に初めて出会ったのがこの稲葉根王子だった、というのです。«山の入口で、稲の神が旅人を迎える»。豊かな実りと旅の安全を願う心が重なっているようです。","明治から大正にかけて、全国で神社をまとめる動きがありました。稲葉根王子も1915年に近くの岩田神社へ合わせられ、社殿も移されます。けれど地元の人々は、元の場所を忘れませんでした。1956年、ふたたび旧地へ神さまの分霊を迎え、いまも川のほとりに小さな社が立っています。"],"tl":[["1109年","『中右記』に «伊奈波禰王子社» として初めて見える"],["1201年","後鳥羽院の熊野御幸。『明月記』に准五体王子と記される"],["1326年","『熊野縁起』（仁和寺蔵）に五体王子として記される"],["1427年","『熊野詣日記』にも五体王子として見える"],["1915年","岩田神社へ合祀され、翌年社殿が移される"],["1956年","旧社地へ分霊を迎える"],["1958年","和歌山県の史跡に指定"]],"who":[["藤原宗忠","『中右記』で稲葉根王子を初めて記録した貴族"],["後鳥羽上皇","何度も熊野御幸を行った。1201年の御幸でここを通った"],["藤原定家","1201年の御幸に随行し、岩田川の渡河などを日記に記した"],["円珍","天台宗の僧。この地で稲荷の老翁に会ったという説話がある"],["北野殿","足利義満の側室。1427年の熊野参詣記に登場"]],"deep":["史料上の初見は天仁2年（1109年）10月22日の『中右記』。表記は «伊奈波禰» のほか «稲羽»«稲持王子» などさまざまです。","『明月記』所収の建仁元年（1201年）の記録では «准五体王子»、鎌倉末の『熊野縁起』では «五体王子» とされ、格が上がっていったことがわかります。","祭神は稲荷神の姿をした金剛童子（『熊野縁起』）。稲荷老翁と円珍の出会いの説話は『二十二社註式』に見えます。","江戸時代には岩田村の産土神で、本殿は1間四方の小さなものでした（1792年『田辺領神社書上帳』）。","明治末からの神社合祀政策で多くの王子社が合祀されました。熊野の合祀に強く反対したのが、田辺に住んだ博物学者・南方熊楠です。"],"look":["岩田川（富田川）のほとりに立つ王子社","水垢離が行われた川原の景色","中辺路の道しるべ・案内板","近くの一ノ瀬王子など、次の王子への道"],"q":["熊野詣での人々が岩田川でした、冷たい水で身をきよめる行いを何という？","«水垢離»（みずごり）。熊野の神に会う前の大切な儀式でした。"],"koji":[],"myth":"円珍と稲荷老翁の話は説話。岩田川で罪が消えるという考えは中世の信仰。","img":["九十九王子","熊野古道","中辺路","南方熊楠"],"wp":"稲葉根王子","rel":{"ev":[],"grave":[]},"ph":[["c:3/3c/Inabaneoji_-_Feb_19%2C_2006.jpg",2272,1704,"稲葉根王子"],["c:f/fc/Daimonzaka17_1024.jpg",768,1024,"九十九王子"],["c:b/b5/Minakata-Kumagusu.jpg",900,1300,"南方熊楠"]]},{"id":"30_hirasuka_jo","n":"平須賀城跡（野辺氏・南部の山城）","yomi":"へいすがじょうあと","cat":"城","rank":"B","y":1522,"era":["muromachi"],"sh":"みなべ町指定文化財","ad":"日高郡みなべ町西本庄","st":"JR紀勢本線・南部駅から車で約15分。山城なので登山の準備を","la":33.8153,"lo":135.3293,"hook":"主君を追い出した家臣・野辺氏。その居城は、わずか2年後に熊野の軍勢に攻め落とされた——南部の梅の里にねむる戦国の山城。","lead":"平須賀城は、みなべ町の南部川下流、南部平野のいちばん奥の山（標高207メートル）にあった山城の跡です。紀伊の守護・畠山氏の家臣、野辺氏の城と伝わります。1522年に熊野本宮の軍勢に攻め落とされたと記録にあり、発掘でもそのころの遺物が多く見つかっています。","story":["梅の里として知られるみなべ町。南部川ぞいに梅畑が広がる平野のいちばん奥に、ひときわ高い山があります。平須山。ここにあったのが平須賀城です。ふもととの高さの差は177メートル。«南部の平野と海をひと目で見わたす» 山城でした。","城のあるじとされる野辺氏は、もとは武蔵国（いまの東京・埼玉）の武士でした。«なぜ関東の武士が紀州に?» 紀伊の守護・畠山政長に従って紀伊に入り、15世紀の中ごろから、紀伊の南部を治める «小守護代» として活動していたことがわかっています。","畠山家では、政長と義就のあいだで家督をめぐるはげしい争いが続いていました。平須賀城は政長の流れをくむ畠山氏の拠点のひとつとして使われます。政長の子・尚順の手紙には、目良左京亮という武士が «平守城» で忠節をつくしたとほめる言葉が残っています。","ところが1520年、野辺慶景たちが主君の畠山尚順と戦い、紀伊から追い出してしまいます。«下剋上» です。けれど、その勝利は長く続きませんでした。1522年、熊野本宮の軍勢が «南部の野辺城» を攻め落とした、と『熊野年代記』は記します。尚順は熊野の勢力と手を結んでいたとされ、その反撃だったのかもしれません。","この落城のころから、記録に野辺氏の名は見えなくなります。発掘調査で出た遺物の多くも15世紀後半〜16世紀前半のもので、記録とよく合います。ただ、城の造りからみて、もう少し後まで使われたと考える研究者もいます。梅の香る里の山に、戦国の興亡がひっそりとねむっています。"],"tl":[["15世紀前半","守護代の遊佐家久が湯河氏に «平祝候城» へ人を置くよう指示"],["1460〜1466年ごろ","野辺氏が紀伊奥郡の小守護代として活動"],["1518〜1519年ごろ","畠山尚順が目良左京亮の «平守城» での忠節をたたえる"],["1520年","野辺慶景らが畠山尚順を紀伊から追放"],["1522年","熊野本宮勢に攻められ落城と伝わる（『熊野年代記』）"]],"who":[["野辺慶景","畠山氏の家臣。主君尚順を追放した"],["畠山尚順","政長の子。野辺氏に追われた紀伊守護"],["遊佐家久（禅久）","紀伊奥郡の守護代。平須賀城に人を置くよう命じた"],["目良左京亮","平須賀城で忠節をつくしたと尚順の書状に記された武士"],["熊野本宮の勢力","1522年に城を攻め落としたとされる"]],"deep":["標高207メートル、比高177メートル。«平須山城» ともよばれ、史料には «平祝候城»«平守城»«ヘイシュ野辺城» などさまざまな表記で登場します。","野辺氏は平須賀城と、ふもとの気佐藤にある «高田土居»（平地の館）をセットで使ったと考えられています。山城と平城を組み合わせる運用は、16世紀前半の政長流畠山氏の特徴とされます。","『熊野年代記』の1522年落城の記事は、1520年の尚順追放、その後の野辺氏の消息がとだえることと合わせて、信頼性が高いとみられています。","発掘では遺物の大半が15世紀後半〜16世紀前半のものでした。一方、城の構造から廃城をもっと遅いとみる説もあります。","広城（広川町）とともに、畠山氏の家督争いの舞台となった紀伊の城のひとつです。"],"look":["山上の曲輪や堀切などの遺構","山頂から見る南部平野と梅畑、海","ふもとの高田土居の推定地（気佐藤）"],"q":["平須賀城を居城にしたと伝わる野辺氏は、もとはどこの国の武士？","武蔵国（いまの東京都・埼玉県など）。畠山政長に従って紀伊に来たとみられます。"],"koji":[{"w":"下剋上","m":"下の者が上の者をしのいで力をにぎること。野辺氏が主君畠山尚順を追放した事件がその例"}],"myth":"野辺氏の居城というのは伝承。廃城時期は諸説。","img":["畠山尚順","広城","みなべ町","南部梅林"],"wp":"平須賀城","rel":{"ev":[],"grave":[]},"ph":[["c:c/c5/%E6%97%A5%E6%9C%AC%E3%81%AE%E5%9F%8E%E8%B7%A1.png",971,940],["c:6/62/%E7%95%A0%E5%B1%B1%E5%B0%9A%E9%A0%86%E3%81%AE%E4%BD%8D%E7%BD%B2%E3%81%A8%E8%8A%B1%E6%8A%BC.jpg",1212,2213,"畠山尚順"],["c:9/9b/Minabe-Bairin_Minabe_Wakayama05n4272.jpg",2848,4272,"みなべ町"],["c:3/3d/Minabe-Bairin_Minabe_Wakayama02n4272.jpg",4272,2848,"南部梅林"]]},{"id":"30_niu_sakadono","n":"丹生酒殿神社（丹生都比売の降臨伝承）","yomi":"にうさかどのじんじゃ","cat":"寺社","rank":"B","y":900,"era":["myth","heian","edo"],"sh":"国指定史跡（高野参詣道 三谷坂）・世界遺産","ad":"伊都郡かつらぎ町三谷","st":"JR和歌山線・妙寺駅から紀の川を渡り、歩いて約20分","la":34.2892,"lo":135.52,"hook":"女神が榊の枝を手に天から降りたった «はじまりの地»。紀の川の水で酒をかもしたことが、社の名のいわれという。","lead":"丹生酒殿神社は、高野山のふもと、紀の川のほとりにある神社です。丹生都比売大神が最初に天から降りた地と伝わり、山の上の丹生都比売神社へ向かう参詣道 «三谷坂» の出発点でもあります。秋には大イチョウが境内を黄色に染めます。","story":["神代のむかし、丹生都比売大神は榊の枝を手に、この地の裏山 «榊山» に降りたったと伝わります。御子神の高野御子大神と、百二十の神々をしたがえて。女神は大和や紀伊をめぐって、人々に田をつくること、機を織ること、糸をつむぐこと、煮たきをすることを教え、最後に山の上の天野に落ち着いた——社伝はそう語ります。","«酒殿» という名前にも伝えがあります。女神が紀の川の水で酒をかもしたから、とも、この山の地主神 «竈門明神» が酒を造って神前に初めて供えたから、ともいわれます。夏の祭りで奉納される «笹踊り» の «ささ» は、お酒のことだといいます。","丹生都比売神社の神主（惣神主）は、かつてこのあたりに住んでいたと伝わります。天野の本社へ通うために登った道が «三谷坂»。のちには高野山へ向かう参詣道のひとつにもなりました。山の上の社と、ふもとの社。«山宮» と «里宮» のように、二つの神社は深く結びついていたのです。","境内の奥には «鎌八幡宮» があります。ご神木に鎌を打ちこんで願いをかけるという、全国でもめずらしい信仰です。«鎌が深く刺さって抜けなければ願いがかなう» と信じられてきました。もとは空海が讃岐の八幡さまを高野山に迎えたものと伝わり、明治に兄井村を経てここへ移されました。","拝殿の前には、大きな石灯籠が立っています。刻まれた名は «華岡随賢»。紀州出身の医師・華岡青洲の別名とされます。青洲は1804年、自ら開発した麻酔薬で乳がんの手術をおこなった人物です。地元の偉人も、この神社に灯をささげていたのです。"],"tl":[["神代（伝承）","丹生都比売大神が榊山に降臨したと伝わる"],["1334年","後醍醐天皇が和泉国麻生郷を祈祷田とする綸旨を出したと伝わる"],["1804年","華岡青洲が全身麻酔による乳がん手術を行う"],["1834年","華岡随賢（青洲）の名を刻む石灯籠が奉納される"],["1909年","兄井村の鎌八幡宮を合祀"],["1935年","丹生都比売神社の摂社となる（戦後に独立）"],["2004年","三谷坂が世界遺産 «紀伊山地の霊場と参詣道» の一部に"]],"who":[["丹生都比売大神","紀の川流域の女神。ここに最初に降臨したと伝わる"],["高野御子大神（狩場明神）","丹生都比売の御子神。空海を高野山へ導いたとされる"],["空海","鎌八幡宮の神を讃岐から高野山へ迎えたと伝わる"],["華岡青洲","紀州出身の外科医。石灯籠を奉納したとされる"],["丹生都比売神社の惣神主","この地に住み、三谷坂を通って天野へ通ったと伝わる"]],"deep":["『丹生大明神告門』に «最初に降りたのは伊都郡奄太村の石口» とあり、『紀伊続風土記』はそれを «三谷村榊山酒殿社の所» と解釈しています。具体的な降臨地は裏の谷の «七尋滝» とされます。","近世の史料によれば、丹生都比売神社の惣神主が正月2日や2・8・11月などにこの社で祭祀を行っていました。10月の御神酒の献上は «酒殿» の名にかかわる神事です。","明治の神仏分離まで、境内には別当寺の護摩院（榊山福林寺）がありました。跡地は小学校に転用されました。","御神木の大イチョウは幹周り約5.26メートル、高さ約25メートル（環境省の巨樹調査）。社伝では樹齢800年といわれます。","石灯籠は高さ約2メートル、«天保五年» の銘。鎌八幡宮とともに兄井村から移されたものです。","毎年8月16日の «三谷の笹踊り» では、短冊で飾った笹を持って踊りを奉納します。"],"look":["御神木の大イチョウ（11月下旬〜12月上旬の黄葉）","鎌が刺さった鎌八幡宮のご神木","華岡随賢銘の石灯籠","三谷坂の登り口（丹生都比売神社への道）"],"q":["鎌八幡宮では、願いをかけるときにご神木に何をする？","鎌を打ちこむ（奉献する）。全国でもめずらしい信仰です。"],"koji":[],"myth":"降臨・酒造りの由来、天皇の綸旨、空海の勧請は社伝・伝承。","img":["丹生都比売神社","高野参詣道","華岡青洲","丹生都比売"],"wp":"丹生酒殿神社","rel":{"ev":[],"grave":[]},"ph":[["c:1/11/Niu-Sakadono-Shrine-01.jpg",4000,3000,"丹生酒殿神社"],["c:6/6c/Niu-Sakadono-jinja%2C_Torii_of_Auxiliary_Kama-hachiman-gu_Shrine_001.jpg",4000,3000],["c:e/e6/Niu-Sakadono-jinja%2C_Sacred_Tree_and_Torii_of_Auxiliary_Kama-hachiman-gu_Shrine_001.jpg",4000,3000],["c:7/7c/Niu-Sakadono-jinja%2C_Ema_of_Auxiliary_Kama-hachiman-gu_Shrine_001.jpg",4000,3000],["c:2/21/Niu-Sakadono-Shrine-03.jpg",4000,3000],["c:c/cd/Niu-Sakadono-Shrine-02.jpg",3817,3530],["c:7/7c/Niu-Sakadono-Shrine-Sessya-Sakakiyama-Shrine01.jpg",3969,2976],["c:3/3d/Niu-Sakadono-jinja%2C_Sacred_Tree_of_Auxiliary_Kama-hachiman-gu_Shrine.jpg",2640,3520]]},{"id":"30_yura_yosai","n":"深山砲台跡（加太・由良要塞）","yomi":"みやまほうだいあと","cat":"近代","rank":"B","y":1900,"era":["meiji","showa"],"sh":"","ad":"和歌山市深山（休暇村紀州加太周辺）","st":"南海加太線・加太駅から車で約5分（歩くと約30分）","la":34.279,"lo":135.07,"hook":"森の奥にレンガのトンネルが口を開ける。大阪湾を守るため明治につくられ、一度も敵を撃たなかった砲台。","lead":"深山砲台は、明治時代に大阪湾の入口・紀淡海峡を守るために造られた «由良要塞» の砲台のひとつです。対岸の淡路島・友ヶ島の砲台とともに海峡をにらみました。いまは休暇村紀州加太のまわりの散策道ぞいに、レンガ造りの遺構が残っています。","story":["明治のはじめ、日本は外国の軍艦から大都市を守る方法を考えていました。大阪湾に入るには、紀伊半島と淡路島のあいだの «紀淡海峡» を通るしかありません。«ここに大砲を並べれば、大阪を守れる»。1889年、淡路島の生石山で砲台の工事が始まり、由良要塞づくりがスタートしました。","和歌山側の加太・深山にも砲台が造られます。深山第一・第二砲台には28センチ榴弾砲が6門ずつ、第三（男良谷）砲台には12センチカノン砲が置かれました。森の中の砲台は、海からは見えにくいように工夫されていたのです。深山村には «深山重砲兵連隊» が置かれ、兵士たちが砲台を守りました。","砲台への物資は、加太軽便鉄道（いまの南海加太線）が運びました。«海のリゾートの電車» のイメージがある加太線ですが、もとは要塞を支える鉄道でもあったのです。","けれど時代は変わります。戦争の主役は飛行機になり、海峡の大砲は «使われないまま» 役目を終えました。1945年の終戦後、砲はアメリカ軍に撤去されます。一度も敵艦を撃つことのなかった要塞。それは平和のためには幸いなことでした。","いま、深山第二砲台の跡には休暇村紀州加太が建ち、レンガ造りの «棲息掩蔽部»（兵士が身を守る部屋）が一つ残ります。第一・第三砲台は散策道ぞいに比較的よい状態で保たれ、苔むしたレンガが静かに森にとけこんでいます。見学するときは、ここで訓練にあけくれた兵士たちの時間にも思いをはせてみてください。"],"tl":[["1889年3月","淡路島の生石山第三砲台が起工。由良要塞の建設開始"],["1896年","由良要塞司令部が開設される"],["1903年","鳴門要塞を編入"],["1904年","日露戦争で動員が下る"],["1913年","深山第一・第二砲台などを廃止する方針が出される"],["1941年","友ヶ島の部隊が淡路島側の連隊に編入"],["1945年","終戦。砲は米軍により撤去"],["2003年","友ヶ島の砲台群が土木学会選奨土木遺産に"]],"who":[["深山重砲兵連隊","深山村に置かれ、和歌山側の砲台を運用した部隊"],["由良要塞重砲兵連隊","淡路島の由良に置かれ、要塞の中心部を運用した"],["大日本帝国陸軍","紀淡海峡の防衛のため由良要塞を築いた"]],"deep":["由良要塞は由良（淡路島）・友ヶ島・加太深山の3地区で始まり、1903年に鳴門地区が加わって4地区となりました。","和歌山側には深山第一〜第三砲台のほか、加太砲台（27センチカノン砲）、田倉崎、大川山・佐瀬川・西ノ庄の堡塁、探照灯台、火薬庫などが置かれました。","堡塁は、海岸の砲台を陸側からの攻撃から守るために造られたものです。","加太砲台跡は和歌山市立少年自然の家の敷地にあり、砲座や観測所跡が残ります。見学は事務所への申請が必要とされます。","西ノ庄堡塁の跡地には和歌山県立和歌山西高校が建ちました。","沖の友ヶ島の砲台跡は、アニメ映画の世界のようだとして観光客に人気です。"],"look":["休暇村紀州加太にあるレンガ造りの棲息掩蔽部","散策道ぞいの深山第一・第三（男良谷）砲台跡","砲台跡から見る紀淡海峡と友ヶ島","加太砲台跡（少年自然の家。見学は事前に申請を）"],"q":["深山砲台などへ物資を運んだ鉄道は、いまの何線？","南海加太線（もとの加太軽便鉄道）。"],"koji":[],"myth":"深山砲台の正確な完成年は未確認。遺構は森の中で足もとが悪い所もある。","img":["友ヶ島","加太","南海加太線"],"wp":"由良要塞","rel":{"ev":[],"grave":[]},"ph":[["c:b/b1/%E5%8A%A0%E5%A4%AA%E7%A0%B2%E5%8F%B0%E7%94%B1%E8%89%AF%E8%A6%81%E5%A1%9E_%E3%83%AC%E3%83%B3%E3%82%AC%E5%80%89%E5%BA%ABPA070938.jpg",1280,960,"由良要塞"],["c:5/56/%E6%B7%B1%E5%B1%B1%E7%A0%B2%E5%8F%B0%E8%B7%A1_2024.jpg",4032,3024],["c:4/4a/Yura_Fortress%2C_Oishiyama_Hodai-1-1.jpg",5568,3712],["c:7/7d/Ch%C3%A2teau_de_Himeji02.jpg",2592,1944],["c:1/18/%E5%8F%8B%E3%81%8C%E5%B3%B6%E3%83%BB%E7%B4%80%E6%B7%A1%E6%B5%B7%E5%B3%A1PA071003.jpg",1280,960,"友ヶ島"],["c:e/eb/Nankai-PICT2090-2.jpg",480,640,"南海加太線"]]},{"id":"30_kenpaku","n":"和歌山県立博物館（紀州の歴史をまとめて見る）","yomi":"わかやまけんりつはくぶつかん","cat":"学び","rank":"B","y":1971,"era":["showa","heisei"],"sh":"","ad":"和歌山市吹上1丁目","st":"JR和歌山駅・南海和歌山市駅からバスで «県庁前» 下車、歩いて約3分","la":34.2245,"lo":135.1716,"hook":"縄文の土器から高野山・熊野の宝物、紀州徳川家の品まで——紀伊の国の «歴史のまとめ» を一気に見られる場所。","lead":"和歌山県立博物館は、和歌山城のすぐ近くにある県の歴史博物館です。1971年に設立され、いまの建物は1994年に黒川紀章の設計で開館しました。古代の人々の暮らし、高野山と熊野、熊野古道、紀州徳川家に伝わる品などを通して、和歌山の歴史と文化を紹介しています。","story":["和歌山城の天守を見上げながら坂を下ると、白い大きな建物が見えてきます。和歌山県立博物館です。«紀州の歴史って、どこから見ればいいの?» そんなとき、最初に訪れたいのがここ。史跡めぐりの «予習» にも «復習» にもなる場所です。","館は1971年に設立され、1994年に今の建物に移りました。設計したのは、世界的な建築家・黒川紀章。となりの県立近代美術館と地下でつながり、空調や電気も共通の «ひとつの建物» として造られています。建物そのものも見どころです。","展示室を歩くと、紀伊の国の長い歴史が順番に見えてきます。縄文・弥生の暮らし、古墳の時代の紀氏。そして平安時代からは、高野山と熊野三山という二つの大きな聖地。紀伊が «祈りの国» とよばれたわけが、仏像や経典、古文書からよくわかります。","江戸時代に入ると、紀州は徳川御三家のひとつになりました。初代藩主の徳川頼宣、のちに8代将軍になった吉宗。紀州徳川家に伝わった品々からは、城下町・和歌山のはなやかさが伝わってきます。すぐ近くの岡山の時鐘堂や和歌山城と合わせて歩くと、江戸の城下が立体的に浮かびます。","博物館は、展示するだけの場所ではありません。県内のお寺や神社、家に伝わる大切な文化財をあずかって守り、調べる役目もあります。湯浅の施無畏寺に伝わる境内絵図の一部もここにあずけられています。展示は時期によって入れ替わるので、特別展や企画展の予定を調べてから出かけましょう。"],"tl":[["1971年","和歌山県立博物館が設立される"],["1994年","黒川紀章の設計による現在の建物が開館（近代美術館と一体の建築）"],["現在","常設展示と特別展・企画展で紀伊の歴史文化を紹介"]],"who":[["黒川紀章","現在の建物を設計した建築家"],["徳川頼宣・徳川吉宗","紀州藩主。紀州徳川家ゆかりの品が展示される"],["空海","高野山を開いた僧。高野山関係の展示で登場"],["県内の寺社・所蔵者","文化財を博物館にあずけ、守り伝えている"]],"deep":["建物は鉄筋コンクリート造、延床面積約6,867平方メートル。近代美術館と地下でつながり、設備を共有する一体の建築です。","常設展示は古代の生活から、高野山・熊野三山・熊野古道、紀州徳川家旧蔵品まで、県の歴史をひとめぐりできる構成です。","県内の寺社や個人の文化財の寄託を受け、保存・調査を行っています。施無畏寺の «紙本淡彩施無畏寺境内絵図»（県指定）も一部が寄託されています。","近くには和歌山城、岡山の時鐘堂、首大仏で知られる無量光寺があり、城下町の史跡めぐりの起点になります。","展示替えが多く、見たい文化財が常に出ているとは限りません。目当ての品があるときは公式サイトで確認を。"],"look":["常設展示室（古代〜近世の紀伊の歴史）","高野山・熊野関係の展示","紀州徳川家ゆかりの品","黒川紀章設計の建物と、となりの近代美術館"],"q":["和歌山県立博物館の現在の建物を設計した建築家は？","黒川紀章。となりの県立近代美術館と一体の建物です。"],"koji":[],"myth":"","img":["和歌山県立近代美術館","黒川紀章","和歌山城","紀州藩"],"wp":"和歌山県立博物館","rel":{"ev":[],"grave":[]},"ph":[["c:8/8a/%E5%92%8C%E6%AD%8C%E5%B1%B1%E7%9C%8C%E7%AB%8B%E5%8D%9A%E7%89%A9%E9%A4%A8.jpg",4032,3024,"和歌山県立博物館"],["c:c/c0/250830_Wakayama_Prefectural_Museum_Wakayama%2C_Japan02s3.jpg",5472,3648],["c:3/3a/%E5%92%8C%E6%AD%8C%E5%B1%B1%E7%9C%8C%E7%AB%8B%E8%BF%91%E4%BB%A3%E7%BE%8E%E8%A1%93%E9%A4%A8.jpg",4032,3024,"和歌山県立近代美術館"],["c:b/be/%E9%BB%92%E5%B7%9D%E7%B4%80%E7%AB%A0.jpg",150,200,"黒川紀章"],["c:5/51/%E5%92%8C%E6%AD%8C%E5%B1%B1%E5%9F%8E_%E5%A4%A9%E5%AE%88%E9%96%A3%EF%BC%882024%E5%B9%B4%EF%BC%89.jpg",3024,4032,"和歌山城"],["c:b/b7/Wakayama_Castle_2011_Kuruwa.jpg",1936,1296,"紀州藩"]]}];
